			short = "Строптивая берет начало высоко на горе Хиджал: она вырывается из горного озера водопадом, с громом обрушивающимся в низины.",
			full = "Строптивая берет начало высоко на горе Хиджал: она вырывается из горного озера водопадом, с громом обрушивающимся в низины. Оттуда река течет широко и стремительно, рассекая землю надвое: она отмечает место, где Ясеневый лес сменяется Азшарой, а южнее — где заканчиваются Степи и начинается Дуротар. В устье река бросается последним каскадом в Великое море, чуть северо-восточнее гоблинского порта Кабестан.\n\nЧерез нее перекинуты мосты: один соединяет Азшару с Ясеневым лесом, другой — Дуротар со Степями. Где-то на течении реки есть участок воды, который касается сразу всех четырех земель, — единственное место, где сходятся Ясеневый лес, Азшара, Дуротар и Степи.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["spirit rock"] = {
			name = "Священный Камень",
			short = "Высоко над Долиной Испытаний, там, где Потайная тропа поднимается в холмы Дуротара, стоит Священный Камень, почитаемый шаманами Орды.",
			full = "Высоко над Долиной Испытаний, там, где Потайная тропа поднимается в холмы Дуротара, стоит Священный Камень, почитаемый шаманами Орды. Здесь, у камня, будущие шаманы выпивают сапту, стремясь вступить в общение с землей.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rock",
		},
		["thunder ridge"] = {
			name = "Громовой хребет",
			short = "Громовой хребет — ущелье на северо-западе Дуротара, к юго-западу от Оргриммара. В нем растет лес древних деревьев, живший в гармонии с рокочущими ящерицами, что гнездятся среди них.",
			full = "Громовой хребет — ущелье на северо-западе Дуротара, к юго-западу от Оргриммара. В нем растет лес древних деревьев, живший в гармонии с рокочущими ящерицами, что гнездятся среди них.\n\nГармония нарушилась, когда люди начали валить здесь лес, и ящерицы обезумели. Рексар, посланный собрать мерцающую траву для Дрек'Тара, заметил перемену в зверях и принес весть в Оргриммар. Вместе с Дрек'Таром он вернулся, отыскал лесозаготовку, и им пришлось перебить обезумевших ящериц, чтобы предотвратить беду, хотя потом Рексар собрал их яйца, чтобы Дрек'Тар мог их изучить.\n\nДжайна Праудмур, посланная Траллом узнать, что еще тревожит хребет, обнаружила, что деревья здесь срублены демонической магией — это Пылающий Клинок пытался расшатать порядок в крае. Небольшая шайка его культистов во главе с Физзлом Темным Когтем разбила здесь лагерь, чтобы сеять еще больший хаос, и Оргнил Душегрыз потребовал смерти Физзла, а в доказательство — его коготь.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Ridge",
		},
		["tiragarde keep"] = {
			name = "Крепость Тирагард",
			short = "Крепость Тирагард белеет на фоне красных скал Берега Разбитых Кораблей — твердыня, которой вовсе не следовало появляться в Дуротаре.",
			full = "Крепость Тирагард белеет на фоне красных скал Берега Разбитых Кораблей — твердыня, которой вовсе не следовало появляться в Дуротаре.\n\nЕе возвели в спешке по приказу великого адмирала Кул Тираса Даэлина Праудмура. Третья война закончилась непрочным миром между Траллом и леди Джайной Праудмур, родной дочерью адмирала, но Даэлин не доверял ни одному орку и не признавал перемирия, заключенного от его имени. Он привел свой флот из Кул Тираса к берегам Дуротара и бросил его против Орды, построив крепость Тирагард как плацдарм для войны, которую намеревался довести до конца. Наступление разбилось об орков, и крепость вместе с ним обратилась в руины.\n\nСам Даэлин не дожил до ее восстановления: он погиб, когда Орда во главе с Рексаром штурмовала Терамор. Но перед отплытием из Кул Тираса он оставил запечатанные приказы на тот день, когда его флот умолкнет. Когда вестей так и не пришло, приказы были вскрыты, и лейтенанта Бенедикта отправили вернуть руины и продолжить крестовый поход своего командира.\n\nТак крепость встала вновь — потрепанная, но удержанная, сияющий шрам чуждого цвета на багровом камне.",
			source = "https://warcraft.wiki.gg/wiki/Tiragarde_Keep",
		},
		["torkren farm"] = {
			name = "Ферма Тор'кренов",
			short = "Ферма Тор'кренов лежит между Громовым хребтом и водоразделом Строптивой — скромное хозяйство, никогда не приносившее такого дохода, как соседские.",
			full = "Ферма Тор'кренов лежит между Громовым хребтом и водоразделом Строптивой — скромное хозяйство, никогда не приносившее такого дохода, как соседские. Когда-то на ней трудились Майша Тор'крен и ее сын Крон, пока Крон не спустился к реке Строптивой охотиться на кроколисков и не вернулся домой. Теперь Майша ведет хозяйство одна и просит ожерелье из зубов кроколиска, чтобы хранить память о нем.",
			source = "https://warcraft.wiki.gg/wiki/Tor'kren_Farm",
		},
		["valley of trials"] = {
			name = "Долина Испытаний",
			short = "Долина Испытаний лежит, окруженная скалами, на юге Дуротара — чаша выжженной земли, где каждый молодой орк начинает жизнь, уготованную ему Ордой.",
			full = "Долина Испытаний лежит, окруженная скалами, на юге Дуротара — чаша выжженной земли, где каждый молодой орк начинает жизнь, уготованную ему Ордой. Тех, кто не справился, отсюда не выносят. Их оставляют там, где они пали, печься на солнце, пока пустыня не довершит то, что начало испытание.\n\nВ сердце долины находится Логово — пещера, вырубленная в скале и обустроенная с нехитрыми удобствами жизни, отданной служению. Ее хранят старейшины, обучающие молодых их призванию и назначающие им испытания.\n\nК северу в скалах когда-то пустовала вереница небольших естественных пещер. С тех пор в них кое-что проникло. Теперь там гнездятся демоны Пылающего Клинка, выбираясь в саму долину, и их присутствие придало веса давним слухам о том, что Совет Теней обрел в этом краю опору. Демоны слабы, но в пещерах они не сидят, и скверна, которую они несут, начала расползаться за пределы камня, некогда сдерживавшего ее.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
	},
	-- Мулгор: 18 subzones
	[1412] = {
		["baeldun digsite"] = {
			name = "Раскопки Бейл'дана",
			short = "Экспедиция Бейл'дана врезала свой карьер в западный край Мулгора, вгрызаясь кирками в склон горы.",
			full = "Экспедиция Бейл'дана врезала свой карьер в западный край Мулгора, вгрызаясь кирками в склон горы. Их раскопки были объявлены оскорблением Матери-Земли, и когда слова не смогли их остановить, племя Кровавого Копыта захватило и сломало инструменты захватчиков, чтобы прогнать их.\n\nДворфы все равно продолжали копать, не внимая предупреждениям, и их безрассудная работа пробудила гнев духов земли. Карьер остался — шрам, врезанный в землю Мулгора.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Digsite",
		},
		["bloodhoof village"] = {
			name = "Деревня Кровавого Копыта",
			short = "Деревня Кровавого Копыта стоит у вод Озера Каменного Быка на равнинах Мулгора и носит имя племени, которое называет ее своим домом.",
			full = "Деревня Кровавого Копыта стоит у вод Озера Каменного Быка на равнинах Мулгора и носит имя племени, которое называет ее своим домом. Здесь объезжают и обучают диких кодо с равнин, пока те не станут достаточно спокойны, чтобы нести всадника, и деревня славится этим ремеслом не меньше, чем чем-либо другим.\n\nБейн Кровавое Копыто присматривает за деревней и заботится о ее защите. Зарельман Две Луны печется о духовной жизни племени Кровавого Копыта: этот старейшина говорит от имени предков и Матери-Земли с теми, кто живет здесь и кто проходит мимо.",
			source = "https://warcraft.wiki.gg/wiki/Bloodhoof_Village",
		},
		["brambleblade ravine"] = {
			name = "Ежевичная лощина",
