		["golden plains"] = {
			name = "Золотые равнины",
			short = "Золотые равнины, низина с колышущейся зеленой травой к юго-востоку от Громового Утеса, высоко ценятся на родине тауренов как охотничьи угодья.",
			full = "Золотые равнины, низина с колышущейся зеленой травой к юго-востоку от Громового Утеса, высоко ценятся на родине тауренов как охотничьи угодья. Сюда на выпас собираются огромные стада кодо, и где-то в траве, говорят, обитает знаменитая Арра'чея.",
