		["palemane rock"] = {
			name = "Утес Бледногривов",
			short = "Утес Бледногривов — пещера, глубоко уходящая в склон горы на западе Мулгора, где живут гноллы племени Бледногривов.",
			full = "Утес Бледногривов — пещера, глубоко уходящая в склон горы на западе Мулгора, где живут гноллы племени Бледногривов. Они занимают и пещеру, и лагерь у входа в нее, и легко пускают в ход оружие, набрасываясь на всякого, кто подойдет слишком близко к их земле.",
