		["ravaged caravan"] = {
			name = "Разграбленный караван",
			short = "На северо-восточном берегу Озера Каменного Быка тлеют остатки каравана Торговой компании, все еще извергая черный дым в небо над Мулгором.",
			full = "На северо-восточном берегу Озера Каменного Быка тлеют остатки каравана Торговой компании, все еще извергая черный дым в небо над Мулгором. Караван вез припасы для рудника бригадира Шумовика, когда таурены, уставшие от гоблинов на своей земле, напали на него.\n\nУцелевшие так и не покинули обломки. Они до сих пор удерживают дымящуюся груду и ее обгоревший груз, отбиваясь от всех, кто подойдет близко.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Плато Красного Облака",
			short = "Плато Красного Облака — простор холмистых равнин на высоких утесах южного Мулгора, известный своей тихой, открытой красотой.",
			full = "Плато Красного Облака — простор холмистых равнин на высоких утесах южного Мулгора, известный своей тихой, открытой красотой. Именно здесь юные таурены доказывают свою доблесть, выступая против свинобразов-дыбогривов, которые удерживают Ежевичную лощину на северо-востоке.\n\nЛагерь Нараче на северо-западе плато — последнее безопасное место на нем. От кладбища к западу от лагеря тропа поднимается на вершину Плато Дальнего Взора.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Красные скалы",
			short = "Красный песчаник Красных скал возвышается на северо-востоке Мулгора — там, где мир Громового Утеса отступает и его место занимает нечто более тихое.",
			full = "Красный песчаник Красных скал возвышается на северо-востоке Мулгора — там, где мир Громового Утеса отступает и его место занимает нечто более тихое. Здесь таурены очищающим пламенем отправляют своих почтенных мертвых к Матери-Земле и Отцу-Небу. Сюда приносят не каждого павшего таурена: такой покой даруется лишь самым доблестным — воинам, что основали и защищали Громовой Утес, тем, кто отдал жизнь за свои племена и вождей. Сюда же приходят юные воины, чтобы завершить свой путь к зрелости, — они стоят среди камней и вслушиваются в ветер, ловя голоса предков.\n\nСвятость этого места не уберегла его. Отряд свинобразов-дыбогривов ворвался на Красные скалы и осквернил священную землю своим присутствием, что вызвало глубокий гнев у тауренов Громового Утеса, которым это место дорого.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Холмистые равнины",
			short = "Холмистые равнины простираются к югу от деревни Кровавого Копыта, до самой границы Степей. Волки и пумы бродят в траве рядом с кодо и долгоногами.",
			full = "Холмистые равнины простираются к югу от деревни Кровавого Копыта, до самой границы Степей. Волки и пумы бродят в траве рядом с кодо и долгоногами.\n\nВ отличие от остального Мулгора, равнины не закрыты со всех сторон: кентавры-разведчики нашли здесь путь и забираются туда, куда не ступал ни один другой кентавр. На востоке обосновалось гнездо гарпий Ярости Ветра.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["stonebull lake"] = {
