			full = "Озеро Каменного Быка с трех сторон огибает деревню Кровавого Копыта длинной подковой прохладной воды. В его водах полно рыбы, и сюда закидывают удочки долгими тихими часами. Там, где озеро сужается, через него перекинут мост, по которому идет дорога, соединяющая деревню Кровавого Копыта с Громовым Утесом.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Колодец Громового Рога",
			short = "Колодец стоит посреди открытой степи Мулгора, у северной дороги между Громовым Утесом и деревней Кровавого Копыта.",
			full = "Колодец стоит посреди открытой степи Мулгора, у северной дороги между Громовым Утесом и деревней Кровавого Копыта. Когда-то его захватила Торговая компания, надеясь перекрыть тауренам воду, но таурены прогнали их и вернули колодец себе.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
