		["venture co mine"] = {
			name = "Рудник Торговой компании",
			short = "Рудник глубоко врезается в восточные утесы Мулгора, и попасть в него можно тремя путями: пешком через главные ворота, по склону утеса и через небольшой лесозаготовительный лагерь за ним.",
			full = "Рудник глубоко врезается в восточные утесы Мулгора, и попасть в него можно тремя путями: пешком через главные ворота, по склону утеса и через небольшой лесозаготовительный лагерь за ним. Ему здесь не место. Таурены отказали Торговой компании в праве добывать руду на их родине, и компания попросту начала копать без спроса, поставив во главе работ бригадира Шумовика, а совет магната Раздунка давил на него, требуя расширяться еще дальше, заняться лесом, и присылал новые крошшеры и материалы для лесопилки, которая пожирала бы древесину Мулгора.\n\nТаурены не оставили это вторжение без ответа. Караван с горным снаряжением, шедший под охраной вдоль северного берега Озера Каменного Быка, обнаружили скороходы; они напали на него и сожгли все, что смогли, бросив обломки в уверенности, что огонь испортил все ценное. Но это было не так. Позже видели, как сборщики Торговой компании копаются в пепле, собирая то, что пощадило пламя.\n\nЭта находка сделала рудник целью для возмездия — предупреждения, нанесенного по хозяйству Шумовика за нежелание компании оставить землю тауренов в покое.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Колодец Буйногривых",
			short = "Колодец Буйногривых стоит к северу от Громового Утеса — самый северный из священных колодцев тауренов. Землю вокруг него захватили гарпии Ярости Ветра, и колодец осквернен и ждет очищения.",
			full = "Колодец Буйногривых стоит к северу от Громового Утеса — самый северный из священных колодцев тауренов. Землю вокруг него захватили гарпии Ярости Ветра, и колодец осквернен и ждет очищения.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Гряда Ярости Ветра",
			short = "Гряда Ярости Ветра получила свое имя от гарпий, гнездящихся на ее высотах, — свирепых созданий, что пикируют на всякого, кто подойдет слишком близко, убивая или унося зазевавшихся.",
			full = "Гряда Ярости Ветра получила свое имя от гарпий, гнездящихся на ее высотах, — свирепых созданий, что пикируют на всякого, кто подойдет слишком близко, убивая или унося зазевавшихся. По окрестным холмам рыщут также пумы и волки.\n\nИ все же яркие перья гарпий высоко ценятся тауренами Громового Утеса, которые берут их для свадеб и пиров.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Колодец Заиндевевшего Копыта",
			short = "Колодец Заиндевевшего Копыта лежит на краю Холмистых равнин на юге Мулгора. Спустя годы после Третьей войны Торговая компания захватила его и отравила воду, чтобы лишить тауренов питья.",
			full = "Колодец Заиндевевшего Копыта лежит на краю Холмистых равнин на юге Мулгора. Спустя годы после Третьей войны Торговая компания захватила его и отравила воду, чтобы лишить тауренов питья. Мулл Громовой Рог изготавливает тотемы, чтобы очистить скверну, но колодец пока еще не чист.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- Степи: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Агама'гор",
			short = "Агама'гор лежит к северу от дороги, что идет на запад от Лагеря Таурахо, — лабиринт колючих зарослей, занятый свинобразами-дыбогривами.",
			full = "Агама'гор лежит к северу от дороги, что идет на запад от Лагеря Таурахо, — лабиринт колючих зарослей, занятый свинобразами-дыбогривами. Их мертвые оставляют после себя осколки засохшей крови — вещицы, которые ценит изгнанник Кривозуб, обменивающий на них свои странные милости.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Бейл Модан",
			short = "Каменная твердыня Крепости Бейл'дан стоит там, где некогда была деревня тауренов племени Каменного Копья.",
			full = "Каменная твердыня Крепости Бейл'дан стоит там, где некогда была деревня тауренов племени Каменного Копья. Под ней дворфы-землекопы пробиваются к древнему комплексу титанов — исследовательскому центру, погребенному еще до того, как по этой земле ступили сами таурены; его реликвии по большей части все еще лежат во тьме нетронутыми.\n\nДворфы пришли со взрывчаткой и принялись взрывать землю, которую племя Каменного Копья почитало священной. Раскопки разорвали землю, а вместе с ней разорвали и тауренов: большая часть племени погибла или рассеялась, лишившись земель, которые они хранили поколениями. Их старая деревня теперь изрыта копательными машинами дворфов. Ганн Каменное Копье, который до сих пор бродит по окрестным дорогам, пытался уладить дело как вождь с вождем, словами, а не оружием. Дворфы отказались оставить раскопки. Тогда он сменил дипломатию на войну и ищет любую силу, способную их изгнать.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Крепость Бейл'дан",
			short = "Крепость Бейл'дан возвышается над раскопками в Бейл Модане на юге Степей. Ею командует генерал Двукосс, удерживая крепость и ее дворфов против тауренов и орков окрестных равнин.",
			full = "Крепость Бейл'дан возвышается над раскопками в Бейл Модане на юге Степей. Ею командует генерал Двукосс, удерживая крепость и ее дворфов против тауренов и орков окрестных равнин.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Хребет Черных Шипов",
			short = "Долину к северу от Лабиринтов Иглошкурых заполонили колючие заросли, которые удерживают свинобразы-иглогривы. На хребте живет шаманка Брин. Под ее лагерем лежит пруд с водой, чистой и прозрачной посреди колючек.",
			full = "Долину к северу от Лабиринтов Иглошкурых заполонили колючие заросли, которые удерживают свинобразы-иглогривы. На хребте живет шаманка Брин. Под ее лагерем лежит пруд с водой, чистой и прозрачной посреди колючек.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Каменный карьер",
			short = "Каменный карьер находится в Степях; его штольни укреплены оркскими бревнами и увешаны знаменами Орды — выцветшими реликвиями тех, кто первым пробил эти шахты в скале.",
			full = "Каменный карьер находится в Степях; его штольни укреплены оркскими бревнами и увешаны знаменами Орды — выцветшими реликвиями тех, кто первым пробил эти шахты в скале. Той заявки больше нет. Теперь рудником владеет Торговая компания, и гоблины снуют по галереям, где когда-то трудились орки.\n\nДо управляющего пристанью Головокружилкинса дошли слухи, что один из шахтеров вскрыл жилу и добыл огромный изумруд. Управляющий так жаждал его заполучить, что пообещал долю прибыли всякому, кто решится пойти туда и вырвать камень из рук Торговой компании.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Ежевичный овраг",
			short = "Ежевичный овраг удерживают свинобразы-иглогривы. По другую сторону дороги, в Агама'горе, засели дыбогривы, и между двумя племенами идет лишь война.",
			full = "Ежевичный овраг удерживают свинобразы-иглогривы. По другую сторону дороги, в Агама'горе, засели дыбогривы, и между двумя племенами идет лишь война. Подойдите слишком близко к логову иглогривов, и свинобразы не станут ждать, пока их спровоцируют.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Лагерь Таурахо",
			short = "Лагерь Таурахо стоит в Степях, неподалеку от горного перевала, ведущего в Мулгор. Он дает отдых и припасы тем, кто идет из деревни Кровавого Копыта, прежде чем они продолжат путь к родине тауренов.",
			full = "Лагерь Таурахо стоит в Степях, неподалеку от горного перевала, ведущего в Мулгор. Он дает отдых и припасы тем, кто идет из деревни Кровавого Копыта, прежде чем они продолжат путь к родине тауренов.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "Перекресток",
			short = "Перекресток стоит там, где сходятся дороги: тракт с севера на юг, спускающийся от Золотого Пути, и длинный путь с востока на запад, ведущий от Кабестана к Когтистым горам.",
			full = "Перекресток стоит там, где сходятся дороги: тракт с севера на юг, спускающийся от Золотого Пути, и длинный путь с востока на запад, ведущий от Кабестана к Когтистым горам. Это место создано самим пересечением путей, а не тем, что здесь построено: немного ночлегов, никаких могучих стен — лишь шатры, прилавки и торговцы, перекрикивающие друг друга, чтобы продать свой товар.\n\nЗа краем поселения лежит кладбище, простое и тихое на фоне шума торговой площади позади. Сюда Орда приходит почтить своих мертвых — так же, как Альянс ходит для этого на Сторожевой холм.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Пещера Багрового Тумана",
			short = "Над Вершиной Багрового Тумана вечно висит темно-красная мгла, окутывая ее сумраком. Внутри культисты Пылающего Клинка удерживают Пещеру Багрового Тумана, охраняя Демоново семя — артефакт, который они ценят превыше всего.",
			full = "Над Вершиной Багрового Тумана вечно висит темно-красная мгла, окутывая ее сумраком. Внутри культисты Пылающего Клинка удерживают Пещеру Багрового Тумана, охраняя Демоново семя — артефакт, который они ценят превыше всего. Сам туман словно скрывает их поклонение демонам от посторонних глаз.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Вершина Багрового Тумана",
			short = "К северо-западу от Перекрестка в Степях возвышается Вершина Багрового Тумана, чья макушка утопает в красной мгле — остатке древнего демонического проклятия.",
			full = "К северо-западу от Перекрестка в Степях возвышается Вершина Багрового Тумана, чья макушка утопает в красной мгле — остатке древнего демонического проклятия. На ней обосновались культисты Пылающего Клинка, охраняющие Демоново семя в Пещере Багрового Тумана внизу.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Сухие холмы",
			short = "Сухие холмы зеленеют среди пыли Степей — предгорья, поднимающиеся к Когтистым горам.",
			full = "Сухие холмы зеленеют среди пыли Степей — предгорья, поднимающиеся к Когтистым горам. Эту землю удерживают гарпии Зачарованного Крыла, и они осмелели: нападают на караваны на северном участке Золотого Пути, а затем вновь исчезают в зелени.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Дальняя застава",
			short = "Дальняя застава стоит чуть западнее моста, соединяющего Дуротар со Степями, и это немногим больше, чем сторожевая башня, оркская землянка и ряд катапульт, да еще волчий загон с двумя батраками чуть южнее.",
			full = "Дальняя застава стоит чуть западнее моста, соединяющего Дуротар со Степями, и это немногим больше, чем сторожевая башня, оркская землянка и ряд катапульт, да еще волчий загон с двумя батраками чуть южнее. Служба здесь неуютная, но необходимая: застава охраняет караваны, идущие в Дуротар, и держит рубеж против Альянса и свинобразов.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Поля Великанов",
			short = "Поля Великанов раскинулись на юге Степей — широкие и открытые просторы, где стада рокочущих ящериц и кодо бродят вместе в таком числе, с каким мало какие земли могут сравниться.",
			full = "Поля Великанов раскинулись на юге Степей — широкие и открытые просторы, где стада рокочущих ящериц и кодо бродят вместе в таком числе, с каким мало какие земли могут сравниться.\n\nЧерез эти равнины проходит южный отрезок Золотого Пути, и здесь он менее безопасен, чем на севере. Когда-то вдоль него стояли сторожевые башни, охранявшие проходящие караваны; теперь они пустуют, брошенные ветру и траве.\n\nОрда не отказалась от этой земли, хотя держится за нее с трудом. На гребне у южного края Полей, вдали от лагерей и перекрестков, живет шаманка Брин. Неподалеку бродит Ганн Каменное Копье, лелея старую обиду: его племя было изгнано из своей деревни, когда дворфы пришли копать землю в поисках руин титанов по соседству с их домом. Эти раскопки стали Бейл Моданом, и Ганн не забыл, чего они стоили его народу.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Забытые пруды",
			short = "Забытые пруды лежат к северу от западной дороги, ведущей от Перекрестка, — самый северный из оазисов, разбросанных по Северным степям.",
			full = "Забытые пруды лежат к северу от западной дороги, ведущей от Перекрестка, — самый северный из оазисов, разбросанных по Северным степям. Их берега остаются зелеными, окаймленные набухшими грибами, каких больше нигде не встретишь, а в их водах водится загадочная рыба, не похожая ни на какую другую в Степях.\n\nУ кромки воды рыщут кентавры племени Колкар, рядом с черепахами и зверями, что находят здесь приют.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Остров Битв",
			short = "Остров Битв лежит — маленький и сухой — у восточного берега Степей.",
			full = "Остров Битв лежит — маленький и сухой — у восточного берега Степей.\n\nОстров служит учебным полем для воинов всех рас и верований, собравшихся здесь под началом Кланнока Маклеода.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Золотой Путь",
			short = "Золотой Путь тянется между Заставой Мор'шан и Великим Разломом, а его южный отрезок за мостом, отмечающим переправу, называют отдельно — Южным Золотым Путем.",
			full = "Золотой Путь тянется между Заставой Мор'шан и Великим Разломом, а его южный отрезок за мостом, отмечающим переправу, называют отдельно — Южным Золотым Путем.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Ферма Гроль'дома",
			short = "Ферма Гроль'дома — одна из свиноферм, появившихся в годы после основания Оргриммара, и ее загоны постоянно страдают от набегов разорителей из племени Иглогривых.",
			full = "Ферма Гроль'дома — одна из свиноферм, появившихся в годы после основания Оргриммара, и ее загоны постоянно страдают от набегов разорителей из племени Иглогривых.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Цветущий оазис",
			short = "Вода собирается там, где обрывается Великий Разлом, и дикие звери спускаются сквозь деревья на водопой. Кентавры племени Колкар поджидают их среди корней, охотясь на животных, которых влекут к себе пруды.",
			full = "Вода собирается там, где обрывается Великий Разлом, и дикие звери спускаются сквозь деревья на водопой. Кентавры племени Колкар поджидают их среди корней, охотясь на животных, которых влекут к себе пруды.\n\nПод оазисом находится вход в Пещеры Стенаний — место, о котором говорят как о проклятом. То, что шевелится внизу, на поверхность не выходит, но его имя все еще нависает над водой.\n\nРыба здесь не похожа ни на какую другую в Степях.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "Торговое побережье",
			short = "Торговое побережье получило свое имя от торговли, что идет здесь бережливо и непрестанно, в руках гоблинов Кабестана.",
			full = "Торговое побережье получило свое имя от торговли, что идет здесь бережливо и непрестанно, в руках гоблинов Кабестана.\n\nЮжное побережье принадлежит Флибустьерам Южных морей. Среди них — барон Дольноберег, который однажды похитил у Газлоу ценный груз и зарыл его, прежде чем его успели поймать, и с тех пор это богатство затерялось где-то на берегу.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Лагерь Мор'шан",
			short = "Лагерь Мор'шан стоит к югу от границы с Ясеневым лесом, неподалеку от Заставы Мор'шан, и это одно из крупнейших владений Орды в Степях.",
			full = "Лагерь Мор'шан стоит к югу от границы с Ясеневым лесом, неподалеку от Заставы Мор'шан, и это одно из крупнейших владений Орды в Степях. Здесь базируются всадники клана Песни Войны, следящие за дорогой, что ведет на север, в оспариваемый лес.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Застава Мор'шан",
			short = "Застава Мор'шан стоит там, где Золотой Путь уходит на север из Степей; ее возвели как стену против натиска Альянса из Ясеневого леса.",
			full = "Застава Мор'шан стоит там, где Золотой Путь уходит на север из Степей; ее возвели как стену против натиска Альянса из Ясеневого леса. Это грубое сооружение, созданное для войны: земляные валы и сторожевые башни, чтобы удерживать рубеж против сил, напирающих с севера.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Земли Ящеров",
			short = "Солнечночешуйчатые ящеры, населяющие эту небольшую долину, не похожи ни на каких других в Степях. Они проявляют неестественную хитрость: строят грубые хижины и мастерят орудия когтями, которым ремесло должно быть неведомо.",
			full = "Солнечночешуйчатые ящеры, населяющие эту небольшую долину, не похожи ни на каких других в Степях. Они проявляют неестественную хитрость: строят грубые хижины и мастерят орудия когтями, которым ремесло должно быть неведомо.\n\nЕще страннее их тяга ко всему блестящему или незнакомому, из-за которой они совершают набеги на соседние поселения Орды, утаскивая все, что попадется им на глаза.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Кабестан",
			short = "Кабестан стоит на восточном берегу Степей — гоблинский портовый город, бойко торгующий с Пиратской бухтой и бароном Ревилгазом за морем.",
			full = "Кабестан стоит на восточном берегу Степей — гоблинский портовый город, бойко торгующий с Пиратской бухтой и бароном Ревилгазом за морем. Газлоу основал его на деньги, которые Тралл заплатил ему за строительство Оргриммара, и город заполнили контрабандисты и все прочие, кого не приняли в приличных местах.\n\nЭто равнодушие едва не обошлось ему дорого. Культ Пылающего Клинка исподволь стравливал Оргриммар и Терамор, устраивая у гавани Кабестана происшествия с кораблями, в которых ни одна из сторон не видела ничего, кроме провокации. Орочьи и человеческие моряки, мирно делившие его причалы, начали драться на улицах, а когда громила Маззлкранк арестовал капитанов Клатта и Джока, Крепость Северной Стражи сочла это доказательством того, что орки собираются на войну. Кабестан стал местом сбора армии Орды, готовившейся выступить против них. Лишь когда открылась причастность Пылающего Клинка, Тралл отменил битву, прежде чем она началась.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Святилище Павшего Воина",
			short = "Истоптанная тропа поднимается на холм к западу от Перекрестка и заканчивается у святилища павшего воина. Здесь не высечено имени, его не отмечает знамя.",
			full = "Истоптанная тропа поднимается на холм к западу от Перекрестка и заканчивается у святилища павшего воина. Здесь не высечено имени, его не отмечает знамя. Холм хранит молчание, и тропа, ведущая наверх, — единственный знак того, что кто-то еще помнит.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "Нефтяное болото",
			short = "Нефтяное болото не всегда было раной на теле земли. Когда-то здесь был пруд с кристально-голубой водой — пока не пришла Торговая компания и не поставила над ним нефтяную вышку.",
			full = "Нефтяное болото не всегда было раной на теле земли. Когда-то здесь был пруд с кристально-голубой водой — пока не пришла Торговая компания и не поставила над ним нефтяную вышку. Теперь от него осталась лишь трясина промышленных отходов, где работы идут под надзором гоблина-бригадира, отвечающего за них перед компанией.\n\nВышка привлекла соперников не меньше, чем отравила воду. Союз ремонтников в Кабестане, которого директор Ридлвокс торопил сравняться с новыми крошшерами Торговой компании, отказался от попыток превзойти их и решил попросту украсть чертежи. Гоблин Пароклапан отправил Визлкранка захватить одну из машин на болоте и пригнать ее в Кабестан. Визлкранку удалось лишь забраться в крошшер, после чего он обнаружил, что у него нет ключа, чтобы сдвинуть его с места, и сидел в ловушке на вражеской земле, пока не подоспела помощь и машину не увели прямо из-под носа у рабочих компании.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Южный Золотой Путь",
			short = "Южный Золотой Путь получил свое имя от караванов, что по нему ходят.",
			full = "Южный Золотой Путь получил свое имя от караванов, что по нему ходят. Он тянется от Великого Подъемника на южном краю Степей на север, к мосту, соединяющему две половины Степей, где становится просто Золотым Путем.\n\nТорговцы приходят сюда издалека: из Прибамбасска в Танарисе, из Аубердина на Темных берегах, из Ночной Гавани на севере. Все они следуют по одной дороге, влекомые той же торговлей, что дала ей имя.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Река Строптивая",
			short = "Строптивая берет начало высоко на горе Хиджал: она вырывается из горного озера водопадом, с громом обрушивающимся в низины.",
			full = "Строптивая берет начало высоко на горе Хиджал: она вырывается из горного озера водопадом, с громом обрушивающимся в низины. Оттуда река течет широко и стремительно, рассекая землю надвое: она отмечает место, где Ясеневый лес сменяется Азшарой, а южнее — где заканчиваются Степи и начинается Дуротар. В устье река бросается последним каскадом в Великое море, чуть северо-восточнее гоблинского порта Кабестан.\n\nЧерез нее перекинуты три моста: один соединяет Азшару с Ясеневым лесом, другой ведет путников в Оргриммар, третий соединяет Дуротар со Степями. Чуть севернее самого западного из них есть участок воды, который касается сразу всех четырех земель, — единственное место, где сходятся Ясеневый лес, Азшара, Дуротар и Степи.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "Застывший оазис",
			short = "Застывший оазис — клочок неподвижной зеленой воды между Торговым побережьем и Золотым Путем. По его краям стоят лагерем кентавры племени Колкар, и говорят, что их присутствие и сила берутся из самих застоявшихся вод.",
			full = "Застывший оазис — клочок неподвижной зеленой воды между Торговым побережьем и Золотым Путем. По его краям стоят лагерем кентавры племени Колкар, и говорят, что их присутствие и сила берутся из самих застоявшихся вод. Кодо, что бродят здесь, ослаблены и держатся поодиночке, в отличие от огромных стад Полей Великанов на юге, и стать их добычей куда проще. Под поверхностью плавает загадочная рыба, ценимая в приготовленном виде, а рядом с ней в мутной воде таятся хрустогрызы оазиса.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Тернистый холм",
			short = "Тернистый холм стоит на северном склоне горной вершины между Перекрестком и Дуротаром, и его склоны кишат свинобразами из племени Иглогривых.",
			full = "Тернистый холм стоит на северном склоне горной вершины между Перекрестком и Дуротаром, и его склоны кишат свинобразами из племени Иглогривых. С этой высоты они нападают на караваны Орды, проходящие через край, навлекая на себя гнев тех, кто охраняет дороги внизу.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "Лестница Прилива",
			short = "Лестница Прилива поднимается над Торговым побережьем чередой широких каменных террас, сложенных, словно ступени исполинской лестницы, обращенной к воде.",
			full = "Лестница Прилива поднимается над Торговым побережьем чередой широких каменных террас, сложенных, словно ступени исполинской лестницы, обращенной к воде. На этих уступах держатся два таурена, Ислен Заклинатель Воды и Марен Небесная Провидица: они забрасывают удочки в прибой и беседуют с духами, обитающими в воде внизу.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Пещеры Стенаний",
			short = "Пещеры Стенаний получили свое имя от звуков самого этого места: пар вырывается из трещин в скале и разносится во тьме долгими скорбными стонами.",
			full = "Пещеры Стенаний получили свое имя от звуков самого этого места: пар вырывается из трещин в скале и разносится во тьме долгими скорбными стонами.\n\nНашел их ночной эльф-друид Наралекс, и он же дал им предназначение. Под саванной текли подземные воды, выходившие на поверхность в других местах разбросанными по Степям оазисами, и Наралекс верил, что если соединит эти воды с самим Изумрудным Сном, то сможет вернуть его зеленую жизненную силу иссохшей земле наверху. Он повел своих учеников в пещеры и погрузился в медитацию, открыв себя как проводник между Сном и миром яви.\n\nНо вместо этого его поглотил Изумрудный Кошмар. Наралекс не смог проснуться. Через его открытое спящее тело скверна Кошмара хлынула в пещеры, отравив воды, исказив зверей в странных загадочных существ и доведя большинство его учеников до безумия, — те, кто остался, стали Друидами Клыка.\n\nНаралекс спит там и поныне, а Друиды Клыка удерживают пещеры против всякого, кто захочет его разбудить.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Альтеракские горы: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "Даларан",
			short = "Даларан возник как город магов, основанный после Тролльих войн волшебниками Араторской империи, и стал самостоятельным государством.",
			full = "Даларан возник как город магов, основанный после Тролльих войн волшебниками Араторской империи, и стал самостоятельным государством. Его жители не подчинялись никакой короне, кроме Кирин-Тора — избранного круга могущественнейших заклинателей мира, которым правил Совет Шести. В его сердце стояла Аметистовая цитадель, святилище и прибежище для изучающих тайную магию, и ни один город за пределами эльфийских земель Кель'Таласа не хранил в себе столь огромного средоточия магической силы. Даже высшие эльфы-маги Кель'Таласа при всей своей гордости склонялись перед властью Кирин-Тора.\n\nЭта власть была сломлена в огне. Когда Плеть пришла к Даларану, его жители были изгнаны из собственного королевства, а сам Архимонд обратил город в руины, рассеяв уцелевших членов Кирин-Тора по всему Азероту.\n\nУцелевшие не позволили своему городу остаться мертвым. Они вернулись к развалинам и принялись отстраивать его, воздвигнув огромный магический купол, чтобы укрыть его израненное сердце от новых бед.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Овчарня Дандреда",
			short = "Небольшая ферма с усадьбой стоит на западном краю Высокогорья, там, где земля встречается с Мглистым берегом, а гавань выходит на озеро Лордамер.",
			full = "Небольшая ферма с усадьбой стоит на западном краю Высокогорья, там, где земля встречается с Мглистым берегом, а гавань выходит на озеро Лордамер.\n\nЗдесь живет Алиден, а с ним его возлюбленная Элиза. Она носит ожерелье, некогда принадлежавшее Тарете Фокстон.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Лордамерские выселки",
			short = "Лордамерские выселки стоят на холме над Даларанским кратером — единственный лагерь для интернированных, построенный в Альтеракских горах, под охраной сил Даларана.",
			full = "Лордамерские выселки стоят на холме над Даларанским кратером — единственный лагерь для интернированных, построенный в Альтеракских горах, под охраной сил Даларана.\n\nЗдесь по пути в Даларан принц Артас Менетил и леди Джайна Праудмур однажды под покровом ночи проскользнули мимо патрулей и сторожевых башен, чтобы взглянуть на орков, содержавшихся внутри. То, что они увидели, разделило их. Джайна смотрела на орчих и их младенцев, и ее уверенность дрогнула, сменившись сомнением и раскаянием. Артас не почувствовал ничего подобного и считал, что лагеря необходимы, несмотря ни на что. Их никто не заметил. Они ушли тем же путем, каким пришли, и разногласие между ними ушло вместе с ними.\n\nТеперь гарнизоном командует смотритель Беламур, изучающая артефакты из кровавого камня, которые принесли ей Кеган Мракмар и его товарищи.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "Руины Альтерака",
			short = "Разрушенные стены взбираются по склонам Альтеракских гор там, где когда-то стоял город: его дворец наполовину уцелел, церковь и ратуша обрушились внутрь себя, а ворота построены на манер ворот самого Штормграда.",
			full = "Разрушенные стены взбираются по склонам Альтеракских гор там, где когда-то стоял город: его дворец наполовину уцелел, церковь и ратуша обрушились внутрь себя, а ворота построены на манер ворот самого Штормграда.\n\nЕго погубил собственный король. Во время Второй войны король Эйден Перенольд стал предателем, связав свою судьбу с Ордой орков против собратьев-людей. Альтеракских солдат видели сражающимися бок о бок с орками, а в лагере для пленных близ города держали захваченных жителей Даларана. Когда правда вышла наружу, другие человеческие королевства в отместку двинулись на Альтерак. Люди бежали или были изгнаны из своих домов, а король Лордерона Теренас Менетил II объявил в городе военное положение, низложил Перенольда и заковал его в цепи.\n\nГород так и не поднялся вновь. На опустевших улицах и во дворце обосновались огры Раздробленного Хребта во главе с Муг'Толом, а разрозненные остатки старого альтеракского народа удерживали окрестные деревни. У северного вала и ворот до сих пор лежат разбитые телеги с мясом, а кладбища внутри стен и за ними, занесенная снегом ферма и разбитые баллисты среди развалин остаются такими, какими их оставили.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Высокогорье",
			short = "Когда-то Высокогорье кормило целое королевство. Его холмы были житницей Альтерака, полями и пастбищами старого государства.",
			full = "Когда-то Высокогорье кормило целое королевство. Его холмы были житницей Альтерака, полями и пастбищами старого государства.\n\nЭто государство рухнуло. Высокогорье не перешло ни к какой короне, а досталось Синдикату, который нигде в горах не держится так прочно, как здесь. Среди их лагерей здесь командует барон Вардус — владыка остатков земли павшего королевства.\n\nНа самом западе стоит Овчарня Дандреда — имя, пережившее то, что оно некогда значило.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Нагорье Арати: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Крепость Тяжелого Кулака",
			short = "Крепость Тяжелого Кулака стоит на юге Нагорья Арати, близ Моста Тандола и Деревни Сухокожих, — каменный курган, укрепленный руками огров.",
			full = "Крепость Тяжелого Кулака стоит на юге Нагорья Арати, близ Моста Тандола и Деревни Сухокожих, — каменный курган, укрепленный руками огров. В большой пещере в ее сердце правит Коргреш Ледяная Ярость, вождь клана Тяжелого Кулака.\n\nС тех пор огры расползлись по окрестным холмам, еще сильнее укрепив свою оборону.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Камен'гор",
			short = "К северу от Крепости Стромгард поднимается холм Камен'гор, изломанный и неровный. Здесь стоит курган огров клана Тяжелого Кулака, а рядом с ними на склонах обретаются лесные тролли племени Сухокожих.",
			full = "К северу от Крепости Стромгард поднимается холм Камен'гор, изломанный и неровный. Здесь стоит курган огров клана Тяжелого Кулака, а рядом с ними на склонах обретаются лесные тролли племени Сухокожих. На восточном склоне находится Круг Стихий, а чуть южнее холма лежат две фермы.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Восточный круг Обуздания",
			short = "Камень Восточного Обуздания стоит на страже восточных земель Нагорья Арати, близ Павшего Молота, отмечая один из Кругов Обуздания, разбросанных по краю.",
			full = "Камень Восточного Обуздания стоит на страже восточных земель Нагорья Арати, близ Павшего Молота, отмечая один из Кругов Обуздания, разбросанных по краю. Камень до сих пор охраняют элементали воды, привязанные к этому месту, словно исполняя какое-то старое, так и не завершенное поручение.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Внутренний Круг Обуздания",
			short = "Внутренний Круг Обуздания находится на юге Нагорья Арати близ Крепости Стромгард, и его охраняют элементали земли. Здесь покоится Внутренний связывающий камень, сильнейший из камней.",
			full = "Внутренний Круг Обуздания находится на юге Нагорья Арати близ Крепости Стромгард, и его охраняют элементали земли. Здесь покоится Внутренний связывающий камень, сильнейший из камней.\n\nЧерез его осколок Мизраэль нашла способ говорить со смертными.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Внешний Круг Обуздания",
			short = "Внешний Круг Обуздания лежит неподалеку от Опорного пункта в Нагорье Арати. В его центре стоит Внешний связывающий камень, неизменно охраняемый элементалями воздуха.",
			full = "Внешний Круг Обуздания лежит неподалеку от Опорного пункта в Нагорье Арати. В его центре стоит Внешний связывающий камень, неизменно охраняемый элементалями воздуха.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Западный Круг Обуздания",
			short = "Западный Круг Обуздания находится на западе Нагорья Арати, близ Стены Торадина. Там покоится Западный связывающий камень, который охраняют элементали огня, ни на миг не оставляющие его без присмотра.",
			full = "Западный Круг Обуздания находится на западе Нагорья Арати, близ Стены Торадина. Там покоится Западный связывающий камень, который охраняют элементали огня, ни на миг не оставляющие его без присмотра.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Усадьба Дабири",
			short = "На севере Нагорья Арати стоит Усадьба Дабири, которой владеют Кената Дабири и ее дети Фардел и Марсель — жители Стромгарда, верные Альянсу.",
			full = "На севере Нагорья Арати стоит Усадьба Дабири, которой владеют Кената Дабири и ее дети Фардел и Марсель — жители Стромгарда, верные Альянсу. За полями присматривает ополчение, ведь у семьи есть враги.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Подводный риф",
			short = "Под заливом у южного берега Нагорья Арати лежит затонувший эльфийский город, древний и разрушенный. Он уже не пуст: его заняли наги из клана Пронзающего Гребня, которыми правит принц Назжак.",
			full = "Под заливом у южного берега Нагорья Арати лежит затонувший эльфийский город, древний и разрушенный. Он уже не пуст: его заняли наги из клана Пронзающего Гребня, которыми правит принц Назжак.\n\nРиф над ним погубил немало кораблей, среди них «Девичью Блажь» и «Дух Серебряного бора». Говорят, наги Пронзающего Гребня способны поворачивать сами приливы залива, заманивая на камни команды, которые думают, что нашли безопасную гавань в Бухте Фальдира.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Теснина Сухоусов",
			short = "Теснина Сухоусов прорезает горы на востоке Нагорья Арати, к северо-востоку от Павшего Молота. В ее конце находится пещера, где живут кобольды-сухоусы, союзники великанов, с которыми они делят это нагорье.",
			full = "Теснина Сухоусов прорезает горы на востоке Нагорья Арати, к северо-востоку от Павшего Молота. В ее конце находится пещера, где живут кобольды-сухоусы, союзники великанов, с которыми они делят это нагорье.\n\nГлубоко внутри, за норами, лежит каменный осколок, в котором заключена частица сущности принцессы Мизраэли. Кобольды яростно охраняют его, как и частицы, собранные в глубинах пещеры, хотя никто из них, похоже, не знает, что на самом деле хранит осколок.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Бухта Фальдира",
			short = "Бухта Фальдира названа в честь Фальдира, который, как говорят, отметил это место, когда отправлялся в путь со своими последователями.",
			full = "Бухта Фальдира названа в честь Фальдира, который, как говорят, отметил это место, когда отправлялся в путь со своими последователями.\n\nМного позже сюда пришли Разбойники Черноводья в поисках эльфийского сокровища, которое, по слухам, лежало в здешних водах. Капитаны Стальные Нервы и О'Брин привели в бухту три корабля, но против них поднялся странный прилив, вызванный нагами, охранявшими затонувшие руины под рифом, и два корабля из трех пошли ко дну. Лишь «Вестник» достиг берега, и его команда оказалась заперта в заливе, не в силах уйти, пока нагов не прогонят и не достанут судовые журналы с обломков внизу.\n\nПозднее два гнома-инженера, доктор Драксельмер и профессор Физзлторп, построили устройство для поиска эльфийских самоцветов, которые, по слухам, окаменели в камнях Затонувшего рифа.\n\nБухта до сих пор несет шрамы той затопленной истории: риф, обломки и руины — все рассказывает о кораблях, которым не следовало тонуть, и о сокровище, которое море так и не отдало.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Ферма Го'Шека",
			short = "Ферма Го'Шека лежит на востоке Нагорья Арати, близ Деревни Сухокожих.",
			full = "Ферма Го'Шека лежит на востоке Нагорья Арати, близ Деревни Сухокожих. После Третьей войны Отрекшиеся и орки из Павшего Молота заняли ферму для своих целей: орки брали с нее припасы, а Отрекшиеся превратили ее поля и постройки в испытательную площадку для алхимии более темного толка.\n\nРазобраться в происходящем здесь пришли агенты Альянса Кви и Кинелори. С чужой помощью они убили гонца Отрекшихся, направлявшегося в Мельницу Таррен, прежде чем тот успел доставить послание, и обыскали саму ферму, где нашли записи некоего аптекаря Йореля. Его исследования указывали на то, что зреет нечто новое и ужасное: еще одна чума.\n\nТеперь фермой владеют бугаи Павшего Молота.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Павший Молот",
			short = "Земля Павшего Молота помнит, чем была когда-то. После Второй войны Альянс Лордерона построил здесь один из крупнейших лагерей для интернированных, заперев за его стенами пленных орков.",
			full = "Земля Павшего Молота помнит, чем была когда-то. После Второй войны Альянс Лордерона построил здесь один из крупнейших лагерей для интернированных, заперев за его стенами пленных орков. Тюрьмой он оставался недолго. Вождь Тралл и Оргрим Молот Рока повели Орду на лагерь, чтобы освободить свой народ, и в хаосе этого освобождения, когда Тралл прикрывал отход, скачущий рыцарь вонзил копье в спину Оргрима с такой силой, что пробил его доспехи насквозь. Молот Рока погиб там, на земле, которую пришел освободить.\n\nПосле Третьей войны Орда вернулась к руинам и возвела среди них передовую базу, назвав ее Павшим Молотом в честь вождя, павшего при ее взятии. Она стала больше, чем аванпостом, — убежищем для тех, кто чувствовал, что им не осталось места в мире; ее хижины духов, стойла, кузница и большой зал стоят там, где когда-то высились стены лагеря.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Северное поместье",
			short = "После падения Стромгарда Северное поместье перешло в руки Синдиката, который устроил в нем аванпост в Нагорье Арати.",
			full = "После падения Стромгарда Северное поместье перешло в руки Синдиката, который устроил в нем аванпост в Нагорье Арати.\n\nСюда пришел тролль-шаман Тор'ган, привлеченный чем-то неправильным в воздухе. Проследив это до поместья, он обнаружил, что здесь все еще держатся остаточные следы демонического призыва, и, когда он подошел ближе, его собственная кровь закипела яростью, которая принадлежала не только ему. На земле он нашел амулет из кровавого камня, которым призывают демонов, хотя этот уже растратил свою силу. Подозревая, что дела Синдиката зашли дальше простого разбоя, он принялся искать другие такие амулеты, чтобы узнать правду об их намерениях.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Опорный пункт",
			short = "Когда во время Третьей войны столица Стромгарда обратилась в руины, большая часть ее жителей бежала на юг, в Нагорье Арати. Но остатки армии Стромгарда не пошли с ними.",
			full = "Когда во время Третьей войны столица Стромгарда обратилась в руины, большая часть ее жителей бежала на юг, в Нагорье Арати. Но остатки армии Стромгарда не пошли с ними. Они остались, полные решимости вернуть утраченное, и именно здесь, в Опорном пункте, они заняли оборону.\n\nАванпост стал средоточием войны Альянса в Нагорье: его солдаты стремились отбить Крепость Стромгард и добыть для дела Альянса все ресурсы, какие удастся. Такая целеустремленность почти ни для чего другого не оставляла места. Когда Мост Тандола принял тяжелый удар от дворфов Черного Железа, и его дворфы прислали весть с просьбой о помощи, чтобы отвоевать Дун Модр и сам мост, капитан Ниалс не смогла выделить ни души. Стромгард пал, сказала она, и пока он не будет отвоеван, каждый меч и каждая пара рук в Опорном пункте принадлежат лишь этому делу. Честь и долг привязывают их к Нагорью, сказала она гонцу, и Длиннокосу Мрачному придется обойтись без них.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Крепость Стромгард",
			short = "Когда-то Стромгард был Стромом, колыбелью первого королевства людей и столицей Араторской империи.",
			full = "Когда-то Стромгард был Стромом, колыбелью первого королевства людей и столицей Араторской империи. Когда Орда орков пришла в Восточные королевства, он все еще оставался одной из сил Альянса Лордерона, и его имя не склонилось даже после Второй войны.\n\nПосле Третьей войны город был разграблен и оставлен в руинах. Теперь он расколот на три части: внутреннюю крепость удерживает Синдикат, разрушенный квартал магов захватили огры клана Тяжелого Кулака при поддержке троллей из племени Сухокожих, а последний квартал все еще держат войска Стромгарда, откуда принц Гален Троллебой руководит тем, что осталось от его народа.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Мост Тандола",
			short = "Две огромные каменные арки перекинуты через пропасть между Болотиной и Нагорьем Арати; их возвели руки дворфов, и три поколения их охранял род Старой Наковальни.",
			full = "Две огромные каменные арки перекинуты через пропасть между Болотиной и Нагорьем Арати; их возвели руки дворфов, и три поколения их охранял род Старой Наковальни. Их построили после Войны Трех Кланов, когда Стальгорн стремился сохранить верность своим сородичам из клана Громового Молота в Заоблачном Пике, и мосты стали одновременно дорогой и символом, связывающим два дворфийских королевства, по которой шла торговля, обогащавшая обоих.\n\nМосты способны были выдержать вес целых армий и когда-то служили главным торговым путем между дворфами и людьми. Именно здесь Андуин Лотар вытеснил последних воинов Старой Орды из Лордерона обратно в Каз Модан, заставив их, разбитых, отступить через мост.\n\nТеперь мост изранен. Заговор Черного Железа, задуманный Камом Темная Ярость и Балгарасом Гнусным, нанес мостам тяжелый урон, и силы дворфов сражаются, чтобы удержать то, что осталось, и отбить близлежащий городок Дун Модр. В боях погибло много дворфов, среди них Салли Баллу, Эбенезер Ржавый Засов и брат Длиннокоса Мрачного.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Стена Торадина",
			short = "Король Торадин возвел эту стену, чтобы сдерживать троллей Амани, в те дни, когда Стром был молод, а Аратор только-только отвоевал эту землю для человечества.",
			full = "Король Торадин возвел эту стену, чтобы сдерживать троллей Амани, в те дни, когда Стром был молод, а Аратор только-только отвоевал эту землю для человечества. Поколениями она стояла как надежный страж — рубеж, призванный защищать людей от набегов троллей.\n\nСпустя столетия стена все еще стоит, но сильно разрушена: ее камни разбиты, а ее долгий дозор обратился в руины.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Башня Аратора",
			short = "Башня Аратора стоит в квартале магов Крепости Стромгард и названа в честь древней империи Аратор, от которой ведет свой род королевство.",
			full = "Башня Аратора стоит в квартале магов Крепости Стромгард и названа в честь древней империи Аратор, от которой ведет свой род королевство.\n\nКогда-то в ее стенах занимался своими изысканиями верховный маг Трелан, и там он создал защиту, вплетенную в саму башню и дремлющую, пока ее не пробудит зачарованный самоцвет. Когда Синдикат и огры клана Тяжелого Кулака подступили к Стромгарду, Трелан попытался удержать башню с помощью своего творения, но этого оказалось мало. Он бежал из города, и башня пала вместе с ним. Огры клана Тяжелого Кулака забрали квартал себе, а в ее залах поселился огр-маг Руул Одинокий Камень.\n\nТрелан никогда не переставал думать о том, что оставил там, — о своем талисмане, своей сфере и угольном агате, обработанном его собственной рукой. Он обратился к своему бывшему ученику, верховному магу Малину, чтобы тот вернул их у огров, теперь владевших башней. Вскоре Малину донесли, что вещи старого мастера нашлись — они были спрятаны в сундуках в залах, которые он когда-то называл своими.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Деревня Сухокожих",
			short = "Деревня Сухокожих раскинулась вокруг небольшого озера на юго-востоке Нагорья Арати, и в ней живут тролли племени Сухокожих. За деревней находится большая пещера, где чаще всего можно найти вождей племени.",
			full = "Деревня Сухокожих раскинулась вокруг небольшого озера на юго-востоке Нагорья Арати, и в ней живут тролли племени Сухокожих. За деревней находится большая пещера, где чаще всего можно найти вождей племени.\n\nСухокожие объединились с ограми клана Тяжелого Кулака по соседству, и этот союз направлен против Стромгарда и Павшего Молота. Вместе тролли и огры удерживают часть самого Стромгарда, вырванную у его прежних хозяев.\n\nЭта сила сделала Сухокожих меченым народом, на который охотятся и Альянс, и Орда, желая с ними покончить. Среди тех, кто встал против этой расплаты, самым опасным называли Нимара Душегуба — бойца, который и в смерти забрал с собой многих своих врагов.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
