		["camp kosh"] = {
			name = "Лагерь Кош",
			short = "Лагерь Кош стоит на северной границе владений Гнилобрюхих и следит за пустынными дорогами, что вьются к Каргату и спускаются в Тлеющее ущелье.",
			full = "Лагерь Кош стоит на северной границе владений Гнилобрюхих и следит за пустынными дорогами, что вьются к Каргату и спускаются в Тлеющее ущелье. Караваны, пересекающие Бесплодные земли, боятся этого участка пути, ведь огры Коша нападают на них ради всего, что те везут.",
