			full = "Лагерь Вург — одно из пристанищ огров клана Гнилобрюхих, сородичей огров из лагерей Кэгг, Бофф и Кош.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Грот Гнилобрюхих",
			short = "На юго-западе Бесплодных земель поднимается огромный курган из земли и камня, выдолбленный изнутри и занятый ограми клана Гнилобрюхих.",
			full = "На юго-западе Бесплодных земель поднимается огромный курган из земли и камня, выдолбленный изнутри и занятый ограми клана Гнилобрюхих. Грот Гнилобрюхих — их дом, лабиринт туннелей и залов, где клан устроил свое логово среди растрескавшейся, выжженной солнцем земли вокруг.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Знойные Пески",
			short = "Знойные Пески лежат между Каргатом и Долиной Клыков — полоса растрескавшейся, засушливой земли на северо-западе Бесплодных земель. По ним рыщут койоты и канюки, а среди камней шевелятся каменные элементали.",
			full = "Знойные Пески лежат между Каргатом и Долиной Клыков — полоса растрескавшейся, засушливой земли на северо-западе Бесплодных земель. По ним рыщут койоты и канюки, а среди камней шевелятся каменные элементали. Здесь почти ничего не растет, кроме кактусов и нескольких упрямых деревьев. Посреди этой пустоши стоит Лагерь Вург.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
