			full = "Ветра выскабливают Лощину Суховея, пока в ней не остается ничего мягкого — лишь камень да сухие кости оврага. Она лежит к западу от Долины Летлор — полоса голой земли в Бесплодных землях, где пыль никогда не оседает надолго.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Карьер Тяжелоступа",
			short = "Карьер Тяжелоступа находится на севере Бесплодных земель, и в его раскопочных траншеях теперь не слышно шахтеров, что когда-то в них трудились.",
			full = "Карьер Тяжелоступа находится на севере Бесплодных земель, и в его раскопочных траншеях теперь не слышно шахтеров, что когда-то в них трудились. Сам Тяжелоступ покинул раскопки, и на его место пришла шайка дворфов Черного Железа — вероятно, те же силы, что проникли в Ульдаман.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Каргат",
			short = "Каргат стоит в одиночестве посреди Каз Модана — единственный аванпост Орды в этих землях, названный в честь Каргата Острорука, вождя клана Изувеченной Длани.",
			full = "Каргат стоит в одиночестве посреди Каз Модана — единственный аванпост Орды в этих землях, названный в честь Каргата Острорука, вождя клана Изувеченной Длани.\n\nПо приказу самого вождя Тралла каргатский экспедиционный отряд снова и снова выступает в суровые Бесплодные земли. Его истинная цель — проложить путь через Тлеющее ущелье к Черной горе, чтобы Орда могла нанести удар по Ренду Черноруку, вождю Черной Орды, в его собственной твердыне. Этот путь лежит через земли, которые дворфы Черного Железа считают своими, и потому Орда вновь оказалась в войне с ними — не по замыслу, а просто потому, что ей нужно было пересечь эту землю.\n\nДругая ценность Каргата видна проще: это стержень между севером и югом, точка, где дорога от Павшего Молота и Подгорода встречается с дорогой, ведущей вниз, к Гром'голу, Пиратской бухте и Каменору.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Долина Летлор",
			short = "Долина Летлор широко и неровно прорезает восток Бесплодных земель, а по ее дну рыщут дракончики и драконы черной стаи.",
			full = "Долина Летлор широко и неровно прорезает восток Бесплодных земель, а по ее дну рыщут дракончики и драконы черной стаи. По всему ущелью стоят хрустальные обелиски, странные и явно поставленные намеренно среди камня и драконьего пламени.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Терраса Творца",
			short = "У входа в Ульдаман земля снята широкими, продуманными срезами — шрам раскопок, оставленный открытым небу.",
			full = "У входа в Ульдаман земля снята широкими, продуманными срезами — шрам раскопок, оставленный открытым небу. Теперь Террасу удерживают дворфы Черного Железа, наблюдая за раскопками и за дорогой, что ведет вниз, в погребенные глубины.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Маревые равнины",
			short = "Маревые равнины лежат к востоку от Грота Гнилобрюхих в Бесплодных землях. От них осталась лишь полоса ничейной земли, на которую претендуют только гигантские канюки, патриархи горных охотников и бешеные скальные койоты.",
			full = "Маревые равнины лежат к востоку от Грота Гнилобрюхих в Бесплодных землях. От них осталась лишь полоса ничейной земли, на которую претендуют только гигантские канюки, патриархи горных охотников и бешеные скальные койоты.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Ульдаман",
			short = "Глубоко в горах Каз Модана лежит Ульдаман — огромное древнее хранилище, воздвигнутое хранителями-титанами в давно минувшие эпохи.",
			full = "Глубоко в горах Каз Модана лежит Ульдаман — огромное древнее хранилище, воздвигнутое хранителями-титанами в давно минувшие эпохи. Дворфы из Стальгорна когда-то проникли в него и разрабатывали его погребенные залы еще до Третьей войны, но с тех пор хранилище перешло к троггам и дворфам Черного Железа, которые теперь роются в его камне в поисках земных богатств, что в нем еще остались.\n\nУльдаман по-прежнему богат наследием той эпохи, созданной титанами, и те, кто осмелится спуститься в его глубины, все еще находят погребенные в нем артефакты, которые понемногу извлекают на свет археологи и искатели приключений из Лиги Исследователей, продолжающие разбирать руины.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Долина Клыков",
			short = "Долина Клыков узкой полосой пролегает между двумя каменными стенами в Бесплодных землях; ее заняли волки и пумы, чьи клыки и дали этому месту имя.",
			full = "Долина Клыков узкой полосой пролегает между двумя каменными стенами в Бесплодных землях; ее заняли волки и пумы, чьи клыки и дали этому месту имя.\n\nЗдесь стоит лагерем Мартек Изгой, изгнанный оттуда, где когда-то был своим, а вместе с ним Ригглфазз и Джаззрик.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
