	-- Выжженные земли: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "Темный портал",
			short = "Создание портала было предательством с самого первого удара. Гул'дан и человеческий маг Медив, одержимый Темным титаном Саргерасом, вместе прорвали эту брешь.",
			full = "Создание портала было предательством с самого первого удара. Гул'дан и человеческий маг Медив, одержимый Темным титаном Саргерасом, вместе прорвали эту брешь. На Дреноре орков-каменщиков, построивших его каменную раму, убили чернокнижники, чтобы подготовить последнюю печать, а почти всех пленных дренеев, что еще оставались у Орды, привели к его подножию и в одно мгновение высосали из них жизнь, чтобы дать Гул'дану силу соединить два мира. Через эти врата Орда хлынула в Штормград и начала Первую войну, а в последовавшей войне портал бесконечно выпускал в Азерот орков и огров, и болота вокруг него свернулись в кроваво-красную пустошь, позже названную Выжженными землями.\n\nВ конце войны верховный маг Кадгар и его собратья-маги разрушили сооружение со стороны Азерота, чтобы отрезать Орде путь к отступлению, и взрыв был столь силен, что уничтожил и раму на Дреноре. Затем Кадгар возвел Крепость Стражей Пустоты, чтобы та стерегла руины, хотя разрыв между мирами так и не был по-настоящему закрыт, и в последующие годы через него снова приходили демоны.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Форт Молота Ужаса",
			short = "Форт Молота Ужаса — курган, возведенный ограми клана Молота Ужаса, которые пришли в Азерот с Дренора и так и не ушли далеко от Темного портала.",
			full = "Форт Молота Ужаса — курган, возведенный ограми клана Молота Ужаса, которые пришли в Азерот с Дренора и так и не ушли далеко от Темного портала. Они до сих пор удерживают эту землю.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Мастерские Гарнизона",
			short = "В израненной земле Выжженных земель шахтеры Альянса трудятся в Мастерских Гарнизона, вырывая у земли минералы для Крепости Стражей Пустоты.",
			full = "В израненной земле Выжженных земель шахтеры Альянса трудятся в Мастерских Гарнизона, вырывая у земли минералы для Крепости Стражей Пустоты. Все добытое отправляют дальше, в Штормград, а взамен крепость получает прочие припасы, необходимые, чтобы выстоять в этом проклятом месте.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Крепость Стражей Пустоты",
			short = "Крепость Стражей Пустоты стоит на высоком утесе над единственной дорогой в Выжженные земли, и ее стены возведены, чтобы следить за раной в мире, которую никто не хотел бы увидеть открытой вновь.",
			full = "Крепость Стражей Пустоты стоит на высоком утесе над единственной дорогой в Выжженные земли, и ее стены возведены, чтобы следить за раной в мире, которую никто не хотел бы увидеть открытой вновь.\n\nВерховный маг Кадгар призвал построить ее в годы после Второй войны, когда первый Темный портал лежал разрушенным, а родина орков за ним увяла и превратилась в руины. Строительство оплатил Альянс Лордерона — одни королевства охотнее, чем другие, — а возвела ее Гильдия каменщиков под руководством Эдвина ван Клифа. Затем в ней разместился Кирин-Тор, трудясь над тем, чтобы сдержать скверну, что сочилась из раны портала и грозила расползтись по окрестным землям.\n\nКадгар оставался ее хозяином, пока кланы Нер'зула не восстановили Темный портал со стороны Дренора и не осадили крепость. Кадгар и его соратники — Туралион, Данат Троллебой, Аллерия Ветрокрылая и Курдран Громовой Молот — повели Альянс через портал, чтобы сокрушить Орду там, а затем остались по другую сторону, чтобы запечатать его и не дать гибели Дренора последовать за ними домой. Двадцать лет после этого портал молчал.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Утес Осквернителя",
			short = "Утес Осквернителя вздымается посреди Выжженных земель — изрезанная гряда разрушенных гор. Здесь обитает великий демон Разелих, и одного его присутствия достаточно, чтобы дать месту имя.",
			full = "Утес Осквернителя вздымается посреди Выжженных земель — изрезанная гряда разрушенных гор. Здесь обитает великий демон Разелих, и одного его присутствия достаточно, чтобы дать месту имя.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Змеиные Кольца",
			short = "Змеиные Кольца — извилистая система пещер на востоке Выжженных земель, вход в которую отмечен сгоревшими оркскими постройками, оставшимися со времен Второй войны.",
			full = "Змеиные Кольца — извилистая система пещер на востоке Выжженных земель, вход в которую отмечен сгоревшими оркскими постройками, оставшимися со времен Второй войны. Спустя долгое время после окончания той войны пещеры стали логовом для чего-то более темного: культистов, отдавшихся поклонению Кириту Проклятому.\n\nВ этот лабиринт пришел верховный маг Аллистарий и изнутри него направил в дело своих Приверженцев Тени. Неподалеку от входа в сундуке хранится амулет с его именем.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "Гниющий шрам",
			short = "Гниющий Шрам некогда был частью Черных топей, пока скверна Темного портала не просочилась в него, оставив землю сухой, безлесной и красной, как кровь.",
			full = "Гниющий Шрам некогда был частью Черных топей, пока скверна Темного портала не просочилась в него, оставив землю сухой, безлесной и красной, как кровь. Воды здесь больше нет. Демонические звери рыщут по почве, которая уже не помнит, что на ней когда-то росло.\n\nПосле битвы у горы Хиджал владыка эред'рунов Каззак отвел в Шрам то, что осталось от сил Пылающего Легиона на Азероте, и сделал его своей землей. Он поставил над ним своего наместника Разелиха Осквернителя, поручив ему крепко удерживать этот край. Сам Каззак и после этого остался там, и одного его присутствия достаточно, чтобы Шрам по-прежнему считался владениями Легиона — годы спустя после того, как битва за Хиджал была проведена и выиграна в другом месте.\n\nМного позже в Шрам пришел старый человек-чернокнижник, Дайо Дряхлый, и поселился у его алтаря. Там, среди демонов, которых эта земля и так порождала, он без помех совершал свои ритуалы и брал к себе молодых учеников, обучая их инфернальному искусству в месте, уже отданном Скверне.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Тирисфальские леса: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Семейная усыпальница Агамондов",
			short = "К северу от Мельниц Агамондов в этой усыпальнице когда-то покоились мертвые рода Агамондов. Капитан Даргол, прислужник Плети, забрал это место себе и пробудил каждый труп и каждого духа в нем.",
			full = "К северу от Мельниц Агамондов в этой усыпальнице когда-то покоились мертвые рода Агамондов. Капитан Даргол, прислужник Плети, забрал это место себе и пробудил каждый труп и каждого духа в нем. Теперь в темных переходах висит густая пыль, и мстительные мертвецы нападают на всякого, кто войдет без спроса.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Мельницы Агамондов",
			short = "Мельницы Агамондов когда-то вращались для одной из богатейших семей Тирисфаля. Когда Плеть пришла на север, Грегор Агамонд отказался бежать.",
			full = "Мельницы Агамондов когда-то вращались для одной из богатейших семей Тирисфаля. Когда Плеть пришла на север, Грегор Агамонд отказался бежать. Он укрепил мельницы, запас их на случай осады и убедил работников семьи остаться и сражаться бок о бок с ними.\n\nОни должны были выстоять. Не выстояли, потому что предательство пришло изнутри стен. Девлин, младший сын Агамондов, обратился против собственной крови и помог Плети, и гарнизон не сумел сдержать последовавших атак. Со временем чума все равно забрала остальных членов семьи, и Агамонды, погибшие, защищая свой дом, восстали в нем вновь бездумными мертвецами.\n\nМельницы до сих пор стоят на возвышенностях северного Тирисфаля, а семья, что их построила, теперь служит тому самому воинству, что ее сломило.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Ферма Балнира",
			short = "Ферма Балнира лежит к северо-востоку от разрушенной столицы: ее изгороди сломаны, а конюшни пусты, если не считать бродящей Плети.",
			full = "Ферма Балнира лежит к северо-востоку от разрушенной столицы: ее изгороди сломаны, а конюшни пусты, если не считать бродящей Плети.\n\nКогда-то этой землей владела семья Балнир, разводившая огромных белых лошадей, на которых ездил королевский дом Лордерона. В день падения Столицы Плеть пришла на ферму и перебила всю семью, оставив после себя лишь землю, где бродят призраки.\n\nЛьвиный зев, за которым некогда ухаживали в саду фермы, до сих пор растет там диким, и до живых дошли вести, что в него, возможно, проникла порча Чумных земель. Воины Плети, проскользнувшие мимо Бастиона, толпами собираются вокруг разрушенной фермы.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Озеро Ясноводное",
			short = "Озеро Ясноводное лежит к северо-востоку от Брилла, и посреди его вод находится большой остров, на котором ныне стоит Приют Гюнтера.",
			full = "Озеро Ясноводное лежит к северо-востоку от Брилла, и посреди его вод находится большой остров, на котором ныне стоит Приют Гюнтера.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Брилл",
			short = "Когда-то Брилл был обычным городком в королевстве Лордерон, которым владела семья Баровых, а Агамонды держали в его пределах собственную усадьбу.",
			full = "Когда-то Брилл был обычным городком в королевстве Лордерон, которым владела семья Баровых, а Агамонды держали в его пределах собственную усадьбу. Его обыденность закончилась в тот день, когда туда пришел Кел'Тузад. Тогда еще живой человек, некромант избрал Брилл местом для первого испытания чумы нежити, и заражение оказалось столь полным, что придало ему смелости убедить Короля-лича начать вторжение в Лордерон раньше времени. Мертвых в Тирисфальских лесах оказалось больше, чем земля могла достойно похоронить; огромное кладбище за стенами Брилла стало ответом на этот избыток. Собственные защитники города не смогли его удержать, и немногие выжившие бежали, чтобы присоединиться к принцу Артасу Менетилу, когда тот выслеживал источник порчи, охватившей север.\n\nБрилл не остался безмолвным. Годы спустя его заняли Отрекшиеся, и теперь мировой судья Севрен правит тем, что когда-то забрала чума. Здесь живут и старые обиды: Колман Фартинг, некогда служивший семье Агамондов, до сих пор разыскивает их останки — кости, отданные не из милосердия, а из мести за смерть, в которой он винит их.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Ратуша Брилла",
			short = "Ратуша — самое заметное здание Брилла. С ее трибуны мировой судья Севрен говорит от имени города, распределяя задачи между мертвыми Тирисфаля.",
			full = "Ратуша — самое заметное здание Брилла. С ее трибуны мировой судья Севрен говорит от имени города, распределяя задачи между мертвыми Тирисфаля. Мало где подобные залы находятся в руках Отрекшихся так, как этот, — знак того, насколько прочно Брилл принадлежит им.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "Бастион",
			short = "Бастион стоит там, где Тирисфальские леса встречаются с Западными Чумными землями, — рубеж, который Отрекшиеся удерживают против Плети, все еще собирающейся на востоке.",
			full = "Бастион стоит там, где Тирисфальские леса встречаются с Западными Чумными землями, — рубеж, который Отрекшиеся удерживают против Плети, все еще собирающейся на востоке. Здесь защитники-Отрекшиеся и Серебряный Рассвет отложили свои разногласия перед лицом общего врага: они вместе стерегут границу и посылают бойцов на восток, чтобы разить прислужников Короля-лича.\n\nВ отличие от остального Тирисфаля, этот край вовсе не похож на леса: над ним висит чумной туман, окрашивая небо в тот же болезненный желтовато-серый цвет, что и над Западными Чумными землями дальше.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Поместье \"Остывший Очаг\"",
			short = "Когда-то поместье «Остывший Очаг» славилось теплом своего очага и богатством полей. Чума нежити положила этому конец.",
			full = "Когда-то поместье «Остывший Очаг» славилось теплом своего очага и богатством полей. Чума нежити положила этому конец. Все, кто жил или трудился здесь, погибли от болезни, щедрая земля стала бесплодной, а её борозды заполонили безмозглые мертвецы Плети, которые бродят там до сих пор.\n\nОтрекшиеся заняли усадьбу и ведут дела с путниками на соседней дороге.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Застава Алого Ордена",
			short = "На восточных холмах Тирисфальских лесов возвышается дозорная башня, которую удерживает Алый орден.",
			full = "На восточных холмах Тирисфальских лесов возвышается дозорная башня, которую удерживает Алый орден. С её высоты крестоносцы следят за дорогой, что уходит через леса на юг, готовые ударить во фланг любому войску, которое осмелится двинуться на Монастырь Алого ордена. Здесь командует капитан Вакон.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Могильник",
			short = "Могильник лежит в узкой, хорошо охраняемой долине, и именно здесь только что восставшие Отрекшиеся впервые открывают глаза и видят мир, доставшийся им.",
			full = "Могильник лежит в узкой, хорошо охраняемой долине, и именно здесь только что восставшие Отрекшиеся впервые открывают глаза и видят мир, доставшийся им.\n\nВ отличие от других владений мятежной нежити Королевы-банши, сохранивших имена, которые они носили, когда были городами живых, Могильник получил совершенно новое название, отвечающее тому, что происходит здесь теперь, а не тому, что стояло здесь прежде. Почему так вышло, никто уже не помнит.\n\nВыживание здесь — ежедневная борьба, а золото — самая большая редкость. К северо-западу от деревни лежит рудник, богатый металлом, но его заполонили пауки, и мертвецы Могильника снова и снова выходят туда, чтобы очистить его и наконец добраться до руды. По краям долины несут дозор элитные стражи смерти — единственная преграда между хрупкими новыми мертвецами и Плетью с Алым орденом, которые готовы уничтожить их во второй раз.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Могила Фаола",
			short = "К юго-западу от Монастыря Алого ордена, на востоке Тирисфальских лесов, лежит клочок земли, за которым когда-то ухаживали скорбящие: Могила Фаола, место упокоения архиепископа Алонсуса Фаола.",
			full = "К юго-западу от Монастыря Алого ордена, на востоке Тирисфальских лесов, лежит клочок земли, за которым когда-то ухаживали скорбящие: Могила Фаола, место упокоения архиепископа Алонсуса Фаола.\n\nПри жизни Фаола почитали, и его смерть, случившаяся незадолго до прихода Плети, привлекла на эту землю множество скорбящих.\n\nТеперь его могилу никто не навещает. Те, кто приходил сюда прежде, давно исчезли, и заброшенный участок почти забыт.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Таверна \"Петля висельника\"",
			short = "Таверна «Петля висельника» стоит в Брилле, и её название — мрачный отголосок города, которому она служит.",
			full = "Таверна «Петля висельника» стоит в Брилле, и её название — мрачный отголосок города, которому она служит. В погребах под её полом нет бочек, о которых стоило бы упоминать: там держат пленного ревнителя из Алого ордена и дворфа-горного пехотинца, узников Отрекшихся.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Ферма Гаррена",
			short = "Ферма Гаррена когда-то была богатым хозяйством на севере Тирисфальских лесов, с широкими полями и полными амбарами. Чума нежити положила этому конец.",
			full = "Ферма Гаррена когда-то была богатым хозяйством на севере Тирисфальских лесов, с широкими полями и полными амбарами. Чума нежити положила этому конец. Когда Плеть прокатилась по Лордерону, Гаррена и его семью перебили прямо в их доме, а сама земля вокруг разрушенного жилища посерела и омертвела.\n\nУцелевшие постройки захватили гноллы-гнилошкуры во главе с Червеглазом. Они заняли дом и амбар и без колебаний нападали на всякого, кто подходил слишком близко.\n\nФерма так и не оправилась. Она стоит заброшенной, поля её пусты, семьи больше нет, и лишь гноллы остаются здесь как ответ на вопрос, кому она теперь принадлежит.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Приют Гюнтера",
			short = "На острове посреди озера Ясноводного стоит Приют Гюнтера, который захватил лич Отрекшихся Гюнтер Чародей со своими прислужниками-зомби.",
			full = "На острове посреди озера Ясноводного стоит Приют Гюнтера, который захватил лич Отрекшихся Гюнтер Чародей со своими прислужниками-зомби. У юго-западного берега, на голом безымянном островке, стоит странная примета, известная лишь как Обеденный стол Лилит.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Паучья низина",
			short = "Паучья низина — небольшая долина, которую прорезает старый золотой рудник, и то и другое захвачено пауками. Молодняк бродит по открытой низине, а взрослые ночные кругопряды владеют темными штольнями рудника.",
			full = "Паучья низина — небольшая долина, которую прорезает старый золотой рудник, и то и другое захвачено пауками. Молодняк бродит по открытой низине, а взрослые ночные кругопряды владеют темными штольнями рудника.\n\nСюда приходят только что восставшие Отрекшиеся, чтобы проверить, на что ещё способны их тела: сначала они истребляют молодых пауков снаружи и лишь потом решаются войти в сам рудник.\n\nВ самом глубоком его закоулке сидит матриарх ночных кругопрядов — мать всего роя, что копошится над ней.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Долина Кошмаров",
			short = "К западу от сторожевой башни Алого ордена в Тирисфальских лесах лежит пришедшая в запустение долина. Её деревья засохли, а зверье, что когда-то жило среди них, истребили псы Тьмы и огромные летучие мыши-вампиры.",
			full = "К западу от сторожевой башни Алого ордена в Тирисфальских лесах лежит пришедшая в запустение долина. Её деревья засохли, а зверье, что когда-то жило среди них, истребили псы Тьмы и огромные летучие мыши-вампиры. Среди этих охотников летает Рессан Жалящий — редкая белая летучая мышь, не похожая на остальных.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "Северное побережье",
			short = "Северное побережье тянется там, где Тирисфальские леса встречаются с Великим морем; теперь оно отдано мурлокам и морским тварям.",
			full = "Северное побережье тянется там, где Тирисфальские леса встречаются с Великим морем; теперь оно отдано мурлокам и морским тварям. После чумы нежити берег стал темным и холодным, а прилив оставляет у кромки воды гниющие тела мертвых морских созданий.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Руины Лордерона",
			short = "Над погребенным городом всё ещё стоит дворец Лордерона: его залы открыты небу, его сады обратились в руины. Здесь умерло великое королевство Альянса, и здесь его призраки так до конца и не упокоились.",
			full = "Над погребенным городом всё ещё стоит дворец Лордерона: его залы открыты небу, его сады обратились в руины. Здесь умерло великое королевство Альянса, и здесь его призраки так до конца и не упокоились.\n\nКонец ему положил Артас Менетил. Принц вернулся домой во главе армии, поднятой против собственного народа, и в эти ворота его встречали колокольным звоном и ликованием, прежде чем кто-либо понял, кем он стал. В тронном зале его ждал отец, король Теренас, и там Артас убил его. Стоя над телом, он произнёс слова, которые до сих пор звучат в этом зале для всякого, кто задержится: королевство падёт, и из его пепла восстанет новый порядок, который потрясёт мир. Это не было пустой похвальбой. Через несколько дней город и его жители были перебиты, и Лордерон стал владением Плети.\n\nГоворят, что и теперь, бродя по двору, можно услышать то, что помнит камень: приглушённые голоса, звон колоколов, приветствующих гостя, шёпот из тронного зала, который никогда не стихает до конца. Те, кто способен видеть за гранью, утверждают, что жители Лордерона всё ещё ходят здесь, не зная, что их королевства больше нет.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Монастырь Алого ордена",
			short = "При Алом ордене старый монастырь стал казармой и тюрьмой. Инквизитор Вайтмейн и Рено Могрейн сделали его своей резиденцией, и его часовня превратилась в место не только молитвы, но и суда.",
			full = "При Алом ордене старый монастырь стал казармой и тюрьмой. Инквизитор Вайтмейн и Рено Могрейн сделали его своей резиденцией, и его часовня превратилась в место не только молитвы, но и суда.\n\nПрежде чем стать крепостью, старый монастырь был собором Церкви Святого Света, полным библиотек, где обучались паладины. Сам Александрос Могрейн в юности провёл здесь много месяцев в молитвах и учении, прежде чем впервые взял в руки клинок.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Сторожевой пост Алого ордена",
			short = "Сторожевой пост Алого ордена охраняет подступы, которые Монастырь Алого ордена не может защитить сам. Здесь командует капитан Мелраш, удерживая пост против всякого, кто решил бы незаметно ударить в незащищённый бок монастыря.",
			full = "Сторожевой пост Алого ордена охраняет подступы, которые Монастырь Алого ордена не может защитить сам. Здесь командует капитан Мелраш, удерживая пост против всякого, кто решил бы незаметно ударить в незащищённый бок монастыря.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Мрачный склеп",
			short = "Мрачный склеп стоит на вершине склона на кладбище Могильника, высоко в горах Тирисфаля. От его входа вниз, к Могильнику, вьётся протоптанная тропа.",
			full = "Мрачный склеп стоит на вершине склона на кладбище Могильника, высоко в горах Тирисфаля. От его входа вниз, к Могильнику, вьётся протоптанная тропа.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Ферма Соллидена",
			short = "Тыквенные поля Соллидена — один из немногих клочков земли в Тирисфале, где прежнюю жизнь не поглотили ни чума, ни нежить.",
			full = "Тыквенные поля Соллидена — один из немногих клочков земли в Тирисфале, где прежнюю жизнь не поглотили ни чума, ни нежить. Хотя вся округа пала сначала перед Плетью, а затем перед восставшими из неё Отрекшимися, здешние фермеры по-прежнему возделывают свои грядки под надёжной защитой Алого ордена из соседнего Частокола Алого ордена.\n\nЭта защита сделала Соллиден диковиной. Фермеры не доверяют никому, кто не принадлежит к Алому ордену: Отрекшихся они гонят прочь как мерзость той самой чумы, что едва не погубила их самих, а к Альянсу относятся настороженно, опасаясь, что его знамёна втянут их в войну, которой они до сих пор избегали, оставаясь маленькими и забытыми.\n\nИменно это затишье не даёт Отрекшимся покоя. Страж смерти Симмер следит за Соллиденом не из-за того, чем он является сейчас, а из-за того, чем может стать: сегодня это мирные фермеры, завтра — вооружённые арендаторы Альянса, плацдарм на земле, которую Отрекшиеся намерены удержать.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Тихий Омут",
			short = "До чумы Тихий Омут был местом, где живые могли побыть молодыми.",
			full = "До чумы Тихий Омут был местом, где живые могли побыть молодыми. Семьи со всей округи приходили на его берега на пикники, а дети, ещё слишком маленькие, чтобы отважиться на глубокие воды озера Ясноводного, учились плавать здесь.\n\nТеперь вода здесь серая. Рыбы под её поверхностью — лишь кости, которые всё ещё плавают, словно им никто не сказал остановиться. Вдоль берега бродят неприкаянные мертвецы и дикие звери, а у самой кромки воды рыщет пёс Тьмы Бейн, пожирая всякого, кто по неосторожности здесь задержится.\n\nК тому времени, как Отрекшиеся начали поднимать Брилл из руин, воины Алого ордена уже взялись патрулировать берега Тихого Омута.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Терраса Покоя",
			short = "Сразу к северу от Монастыря Алого ордена лежит земля, которой чума так и не коснулась. Здесь растут зелёные живые изгороди, а фонтан бьёт чистой, а не застоявшейся водой, в отличие от остальных Тирисфальских лесов.",
			full = "Сразу к северу от Монастыря Алого ордена лежит земля, которой чума так и не коснулась. Здесь растут зелёные живые изгороди, а фонтан бьёт чистой, а не застоявшейся водой, в отличие от остальных Тирисфальских лесов. Алый орден ухаживает за ней, сохраняя эту маленькую террасу как доказательство того, что посреди скверны всё ещё может уцелеть что-то чистое.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Долина ядовитых пауков",
			short = "Долина ядовитых пауков когда-то была зелёной, полной оленей и кроликов, пока не стала тем, чем является теперь: долиной, кишащей ядовитыми пауками во главе с редкой и смертоносной Шри'скалк, чья паутина заменила траву и дала долине её имя.",
			full = "Долина ядовитых пауков когда-то была зелёной, полной оленей и кроликов, пока не стала тем, чем является теперь: долиной, кишащей ядовитыми пауками во главе с редкой и смертоносной Шри'скалк, чья паутина заменила траву и дала долине её имя. На севере, у лагеря Алого ордена, которым командует лейтенант Сандерс, рыщут псы Тьмы.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "Шепчущие сады",
			short = "Когда-то на холме к югу от Монастыря Алого ордена произошла битва между людьми, которым предстояло стать Алым орденом, и полчищем Плети.",
			full = "Когда-то на холме к югу от Монастыря Алого ордена произошла битва между людьми, которым предстояло стать Алым орденом, и полчищем Плети. С обеих сторон пали многие. В сумерках их духи всё ещё бродят здесь, и их голоса звучат тихим шёпотом среди безмолвных камней сада.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Шепчущий берег",
			short = "Шепчущий берег лежит на западе Тирисфальских лесов, к северу от фермы Соллидена. Когда-то рыбаки любили его за спокойную воду и неизменный улов.",
			full = "Шепчущий берег лежит на западе Тирисфальских лесов, к северу от фермы Соллидена. Когда-то рыбаки любили его за спокойную воду и неизменный улов.\n\nТеперь от этого изобилия ничего не осталось. Берег заполонили мурлоки, которые набрасываются на всякого, кто подойдёт близко, а вода стала холодной и тёмной.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Серебряный бор: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Янтарная мельница",
			short = "Когда-то Янтарная мельница была ничем не примечательным городком лесорубов к юго-западу от озера Лордамер в Серебряном бору.",
			full = "Когда-то Янтарная мельница была ничем не примечательным городком лесорубов к юго-западу от озера Лордамер в Серебряном бору.\n\nПлеть и Пылающий Легион изменили цену этому городку. Его заняли маги Кирин-Тора из Даларана, восстанавливавшегося после собственного краха, и на время Янтарная мельница стала тем, чем не была никогда: настоящим оплотом человеческого сопротивления в Серебряном бору, опирающимся на волшебство Даларана.\n\nОтрекшиеся не оставили это без присмотра. Их стражи смерти узнали от пленника, что маги хранят там документы, касающиеся положения дел в самом Даларане. Лесопилки, конюшни и ратуша по-прежнему в руках Кирин-Тора, а из лесной тени против них действуют лазутчики.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Погибель Берена",
			short = "На холмах к юго-западу от Янтарной мельницы лежит Погибель Берена.",
			full = "На холмах к юго-западу от Янтарной мельницы лежит Погибель Берена. Спустя годы после Третьей войны разведчики Отрекшихся донесли жрецу Тени Алистеру, что там тайно собирается нежить, готовясь к удару по Гробнице. Эта нежить служила некроманту Тулу Когтю Ворона, который выбрал это место, чтобы незаметно собирать своих слуг: достаточно близко, чтобы угрожать Гробнице, и достаточно далеко от дороги, чтобы не привлекать внимания.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Рассветные острова",
			short = "Когда-то Рассветные острова мягко и невысоко поднимались над кристальными водами озера Лордамер — тихие островки, не знавшие бед. Чума нежити всё изменила.",
			full = "Когда-то Рассветные острова мягко и невысоко поднимались над кристальными водами озера Лордамер — тихие островки, не знавшие бед. Чума нежити всё изменила. Деревья на них заболели, а островки заполонили мурлоки и болотные чудища. Болотных чудищ теперь не стало, но мурлоки из племени Злобного Плавника беспрепятственно расплодились и ныне безраздельно владеют островами.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Мертвое поле",
			short = "Мертвое поле лежит заброшенным на севере Серебряного бора: его нивы сгнили, а прежние хозяева забыты.",
			full = "Мертвое поле лежит заброшенным на севере Серебряного бора: его нивы сгнили, а прежние хозяева забыты. Известно лишь то, кто завладел им с тех пор: гноллы-гнилошкуры, состоящие на службе у Плети. Они устроили на разорённой ферме свою базу, и их число растёт так, что можно заподозрить: здесь всё ещё готовится какое-то нападение.\n\nОтрекшиеся не раз наносили удар по ферме, надеясь разбить гноллов прежде, чем те выступят. Все попытки провалились. Всякий раз, когда гнилошкурам грозит опасность, на их зов откликается банши — дух по имени Плеть Ночи, которая повелевает гноллами как своими собственными и появляется словно из ниоткуда, чтобы их защитить.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Старая переправа",
			short = "Когда-то Старая переправа перевозила грузы на остров Фенриса, где было поместье одного лорда и его семьи, и за каждый рейс паромщику платили несколько монет.",
			full = "Когда-то Старая переправа перевозила грузы на остров Фенриса, где было поместье одного лорда и его семьи, и за каждый рейс паромщику платили несколько монет.\n\nЗатем на Лордерон обрушилась Плеть. Паромщика убили прямо за работой, а его паром разбили в щепки.\n\nТеперь по разрушенным причалам бродят вурдалаки, воины-скелеты и гноллы-гнилошкуры, а переправа стоит заброшенной и опасна для всех, кроме сильных.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Серебряный рудник",
			short = "Серебряный рудник находится в Серебряном бору. Аругал позволил своей магии проникнуть в него, и воргены сделали рудник своим логовом; ими предводительствует Мрачнон Белесый, некогда бывший здесь десятником.",
			full = "Серебряный рудник находится в Серебряном бору. Аругал позволил своей магии проникнуть в него, и воргены сделали рудник своим логовом; ими предводительствует Мрачнон Белесый, некогда бывший здесь десятником.\n\nДалар Ткач Рассвета добивался смерти Мрачнона, чтобы Отрекшиеся могли забрать рудник себе как источник ресурсов — во имя Вариматраса.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Остров Фенриса",
			short = "Остров Фенриса лежит посреди озера Лордамер. Вместе с Рассветными островами он образует разорванное кольцо суши, и его, пусть и с оговорками, причисляют к Серебряному бору.",
			full = "Остров Фенриса лежит посреди озера Лордамер. Вместе с Рассветными островами он образует разорванное кольцо суши, и его, пусть и с оговорками, причисляют к Серебряному бору.\n\nДо Третьей войны на острове стояла Крепость Фенриса, военная застава Лордерона. Когда Плеть захлестнула эти земли, крепость пала. Её защитники либо бежали, либо погибли там, где стояли, и остров опустел.\n\nВ эту пустоту пришли гноллы-гнилошкуры, устроившие логово в брошенной крепости. Их хозяином был Тул Коготь Ворона, которого даже среди гноллов помнят как предателя. Он правит гнилошкурами, а через них — всем островом Фенриса, удерживая захваченную крепость, а заодно и соседнюю Старую переправу.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Крепость Фенриса",
			short = "Крепость Фенриса стоит посреди озера Лордамер, на острове Фенриса в Серебряном бору; когда-то здесь размещалась немалая часть войска Лордерона.",
			full = "Крепость Фенриса стоит посреди озера Лордамер, на острове Фенриса в Серебряном бору; когда-то здесь размещалась немалая часть войска Лордерона.\n\nКогда Плеть захлестнула эти земли, крепость пала вместе с ними. В руины пришёл Тул Коготь Ворона, молодой маг, некогда состоявший в Кирин-Торе. Он перешёл на сторону Плети, подчинил своей воле гноллов острова и сковал из них племя гнилошкуров. С этим племенем за спиной он стал хозяином Крепости Фенриса, и теперь гнилошкуры набрасываются на всякого, кто приблизится к их повелителю.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "Стена Седогрива",
			short = "Король Генн Седогрив воздвиг свою стену ещё до Третьей войны, устав от того, что золото Гильнеаса тратится на лагеря для интернированных орков, и измучившись от распрей, раздиравших королей Альянса Лордерона.",
			full = "Король Генн Седогрив воздвиг свою стену ещё до Третьей войны, устав от того, что золото Гильнеаса тратится на лагеря для интернированных орков, и измучившись от распрей, раздиравших королей Альянса Лордерона. Он замкнул своё королевство в себе, отрезав Гильнеас от Лордерона и от всего мира за горами.\n\nСтена устояла перед чумой нежити, но дорогой ценой. Когда Плеть захлестнула Лордерон, беженцы бежали на юг и разбивали лагеря у ворот, но ворота годами не открывались. Беженцы так и погибли там, не дождавшись ответа.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Делянка Ивара",
			short = "Когда-то Делянка Ивара была завидной фермой: её грядки ломились от тыкв, а дом был полон батраков, работавших в поле на человека по имени Ивар.",
			full = "Когда-то Делянка Ивара была завидной фермой: её грядки ломились от тыкв, а дом был полон батраков, работавших в поле на человека по имени Ивар. Жилось здесь хорошо, пока на Лордерон не обрушилась чума нежити и не отняла у него всё.\n\nИвар не просто умер. Он восстал, и вместе с ним восстала его семья и все батраки, что работали на его земле, — все они обратились в гниющих вурдалаков, которые теперь набрасываются на всякого, кто подойдёт близко. Сам же Ивар восстал чем-то куда худшим, и теперь его помнят как Ивара Нечистого.\n\nТрое стражей смерти, посланных на север оценить опасность, попали здесь в засаду вурдалаков, и Ивар Нечистый ранил одного из них, Квинна Йорика, прежде чем Квинн и его родственница Ран забаррикадировались в старом доме Ивара.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Озеро Лордамер",
			short = "Озеро Лордамер раскинулось в тени королевств, что некогда стояли на его берегах.",
			full = "Озеро Лордамер раскинулось в тени королевств, что некогда стояли на его берегах. На северном берегу поднимался Лордерон, и, скорее всего, именно от этого великого города, названного в честь древнего Лордейна, озеро и получило своё имя. Вокруг его вод процветали также Даларан и Альтерак — в те дни, когда Альянс Лордерона объединял королевства людей.\n\nТа эпоха миновала, и осталась лишь граница. Теперь озеро лежит между владениями Отрекшихся в Тирисфальских лесах и Серебряном бору и спорными Альтеракскими горами, отделяя мёртвых от живых.\n\nВ его сердце лежит остров Фенриса, чью крепость удерживают гноллы-гнилошкуры под началом Тула Когтя Ворона.\n\nК востоку от острова Фенриса, на маленьких Рассветных островах, обосновались мурлоки из племени Злобного Плавника, заполонившие их целиком.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Сад Мальдена",
			short = "Деревья в Саду Мальдена потемнели и стали вечнозелёными, а плоды висят на них несобранными сезон за сезоном. Сам Мальден давно исчез: его изгнали из дома, когда на Лордерон обрушилась Плеть.",
			full = "Деревья в Саду Мальдена потемнели и стали вечнозелёными, а плоды висят на них несобранными сезон за сезоном. Сам Мальден давно исчез: его изгнали из дома, когда на Лордерон обрушилась Плеть.\n\nТеперь сад принадлежит воргам, которые во множестве устраивают логова среди деревьев и вокруг единственного уцелевшего маленького домика. Именно сюда пришёл страж смерти Эрланд МакКри, посланный осмотреть сад во время разведки северного леса. Ворги загнали его, прежде чем он успел далеко уйти, и он забаррикадировался в заброшенном домике, где просидел взаперти несколько дней, пока другие агенты Отрекшихся не помогли ему вырваться и вернуться к ждавшим его товарищам.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "Северная приливная низина",
			short = "Северная приливная низина лежит чуть севернее Гробницы в Серебряном бору. Это одно из многих логовищ воргенов Лунного Гнева, слуг верховного мага Аругала.",
			full = "Северная приливная низина лежит чуть севернее Гробницы в Серебряном бору. Это одно из многих логовищ воргенов Лунного Гнева, слуг верховного мага Аругала. Здесь они ставят грубые стоянки, где нет ничего, кроме самого необходимого для выживания, — ровно столько укрытия, сколько нужно созданиям, живущим клыками и силой.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "Берег Северного прилива",
			short = "Северо-западное побережье Серебряного бора, где пляж встречается с холодным Великим морем, носит название Берег Северного прилива.",
			full = "Северо-западное побережье Серебряного бора, где пляж встречается с холодным Великим морем, носит название Берег Северного прилива. На мелководье, наполовину затонув, лежит разбитый корабль Орды: его корпус осел в прибое, и это самая заметная примета на всём этом отрезке берега.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Удел Ольсена",
			short = "Когда-то Удел Ольсена стоял у торговых дорог, пересекающих Серебряный бор, — работящая ферма, чьи поля кормили проезжавших мимо.",
			full = "Когда-то Удел Ольсена стоял у торговых дорог, пересекающих Серебряный бор, — работящая ферма, чьи поля кормили проезжавших мимо.\n\nТретья война положила этому конец. Всего за несколько лет ферма превратилась в руины.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Деревня Погребальных Костров",
			short = "Деревня Погребальных Костров стоит на краю Серебряного бора; здесь ютятся люди, пережившие первое пришествие Плети во время Третьей войны.",
			full = "Деревня Погребальных Костров стоит на краю Серебряного бора; здесь ютятся люди, пережившие первое пришествие Плети во время Третьей войны. К северу от неё стоит крепость, некогда принадлежавшая барону Сребролену, которую охраняли паладин командир Спрингвейл и Серебряная Длань. Сребролена и его людей перебили воргены верховного мага Аругала, который забрал крепость себе и переименовал её в Крепость Темного Клыка. Оттуда Аругал обратил своё безумие на саму деревню, прокляв её жителей: каждую ночь они превращаются в свирепых воргенов Лунного Гнева и растерзывают всякого, кто встанет у них на пути, а на рассвете вновь просыпаются людьми.\n\nНесмотря на это, днём деревня по-прежнему открывает двери путникам, а её жители скованы проклятием Аругала, которому не видно конца.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Гробница",
			short = "Гробница стоит над побережьем Лордерона, на западных холмах Серебряного бора, там, где когда-то дорога пересекала простое кладбище, чьи склепы были лишь местом упокоения мёртвых.",
			full = "Гробница стоит над побережьем Лордерона, на западных холмах Серебряного бора, там, где когда-то дорога пересекала простое кладбище, чьи склепы были лишь местом упокоения мёртвых.\n\nПосле Третьей войны Отрекшиеся заняли старое кладбище и превратили его в опорный пункт, сделав место, построенное для мёртвых, пристанищем для немёртвых.\n\nЭтот выбор был продиктован необходимостью. На юге рыскали воргены, на востоке всё ещё держалась Плеть, а с юго-востока следил Кирин-Тор. Окружённые почти со всех сторон, Отрекшиеся нашли в Гробнице одно из немногих мест в Серебряном бору, где Орда могла стоять в безопасности.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Крепость Темного Клыка",
			short = "Крепость Темного Клыка стоит на высоком утёсе над Деревней Погребальных Костров. Когда-то она принадлежала барону Сребролену, лорду Гильнеаса, пока на Лордерон не обрушилась Плеть и королевский верховный маг Аругал не стал искать способа её остановить.",
			full = "Крепость Темного Клыка стоит на высоком утёсе над Деревней Погребальных Костров. Когда-то она принадлежала барону Сребролену, лорду Гильнеаса, пока на Лордерон не обрушилась Плеть и королевский верховный маг Аругал не стал искать способа её остановить. Опираясь на исследования мага Ура, с благословения короля Генна Седогрива, но вопреки совету Кирин-Тора, Аругал призвал воргенов. Они отбросили волну нежити, а затем обратились против самого Гильнеаса, обрушившись на Стену Седогрива, и вырвались на волю в Серебряный бор. Они напали на крепость и убили барона Сребролена и всех его домочадцев.\n\nАругал, сломленный тем, что выпустил на волю, не бежал от этого. Он назвал воргенов своими детьми, забрал крепость себе и переименовал её в Крепость Темного Клыка. Общаясь с господином, которому служил в Культе Волка, он распространил проклятие по лесу, пока не обратилась сама Деревня Погребальных Костров: её жители днём остаются людьми, а ночью становятся зверьми, и правит ими совет, подчиняющийся одному лишь Аругалу.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Сияющий берег",
			short = "Сияющий берег тянется вдоль озера Лордамер от столицы Лордерона на севере до скалистых холмов, отделяющих Серебряный бор от Альтеракских гор.",
			full = "Сияющий берег тянется вдоль озера Лордамер от столицы Лордерона на севере до скалистых холмов, отделяющих Серебряный бор от Альтеракских гор.\n\nМурлоки из племени Злобного Плавника густо усеяли берег своими поселениями, и путники, не знающие здешних мест, научились его бояться. Покойный аптекарь Берард писал в своих записях о редкой добыче, которую можно получить у Злобных Плавников, — о твёрдой опухоли — и предполагал, что из неё можно было бы создать новую чуму.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Струящаяся Тьма",
			short = "Рудник, известный как Струящаяся Тьма, захватили пауки-снователи, и их паутина свисает с поломанных крепей и ржавых инструментов.",
			full = "Рудник, известный как Струящаяся Тьма, захватили пауки-снователи, и их паутина свисает с поломанных крепей и ржавых инструментов. В глубине прячется матриарх снователей — паучиха чудовищных размеров, правящая роем из тьмы, которую она никогда не покидает. Снаружи среди скал порой в одиночку рыщет редкий Кретис Ткач Теней.\n\nЗемлю усеивают коконы, в которых спелёнаты воргены, ворги и медведи, а также орки, притащенные сюда с обломков корабля на берегу к западу.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "Берег Южного прилива",
			short = "Берег Южного прилива тянется вдоль юго-западного побережья Серебряного бора, там, где суша встречается с Великим морем.",
			full = "Берег Южного прилива тянется вдоль юго-западного побережья Серебряного бора, там, где суша встречается с Великим морем.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Поле Валгана",
			short = "Поле Валгана лежит среди заброшенных ферм на севере Серебряного бора, к западу от Сияющего берега и к северу от небольшой речки.",
			full = "Поле Валгана лежит среди заброшенных ферм на севере Серебряного бора, к западу от Сияющего берега и к северу от небольшой речки. Оно названо в честь фермера, который погиб или был изгнан со своей земли, когда Плеть прокатилась по Серебряному бору. В лучшие дни с фермы открывался вид на озеро Лордамер, вполне достойный былой славы этого места.\n\nТеперь ферма стоит пустой, лишь руиной того, чем была когда-то, хотя порой поблизости можно заметить Плеть Ночи.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Западные Чумные земли: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "Бастион",
			short = "Бастион стоит там, где Тирисфальские леса встречаются с Западными Чумными землями, — это рубеж, который Отрекшиеся удерживают против Плети, что всё ещё собирается на востоке.",
			full = "Бастион стоит там, где Тирисфальские леса встречаются с Западными Чумными землями, — это рубеж, который Отрекшиеся удерживают против Плети, что всё ещё собирается на востоке. Здесь защитники-Отрекшиеся и Серебряный Рассвет отложили свои разногласия перед лицом общего врага: они вместе стерегут границу и посылают бойцов на восток, чтобы разить прислужников Короля-лича.\n\nВ отличие от остального Тирисфаля, этот край совсем не похож на леса. Над ним висит чумной туман, окрашивая небо в тот же болезненный жёлто-серый цвет, что и над Западными Чумными землями дальше на востоке.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Каэр Дарроу",
			short = "На острове посреди озера Дарроумир стояла крепость, давным-давно возведённая руками людей, и в ней хранился древний рунический камень высших эльфов.",
			full = "На острове посреди озера Дарроумир стояла крепость, давным-давно возведённая руками людей, и в ней хранился древний рунический камень высших эльфов. Во время Второй войны Орда захватила остров и разграбила крепость, а рунический камень раскололи, чтобы выковать из него Алтари Бурь, с помощью которых Гул'дан наделил магией огров своей Орды.\n\nКрепость отстроили заново, и она стала резиденцией дома Баровых. Когда годы начали клониться к войне, Баровы, испугавшись потерять всё, что было нажито за десятилетия, заключили сделку с Кел'Тузадом, главой Культа Проклятых. Катакомбы под поместьем превратились в Некроситет, школу некромантии, а собственных слуг семейства отдали в подопытные для чумы нежити. Не прошло и полугода, как болезнь вырвалась на волю и убила всех на острове. Её жертвы не просто умерли: они восстали призраками, обречёнными вновь и вновь переживать свои последние мгновения, и до сих пор бродят по разрушенным залам Каэр Дарроу.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Лагерь Промозглого Ветра",
			short = "Лагерь Промозглого Ветра стоит у южных ворот Западных Чумных земель, там, где Альтеракские горы переходят в отравленную землю. Это последнее место, где путник из Альянса может стоять и всё ещё называть землю чистой.",
			full = "Лагерь Промозглого Ветра стоит у южных ворот Западных Чумных земель, там, где Альтеракские горы переходят в отравленную землю. Это последнее место, где путник из Альянса может стоять и всё ещё называть землю чистой.\n\nЛагерь удерживает небольшой отряд Серебряного Рассвета — всего горстка бойцов и знатоков своего дела. Чего лагерю недостаёт в числе, то он восполняет дерзостью: его люди ведут партизанскую войну против твердыни Плети в Андорале и против чумных котлов, засевающих землю смертью, полагаясь на наёмников, готовых ударить и исчезнуть, а не удерживать землю, которую всё равно не удержать.\n\nЛорд Грейсон Тенелом прислал сюда подающих надежды молодых рыцарей Серебряной Длани, чтобы они встали рядом с командиром Ашламом Смелонравом против Плети в этих краях.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Слезы Далсона",
			short = "Когда-то сад Далсона приносил плоды семье, давшей ему своё имя. Теперь его деревья стоят в Западных Чумных землях под названием, которое хранит память не об урожае, а о горе: Слезы Далсона.",
			full = "Когда-то сад Далсона приносил плоды семье, давшей ему своё имя. Теперь его деревья стоят в Западных Чумных землях под названием, которое хранит память не об урожае, а о горе: Слезы Далсона.\n\nПлеть захватила ферму и превратила её в рану на теле земли. В её центре поставили огромный котёл, который с тех пор не умолкает ни на миг, извергая в воздух заразу, а стережёт его хранитель котла Мальвиниус и служащие ему поражённые скверной мертвецы.\n\nДалсоны так и не ушли. Миссис Далсон до сих пор бродит по усадьбе — скелет, перебирающий землю, за которой она когда-то ухаживала, будучи живой женщиной. Её муж умер не рядом с ней. Его заперли в нужнике и бросили там, и в той запертой тьме он превратился уже не в человека, а в вурдалака.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Озеро Дарроумир",
			short = "Воды Дарроумира всё ещё хранят память о Второй войне, когда озеро было усеяно парусами.",
			full = "Воды Дарроумира всё ещё хранят память о Второй войне, когда озеро было усеяно парусами. Большинство кораблей, бросавших здесь якорь, ходили под флагом флота Праудмура, и ещё до сожжения Кель'Таласа великий адмирал отправил часть из них через эти воды, чтобы доставить Туралиона, Аллерию Ветрокрылую и их войско к Стратхольму. Туралион подумывал о том, чтобы плыть дальше, в сам Кель'Талас, но Аллерия предупредила его, что эльфы ни за что не пропустят корабли людей вверх по своей реке, и флот повернул к Стратхольму. В ту же войну Зул'джина и его отряд оттеснили к берегам озера, и военачальник троллей попал в плен.\n\nПосреди озера стоит островной город Каэр Дарроу, ныне опустевший, а некогда принадлежавший дому Баровых. Под камнями города лежит Некроситет, где Культ Проклятых трудится среди своей нежити, — тьма, покоящаяся под утопленной тишиной острова.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Поле Джанис",
			short = "Когда-то Поле Джанис кормило живых. Этому пришёл конец, когда его накрыла Плеть и больше не позволила ему снова стать фермой.",
			full = "Когда-то Поле Джанис кормило живых. Этому пришёл конец, когда его накрыла Плеть и больше не позволила ему снова стать фермой.\n\nВ самом сердце поля Плеть поставила огромный котёл, и с тех пор он не прекращает своей работы. Из него без передышки валит пар, густо насыщенный заразой. Его стережёт хранитель котла Желчень вместе со скелетами-колдунами, скелетами-свежевателями и брызжущими слюной вурдалаками, так что ничто живое не может подойти к нему и уйти незаражённым.\n\nВ северо-восточном углу всё ещё стоит старый дом, и Джанис Фелстоун до сих пор не покидает его, задерживаясь на земле, что некогда приносила урожай её семье.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Пустошь Гаррона",
			short = "Ферма на восточной окраине Западных Чумных земель когда-то принадлежала Делу Гаррону, и в лучшие дни её называли Цветением Гаррона — местом посевов и роста.",
			full = "Ферма на восточной окраине Западных Чумных земель когда-то принадлежала Делу Гаррону, и в лучшие дни её называли Цветением Гаррона — местом посевов и роста. Теперь там ничего не растёт. Плеть захватила поля и поставила посреди них огромный котёл, который не прекращает своей работы, извергая в воздух заражённый пар, пока сама земля, кажется, не начинает болеть. Его охраняет хранитель котла Душегнев вместе с другими военачальниками Плети, а испарения вызвали к жизни то, чему не следовало бы ходить по земле: призрачные видения, плывущие меж разорённых борозд, воющих смертей и голодных призраков, что не подчиняются никому, кроме собственного голода.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Дольный Очаг",
			short = "Дольный Очаг стоит к северу от Андорала: его стены окружают крепость, башню магов, мельницу и рудник — картина порядка посреди края, обратившегося в руины.",
			full = "Дольный Очаг стоит к северу от Андорала: его стены окружают крепость, башню магов, мельницу и рудник — картина порядка посреди края, обратившегося в руины. Многие годы этот порядок хранил Тирион Фордринг, лорд Марденхольда, пока не помог орку Эйтриггу и не был изгнан за измену. Со временем его место лорда Марденхольда занял его сын Телан.\n\nПозднее Дольный Очаг приютил остатки ордена Серебряной Длани, откликнувшиеся на предложение Телана об убежище после падения столицы. Из-за его стен паладины одерживали победы в последующие годы, пока орден не извратился, превратившись в Алый орден, который забрал город себе.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Крепость Марденхольд",
			short = "Крепость Марденхольд стоит в сердце Дольного Очага с незапамятных для большинства её нынешних обитателей времён, и её стены не пали даже в самые тёмные дни вторжения орков в Лордерон.",
			full = "Крепость Марденхольд стоит в сердце Дольного Очага с незапамятных для большинства её нынешних обитателей времён, и её стены не пали даже в самые тёмные дни вторжения орков в Лордерон. Многие годы она была резиденцией Тириона Фордринга, и здесь, в зале совета, где главенствовали огромный дубовый стол и карта, изображавшая Дольный Очаг вплоть до самой малой дороги, паладин совещался со своими советниками о делах королевства. Обвинённый в измене за помощь орку Эйтриггу, Тирион был отлучён от церкви и изгнан, и со временем Марденхольд перешёл к его собственному сыну, Телану.\n\nПосле того как Плеть опустошила Лордерон, Телан предоставил уцелевшим рыцарям Серебряной Длани пристанище в Дольном Очаге. В этих стенах пришла весть о гибели Александроса Могрейна, и подозрение в предательстве раскололо орден: Максвелл Тиросс увёл своих сторонников и основал Серебряный Рассвет, а оставшиеся приняли имя Алого ордена, и Марденхольд стал их твердыней, а Телан был возведён в сан верховного лорда.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Лесопилка Северного Кряжа",
			short = "Лесопилка Северного Кряжа лежит на севере Западных Чумных земель, неподалёку от Дольного Очага, и её склоны оголены вырубками Алого ордена.",
			full = "Лесопилка Северного Кряжа лежит на севере Западных Чумных земель, неподалёку от Дольного Очага, и её склоны оголены вырубками Алого ордена. Орден использует лесопилку, чтобы добывать древесину, — запасы, которые и Альянсу, и Орде есть причины испортить.\n\nДо Третьей войны лесопилка принадлежала семье Натаниэля Дамаха, которая трудилась на этой земле, пока война и чума не выгнали её отсюда. Когда-то здесь работала и семья Микки Левина.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Руины Андорала",
			short = "Андорал лежит в руинах в самом сердце Западных Чумных земель, и его разбитые дома разбросаны по открытой равнине.",
			full = "Андорал лежит в руинах в самом сердце Западных Чумных земель, и его разбитые дома разбросаны по открытой равнине. То, что от него осталось, удерживает Араж Призыватель, лич немалой силы, и служащие ему мертвецы: вурдалаки, волочащиеся меж упавших камней, скелеты, стоящие на посту там, где когда-то стояла стража, банши, чьи крики разносятся над руинами, и поганища, бредущие сквозь развалины домов.\n\nАраж по-прежнему остаётся в центре всего этого, властвуя над городом, который так и не поднялся вновь.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Некроситет",
			short = "На возвышенности над заброшенным городом Каэр Дарроу стоит поместье, некогда бывшее резиденцией дома Баровых — семьи, чьё влияние простиралось от Каэр Дарроу до Брилла, Южнобережья и Мельницы Таррен.",
			full = "На возвышенности над заброшенным городом Каэр Дарроу стоит поместье, некогда бывшее резиденцией дома Баровых — семьи, чьё влияние простиралось от Каэр Дарроу до Брилла, Южнобережья и Мельницы Таррен. Десятилетиями они правили в довольстве, но по мере приближения войны Баровы стали озлобленными и алчными и не желали, чтобы смерть положила конец всему, что они построили. Поэтому они заключили сделку с Кел'Тузадом, главой Культа Проклятых, чтобы сохранить своё богатство и свои земли за пределами отпущенного смертным срока.\n\nЗа полгода крепость сгнила изнутри и превратилась в нечто совсем иное. Послушники Культа изучали искусство некромантии, а собственных слуг семейства отдали в качестве живых подопытных для чумы нежити. Прежде чем Утер Светоносный успел нанести в поместье назначенный визит, выведенная в его залах болезнь вырвалась на волю и обрушилась на сам Каэр Дарроу. Она не оставила в живых никого и обрекла своих жертв и после смерти скитаться призраками.\n\nСами Баровы восстали нежитью, по-прежнему прикованные к залам, которые они продали. Теперь директором здесь служит смертный некромант Темный магистр Гандлинг, сменивший Аража Призывателя, который, в свою очередь, пришёл на смену Кел'Тузаду.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Холм Печали",
			short = "В более мирные дни Холм Печали служил Андоралу местом упокоения: здесь, под склепами и простыми надгробиями, лежали умершие горожане, и богатые, и бедные.",
			full = "В более мирные дни Холм Печали служил Андоралу местом упокоения: здесь, под склепами и простыми надгробиями, лежали умершие горожане, и богатые, и бедные. Этот покой закончился с приходом чумы нежити. Пока Плеть снова и снова бросалась на Андорал, холм заполнялся быстрее, чем мог вместить, — наспех вырытые безымянные могилы до сих пор уродуют землю там, где пали защитники. Со временем выжившие вовсе перестали хоронить своих мёртвых, боясь, что чума поднимет их любимых против них самих, и вырыли к югу от кладбища братскую могилу, чтобы сжигать тела.\n\nПоследнее деяние города было самым печальным. Когда Артас сразил лорда Утера, оставшиеся жители Андорала воздвигли на вершине холма огромную гробницу и положили в неё изувеченное тело паладина, прежде чем навсегда покинуть свой дом. Некоторые говорят, что холм получил своё имя лишь из-за этой могилы.\n\nЧумные котлы поблизости не пощадили и собственных мертвецов холма. Солдаты и горожане восстали из своих могил и теперь стоят на страже над теми самыми могилами, которые когда-то заполнили.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Река Тондрорил",
			short = "Река Тондрорил разделяет Западные и Восточные Чумные земли. Она берёт начало далеко на севере, у Туннеля Ужаса, и течёт на юг, пока не впадает в озеро Дарроумир, а дальше продолжается уже как река Дарроумир.",
			full = "Река Тондрорил разделяет Западные и Восточные Чумные земли. Она берёт начало далеко на севере, у Туннеля Ужаса, и течёт на юг, пока не впадает в озеро Дарроумир, а дальше продолжается уже как река Дарроумир.\n\nЕё берега принадлежат скверне. Сырую землю облепили личинки и летучие мыши-вампиры, по мелководью рыщут чумные медведи и пауки, а там, где течение замедляется, притаились хрустогрызы.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Гробница Утера",
			short = "Гробница Утера стоит на Холме Печали — единственном месте в Западных Чумных землях, где Свет всё ещё противостоит умиранию земли.",
			full = "Гробница Утера стоит на Холме Печали — единственном месте в Западных Чумных землях, где Свет всё ещё противостоит умиранию земли.\n\nКогда-то Утер Светоносный защищал Андорал от Плети, стоя плечом к плечу с мудрецом Правдоносцем и Балладором Светлым, а за его спиной стояли рыцари Серебряной Длани. Конец этой обороне положил Артас Менетил: он бросил на город свою армию нежити и сразил Правдоносца, Балладора и самого Утера.\n\nТо, что оставил Артас, собрали собственные воины Утера. Они отнесли его тело к югу от руин Андорала и воздвигли над ним гробницу. Надгробие изображает его таким, каким он был при жизни, — с книгой Света в одной руке и боевым молотом в другой, а на камне перед ним высечены слова на всеобщем языке.\n\nВерховный жрец Тель'данис до сих пор хранит гробницу, будучи её смотрителем и стражем. Эта могила священна для тех, кто следует Свету, — одно из немногих мест в Чумных землях, где такая преданность всё ещё что-то значит.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "Грот Слез",
			short = "Грот Слез лежит к западу от реки Тондрорил, и его пустоты кишат болотными чудищами и слизнями, порождёнными зачумлённой землёй. Во тьме бродят гниющие исполины и разлагающиеся ужасы.",
			full = "Грот Слез лежит к западу от реки Тондрорил, и его пустоты кишат болотными чудищами и слизнями, порождёнными зачумлённой землёй. Во тьме бродят гниющие исполины и разлагающиеся ужасы. Говорят, что ещё глубже изредка появляется элементаль по прозвищу Шелуха — странное и тревожное зрелище.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "Удел Страданий",
			short = "Когда-то Удел Страданий был пахотной землёй, которую возделывали, чтобы кормить живых. Этого предназначения больше нет.",
			full = "Когда-то Удел Страданий был пахотной землёй, которую возделывали, чтобы кормить живых. Этого предназначения больше нет. Плеть захватила поля и поставила посреди них огромный котёл, который с тех пор не прекращает своей работы: заражённый пар непрерывно валит из него и стелется по бороздам, где некогда рос урожай.\n\nКотёл не оставлен без охраны. Над ним несёт стражу хранитель котла Разарх, а вокруг него бродят гниющие вурдалаки, леденящие вурдалаки и зловонные зомби, прикованные к этому месту как его стражи.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Восточные Чумные земли: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Озеро Чернолесья",
			short = "Воды озера Чернолесья осквернены: в их мути извиваются порченые водяные элементали. Старые летописи Дарроушира утверждают, что на дне озера, где-то в этой тьме, покоится голова Хоргуса Опустошителя.",
			full = "Воды озера Чернолесья осквернены: в их мути извиваются порченые водяные элементали. Старые летописи Дарроушира утверждают, что на дне озера, где-то в этой тьме, покоится голова Хоргуса Опустошителя.\n\nДо чумы здесь стоял город Чернолесье, родина великого маршала Отмара Гаритоса. Теперь от него не осталось ничего, кроме озера, носящего его имя.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Мельница Бровача",
			short = "Когда-то Стивен Бровач пилил лес на мельнице к северу от Часовни Последней Надежды. Плеть убила его, как и всех, кого коснулась чума, а затем подняла его вурдалаком, обречённым служить ей.",
			full = "Когда-то Стивен Бровач пилил лес на мельнице к северу от Часовни Последней Надежды. Плеть убила его, как и всех, кого коснулась чума, а затем подняла его вурдалаком, обречённым служить ей. Он так и не ушёл. Теперь он стоит на страже в стенах, которые когда-то принадлежали ему.\n\nМельница кишит скелетами, банши и поганищами — это скорее гарнизон, чем руины, и ничто здесь не располагает к тому, чтобы задерживаться.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Перекресток Корина",
			short = "Перекресток Корина лежит там, где сходятся дороги на Андорал, Дарроушир, Стратхольм и Длань Тира, между Чумным оврагом и озером Мерельдар.",
			full = "Перекресток Корина лежит там, где сходятся дороги на Андорал, Дарроушир, Стратхольм и Длань Тира, между Чумным оврагом и озером Мерельдар. Когда-то это был обычный городок на перекрёстке дорог, с ратушей и кузницей.\n\nТеперь его улицы целиком заполнила Плеть, а среди мертвецов бродят создания, которых вовсе не видно, — незримые слуги, для которых скрытность ничего не значит. Тихого пути через Перекресток Корина не существует.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Башня королевской стражи",
			short = "Башня королевской стражи — одна из дозорных башен, что стерегут Восточные Чумные земли. Вторжение Плети в Лордерон опустошило этот край, и башня до сих пор носит его шрамы, безмолвно отмечая мёртвые земли.",
			full = "Башня королевской стражи — одна из дозорных башен, что стерегут Восточные Чумные земли. Вторжение Плети в Лордерон опустошило этот край, и башня до сих пор носит его шрамы, безмолвно отмечая мёртвые земли.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Дарроушир",
			short = "Когда-то Дарроушир был самостоятельной деревней, пока Третья война не привела Плеть к его воротам. Нападение возглавлял повелитель вурдалаков Хоргус Опустошитель вместе с рыцарем смерти Мардуком Блэкпулом.",
			full = "Когда-то Дарроушир был самостоятельной деревней, пока Третья война не привела Плеть к его воротам. Нападение возглавлял повелитель вурдалаков Хоргус Опустошитель вместе с рыцарем смерти Мардуком Блэкпулом. Поначалу защитники деревни отбивались не без успеха, но удача отвернулась от них, и в конце концов все они были перебиты.\n\nСмерть не стала для них концом. Павшие восстали вурдалаками, обречёнными служить той самой Плети, что их убила, и их души оказались заточены в гниющей плоти, некогда принадлежавшей им.\n\nСам Дарроушир теперь стоит безмолвный и разрушенный, и в нём нет ничего, кроме призраков и памяти.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Восточные ворота",
			short = "Восточные ворота — боковой вход в Стратхольм, открывающийся прямо на площадь Старейшин, неподалёку от часовни Алонсуса, где пребывает Аурий.",
			full = "Восточные ворота — боковой вход в Стратхольм, открывающийся прямо на площадь Старейшин, неподалёку от часовни Алонсуса, где пребывает Аурий.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Восточная башня",
			short = "Восточная башня стоит в Восточных Чумных землях — дозорная башня, некогда стерёгшая эти земли для Лордерона. Плеть прокатилась по королевству, и башня до сих пор носит её шрамы, глядя на мёртвые земли.",
			full = "Восточная башня стоит в Восточных Чумных землях — дозорная башня, некогда стерёгшая эти земли для Лордерона. Плеть прокатилась по королевству, и башня до сих пор носит её шрамы, глядя на мёртвые земли.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Грибная долина",
			short = "К северу от Поместья Маррисов и Башни королевской стражи лежит Грибная долина, земля которой под мутной дымкой стала тёмно-лиловой.",
			full = "К северу от Поместья Маррисов и Башни королевской стражи лежит Грибная долина, земля которой под мутной дымкой стала тёмно-лиловой. Здесь чума нежити пустила самые глубокие корни, и Плеть вместе с Культом Проклятых свободно разгуливает среди этой порчи, считая низину целиком своей.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "Чумной овраг",
			short = "Близ Перекрестка Корина рунический меч рыцаря смерти Мардука Блэкпула разбился о щит капитана-дворфа. Мардук оставил себе рукоять, а сломанный клинок отшвырнул как бесполезный.",
			full = "Близ Перекрестка Корина рунический меч рыцаря смерти Мардука Блэкпула разбился о щит капитана-дворфа. Мардук оставил себе рукоять, а сломанный клинок отшвырнул как бесполезный. Но клинок ушёл в землю, и под ним разверзлась бездна, наполнившаяся тёмной водой.\n\nТо, что осталось, противоестественно до самого основания, в отличие от соседнего Морового оврага — обычного природного ущелья.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Озеро Мерельдар",
			short = "Воды озера Мерельдар к югу от Перекрестка Корина густо пропитаны чумой, а под их поверхностью движутся порченые водяные элементали.",
			full = "Воды озера Мерельдар к югу от Перекрестка Корина густо пропитаны чумой, а под их поверхностью движутся порченые водяные элементали. На берегу стоят развалины старого дома, а также хижина и паром, которые когда-то служили ныне заброшенной ферме.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Часовня Последней Надежды",
			short = "У подножия гор к востоку от Чумных земель стоит часовня, куда более древняя, чем окружающие её руины, — одна из старейших и самых почитаемых святынь, когда-либо воздвигнутых Церковью Святого Света.",
			full = "У подножия гор к востоку от Чумных земель стоит часовня, куда более древняя, чем окружающие её руины, — одна из старейших и самых почитаемых святынь, когда-либо воздвигнутых Церковью Святого Света.\n\nПаладины, не пожелавшие идти путём, которым пошёл Алый орден, ушли в Восточные Чумные земли и сделали эту часовню своей базой, назвав себя Серебряным Рассветом. Сначала их вёл лорд Раймонд Джордж, а после его смерти его место занял лорд Максвелл Тиросс. В отличие от Алого ордена, они никого не отвергали из-за его расы.\n\nХотя Серебряный Рассвет держится особняком от Алого ордена, часовня остаётся нейтральной землёй, где обе стороны до сих пор встречаются, чтобы поговорить друг с другом.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "Поместье Маррисов",
			short = "Поместье Маррисов стоит на невысоком гребне над главной дорогой края — ферма, некогда принадлежавшая Натаносу Маррису.",
			full = "Поместье Маррисов стоит на невысоком гребне над главной дорогой края — ферма, некогда принадлежавшая Натаносу Маррису. Какое-то время здесь жил его двоюродный брат Стефон, а Сильвана Ветрокрылая, как известно, навещала Натаноса под этой крышей.\n\nОсвобождённый Королевой-банши после того, как она подняла Отрекшихся в Подгороде, Натанос вернулся в утраченный дом и по её приказу вновь сделал его своим. Отсюда он привлекал воинов Орды к борьбе с Плетью и Алым орденом, всё ещё наводняющими Чумные земли, и собирал реликвии битвы при Дарроушире, храня их в поместье по причинам, которых никому не открывал.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Мазра'Алор",
			short = "В самом сердце Зул'Машара возвышается Мазра'Алор — зиккурат из сложенных камней, стоящий над окружающими его разорёнными землями.",
			full = "В самом сердце Зул'Машара возвышается Мазра'Алор — зиккурат из сложенных камней, стоящий над окружающими его разорёнными землями. Племя Моходеров до сих пор удерживает его, и их темные охотники с его высоты несут дозор над поселением троллей внизу.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Северный Дол",
			short = "Северный Дол — разрушенный город к северу от Часовни Последней Надежды, на границе Кель'Таласа. Здесь Телан Фордринг отрёкся от ордена Серебряной Длани ради Алого ордена.",
			full = "Северный Дол — разрушенный город к северу от Часовни Последней Надежды, на границе Кель'Таласа. Здесь Телан Фордринг отрёкся от ордена Серебряной Длани ради Алого ордена.\n\nТеперь среди развалин бродят банши и незримые соглядатаи. В соседнем озере обитают порченые водяные элементали. Ничего живого здесь не осталось.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Башня Северного перевала",
			short = "Башня Северного перевала — самая северная из сторожевых башен Восточных Чумных земель; она отмечает дорогу к Призрачным землям Кель'Таласа.",
			full = "Башня Северного перевала — самая северная из сторожевых башен Восточных Чумных земель; она отмечает дорогу к Призрачным землям Кель'Таласа. Плеть прокатилась по Лордерону, и башня до сих пор носит её шрамы.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "Ядовитая поляна",
			short = "Ядовитая поляна лежит на холме к северу от Часовни Последней Надежды, и скверна поразила её сильнее, чем окружающие Чумные земли.",
			full = "Ядовитая поляна лежит на холме к северу от Часовни Последней Надежды, и скверна поразила её сильнее, чем окружающие Чумные земли. Воздух здесь густой и болезненно-зелёный, а земля окрасилась в тёмно-лиловый цвет, и ничто зелёное на ней не растёт.\n\nПлеть сделала поляну своей: на отравленной земле стоят чумной котёл, бойня и несколько зиккуратов, а создания Плети бродят здесь во множестве.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Моровой овраг",
			short = "Моровой овраг — глубокое ущелье в поражённых скверной Восточных Чумных землях; скорее всего, когда-то здесь было озеро, высохшее, когда разразилась чума нежити.",
			full = "Моровой овраг — глубокое ущелье в поражённых скверной Восточных Чумных землях; скорее всего, когда-то здесь было озеро, высохшее, когда разразилась чума нежити. Теперь оно почти совсем пересохло и зияет раной в земле, а в его глубинах обитают слизни, порождённые давней порчей.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Проклятый лес",
			short = "Когда-то деревья к югу от Стратхольма стояли зелёными и безмятежными — лес, не так уж непохожий на Элвиннский, а у каменной арки на его опушке ютилась небольшая деревушка.",
			full = "Когда-то деревья к югу от Стратхольма стояли зелёными и безмятежными — лес, не так уж непохожий на Элвиннский, а у каменной арки на его опушке ютилась небольшая деревушка. Именно здесь сержант Мориган, лордеронский солдат, родившийся в этой деревне, первым заметил, как отравленное зерно из Андорала творит своё чёрное дело на этой земле, когда Кел'Тузад приступил к своей работе. Его предупреждение опоздало для королевства, и по той самой дороге, которую он охранял, позднее проехал принц Артас на пути в Стратхольм.\n\nТо, что осталось после, уже не было лесом. Сама почва стала губчатой под ногами, а грибы и поганки разрослись до размеров деревьев, возвышаясь над остатками старого леса. Они выдыхают тёмно-бурый газ, похожий на испарения, что поднимаются над чумными котлами Плети, хотя никто не может сказать наверняка, растут ли грибы просто на отравленной земле или же Плеть выращивает их, чтобы шире распространять свою заразу. Именно из-за этого превращения лес и получил своё новое имя.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Сторожка Кель'Литиен",
			short = "Сторожка Кель'Литиен была лагерем Странников неподалёку от Кель'Таласа — местом тепла и радушия. Таким её и запомнил Лор'темар Терон по собственным визитам, когда его тепло встречали соотечественники, для которых она была домом.",
			full = "Сторожка Кель'Литиен была лагерем Странников неподалёку от Кель'Таласа — местом тепла и радушия. Таким её и запомнил Лор'темар Терон по собственным визитам, когда его тепло встречали соотечественники, для которых она была домом. Когда-то в сторожке хранилось немало эльфийских документов, некоторые из них касались королевской семьи и генерала следопытов Луносвета. Ко времени Второй войны охотников здесь возглавлял Рентар Ястребиное Копьё.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Лагерь Алого ордена",
			short = "На восточном берегу озера Мерельдар, неподалёку от религиозного оплота Длани Тира, за своими баррикадами стоит Лагерь Алого ордена, укрепивший оборону против всего, что может нагрянуть.",
			full = "На восточном берегу озера Мерельдар, неподалёку от религиозного оплота Длани Тира, за своими баррикадами стоит Лагерь Алого ордена, укрепивший оборону против всего, что может нагрянуть.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "Алая Базилика",
			short = "Алая Базилика стоит в Длани Тира — высший престол веры Алого ордена, связанный с соседним аббатством и с далёким Монастырём Алого ордена в Тирисфальских лесах.",
			full = "Алая Базилика стоит в Длани Тира — высший престол веры Алого ордена, связанный с соседним аббатством и с далёким Монастырём Алого ордена в Тирисфальских лесах. Её удерживает лорд-рыцарь Валделмар, чья преданность делу ордена безгранична.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Стратхольм",
			short = "Гибель Стратхольма началась с зерна. Поставки из Андорала, тайно заражённые Культом Проклятых, пошли на хлеб, который ели горожане, так и не узнавшие, что умирают.",
			full = "Гибель Стратхольма началась с зерна. Поставки из Андорала, тайно заражённые Культом Проклятых, пошли на хлеб, который ели горожане, так и не узнавшие, что умирают. Принц Артас Менетил прибыл сюда вместе с Утером Светоносным и Джайной Праудмур и увидел, что чума уже пустила корни. Веря, что единственная оставшаяся милость — быстрая смерть, а не медленное превращение в ходячих мертвецов, Артас приказал предать город огню. Утер и Джайна отказались и увели своих людей. Артас — нет. Огонь охватил улицы, и почти все жители Стратхольма погибли, прежде чем повелитель ужаса Мал'Ганис, ради убийства которого пришёл Артас, со смехом ускользнул, оставив принца сжигать то, что осталось.\n\nЭтого оказалось недостаточно. Мёртвые всё равно восстали, и город стал столицей Плети в Лордероне, где правил сначала лич Кел'Тузад, а затем рыцарь смерти барон Ривендер.\n\nСтратхольм горит до сих пор.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Долина Ужаса",
			short = "Долина Ужаса лежит на краю Проклятого леса; её улицы опустели и отданы Плети и зачумлённым зверям. Лишь торговец Август Помешанный и охотник за призраками Эган всё ещё задерживаются среди руин.",
			full = "Долина Ужаса лежит на краю Проклятого леса; её улицы опустели и отданы Плети и зачумлённым зверям. Лишь торговец Август Помешанный и охотник за призраками Эган всё ещё задерживаются среди руин.\n\nВ городе обитают призраки. Духи бродят по его переулкам, и в некоторых местах сама Долина Ужаса словно колеблется: материальный мир прогибается под тяжестью мира, лежащего за его гранью, будто земля помнит какую-то давнюю муку, которую не может отпустить.\n\nИменно это беспокойство привлекло сюда лорда Грейсона Тенелома, увидевшего в духах достойное испытание для паладинов, стремящихся доказать, что они достойны суда и жертвы, — шаг к тому, чтобы заслужить боевых коней, предназначенных лишь для истинно достойных. Кем были эти духи при жизни, нигде не записано; известно лишь, что их мука была настолько реальной, что искажала город вокруг них.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Туннель Ужаса",
			short = "Туннель пронзает гору к северо-западу от Долины Ужаса и тянется на юг, туда, где выходит к реке Тондрорил.",
			full = "Туннель пронзает гору к северо-западу от Долины Ужаса и тянется на юг, туда, где выходит к реке Тондрорил. Проход сплошь забит нерубскими некрорахнидами, а среди них рыщет нечто худшее — нерубский надзиратель, куда более смертоносный, чем его сородичи.\n\nУ выхода из туннеля к реке несёт дозор Тирион Фордринг, стоя на свету перед тьмой прохода.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Река Тондрорил",
			short = "Река Тондрорил разделяет Западные и Восточные Чумные земли. Она берёт начало далеко на севере, у Туннеля Ужаса, и течёт на юг, пока не впадает в озеро Дарроумир, а дальше продолжается уже как река Дарроумир.",
			full = "Река Тондрорил разделяет Западные и Восточные Чумные земли. Она берёт начало далеко на севере, у Туннеля Ужаса, и течёт на юг, пока не впадает в озеро Дарроумир, а дальше продолжается уже как река Дарроумир.\n\nЕё берега принадлежат скверне. Сырую землю облепили личинки и летучие мыши-вампиры, по мелководью рыщут чумные медведи и пауки, а там, где течение замедляется, притаились хрустогрызы.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Длань Тира",
			short = "Длань Тира — укреплённый город людей, один из последних оплотов живых против Плети в этом краю.",
			full = "Длань Тира — укреплённый город людей, один из последних оплотов живых против Плети в этом краю. Его окрестности сохранились куда лучше, чем остальные Чумные земли, хотя деревья и травы всё равно гниют.\n\nГород — одна из старейших и самых почитаемых святынь Церкви Света; он почти целиком состоит из храмов, а венчают его Алая Базилика и укреплённое аббатство.\n\nКогда пришла Плеть и Восточные леса превратились в Чумные земли, Длань Тира не пала. Под началом лорда Валделмара город выдерживал ежедневные штурмы, укрываясь сначала под защитой рыцарей Серебряной Длани, а затем Алого ордена. Отсюда отправляли припасы и подкрепления в другие владения ордена, а из Стратхольма ежедневно приходили донесения с гонцами, которым приходилось с боем пробиваться по дорогам, пропитанным чумой.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "Крипта",
			short = "Крипта — склеп на юго-западе Восточных Чумных земель, где обитают тролли-нежить во главе с Зельдарром Изгоем, восставшим из мёртвых троллем-громилой.",
			full = "Крипта — склеп на юго-западе Восточных Чумных земель, где обитают тролли-нежить во главе с Зельдарром Изгоем, восставшим из мёртвых троллем-громилой. Отсюда он совершает набеги на погребальную яму Серебряного Рассвета у Часовни Последней Надежды, похищая тела для своих нужд.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Зул'Машар",
			short = "Когда-то Зул'Машар был столицей племени Моходеров, лесных троллей северо-востока Восточных Чумных земель.",
			full = "Когда-то Зул'Машар был столицей племени Моходеров, лесных троллей северо-востока Восточных Чумных земель. Долгие войны с людьми Лордерона привели земли племени в упадок, а последовавшая за ними чума нежити довершила разорение. Город, что некогда правил здесь, теперь лишь тень своей былой славы.\n\nЕго зиккурат Мазра'Алор по-прежнему стоит в сердце города, и теперь его удерживают военачальник Треш'джин и Зул'Брин Кривосук. Но самих Моходеров тайно превращает чума, и Зул'Машару грозит стать не более чем оплотом нежити.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Предгорья Хилсбрада: 29 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Лазуритовый рудник",
			short = "Лазуритовый рудник лежит на юго-западной окраине Предгорий Хилсбрада, и его холм когда-то считался частью Гильнеаса, пока не поднялась Стена Седогрива, отрезавшая королевство от мира.",
			full = "Лазуритовый рудник лежит на юго-западной окраине Предгорий Хилсбрада, и его холм когда-то считался частью Гильнеаса, пока не поднялась Стена Седогрива, отрезавшая королевство от мира.\n\nРудник принадлежит Альянсу: в нём трудятся рудокопы под присмотром стражи, а его железо идёт в оружейные Альянса.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Берег Промозглого Ветра",
			short = "Берег Промозглого Ветра получил своё имя от холодного ветра, который дует с Западных Чумных земель и устремляется через лощину внизу. Возвышенность венчают древние руины троллей — всё, что осталось от их строителей.",
			full = "Берег Промозглого Ветра получил своё имя от холодного ветра, который дует с Западных Чумных земель и устремляется через лощину внизу. Возвышенность венчают древние руины троллей — всё, что осталось от их строителей. Когда-то этот перевал принадлежал королевству Лордерон. Теперь в руинах обитает тролль джунглей Бат'ра Ветростраж.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Уступ Коррана",
			short = "Уступ Коррана — второй из четырёх пальцев Хилсбрада. Этот холм удерживает Синдикат.",
			full = "Уступ Коррана — второй из четырёх пальцев Хилсбрада. Этот холм удерживает Синдикат.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Логово Раздробленного Хребта",
			short = "Логово Раздробленного Хребта находится неподалёку от Руин Альтерака — это пещера, вырытая в земляном холме.",
			full = "Логово Раздробленного Хребта находится неподалёку от Руин Альтерака — это пещера, вырытая в земляном холме. Вокруг неё раскинули свои стоянки огры из клана Раздробленного Хребта — многочисленные и свирепые, они удерживают склоны над лежащим внизу разрушенным городом.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Холм Дарроу",
			short = "Холм Дарроу лежит на севере Предгорий Хилсбрада, под Высоким отрогом.",
			full = "Холм Дарроу лежит на севере Предгорий Хилсбрада, под Высоким отрогом. По его открытым полям бродят горные львы и олени, а в Пещерах предгорий устроили логово йети — среди жил альтеракского гранита, пронизывающих скалу.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Дун Гарок",
			short = "Дун Гарок стоит на холмах Предгорий Хилсбрада — это крепость дворфов под командованием капитана Железной Горы.",
			full = "Дун Гарок стоит на холмах Предгорий Хилсбрада — это крепость дворфов под командованием капитана Железной Горы. Его гарнизон охраняет людей Хилсбрада и присматривает за Лазуритовым рудником, и Отрекшиеся не могут стерпеть такого соседства: они сулят золото всякому, кто проберётся в крепость и перебьёт её дворфов.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Крепость Дарнхольд",
			short = "Крепость Дарнхольд лежит в развалинах к востоку от Мельницы Таррен: её казармы и башня магов обрушились, а арена умолкла.",
			full = "Крепость Дарнхольд лежит в развалинах к востоку от Мельницы Таррен: её казармы и башня магов обрушились, а арена умолкла. Когда-то здесь был центр системы лагерей для интернированных орков, созданной после Второй войны, и правил ею генерал-лейтенант Эделас Блэкмур — самовлюблённый пьяница, использовавший лагерь ради собственного возвышения.\n\nИменно Блэкмур нашёл младенца-орка среди тел убитых родителей и привёз его в крепость, назвав Траллом. Мальчика растили и учили здесь; его выкормила человеческая женщина, чья дочь, Тарета Фокстон, крепко с ним сдружилась. Годами Блэкмур избивал мальчика и выставлял его на бои на арене, наживаясь на его силе, чтобы подняться в чинах. Тарета тайно писала ему, и он отвечал ей, пока наконец не сообщил, что собирается бежать. Она устроила отвлекающий манёвр, позволивший ему ускользнуть, встретила его за стенами и дала ему припасов в дорогу.\n\nСпустя годы он действительно вернулся — во главе собранных им свободных орков. Тралл осадил Дарнхольд, убил Блэкмура в поединке и воззвал к духу земли, чтобы сровнять крепость с землёй. Оставшиеся руины с тех пор привлекли Синдикат, который считает их своими.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Восточное побережье",
			short = "Восточное побережье тянется вдоль юго-восточного берега Предгорий Хилсбрада, а его двойник лежит дальше к западу вдоль того же берега.",
			full = "Восточное побережье тянется вдоль юго-восточного берега Предгорий Хилсбрада, а его двойник лежит дальше к западу вдоль того же берега. Эта полоса песка принадлежит нагам из клана Пронзающего Гребня, которые удерживают пляжи и мелководье за ними.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Перекресток Висельников",
			short = "На Перекрестке Висельников, где сходятся дороги в Альтеракских горах неподалёку от разрушенных чертогов Альтерака, стоит разбитая и пустая дозорная башня.",
			full = "На Перекрестке Висельников, где сходятся дороги в Альтеракских горах неподалёку от разрушенных чертогов Альтерака, стоит разбитая и пустая дозорная башня. Теперь перекрёсток удерживают огры из клана Раздробленного Хребта, рыщущие среди камней вокруг остатков башни, и больше здесь ничто не шевелится.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Возвышенность Гэвина",
			short = "Возвышенность Гэвина — последний из четырёх холмов Хилсбрада и самый охраняемый.",
			full = "Возвышенность Гэвина — последний из четырёх холмов Хилсбрада и самый охраняемый.\n\nПо этому холму бродят горные львы, и среди них — Арага, выделяющаяся своим необычным окрасом.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Промерзшая пещера",
			short = "В Альтеракских горах есть пещера, где укрываются горные йети, а у её входа часто можно встретить Скхоула.",
			full = "В Альтеракских горах есть пещера, где укрываются горные йети, а у её входа часто можно встретить Скхоула. В её глубине горит Пламя Узеля — костёр, сложенный человеком по имени Гелькулар для ритуала, который должен был превратить его в лича. Мясо, сожжённое на нём, приманивает ко входу могучего йети Ледочрева.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "Высокий отрог",
			short = "Высокий отрог — один из пальцев суши, протянувшихся через Хилсбрад.",
			full = "Высокий отрог — один из пальцев суши, протянувшихся через Хилсбрад.\n\nЗдесь, на склоне утёса, отдыхает среди своих детёнышей Арага.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Хилсбрадские поля",
			short = "Хилсбрадские поля, плодородные и возделанные, раскинулись на западе Предгорий Хилсбрада и кормят Южнобережье, а заодно и город Хилсбрад.",
			full = "Хилсбрадские поля, плодородные и возделанные, раскинулись на западе Предгорий Хилсбрада и кормят Южнобережье, а заодно и город Хилсбрад. Землю покрывают яблоневые сады, тыквенные грядки и пастбища со скотом, а на Лазуритовом руднике по-прежнему трудятся горожане.\n\nВ начале Второй войны Молот Рока обрушил свои армии на Хилсбрад и приказал уничтожить его с чудовищной жестокостью, чтобы преподать урок королевствам людей. После войны город отстроили, и он по-прежнему обитаем — один из немногих уголков бывшего Лордерона, который не был ни брошен в руинах, ни поглощён Алым орденом. Его стражники всё ещё носят гербовые накидки своего королевства, а судья Бернсайд правит из ратуши вместе с Советом Хилсбрада и клерком Горацием Белоконем.\n\nТеперь полям вновь грозит опасность — от войск верховного палача Дарталии из Мельницы Таррен. Крестьяне и фермеры терпят набеги, но многие из них в ответ устраивают нежити собственные засады, вооружённые кузнецом Верринтаном и его подмастерьями.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Мглистый берег",
			short = "Мглистый берег тянется вдоль озера Лордамер между Овчарней Дандреда и Далараном. По его мелководью неспешно бродят черепахи.",
			full = "Мглистый берег тянется вдоль озера Лордамер между Овчарней Дандреда и Далараном. По его мелководью неспешно бродят черепахи.\n\nЭтот берег удерживают двое воинов Алого ордена, набрасываясь на всякого, кто подойдёт слишком близко, словно сама земля нуждается в охране.\n\nЗа водой виднеются Рассветные острова, а сквозь туман смутно и мрачно проступает Крепость Фенриса.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Владение Нетандера",
			short = "Владение Нетандера лежит чуть восточнее Южнобережья; его поля давно заброшены и заполонены гноллами из племени Грязного Рыла — больше нигде это племя не встречается.",
			full = "Владение Нетандера лежит чуть восточнее Южнобережья; его поля давно заброшены и заполонены гноллами из племени Грязного Рыла — больше нигде это племя не встречается. Здесь в изобилии растут огромные белые грибы, называемые цветами Грязного Рыла, которые когда-то искал аптекарь Лидон для своего смертоносного Эликсира агонии.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Остров Очищения",
			short = "К югу от берега Хилсбрада поднимается спираль из камня, увенчанная кладбищем и разбитыми остатками дозорной башни. До Первой войны Остров Очищения принадлежал Кул Тирасу.",
			full = "К югу от берега Хилсбрада поднимается спираль из камня, увенчанная кладбищем и разбитыми остатками дозорной башни. До Первой войны Остров Очищения принадлежал Кул Тирасу.\n\nЧто было потом, неизвестно, но мёртвые здесь не знают покоя. По острову бродят десятки духов — люди и дворфы, паладины и жрецы, монахи и маги, проклятые души, прикованные к его камням.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Поместье Черного Ворона",
			short = "Поместье Черного Ворона намеренно стоит в стороне от мира.",
			full = "Поместье Черного Ворона намеренно стоит в стороне от мира. Добраться до него можно лишь по узкой извилистой тропе, что поднимается с плато к северо-западу от Крепости Дарнхольд и петляет среди гор и через небольшую пещеру, прежде чем выйти к усадьбе, — на такое место случайно не набредёшь. Чужакам здесь не рады, и те, кто служит лорду Джораху Черному Ворону, следят, чтобы так было и впредь.\n\nПоместье принадлежит ему; его оранжевые крыши выстроены в старинном стиле Альтерака, королевства, которому эта земля принадлежала до Первой войны.\n\nВ последующие годы по этой части нагорья бродил Синдикат, и Черный Ворон противостоял этой напасти, укрывшись за своей потайной тропой и охраняемыми воротами.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Кровавая низина",
			short = "Глубоко в Альтеракских горах огры из клана Раздробленного Хребта устроили себе дом в Кровавой низине — кургане, утопленном в холмах.",
			full = "Глубоко в Альтеракских горах огры из клана Раздробленного Хребта устроили себе дом в Кровавой низине — кургане, утопленном в холмах. Об этом месте известно немногим больше, чем об удерживающих его ограх, но одно лишь название говорит о том, что ждёт всякого, кто забредёт слишком близко.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Возвышенность Соферы",
			short = "Возвышенность Соферы — один из четырёх пальцев Хилсбрада. Холм удерживает Синдикат, наблюдая за землёй внизу.",
			full = "Возвышенность Соферы — один из четырёх пальцев Хилсбрада. Холм удерживает Синдикат, наблюдая за землёй внизу.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
