		["southpoint tower"] = {
			name = "Южная башня",
			short = "Южная башня стоит на самой западной окраине Предгорий Хилсбрада, чуть южнее дороги, что ведёт дальше к Серебряному бору.",
			full = "Южная башня стоит на самой западной окраине Предгорий Хилсбрада, чуть южнее дороги, что ведёт дальше к Серебряному бору. Каменная кладка стара и покрыта трещинами — дозорный пост, брошенный на разрушение, хотя саму башню так и не повалили в боях, прокатившихся через эти места. Неподалёку, между Мельницей Таррен и Южнобережьем, стоит ещё одна безымянная башня, которую тоже пощадило разорение, охватившее остальные предгорья.",
