		["strahnbrad"] = {
			name = "Странбрад",
			short = "Странбрад лежит в северо-восточных предгорьях Альтеракских гор; его ратуша и кузница теперь пустуют.",
			full = "Странбрад лежит в северо-восточных предгорьях Альтеракских гор; его ратуша и кузница теперь пустуют. Когда-то он принадлежал королевству Альтерак, а после Второй войны перешёл в руки Лордерона.\n\nГибель города началась незадолго до Третьей войны, когда на него обрушились орки Черной горы, чтобы захватить рабов для жертвоприношений Пылающему Легиону. У Странбрада было лишь несколько пехотинцев для обороны, но весть успела дойти до рыцарей Серебряной Длани. Утер Светоносный поскакал вперёд, чтобы попытаться перехватить нападающих, а принца Артаса Менетила отправили удерживать сам город. Артас не успел вовремя. Дин, Джо, Майк, Скотт и многие другие погибли прежде, чем он достиг Странбрада, а уцелевшие защитники присоединились к нему, чтобы разгромить орков и убить надсмотрщика за рабами, возглавлявшего набег. Альянс победил, но жителей Странбрада уже не было в живых.\n\nПозднее Синдикат занял разрушенный город и сделал его опорой для захвата Альтеракских гор, а в одной из его камер держал пленного орка Гол'дира, заставляя его как раба таскать грузы и копать.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Мельница Таррен",
			short = "Когда-то Мельница Таррен была простым лордеронским городком среди лугов у подножия Альтеракских гор.",
			full = "Когда-то Мельница Таррен была простым лордеронским городком среди лугов у подножия Альтеракских гор. В первые дни Второй войны лучники высших эльфов из Луносвета, посланные на юг, чтобы своими глазами увидеть угрозу со стороны орков, попали в засаду близ города и были уведены в соседний лагерь для пленных. Король Теренас отправил солдат Альянса освободить их, и спасение удалось. Именно этот успех побудил совет Луносвета присоединить армии Кель'Таласа к Альянсу Лордерона.\n\nМельница Таррен не осталась в руках людей. Со временем её захватили Отрекшиеся и оставили её такой же, как и другие свои владения: церковь, горстка домов, сгнившие сады — всё стоит, но ничто не цело. Отсюда Отрекшиеся ведут войну против сил Альянса в Южнобережье и Дун Гароке, а земля между Мельницей Таррен и Южнобережьем прославилась бесконечными стычками между двумя городами, ни один из которых не может сломить другой.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
