	[1425] = {
		["aerie peak"] = {
			name = "Заоблачный Пик",
			short = "Дворфы Громового Молота не сразу выбрали Внутренние земли.",
			full = "Дворфы Громового Молота не сразу выбрали Внутренние земли. Их домом был Грим Батол, укрытый глубоко в горе, пока не закончилась Война Трех Кланов и дворфы, вернувшись, не обнаружили, что их крепость отравлена смертью Модгуд. Жить в Грим Батоле снова было невозможно. Поэтому дворфы Громового Молота построили новый дом здесь — на склоне горы, а не внутри неё: после ужасов подземных боёв с дворфами Черного Железа они не желали вновь хоронить себя в камне. Именно из-за той войны Заоблачный Пик открыт небу.\n\nИменно отсюда Курдран Громовой Молот повёл своих всадников на грифонах против войск орков, посланных ударить по Внутренним землям для отвода глаз, пока настоящая армия Орды двигалась на Кель'Талас. Войска Андуина Лотара пришли ему на помощь и помогли изгнать орков и лесных троллей с земель Громового Молота, и за это Курдран поклялся в верности своего клана Альянсу.\n\nФалстад Громовой Молот, ставший верховным таном, когда Курдран не вернулся, по-прежнему правит Заоблачным Пиком. Лесные тролли Внутренних земель, считающие дворфов Громового Молота захватчиками земли своих предков, до сих пор совершают набеги на грифоньи гнёзда, а высшие эльфы Кель'Данила остаются союзниками дворфов в борьбе с тем же врагом.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
