		["hiriwatha"] = {
			name = "Хири'вата",
			short = "Хири'вата принадлежит троллям племени Сухокожих: эта деревня лежит к югу от Сторожки Кель'Данил во Внутренних землях, в глубине леса, который они считают своим.",
			full = "Хири'вата принадлежит троллям племени Сухокожих: эта деревня лежит к югу от Сторожки Кель'Данил во Внутренних землях, в глубине леса, который они считают своим.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
