		["jinthaalor"] = {
			name = "Джинта'Алор",
			short = "Джинта'Алор уступами поднимается над Внутренними землями; среди городов лесных троллей он уступает размерами лишь Зул'Аману.",
			full = "Джинта'Алор уступами поднимается над Внутренними землями; среди городов лесных троллей он уступает размерами лишь Зул'Аману. Город был возведён во времена империи Амани и назван в честь Джинты, одного из древних вождей Амани.\n\nОн принадлежит племени Порочной Ветви, которое превратило его вершины в крепость жертвоприношений. Там правит коварная жрица Ведьмиса, служащая Хаккару Свежевателю Душ, и тролли Порочной Ветви безжалостно охотятся на более слабое племя Сломанного Клыка, чтобы утолить голод своего бога. Во время одного из таких набегов был схвачен старейшина Сломанный Клык, и его до сих пор держат в плену в городе; в той же схватке попал в плен и капитан его стражи, охотник Малькор, — его казнили, а останки бросили волкам и слизням, которых держат за стенами.\n\nКлан Громового Молота и племя Сломанного Клыка, объединённые общей обидой на Порочную Ветвь, вместе осадили город, чтобы положить конец набегам и отомстить за своих погибших.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Отвесные скалы",
			short = "Отвесные скалы отмечают место, где Внутренние земли перестают быть горами и становятся небом.",
			full = "Отвесные скалы отмечают место, где Внутренние земли перестают быть горами и становятся небом. Великая река, что вьётся по этому краю, собирается здесь воедино и низвергается с обрыва одним огромным водопадом на берег внизу.\n\nСкалы круты и обманчиво высоки. Многие, подходившие к самому краю, недооценивали высоту и срывались навстречу гибели.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
