		["plaguemist ravine"] = {
			name = "Чумная лощина",
			short = "Там, где горная стена расступается к западу от Сторожки Кель'Данил, висит туман, отмечая лощину, что уходит на север, к Каэр Дарроу. В этом проходе ничто не живёт.",
			full = "Там, где горная стена расступается к западу от Сторожки Кель'Данил, висит туман, отмечая лощину, что уходит на север, к Каэр Дарроу. В этом проходе ничто не живёт. Ни одна птица не пролетает над ним, ни один зверь не устраивает логова в его камнях.\n\nВнутренние земли вокруг остаются зелёными и чистыми, но лощина дышит чем-то иным — дымкой, чуждой лесу. Потому это место и зовётся теперь так: Чумная лощина, по болезненному туману, что отравляет лишь этот путь, тогда как остальная земля остаётся нетронутой.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Сторожка Кель'Данил",
			short = "Сторожка Кель'Данил — одно из последних настоящих поселений высших эльфов, большее из двух таких поселений, что ещё остались в Лордероне.",
			full = "Сторожка Кель'Данил — одно из последних настоящих поселений высших эльфов, большее из двух таких поселений, что ещё остались в Лордероне. После Третьей войны она стала местом переписки: её посланники налаживали связи с другими народами Альянса. Эти усилия принесли эльфам Высокодолья союз с дворфами Громового Молота и навлекли на них ненависть троллей Сломанного Клыка, которые желали перебить эльфов и сжечь их записи. Документы уцелели: записи о смертях, рождениях, сменах времён года и о каждом договоре, который когда-либо заключали эльфы.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Деревня Сломанного Клыка",
			short = "Деревня Сломанного Клыка стоит на побережье Внутренних земель — последний дом племени лесных троллей, предпочётшего верность выживанию.",
			full = "Деревня Сломанного Клыка стоит на побережье Внутренних земель — последний дом племени лесных троллей, предпочётшего верность выживанию.\n\nКогда во Второй войне старая Орда была разбита, а орки попали в плен, их тюремщики обратились против бывших союзников, и племена лесных троллей по всему краю без колебаний покинули Орду. Но не Сломанный Клык. Им недоставало сил, чтобы освободить пленных орков, которые, впрочем, и сами не особенно стремились на свободу, однако их неизменная верность сделала их мишенью для других троллей, не желавших больше иметь с орками ничего общего. Изгнанные со своих земель, тролли Сломанного Клыка бежали на побережье Внутренних земель в надежде, что уединение убережёт их, и выстроили там свою деревню.\n\nСо временем до них дошла весть, что Тралл возродил Орду и вернул свой народ к шаманским обычаям предков. Сломанный Клык отправил на поиски Тралла самых быстрых гонцов, и из той встречи родился договор о дружбе между племенем и новой Ордой. Другие лесные тролли так и не простили этого, называя Сломанный Клык слабаками и изменниками, а сами тролли Сломанного Клыка считают истинными предателями всех, кто покинул Орду.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Серадан",
			short = "На северо-востоке Внутренних земель лежит Серадан, где стоит огромный круглый портал, открытый в Изумрудный Сон. Лес принадлежит зелёным драконам, что пришли сюда охранять священный для их рода порог.",
			full = "На северо-востоке Внутренних земель лежит Серадан, где стоит огромный круглый портал, открытый в Изумрудный Сон. Лес принадлежит зелёным драконам, что пришли сюда охранять священный для их рода порог. Среди этих деревьев поселились драконы Ротос и Сноловец.\n\nБольшинство стражей леса — драконорождённые, порождённые силой стаи. Они ходят тройками — изумрудный оракул в окружении стражей ветвей и древесных хранителей, — патрулируя спутанные тропы и неусыпно охраняя путь в Сон.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Шадра'Алор",
			short = "Во Внутренних землях стоит Шадра'Алор, поселение, возведённое лесными троллями империи Амани. Здесь можно было призвать и низвести лоа Шадру — это место было отведено исключительно для этой цели.",
			full = "Во Внутренних землях стоит Шадра'Алор, поселение, возведённое лесными троллями империи Амани. Здесь можно было призвать и низвести лоа Шадру — это место было отведено исключительно для этой цели.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Шаол'вата",
