	-- Дун Морог: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Ферма Янтарленов",
			short = "Ферма Янтарленов стоит в стороне от дороги на Лок Модан, к северу от карьера Гол'Болар; здесь дворфы из семьи Янтарленов разводят свои стада наперекор холодам Дун Морога.",
			full = "Ферма Янтарленов стоит в стороне от дороги на Лок Модан, к северу от карьера Гол'Болар; здесь дворфы из семьи Янтарленов разводят свои стада наперекор холодам Дун Морога. Рудра Янтарлен выращивает здесь породистых баранов, а юная Ярлин не отходит от своих снежных кроликов.\n\nСтада не знают покоя. Вендиго по имени Вагаш повадился охотиться на скот фермы, и Янтарленам приходится защищать своё хозяйство от его голода.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Старая Наковальня",
			short = "В Холодной долине стоит Старая Наковальня — чертог, построенный вокруг огромной кузни. Это было первое настоящее поселение, которое дворфы возвели в этих северных краях, место сбора ещё до того, как появились все прочие.",
			full = "В Холодной долине стоит Старая Наковальня — чертог, построенный вокруг огромной кузни. Это было первое настоящее поселение, которое дворфы возвели в этих северных краях, место сбора ещё до того, как появились все прочие. Кузня в его сердце горит до сих пор, хотя кузнецы больше не обучают здесь своему ремеслу.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Поселок Пивоваров",
			short = "Поселок Пивоваров расположен в Долине Промозглого Ветра, неподалёку от Гномрегана; здесь живёт семья Ячменоваров. Ячменовары посвятили себя одному-единственному делу — совершенствованию дворфийского искусства пивоварения.",
			full = "Поселок Пивоваров расположен в Долине Промозглого Ветра, неподалёку от Гномрегана; здесь живёт семья Ячменоваров. Ячменовары посвятили себя одному-единственному делу — совершенствованию дворфийского искусства пивоварения. Молодёжь они отправляют из деревни охранять её от диких зверей и искать редкие ингредиенты для непревзойдённого эля.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Долина Промозглого Ветра",
			short = "Долина Промозглого Ветра тянется с востока на запад между Гномреганом и Караносом, и её тропа хорошо знакома юным дворфам и гномам, что ходят здесь.",
			full = "Долина Промозглого Ветра тянется с востока на запад между Гномреганом и Караносом, и её тропа хорошо знакома юным дворфам и гномам, что ходят здесь. Но долина ветвится и на север, и на юг, и там снег рассказывает иную историю: по белизне широко расползаются пятна крови, и повсюду брошены растерзанные туши животных. Мало кто по доброй воле ходит по этим ответвлениям. Те же, кто решается, отправляются охотиться на виновных в этом зверей, надеясь избавить дворфийские земли от угрозы, и многие не возвращаются. В глубине одной из пещер устроил логово вендиго — тот, кто больше всех повинен в крови на снегу.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Туннель Холодной долины",
			short = "Туннель Холодной долины — узкий выход из Холодной долины, последний отрезок пути, который дворфу предстоит преодолеть, прежде чем он доберётся до Караноса и широких дорог Дун Морога.",
			full = "Туннель Холодной долины — узкий выход из Холодной долины, последний отрезок пути, который дворфу предстоит преодолеть, прежде чем он доберётся до Караноса и широких дорог Дун Морога. Туннель заполонили трогги, и у путников остаётся лишь два выхода: пробежать насквозь со всех ног или прорубить себе кровавую дорогу сквозь захватчиков.\n\nОднажды Фендриг Рыжебород повёл в туннель ещё двенадцать рудокопов, чтобы разобраться с нашествием. В глубине его придавило обвалом. Остальные вернулись, чтобы откопать его, но от их усилий свод туннеля обрушился на них самих. Двенадцать рудокопов погибли. Выжил лишь Фендриг, которого вытащили из-под завала.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Холодная долина",
			short = "Холодную долину укрывает толстый слой снега; со всех сторон её окружают стены гор, и единственный выход из неё — узкий Туннель Холодной долины на северо-востоке.",
			full = "Холодную долину укрывает толстый слой снега; со всех сторон её окружают стены гор, и единственный выход из неё — узкий Туннель Холодной долины на северо-востоке. Этот проход кишит троггами-налётчиками, грубыми тварями, из-за которых путь в Каранос и Стальгорн давно стал опасен для всякого, кто идёт в одиночку.\n\nЗа туннелем дорога поднимается на восток, затем ведёт на север через Каранос и, петляя меж гор, выводит к самим вратам Стальгорна.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Форт Мерзлогривов",
			short = "Форт Мерзлогривов стоит на западной окраине холодных гор Дун Морога, к югу от Гномрегана: это россыпь построек, связанных с системой пещер, уходящих в склон горы.",
			full = "Форт Мерзлогривов стоит на западной окраине холодных гор Дун Морога, к югу от Гномрегана: это россыпь построек, связанных с системой пещер, уходящих в склон горы. Здесь расположен главный лагерь снежных троллей племени Мерзлогривов, которые удерживают эти земли; на каждом подступе стоят их охотники за головами и свежеватели.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Врата Стальгорна",
			short = "Врата Стальгорна высятся там, где огромный подъём Дун Морога встречается с горой; их видно за много миль над снегами задолго до того, как путник к ним подойдёт.",
			full = "Врата Стальгорна высятся там, где огромный подъём Дун Морога встречается с горой; их видно за много миль над снегами задолго до того, как путник к ним подойдёт. Они служат порогом между открытыми землями дворфов и самим Стальгорном.\n\nПройдя через них, путник оказывается под взглядом огромной статуи Верховного короля Модимуса Старая Наковальня, поставленной сразу за входом, чтобы никто не вошёл в город, не пройдя сперва под его взором.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Гномреган",
			short = "Гномреган — подземная столица одноимённого королевства гномов, выкованное из железа свидетельство гномьей гениальности, честолюбия и изобретательности.",
			full = "Гномреган — подземная столица одноимённого королевства гномов, выкованное из железа свидетельство гномьей гениальности, честолюбия и изобретательности.\n\nВо время Третьей войны его погубило нашествие троггов. Потрясения, охватившие обиталища титанов, пробудили троггов от сна, и они хлынули в город снизу. В отчаянной попытке уничтожить захватчиков Главный механик Гелбин Меггакрут по совету своего советника Сикко Термоштепселя приказал открыть клапаны давления огромных дробильных машин и выпустить по всему Гномрегану ядовитую радиацию. Газ убил часть троггов, но других лишь сделал сильнее, а почти восемьдесят процентов гномов погибли за считаные дни. Уцелевшие бежали под защиту Стальгорна. Другие же превратились в жутких, безмозглых и злобных лепрогномов, что до сих пор бродят по разрушенным туннелям.\n\nСам обезумевший от радиации Термоштепсель провозгласил себя «королём Гномрегана» и захватил власть в отравленном городе, ведя армию троггов и лепрогномов по его разорённым залам и мастерским.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Карьер Гол'Болар",
			short = "Карьер Гол'Болар врезан в землю на юго-востоке Дун Морога — это лагерь рудокопов, работу которых оборвало то, что выползло из-под земли.",
			full = "Карьер Гол'Болар врезан в землю на юго-востоке Дун Морога — это лагерь рудокопов, работу которых оборвало то, что выползло из-под земли. Дворфы начали раскопки в поисках богатств горы, но разбудили троггов, которые хлынули из глубин рудника и заполонили ямы и туннели, прорытые рудокопами.\n\nОставшийся лагерь — лишь плацдарм, а не победа: дворфы удерживают поверхность, а рудник внизу по-прежнему в руках троггов.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "Серая берлога",
			short = "К юго-западу от Караноса открывается обширная система пещер, глубоко уходящая во льды Дун Морога. Здесь устроили логово вендиго — косматые звери с ледяным дыханием, что сбиваются в стаю против всякого незваного гостя.",
			full = "К юго-западу от Караноса открывается обширная система пещер, глубоко уходящая во льды Дун Морога. Здесь устроили логово вендиго — косматые звери с ледяным дыханием, что сбиваются в стаю против всякого незваного гостя. Их гривы ценятся как обивка для сидений, однако мало кто из отправившихся за ними возвращается без боя: вендиго не разбегаются, а смыкают ряды и выгоняют чужаков когтями и морозным дыханием.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Озеро Хельмово Ложе",
			short = "Озеро Хельмово Ложе почти весь год сковано льдом, настолько толстым, что по нему можно спокойно ходить. Открытой держат лишь одну прорубь, чтобы из-подо льда по-прежнему можно было набирать свежую воду.",
			full = "Озеро Хельмово Ложе почти весь год сковано льдом, настолько толстым, что по нему можно спокойно ходить. Открытой держат лишь одну прорубь, чтобы из-подо льда по-прежнему можно было набирать свежую воду.\n\nНо безопасность кончается у берега. По берегам рыщут волки и другие дикие звери, а в окрестных скалах бродят отбившиеся от своих трогги. К югу от озера стоит заброшенное здание, которое захватили дворфы Черного Железа, нападающие на всякого, кто подойдёт слишком близко.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Заледеневшее озеро",
			short = "В холода Дун Морога Заледеневшее озеро промерзает насквозь, но дворфы из Поселка Пивоваров поддерживают во льду одну прорубь, добывая из-под замёрзшей глади свежую воду и рыбу.",
			full = "В холода Дун Морога Заледеневшее озеро промерзает насквозь, но дворфы из Поселка Пивоваров поддерживают во льду одну прорубь, добывая из-под замёрзшей глади свежую воду и рыбу.\n\nБлиже к середине озера поднимаются два острова, к которым лучше не приближаться. Их захватила стая голодных волков во главе с воргом по имени Тимбер, и из-за них на островах нет никого, кроме зверей, что там хозяйничают.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Мастерская Сталекрута",
			short = "К югу от озера Хельмово Ложе стоит Мастерская Сталекрута — оплот дворфов Черного Железа, нападающих на всякого, кто подойдёт слишком близко. Когда-то это место принадлежало Стурги Сталекруту, пока не попало в руки Черного Железа.",
			full = "К югу от озера Хельмово Ложе стоит Мастерская Сталекрута — оплот дворфов Черного Железа, нападающих на всякого, кто подойдёт слишком близко. Когда-то это место принадлежало Стурги Сталекруту, пока не попало в руки Черного Железа.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["kharanos"] = {
			name = "Каранос",
			short = "Каранос раскинулся среди горных вершин Дун Морога, и его улицы окружены зимней глушью, которая не даёт местным жителям размякнуть.",
			full = "Каранос раскинулся среди горных вершин Дун Морога, и его улицы окружены зимней глушью, которая не даёт местным жителям размякнуть. В его сердце горит кузня, гремит гномья мастерская, а таверна «Громоварка» разливает один из лучших элей, какой только можно найти, но городок никогда не мог беззаботно наслаждаться своим очарованием. К западу лежит пещера, кишащая вендиго, а на северо-западе тролли Мерзлогривов удерживают Мерцающий хребет, наблюдая за городом внизу.\n\nОднажды это наблюдение обернулось войной: огромный тролль из племени Мерзлогривов напал на Каранос и едва не перебил всех живших там дворфов. Там, где защитники города дрогнули, один дворф выстоял. Лазло Гриндвиджет в одиночку сразился с троллем и сразил его, и за это город назвал его героем. С тех пор это звание следует за ним по улицам, которые помнят, как близко они были к тому, чтобы умолкнуть навсегда.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Сторожка у заснеженной сосны",
			short = "Сторожка у заснеженной сосны тихо стоит в центре Дун Морога, на укромной поляне среди отягощённых снегом сосен.",
			full = "Сторожка у заснеженной сосны тихо стоит в центре Дун Морога, на укромной поляне среди отягощённых снегом сосен.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "Форт у северных врат",
			short = "Форт у северных врат стоит у Северных врат — узкого прохода в горах, соединяющего Дун Морог с Лок Моданом; это самый северо-восточный из дворфийских оплотов в этом высокогорье.",
			full = "Форт у северных врат стоит у Северных врат — узкого прохода в горах, соединяющего Дун Морог с Лок Моданом; это самый северо-восточный из дворфийских оплотов в этом высокогорье.\n\nРазмещённые здесь горные пехотинцы дни напролёт отбивают натиск зверья, что теснит их с окрестных вершин. Некоторые из тех, кто отправился охотиться на самых опасных зверей, так и не вернулись; горы обыскивали в поисках вестей о них, но почти безрезультатно.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "Северные врата",
			short = "Этот проход пересекает высокие горы, спускаясь от Дун Морога к Лок Модану.",
			full = "Этот проход пересекает высокие горы, спускаясь от Дун Морога к Лок Модану. Это кратчайшая дорога между двумя краями, и путники, направляющиеся в земли за озером Лок, ходят здесь чаще, чем любым другим путём.\n\nПроход охраняет Форт у северных врат.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Мерцающий хребет",
			short = "Мерцающий хребет поднимается на севере Дун Морога. Его удерживают тролли Мерзлогривов, у которых здесь два лагеря, соединённые мостом: среди скал они выращивают звездолист и приручают вепрей.",
			full = "Мерцающий хребет поднимается на севере Дун Морога. Его удерживают тролли Мерзлогривов, у которых здесь два лагеря, соединённые мостом: среди скал они выращивают звездолист и приручают вепрей.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "Форт у Южных врат",
			short = "Форт у Южных врат стоит там, где проход между Дун Морогом и Лок Моданом сужается, — это каменное горлышко, которое удерживают дворфийские горные пехотинцы.",
			full = "Форт у Южных врат стоит там, где проход между Дун Морогом и Лок Моданом сужается, — это каменное горлышко, которое удерживают дворфийские горные пехотинцы. Их служба спокойнее, чем у сородичей у Северных врат: они уже отогнали зверьё, которое некогда теснило проход, и дорога через него остаётся открытой и безопасной для тех, кто направляется в Телсамар или возвращается оттуда.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "Южные врата",
			short = "Южные врата прорезают горы, соединяя высокие снега Дун Морога с нижними долинами Лок Модана. Это кратчайший путь вниз, к Телсамару, проторённый путниками, что ходят между двумя краями.",
			full = "Южные врата прорезают горы, соединяя высокие снега Дун Морога с нижними долинами Лок Модана. Это кратчайший путь вниз, к Телсамару, проторённый путниками, что ходят между двумя краями.\n\nЗдесь стоит Форт у Южных врат — сторожевой пост, наблюдающий за проходом.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Поселок Сталежара",
			short = "Поселок Сталежара расположен к востоку от Караноса — небольшой лагерь рудокопов и инженеров, что трудятся на мёрзлой земле Дун Морога.",
			full = "Поселок Сталежара расположен к востоку от Караноса — небольшой лагерь рудокопов и инженеров, что трудятся на мёрзлой земле Дун Морога.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Таверна \"Громоварка\"",
			short = "Таверна «Громоварка» стоит в Караносе, и её имя благодаря качеству эля известно далеко за пределами дворфийского городка. Заведение держит хозяин таверны Белм, предлагая отдых и выпивку всем, кто проходит мимо.",
			full = "Таверна «Громоварка» стоит в Караносе, и её имя благодаря качеству эля известно далеко за пределами дворфийского городка. Заведение держит хозяин таверны Белм, предлагая отдых и выпивку всем, кто проходит мимо.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
