		["tundrid hills"] = {
			name = "Холмы Тандрид",
			short = "Холмы Тандрид лежат к югу от карьера Гол'Болар — это продуваемые ветрами земли, по которым мало кто ходит без клинка в руке.",
			full = "Холмы Тандрид лежат к югу от карьера Гол'Болар — это продуваемые ветрами земли, по которым мало кто ходит без клинка в руке. По склонам рыщут волки и другие дикие твари, и те, кто пересекает холмы, срезая путь между Холодной долиной и восточным Дун Морогом, знают, что дорога через Каранос была бы безопаснее.\n\nТролли Мерзлогривов разбили в здешней долине лагерь и удерживают эти земли на виду у дворфийского карьера.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
