	-- Тлеющее ущелье: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Обугленная пещера",
			short = "Обугленная пещера лежит запечатанной неподалёку от Черной горы: её тёмный камень безмолвен и отрезан от внешнего мира.",
			full = "Обугленная пещера лежит запечатанной неподалёку от Черной горы: её тёмный камень безмолвен и отрезан от внешнего мира.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Черная гора",
			short = "Черная гора родилась не из обычного огня.",
			full = "Черная гора родилась не из обычного огня. Когда во время Войны Трех Кланов армии Бронзобородов и Громового Молота выступили, чтобы покончить с кланом Черного Железа, тан-чародей Тауриссан дотянулся до расплавленного сердца мира и вытащил его силу наружу как оружие. На его зов откликнулся Рагнарос. Возрождение Повелителя Огня разорвало горы, затопило окрестные земли пламенем и заставило обоих королей повернуть армии вспять, лишь бы не встретиться с ним. Там, где стояло королевство Черного Железа, теперь курился вулкан, а к югу от него легли Пылающие степи, к северу — Тлеющее ущелье. Рагнарос удалился в недра горы и поработил уцелевших дворфов Черного Железа, заставив их высечь город Тенегорн под их собственным разрушенным домом.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "Котлован",
			short = "Котлован — огромная выработка, вырытая в самом центре Тлеющего ущелья; дворфы Черного Железа укрепили её через некоторое время после того, как призвали Рагнароса.",
			full = "Котлован — огромная выработка, вырытая в самом центре Тлеющего ущелья; дворфы Черного Железа укрепили её через некоторое время после того, как призвали Рагнароса. Огромные машины, которыми они вскрыли землю, до сих пор стоят по её краям. Внизу, в растрескавшихся светящихся расселинах, движутся огненные и магматические элементали.\n\nРабы, захваченные Черным Железом, бесконечно трудятся там, внизу, сломленные работой и гнетущим жаром. Они больше не отличают друзей от поработителей и встречают любого пришельца с той же бездумной яростью, что и любой надсмотрщик.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Выжженная долина",
			short = "Выжженная долина прорезает Тлеющее ущелье: продуваемая ветрами земля ведёт на север, к воротам Подгорной тропы, а за ними — к Долине Королей в Лок Модане.",
			full = "Выжженная долина прорезает Тлеющее ущелье: продуваемая ветрами земля ведёт на север, к воротам Подгорной тропы, а за ними — к Долине Королей в Лок Модане.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Гряда Огненной стражи",
			short = "Гряда Огненной стражи — главный лагерь дворфов Черного Железа в Тлеющем ущелье, откуда видна огромная выработка Котлована.",
			full = "Гряда Огненной стражи — главный лагерь дворфов Черного Железа в Тлеющем ущелье, откуда видна огромная выработка Котлована. Дворфы Черного Железа удерживают склоны с помощью механических големов и огромных огненных пауков, и ступать по гряде опасно.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Карьер Грязнули",
			short = "Когда-то здесь вели раскопки дворфы Стальгорна, пока не пришли дворфы Черного Железа и не захватили раскопки себе. Они по-прежнему в руках Черного Железа.",
			full = "Когда-то здесь вели раскопки дворфы Стальгорна, пока не пришли дворфы Черного Железа и не захватили раскопки себе. Они по-прежнему в руках Черного Железа.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "Пепельное Море",
			short = "Пепельное Море раскинулось ровной открытой равниной на юге Тлеющего ущелья, к северу от Черной горы. Здесь ничего не растёт.",
			full = "Пепельное Море раскинулось ровной открытой равниной на юге Тлеющего ущелья, к северу от Черной горы. Здесь ничего не растёт. Земля всё ещё тлеет, а ветер непрестанно поднимает пепел и несёт его над бесплодными равнинами. Огонь и ветер не оставили после себя ничего, кроме пустоши, и пожар здесь так и не утих.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "Шлаковая Яма",
			short = "Шлаковая Яма глубоко уходит в выработку Котлована в Тлеющем ущелье; в ней трудятся рабы под гнётом жестоких дворфов Черного Железа.",
			full = "Шлаковая Яма глубоко уходит в выработку Котлована в Тлеющем ущелье; в ней трудятся рабы под гнётом жестоких дворфов Черного Железа. Работорговцы и надсмотрщики подгоняют работу, и даже запуганные рабочие набросятся на любого, кто поднимет руку на их хозяев. На всякое вмешательство в свою добычу Черное Железо отвечает открытой враждой, а в глубокой тьме ямы, среди выработок, гнездятся ненасытные пламезавры.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Подгорная тропа",
			short = "Туннель, известный как Подгорная тропа, прорезает горы в северной части Выжженной долины, соединяя Тлеющее ущелье с Долиной Королей в Лок Модане.",
			full = "Туннель, известный как Подгорная тропа, прорезает горы в северной части Выжженной долины, соединяя Тлеющее ущелье с Долиной Королей в Лок Модане. Это творение Франклорна Искусника, который возвёл также Каменную Плотину и многие другие каменные сооружения дворфов по всем Восточным королевствам.\n\nВорота со стороны Лок Модана держит на замке горный пехотинец Щебеночка, преграждая путь всем, кроме тех, кто доказал свою доблесть в схватке с Марголом Неистовым.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Палатка Дубильщицы",
			short = "Сара Дубильщица, мастер кожевничества стихий, держит одинокую палатку в Тлеющем ущелье. За ней вглубь горы уходит длинный проход, в конце которого ждёт громоящер Маргол Неистовый.",
			full = "Сара Дубильщица, мастер кожевничества стихий, держит одинокую палатку в Тлеющем ущелье. За ней вглубь горы уходит длинный проход, в конце которого ждёт громоящер Маргол Неистовый.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Лагерь Братства Тория",
			short = "На выжженном севере Тлеющего ущелья стоит Лагерь Братства Тория — небольшой нейтральный городок, принадлежащий Братству Тория. Живут в нём по большей части дворфы Черного Железа, хранящие верность Братству, а не тёмным силам, что таятся под горами.",
			full = "На выжженном севере Тлеющего ущелья стоит Лагерь Братства Тория — небольшой нейтральный городок, принадлежащий Братству Тория. Живут в нём по большей части дворфы Черного Железа, хранящие верность Братству, а не тёмным силам, что таятся под горами. Здесь наготове горн и наковальня, огонь в которых поддерживают среди пепла и жара, и металл здесь по-прежнему куют, чем бы ни стало ущелье.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Пылающие степи: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Черная гора",
			short = "Черная гора родилась не из обычного огня.",
			full = "Черная гора родилась не из обычного огня. Когда во время Войны Трех Кланов армии Бронзобородов и Громового Молота выступили, чтобы покончить с кланом Черного Железа, тан-чародей Тауриссан дотянулся до расплавленного сердца мира и вытащил его силу наружу как оружие. На его зов откликнулся Рагнарос. Возрождение Повелителя Огня разорвало горы, затопило окрестные земли пламенем и заставило обоих королей повернуть армии вспять, лишь бы не встретиться с ним. Там, где стояло королевство Черного Железа, теперь курился вулкан, а к югу от него легли Пылающие степи, к северу — Тлеющее ущелье. Рагнарос удалился в недра горы и поработил уцелевших дворфов Черного Железа, заставив их высечь город Тенегорн под их собственным разрушенным домом.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Перевал Черной горы",
			short = "Перевал Черной горы — порог между двумя мирами. По одну его сторону лежит Красногорье, зелёное и тихое. По другую ждут Пылающие степи, выжженные и изуродованные до неузнаваемости.",
			full = "Перевал Черной горы — порог между двумя мирами. По одну его сторону лежит Красногорье, зелёное и тихое. По другую ждут Пылающие степи, выжженные и изуродованные до неузнаваемости. На границе стоят ворота, ясно отмечая черту.\n\nПройти через них — значит одним шагом оставить безопасность позади. Тех, кто забредает сюда неподготовленным, перемена застаёт врасплох: существа по ту сторону куда свирепее всего, что водится в горах за их спиной.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Крепость Черной горы",
			short = "Крепость возвышается на краю Пылающих степей, в самой тени Вершины Черной горы, — твердыня из чёрного камня, которую удерживает клан Черной горы.",
			full = "Крепость возвышается на краю Пылающих степей, в самой тени Вершины Черной горы, — твердыня из чёрного камня, которую удерживает клан Черной горы. За её стенами, на Полях Чести, воины клана и их союзники собираются и упражняются, а сержанты Черной горы держат их в узде плетью и окриком.\n\nКомандует крепостью генерал Торг'изог: он муштрует собранные на полях войска и следит, чтобы его приказы исполнялись беспрекословно.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Драко'дар",
			short = "Холмы Драко'дара черны и выжжены — они целиком отданы во власть черных драконов. Их сородичи свободно бродят по этой земле, и так густо, что никому не стоит ступать сюда без осторожности и без спутников.",
			full = "Холмы Драко'дара черны и выжжены — они целиком отданы во власть черных драконов. Их сородичи свободно бродят по этой земле, и так густо, что никому не стоит ступать сюда без осторожности и без спутников.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Скала Молота Ужаса",
			short = "Скала Молота Ужаса — твердыня из каменных троп и выдолбленных огрских курганов, оплот клана Огненного Чрева.",
			full = "Скала Молота Ужаса — твердыня из каменных троп и выдолбленных огрских курганов, оплот клана Огненного Чрева. С её высот и из её туннелей Огненное Чрево совершает набеги на юг, в Красногорье, используя скалу как базу, а затем отступает в её глубины.",
