		["morgans vigil"] = {
			name = "Дозор Моргана",
			short = "Дозор Моргана лежит в руинах на юго-востоке Пылающих степей: его дома сгорели дотла, а башня магов рассыпалась грудой обломков.",
			full = "Дозор Моргана лежит в руинах на юго-востоке Пылающих степей: его дома сгорели дотла, а башня магов рассыпалась грудой обломков. Среди развалин стоят палатки, укрывая тех, кто здесь остался.\n\nИз этих палаток Альянс наблюдает за Черной горой, нанося удары по угрозе ближе к её источнику.",
