	-- Элвиннский лес: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Тыквенное поле Бреквеллов",
			short = "На юго-востоке Элвиннского леса стоит усадьба, некогда принадлежавшая семье Бреквеллов. Что с ними стало, никто сказать не может.",
			full = "На юго-востоке Элвиннского леса стоит усадьба, некогда принадлежавшая семье Бреквеллов. Что с ними стало, никто сказать не может. Братство Справедливости присвоило это место, а Бреквеллы попросту исчезли со своих полей и из-за своих изгородей.\n\nОт них осталось лишь одно воспоминание: призовая свинья по кличке Принцесса, отъевшаяся до огромных размеров на овощах, которые она ночь за ночью таскала с соседней Фермы Стоунфилдов задолго до того, как сюда пришли разбойники.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Озеро Хрустальное",
			short = "Озеро Хрустальное лежит к востоку от Златоземья; в его водах кишат мурлоки, и неосторожным на берегу лучше не задерживаться. С южного берега за водой присматривает человеческая усадьба.",
			full = "Озеро Хрустальное лежит к востоку от Златоземья; в его водах кишат мурлоки, и неосторожным на берегу лучше не задерживаться. С южного берега за водой присматривает человеческая усадьба.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Лесопилка Восточной долины",
			short = "Лесопилки Восточной долины разбросаны по востоку Элвиннского леса, жилые дома тянутся между пильными ямами, и работа здесь по-настоящему не прекращается никогда.",
			full = "Лесопилки Восточной долины разбросаны по востоку Элвиннского леса, жилые дома тянутся между пильными ямами, и работа здесь по-настоящему не прекращается никогда. Заказы на древесину поступают быстрее, чем позволяют сроки, и лесорубы трудятся под постоянным давлением покупателей, дожидающихся штормградского леса.\n\nМаршал Хаггард, когда-то командовавший Штормградской стражей, несколько лет назад оставил этот пост и решил провести остаток своих дней в усадьбе в лагере, а не в городе, который некогда защищал. Здесь же выросла и Сейя Нортбрук.\n\nЛес подступает вплотную со всех сторон, и его дикость — вовсе не пустяк. Волки и медведи не дают покоя лесорубам, разгоняя рабочие бригады и угрожая окончательно сорвать все сроки. Беда стала настолько серьёзной, что Штормградской страже пришлось просить помощи со стороны, чтобы проредить зверьё.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Рудник Горного Эха",
			short = "Туннели Рудника Горного Эха лежат на северо-западе Долины Североземья.",
			full = "Туннели Рудника Горного Эха лежат на северо-западе Долины Североземья. Шахты заполонили кобольды, сделав их своими, к великой досаде живущих поблизости людей, и маршал Макбрайд мог лишь раз за разом посылать людей, чтобы сократить их число.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Рудник Подземных Глубин",
			short = "Когда-то в Руднике Подземных Глубин добывали золото для Штормграда, и его шахты уходили глубоко в землю Элвиннского леса. Теперь он заброшен, а его туннели захватил клан кобольдов.",
			full = "Когда-то в Руднике Подземных Глубин добывали золото для Штормграда, и его шахты уходили глубоко в землю Элвиннского леса. Теперь он заброшен, а его туннели захватил клан кобольдов. Нижние шахты, глубокие выработки под основным рудником, уходят ещё дальше во тьму.\n\nМаршал Дугхан, оберегающий покой Элвиннского леса, распорядился усилить окрестные патрули, как только присутствие кобольдов подтвердилось. Среди кобольдов прячется Фикс, у которого хранится ожерелье, украденное у тетушки Бернис Стоунфилд, — памятная вещь, которую она всё ещё надеется увидеть снова.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Лесная опушка",
			short = "Лесная опушка лежит к юго-западу от Штормграда — узкая полоса леса между Садом у Зеркального озера, рекой Назферити и небольшим ручьём, текущим к Западному Краю.",
			full = "Лесная опушка лежит к юго-западу от Штормграда — узкая полоса леса между Садом у Зеркального озера, рекой Назферити и небольшим ручьём, текущим к Западному Краю. В её подлеске роются вепри, а вдоль берегов тянутся медные жилы. Лес принадлежит банде гноллов, и среди них есть один, кто вовсе не простой зверь из стаи. Дробитель рыщет по лесу среди гноллов помельче, и он совсем не обычная шавка.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Златоземье",
			short = "Златоземье раскинулось в самом сердце Элвиннского леса: его поля видны из Североземья, а дороги ведут к Штормграду, Западному Краю и Красногорью.",
			full = "Златоземье раскинулось в самом сердце Элвиннского леса: его поля видны из Североземья, а дороги ведут к Штормграду, Западному Краю и Красногорью. Городок вырос в годы после основания Штормграда, когда жители королевства расселились из столицы по окрестным землям.\n\nСамый страшный час городка пришёлся на Первую войну, когда вождь Чернорук направил Орду на ту жизненно важную связь, что соединяла крепость Штормграда с её народом. Златоземье и Луноречье были последними двумя городками между орками и столицей, и когда они пали, путь к крепости оказался открыт. Златоземье поднялось из руин лишь после Второй войны, когда его отстроил Альянс Лордерона, а сам верховный главнокомандующий Туралион позаботился о возвращении рассеянных жителей Штормграда.\n\nТеперь здесь спокойнее: в центре городка стоит таверна «Гордость льва», чей очаг и эль притягивают путников со всех сходящихся здесь дорог. Маршал Дугхан из Штормградской стражи по-прежнему охраняет городок, помня, чего когда-то стоила его потеря.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Часовые Вечности",
			short = "Круг стоячих камней опоясывает маленький остров на Озере Каменных Столбов, а в его центре стоит Камень Воспоминаний.",
			full = "Круг стоячих камней опоясывает маленький остров на Озере Каменных Столбов, а в его центре стоит Камень Воспоминаний. Он чтит память павших в Первой войне, когда орки разорили Златоземье и окрестные земли и предали их огню.\n\nТеперь островом владеют маги-отступники. Среди камней лежит тело Хенза Фолка, оставленное там, где он пал.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Яшмовая шахта",
			short = "Когда-то Яшмовая шахта питала кузни Штормграда: это было одно из мест в Элвиннском лесу, поставлявших руду, которая требовалась городу для его войн.",
			full = "Когда-то Яшмовая шахта питала кузни Штормграда: это было одно из мест в Элвиннском лесу, поставлявших руду, которая требовалась городу для его войн. Эта работа окончена. Туннели заполонили кобольды, а у армии Штормграда, силы которой распылены на борьбу с более серьёзными угрозами, нет лишних людей, чтобы выкурить их оттуда.\n\nНо кобольды — не единственная опасность под землёй. В самых глубоких закоулках шахты обосновалась колония шахтных пауков, и для них кобольды не захватчики, которых стоит бояться, а добыча. Их королева, Мать Клык, таится во тьме и не терпит никого в своём гнезде.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Лагерь Джерода",
			short = "Лагерь Джерода — лодочная пристань на элвиннском берегу реки Назферити.",
			full = "Лагерь Джерода — лодочная пристань на элвиннском берегу реки Назферити. Её удерживает Братство Справедливости: портовый начальник и его люди переправляют через неё краденое из Красногорья в Башню Клейвена в Западном Краю.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Виноградники Маклура",
			short = "Виноградники Маклура раскинулись на юге Элвиннского леса; длинные ряды лоз на ухоженной земле возделывает семья Маклуров.",
			full = "Виноградники Маклура раскинулись на юге Элвиннского леса; длинные ряды лоз на ухоженной земле возделывает семья Маклуров. Маклуры ведут ожесточённую вражду с соседями Стоунфилдами, обмениваясь неприязнью так же охотно, как ничем другим не обмениваются. И всё же отпрыск Маклуров и отпрыск Стоунфилдов полюбили друг друга наперекор всему, за что стоят их родные, и кое-кто надеется, что такая любовь сумеет исцелить то, чего не смогли исправить поколения вражды.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Зеркальное озеро",
			short = "Зеркальное озеро, маленькое и тихое, лежит на западе Элвиннского леса; его водопад сверкает рядом с соседним садом, и кажется, что это место создано для купания или рыбалки.",
			full = "Зеркальное озеро, маленькое и тихое, лежит на западе Элвиннского леса; его водопад сверкает рядом с соседним садом, и кажется, что это место создано для купания или рыбалки. Но теперь всё не так просто. Леса вокруг облюбовали разбойники из Братства Справедливости, и место, которое должно было дарить отдых, стало таким, где проходить нужно с опаской.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Сад у Зеркального озера",
			short = "Сад у Зеркального озера лежит на его южном берегу: ряды деревьев и одинокий домик стоят среди полей западной части Элвиннского леса.",
			full = "Сад у Зеркального озера лежит на его южном берегу: ряды деревьев и одинокий домик стоят среди полей западной части Элвиннского леса. Когда-то сад и домик рядом с ним занимали разбойники из Братства Справедливости, распоряжаясь этим местом как своим, и никто не может сказать наверняка, не они ли прогнали отсюда настоящих хозяев сада.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Аббатство Североземья",
			short = "Аббатство Североземья покоится в долине, носящей его имя, в предгорьях Элвиннского леса: его главный зал, оружейный зал и библиотечное крыло стоят там, где впервые поселились клирики Церкви Священного Света, пришедшие на юг из Лордерона.",
			full = "Аббатство Североземья покоится в долине, носящей его имя, в предгорьях Элвиннского леса: его главный зал, оружейный зал и библиотечное крыло стоят там, где впервые поселились клирики Церкви Священного Света, пришедшие на юг из Лордерона. Отсюда Священный орден клириков Североземья дарил Штормграду утешение и мудрость, и именно в этих стенах долгие годы выхаживали впавшего в забытьё Медива, Хранителя Тирисфаля.\n\nПервая война не обошла аббатство стороной. Его настоятель отдал клириков Североземья на защиту Штормграда, и вскоре после того, как сюда привезли пленённую полуорчиху Гарону, орки захватили Североземье и сожгли его дотла. Беженцы бежали в Лордерон, но прежде успели вынести из развалин священные книги — тексты, по которым маги Даларана впоследствии научились искусству невидимости.\n\nРазрушенные земли не долго пустовали. Во время Второй войны клан Сумеречного Молота во главе с Чо'Галлом устроил здесь свою ставку, пока Альянс не отвоевал Элвиннский лес и архиепископ Алонсус Фаол не отстроил аббатство камень за камнем, основав в его стенах Братство Североземья.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Долина Североземья",
			short = "Долина Североземья замкнута со всех сторон, кроме одной: её горы непроходимы, а единственный проход на юг перекрыт толстыми каменными стенами и охраняемыми воротами.",
			full = "Долина Североземья замкнута со всех сторон, кроме одной: её горы непроходимы, а единственный проход на юг перекрыт толстыми каменными стенами и охраняемыми воротами. Её тишину прорезает река, петляющая к Озеру Хрустальному мимо аббатства и рядов виноградных лоз, придающих этому месту умиротворённый вид.\n\nНо этот покой не всегда был прочен. Во время Второй войны в Аббатстве Североземья располагалась ставка клана Сумеречного Молота во главе с Чо'Галлом, присягнувшего делу Гул'дана, и в его стенах укрывались не послушники и земледельцы, а военные советы орков.\n\nТеперь гарнизоном аббатства командует маршал Макбрайд, отвечающий за безопасность всего Североземья, хотя даже под его надзором в долине нет полного спокойствия. Из Сумеречного леса надвигаются волки, и никто не может сказать, почему их так много, а кобольды роют ходы в Руднике Горного Эха.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Виноградники Североземья",
			short = "Виноградники тянутся к востоку от аббатства; когда-то здесь собирали урожай, пока эти земли не захватило Братство Справедливости.",
			full = "Виноградники тянутся к востоку от аббатства; когда-то здесь собирали урожай, пока эти земли не захватило Братство Справедливости. Гаррик Тихокрад возглавлял удерживавших их агентов, превратив ряды лоз в опорный пункт для прислужников Братства, которые унесли с собой имущество, украденное у Милли Осворт.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Дозорная башня",
			short = "Дозорная башня следит за границей Элвиннского леса — это одна из разведывательных башен Штормградской стражи.",
			full = "Дозорная башня следит за границей Элвиннского леса — это одна из разведывательных башен Штормградской стражи. Её часовые обращают взоры к Красногорью, где собираются гноллы и орки, к Сумеречному лесу, где мёртвые не желают лежать в могилах, и к ближним лагерям Братства Справедливости. Гарнизон надёжно защищён от всех трёх угроз.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Озеро Каменных Столбов",
			short = "Озеро Каменных Столбов получило своё название от Часовых Вечности — памятника из камней, воздвигнутого на острове посреди озера в память о павших в Первой войне против орков, когда погибших было так много, что ни одна могила не смогла бы вместить память о них.",
			full = "Озеро Каменных Столбов получило своё название от Часовых Вечности — памятника из камней, воздвигнутого на острове посреди озера в память о павших в Первой войне против орков, когда погибших было так много, что ни одна могила не смогла бы вместить память о них. Когда-то сюда приходили в тихое паломничество.\n\nЭтот покой ушёл. Остров захватили маги-отступники, и памятник, воздвигнутый для скорби, теперь стоит у них за спиной. Вдоль южных берегов племя мурлоков выстроило свои грубые жилища, равнодушное к монументу на другом берегу.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "Ферма Стоунфилдов",
			short = "Ферма Стоунфилдов лежит на юге Элвиннского леса; её возделывает семья Стоунфилдов, которая ведёт ожесточённую вражду с соседями Маклурами.",
			full = "Ферма Стоунфилдов лежит на юге Элвиннского леса; её возделывает семья Стоунфилдов, которая ведёт ожесточённую вражду с соседями Маклурами. И всё же дети обоих семейств полюбили друг друга наперекор старой обиде между их родами. Кое-кто надеется, что эта любовь добьётся того, чего не смогли годы раздоров, и исцелит то, что сломала вражда.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Ревущий водопад",
			short = "Тропа от водопада Зеркального озера круто и узко поднимается в горы, а затем выводит к Ревущему водопаду — ущелью, которое отличается от прочих в Элвиннском лесу тем, что вода низвергается в него с обоих концов.",
			full = "Тропа от водопада Зеркального озера круто и узко поднимается в горы, а затем выводит к Ревущему водопаду — ущелью, которое отличается от прочих в Элвиннском лесу тем, что вода низвергается в него с обоих концов. Третий водопад обрушивается с северных утёсов, питая ущелье сверху. Ниже по склону стоит небольшой сельский домик с наковальней и горящим очагом, а у реки рядом с ним — маленький причал и лодка. Возле домика околачиваются разбойники. Дальше река срывается вторым водопадом у границы Западного Края. Говорят, что фиолетовый окунь, который водится в этих водах, нигде не ловится так легко, как здесь.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Башня Азоры",
			short = "Башня Азоры возвышается среди полей в центре Элвиннского леса; в ней живёт отряд слуг-гномов, подчиняющихся верховному магу Теокриту.",
			full = "Башня Азоры возвышается среди полей в центре Элвиннского леса; в ней живёт отряд слуг-гномов, подчиняющихся верховному магу Теокриту.\n\nДалеко в Красногорье стоит её соперница — Башня Илгалара, которой правит чародей Моргант. Две башни никогда не воевали в открытую, но постоянно следят друг за другом с помощью магии, выжидая, когда соперник оступится.\n\nМагия башни выплёскивается на окрестные поля, и всё, что задерживается слишком близко, рискует попасть под её влияние и превратиться в нечто более странное, чем было прежде. Слуги берегут свою башню от этой мелкой, но постоянной напасти, не спуская глаз с Красногорья.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Гарнизон у Западного ручья",
			short = "Гарнизон у Западного ручья стоит на западной окраине Элвиннского леса, там, где деревья уступают место более бедным землям Западного Края, и служба здесь для Штормградской стражи всегда была одинокой.",
			full = "Гарнизон у Западного ручья стоит на западной окраине Элвиннского леса, там, где деревья уступают место более бедным землям Западного Края, и служба здесь для Штормградской стражи всегда была одинокой.\n\nСамые тяжёлые годы наступили, когда порча леди Катраны Престор тяжким грузом легла на королевство, а основные силы армии Штормграда были заняты в других краях. Солдат не хватало, и с каждым сезоном гноллы и воры из Западного Края всё сильнее теснили лес, а гарнизон с трудом обеспечивал безопасность дорог.\n\nСреди гноллов вождь Речной Лапы Дробитель стал именем, внушающим ужас. Он одолевал всех, кто пытался его поймать, и объявления о его розыске до сих пор висят у ворот гарнизона, так никем и не исполненные.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Перевал Мертвого Ветра: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Лагерь Аридена",
			short = "Лагерь заброшен и лежит к северу от дороги через Перевал Мертвого Ветра — россыпь остывших кострищ и пустых спальных мешков под вечно тёмными деревьями.",
			full = "Лагерь заброшен и лежит к северу от дороги через Перевал Мертвого Ветра — россыпь остывших кострищ и пустых спальных мешков под вечно тёмными деревьями. Когда-то отсюда Ариден командовал Темными всадниками; он разбил здесь лагерь ещё до того, как на него пало проклятие, и пытался сбывать поддельные артефакты, которые якобы принадлежали Медиву. Теперь от всего этого осталась лишь сама стоянка.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Перекресток Мертвеца",
			short = "На перекрёстке стоит дерево висельников, и с его ветвей до сих пор свисают два трупа. Рядом с ним указатель с двумя предупреждениями: «Поворачивай назад!» и «Оставь надежду, всяк сюда входящий».",
			full = "На перекрёстке стоит дерево висельников, и с его ветвей до сих пор свисают два трупа. Рядом с ним указатель с двумя предупреждениями: «Поворачивай назад!» и «Оставь надежду, всяк сюда входящий».\n\nОтсюда дорога на запад ведёт к Сумеречному лесу, на восток — к Болоту Печали, а на юг — в Перевал Мертвого Ветра, где стоит Каражан. Виселицу и предупреждение поставили для всякого, кого потянет свернуть с перекрёстка на перевал.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Овраг Мертвого Ветра",
			short = "Овраг прорезает горы скалистой расселиной; его западная дорога идёт по верхнему уровню к Каражану, зловещий силуэт которого ждёт в дальнем конце.",
			full = "Овраг прорезает горы скалистой расселиной; его западная дорога идёт по верхнему уровню к Каражану, зловещий силуэт которого ждёт в дальнем конце. В конце оврага лежит южный мост — последняя переправа перед самой башней.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Поселок Грош'гок",
			short = "Огры Мертвого Ветра считают Поселок Грош'гок своим — это курган из земли и камня, насыпанный в Погани.",
			full = "Огры Мертвого Ветра считают Поселок Грош'гок своим — это курган из земли и камня, насыпанный в Погани. Из пещер, что изрыли этот край, эта лежит южнее всех, и ни одна другая не сравнится с ней размерами.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Каражан",
			short = "Каражан стоит заброшенным на юге Перевала Мертвого Ветра, возведённый на пересечении силовых линий. Больше всего башня известна своим последним обитателем — Медивом, последним Хранителем Тирисфаля.",
			full = "Каражан стоит заброшенным на юге Перевала Мертвого Ветра, возведённый на пересечении силовых линий. Больше всего башня известна своим последним обитателем — Медивом, последним Хранителем Тирисфаля. После того как Медива убили Кадгар, Андуин Лотар и Гарона, башня отгородилась от мира. Но недавно Каражан вновь пробудился: им завладело злое присутствие, его залы кишат духами и демонами, а Тень Медива всё ещё витает здесь, и сила его так велика, что его магия до сих пор отзывается эхом по всей башне.\n\nНевозможно взглянуть на Каражан, не вспомнив мрачную историю его хозяина. Как и подобало его званию, последний Хранитель Тирисфаля собрал огромную коллекцию сочинений и артефактов, затмевавшую даже собрание Кирин-Тора. Башня огромна и опасна, а её залы полны призраков.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "Хозяйский погреб",
			short = "Под разрушенной деревней к югу от Каражана, где когда-то жили слуги башни, земля открывается в погреба, которые больше не принадлежат живым.",
			full = "Под разрушенной деревней к югу от Каражана, где когда-то жили слуги башни, земля открывается в погреба, которые больше не принадлежат живым. Вниз ведут два входа. Один открывается в огромный винный погреб, стеллажи и бочки которого давно оставлены мертвецам. Другой ведёт во второй погреб, пол которого полностью провалился, обрушившись в систему пещер, уходящую глубоко под землю.\n\nОба кишат неупокоенными: неживые смотрители, которые словно всё ещё ухаживают за домом без хозяина, проклятые души, не находящие покоя тени, призраки, чьи вопли доносятся сквозь расколотый камень. Какая бы служба ни связывала их с Каражаном при жизни, она обратилась в нечто, что не отпускает их и после смерти.\n\nЛишь в винном погребе есть хоть что-то, выделяющееся среди мертвецов. Нижние пещеры, безмолвные и утонувшие во тьме, не хранят ничего, кроме всё тех же неупокоенных мертвецов, — ничего, что носило бы имя, ничего, что кто-либо счёл бы достойным памяти.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Надел Моргана",
			short = "Позади Каражана стоит маленькая ветхая церковь, её кладбище и склеп утопают во мраке Перевала Мертвого Ветра.",
			full = "Позади Каражана стоит маленькая ветхая церковь, её кладбище и склеп утопают во мраке Перевала Мертвого Ветра. В часовне давно обитают те, кто не может обрести покой, а по холму чуть ниже по-прежнему бродит кто-то ещё.\n\nТо, что место, предназначенное для мёртвых, так часто не может их удержать, кое-что говорит о том, что лежит за ним.",
