	-- Сумеречный лес: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Участок Эддла",
			short = "Участок Эддла заброшен и лежит среди полей на юго-западе Сумеречного леса — одна из многих усадеб, оставленных гнить, когда на эту землю опустилась тьма.",
			full = "Участок Эддла заброшен и лежит среди полей на юго-западе Сумеречного леса — одна из многих усадеб, оставленных гнить, когда на эту землю опустилась тьма. Амбар пуст, фермерский дом безмолвен, и здесь бродят теперь лишь заблудшие духи — говорят, это тени погибших членов Братства Справедливости, что некогда захватили это место.\n\nБратство Справедливости целиком завладело Участком Эддла: его люди крались по заросшему полю, прятались в амбаре и рыскали по комнатам фермерского дома.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Приют Бродяги",
			short = "Башня под названием Приют Бродяги стоит заброшенной над дорогой в Перевал Мертвого Ветра, к северо-востоку от Поместья Мистмантла.",
			full = "Башня под названием Приют Бродяги стоит заброшенной над дорогой в Перевал Мертвого Ветра, к северо-востоку от Поместья Мистмантла. Её возвели как разведывательный пост Штормградской стражи, но теперь она служит Отрекшимся: страж смерти Зредус и аптекарь Фаустин ставят в её стенах свои опыты.\n\nТропа спускается к небольшому пруду, который питает водопад; там, под двумя огромными статуями, высеченными наподобие тех, что стоят у Темного портала, покоится безымянная могила. Неподалёку от башни есть ещё одно маленькое кладбище, где находится могила Неизвестного солдата.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Светлая роща",
			short = "Светлая роща лежит чуть западнее Темнолесья, и её немногочисленные постройки давно обратились в руины.",
			full = "Светлая роща лежит чуть западнее Темнолесья, и её немногочисленные постройки давно обратились в руины. То, что осталось от этого места, теперь принадлежит воргенам стаи Ночной Погибели: они стаями рыщут по тёмным полям, разбивают среди развалин грубые лагеря и набрасываются на всякого, кто подойдёт слишком близко.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "Темный берег",
			short = "Темный берег тянется вдоль северного побережья Сумеречного леса, от западного края этих земель на восток, до моста, соединяющего их с Красногорьем.",
			full = "Темный берег тянется вдоль северного побережья Сумеречного леса, от западного края этих земель на восток, до моста, соединяющего их с Красногорьем. На его западном конце стоит небольшой лагерь, где нашли приют беженцы Свен Йорген и Ларс, которых загнало к самой воде то, из-за чего остальной Сумеречный лес стало слишком опасно удерживать.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Темнолесье",
			short = "Темнолесье не всегда носило это имя. Давным-давно оно возникло как Большая Деревня — небольшой лесной городок, выросший, когда жители Штормграда расселились по соседним землям.",
			full = "Темнолесье не всегда носило это имя. Давным-давно оно возникло как Большая Деревня — небольшой лесной городок, выросший, когда жители Штормграда расселились по соседним землям. Но сама земля так и не оправилась от того, что случилось в Каражане. Когда Хранитель Медив был убит в своей башне, высвобожденная его смертью энергия Скверны проникла в окрестный лес и исказила его, превратив в тернистое, лишённое света место, каким он остаётся и поныне. Светлый лес стал Сумеречным, а Большая Деревня получила более правдивое имя — Темнолесье.\n\nГородское ополчение, Ночной Дозор, существует потому, что Штормград бросил город на произвол судьбы. Когда интриги леди Катраны Престор в Штормграде лишили лес королевских гарнизонов, горожане взялись за оружие сами, не дожидаясь солдат, которые так и не пришли. Созданный и обученный целиком жителями леса, Дозор с тех пор защищает дороги от волков, ходячих трупов и кое-чего похуже, не имея иной армии, кроме самих себя.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Катакомбы Утреннего Леса",
			short = "Под Кладбищем Вороньего Холма земля открывается в Катакомбы Утреннего Леса — лабиринт туннелей, уходящих так глубоко, что мало кто из вошедших туда в одиночку возвращается назад.",
			full = "Под Кладбищем Вороньего Холма земля открывается в Катакомбы Утреннего Леса — лабиринт туннелей, уходящих так глубоко, что мало кто из вошедших туда в одиночку возвращается назад. Вниз ведут два пути. Восточный проход открывается в логово вурдалаков, заразных и свирепых. Западный — в зал скелетов, что стоят на страже над гробницами тех мертвецов, которыми когда-то были они сами.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Покинутая усадьба",
			short = "Покинутая усадьба — холм на северной окраине Кладбища Вороньего Холма — окутана тьмой, что льнёт ближе, чем тень окрестных деревьев.",
			full = "Покинутая усадьба — холм на северной окраине Кладбища Вороньего Холма — окутана тьмой, что льнёт ближе, чем тень окрестных деревьев. Здесь стоит дом Морбента Скверна, некроманта, который подчиняет своей воле нежить леса с помощью злой тайной магии. Лишь одно оружие великой силы может надеяться его остановить.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "Затихший берег",
			short = "Затихший берег тянется вдоль западной реки Сумеречного леса, от места, где сходятся Западный Край, Элвиннский лес и Сумеречный лес, на юг, к Тернистой долине.",
			full = "Затихший берег тянется вдоль западной реки Сумеречного леса, от места, где сходятся Западный Край, Элвиннский лес и Сумеречный лес, на юг, к Тернистой долине. Здесь через реку перекинут крытый мост, соединяющий Сумеречный лес с Западным Краем.\n\nВ северной части берега разбили лагерь братья Ларс и Свен Йорген.\n\nСреди деревьев по берегу рыщут волки и пауки.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Поместье Мистмантла",
			short = "Поместье Мистмантла стоит на северо-востоке Сумеречного леса; его земли прогнили, а сады обратились в руины.",
			full = "Поместье Мистмантла стоит на северо-востоке Сумеречного леса; его земли прогнили, а сады обратились в руины. Когда-то здесь жил Сталван Мистмантл, школьный учитель и наставник, ставший прислужником нежити; вместо себя он оставил бродить по поместью вурдалаков. Среди этой порчи растёт лишь одно: единственный цветок, называемый слезой Тиллоа, — последний признак жизни в саду, во всём остальном отданном гнили.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Вороний Холм",
			short = "Дома Вороньего Холма на западе Сумеречного леса стоят пустыми, отданные гнили и тьме. Лишь несколько душ всё же остались здесь: Трясунчик и гоблин Блицтик, прятавшийся от чужих глаз на верхнем этаже.",
			full = "Дома Вороньего Холма на западе Сумеречного леса стоят пустыми, отданные гнили и тьме. Лишь несколько душ всё же остались здесь: Трясунчик и гоблин Блицтик, прятавшийся от чужих глаз на верхнем этаже.\n\nПо городку бродят Незримые — незримые не только по названию, — скитаясь по его пустым комнатам.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Кладбище Вороньего Холма",
			short = "Кладбище Вороньего Холма раскинулось к северу от городка, давшего ему имя, и с тех пор, как Сумеречный лес охватила порча, оно разрослось далеко за свои прежние границы.",
			full = "Кладбище Вороньего Холма раскинулось к северу от городка, давшего ему имя, и с тех пор, как Сумеречный лес охватила порча, оно разрослось далеко за свои прежние границы. Теперь среди надгробий бродит нежить, а огромные пауки и шайки расхитителей могил беспрепятственно хозяйничают на могилах, прогоняя всякого, кто случайно помешает их делам.\n\nВ северо-западном углу кладбища стоит Покинутая усадьба — дом некроманта Морбента Скверна, чья тёмная работа тревожит здешних мертвецов.\n\nИмя Ладимор связано с самым давним горем этого кладбища. Морган Ладимор вернулся с Третьей войны и узнал, что его жена и дети уже похоронены здесь. Горе сломило его: над их могилами он убил троих смотрителей кладбища. Теперь по кладбищу бродит нежить Мор'Ладим, и смерть приходит быстро и незаметно к любому, кого он застанет врасплох среди надгробий.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Погибель Роланда",
			short = "Погибель Роланда — рудник на юго-востоке Сумеречного леса, к востоку от Гниющего сада.",
			full = "Погибель Роланда — рудник на юго-востоке Сумеречного леса, к востоку от Гниющего сада. Жрица ночных эльфов Велинда Песнь Звезд принесла в эти холмы Косу Элуны незадолго до своего исчезновения, и реликвия затерялась в руднике. Её нашёл там человек по прозвищу Трясунчик, и эта находка навлекла на Сумеречный лес и Темнолесье ещё больше воргенов.\n\nТеперь рудник принадлежит Гатспиллу и Нефару из стаи Ночной Погибели, чьи воргены бродят до самого Гниющего сада.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "Гниющий сад",
			short = "Сад лежит на юге Сумеречного леса: его деревья почернели от гнили, а постройки обратились в руины между Усадьбой Йоргена и Безмятежным кладбищем.",
			full = "Сад лежит на юге Сумеречного леса: его деревья почернели от гнили, а постройки обратились в руины между Усадьбой Йоргена и Безмятежным кладбищем.\n\nВоргены стаи Ночной Погибели сделали его своим. Ткачи теней творят свою магию среди разрушенных построек, а ловцы незримо поджидают во тьме между деревьями.\n\nСтоять здесь сейчас — значит стоять в месте, которое перестало быть фермой и стало охотничьими угодьями.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Безмятежное кладбище",
			short = "Безмятежное кладбище лежит к юго-востоку от Темнолесья, и его название теперь звучит как горькая насмешка.",
			full = "Безмятежное кладбище лежит к юго-востоку от Темнолесья, и его название теперь звучит как горькая насмешка. Мёртвые здесь не знают покоя, хотя они слабее нежити, что встречается в других уголках Сумеречного леса; они бродят среди надгробий и разрушенной церкви в самом сердце кладбища. Здесь обитает Безумный вурдалак — порой в разбитой церкви, порой среди могил. Чуть севернее стоит дом Слепой Мэри.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Мглистая роща",
			short = "В самом сердце Мглистой рощи, в глубине Сумеречного леса, стоит огромное безымянное дерево, а рядом — лунный колодец и старая беседка ночных эльфов.",
			full = "В самом сердце Мглистой рощи, в глубине Сумеречного леса, стоит огромное безымянное дерево, а рядом — лунный колодец и старая беседка ночных эльфов. Под его ветвями находится один из всего четырёх порталов в Изумрудный Сон, родственный тем, что скрыты в Фераласе, Внутренних землях и Ясеневом лесу.\n\nПортал рощи не оставался без охраны. Четыре великих дракона, когда-то гордые наместники Изеры, Аспекта Снов, несли здесь стражу как избранные ею защитники Сна. Но Изумрудный Кошмар поразил и их, превратив стражей в разрушителей, не желавших ничего, кроме смерти, и Альянсу и Орде пришлось взяться за оружие против тех самых драконов, что некогда охраняли это место.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Лощина Вул'Гол",
			short = "Юг Сумеречного леса спускается в небольшую низину, где дорога разветвляется в сторону Тернистой долины и где до прихода огров стояли фермерские дома.",
			full = "Юг Сумеречного леса спускается в небольшую низину, где дорога разветвляется в сторону Тернистой долины и где до прихода огров стояли фермерские дома. Теперь её удерживают огры из клана Расколотого Кулака, а название она получила по имени их вожака Ззарк'Вула, который правит курганом изнутри.\n\nРазрушенные фермерские дома — единственный знак того, что здесь жили люди, прежде чем огры забрали низину себе. Что бы ни стало с этими семьями, огры не оставили после них ничего, кроме разбитых стен.\n\nНочной Дозор не выделяет сюда своих людей, считая здешнюю угрозу менее срочной, чем другие, нависшие над Сумеречным лесом, и потому прореживать ряды огров, когда нужно, приходится чужакам. Среди добычи огров оказался ящик с инструментами и травами, украденный у некроманта Аберкромби и унесённый в курган после того, как огры одолели его. А сам Ззарк'Вул носит монокль, которого когда-то жаждал для своих исследований один учёный, — маленькое тщеславие жестокого существа.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "Усадьба Йоргена",
			short = "Усадьба Йоргена заброшена и лежит на юге Сумеречного леса, а её поля сгнили. Когда-то эту землю возделывал Свен Йорген, но теперь он живёт в небольшом лагере на Темном берегу.",
			full = "Усадьба Йоргена заброшена и лежит на юге Сумеречного леса, а её поля сгнили. Когда-то эту землю возделывал Свен Йорген, но теперь он живёт в небольшом лагере на Темном берегу. Сама усадьба с тех пор попала в руки Братства Справедливости, чьи убийцы незримо движутся по полям и наносят удар лишь тогда, когда уже слишком поздно.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Лок Модан: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "Станция Альгаз",
			short = "Станция Альгаз стоит к востоку от Северных врат и носит имя Дун Альгаза, лежащего к северу.",
			full = "Станция Альгаз стоит к востоку от Северных врат и носит имя Дун Альгаза, лежащего к северу. Здесь несут дозор дворфийские горные пехотинцы, среди которых и горный пехотинец Грозовая Вершина, а оружейник Готор Брумн следит за их снаряжением.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Дун Альгаз",
			short = "Туннель через Дун Альгаз старше раздора, расколовшего дворфов. Когда Война Трех Кланов изгнала клан Громового Молота из Стальгорна, именно через этот проход он отступал.",
			full = "Туннель через Дун Альгаз старше раздора, расколовшего дворфов. Когда Война Трех Кланов изгнала клан Громового Молота из Стальгорна, именно через этот проход он отступал.\n\nЧерез него же отступала и Орда. Отброшенные от Дун Модра, орки откатились на юг через долину Тандол и окопались в здешнем форпосте, а Андуин Лотар, желая полностью выбить их из Каз Модана, отправил свои войска разрушить эту твердыню. Штурм провалился. Орки удержались, и Дун Альгаз стал последним клочком земли, который Орда сохранила в этом краю, — плацдармом, который так и не удалось отбить.\n\nДворфийские горные пехотинцы, охранявшие этот проход, держались в основном на холмах над ним, но клан Драконьей Пасти захватил их пост и оттеснил их в верхний туннель, где они держатся до сих пор. С потерей нижнего прохода дорога между дворфийскими землями и Гаванью Менетилов стала куда опаснее.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Приют Странников",
			short = "Приют Странников стоит на юго-востоке Лок Модана; его архитектура безошибочно выдаёт работу высших эльфов, хотя в его залах остался лишь один представитель этого народа.",
			full = "Приют Странников стоит на юго-востоке Лок Модана; его архитектура безошибочно выдаёт работу высших эльфов, хотя в его залах остался лишь один представитель этого народа. С тех пор здесь поселились люди и дворфы, среди них охотники, живущие в стенах, воздвигнутых руками тех, кто давно покинул это место.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
