		["grizzlepaw ridge"] = {
			name = "Хребет Седых Лап",
			short = "Хребет Седых Лап поднимается к югу от Телсамара, и на его высотах хозяйничают многочисленные медведи.",
			full = "Хребет Седых Лап поднимается к югу от Телсамара, и на его высотах хозяйничают многочисленные медведи. Главный среди них — Старина Сажа, медведь устрашающего роста и нрава, который спускается из своего логова к подножию долины и мигом набрасывается на всякого, кому не повезло его разозлить.\n\nНа хребте живёт и Горик Газлдрафт.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Раскопки Сталекрута",
			short = "Раскопки Сталекрута на юго-востоке Лок Модана — дворфийские раскопки, начатые геологом Сталекрутом в поисках того, что было погребено древними.",
			full = "Раскопки Сталекрута на юго-востоке Лок Модана — дворфийские раскопки, начатые геологом Сталекрутом в поисках того, что было погребено древними. Но земля выдала не только реликвии: трогги, более крупные и буйные, чем на других дворфийских раскопках, поднялись из глубин и заполонили раскопки, прогнав открывших их геологов и рудокопов.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
