		["mogrosh stronghold"] = {
			name = "Оплот Мо'грош",
			short = "Пещеры Оплота Мо'грош лежат на северо-востоке Лок Модана. Здесь обитает племя огров, чьи темные громилы и повелители земли не подчиняются никому, кроме своих.",
			full = "Пещеры Оплота Мо'грош лежат на северо-востоке Лок Модана. Здесь обитает племя огров, чьи темные громилы и повелители земли не подчиняются никому, кроме своих.",
