		["north gate pass"] = {
			name = "Северные врата",
			short = "Перевал прорезает высокие горы, спускаясь из Дун Морога к Лок Модану.",
			full = "Перевал прорезает высокие горы, спускаясь из Дун Морога к Лок Модану. Это кратчайший путь между двумя краями, и путники, направляющиеся в земли за озером, чаще всего идут именно здесь.\n\nПроход охраняет Форт у северных врат.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Рудник у Серебряного ручейка",
			short = "Когда-то Рудник у Серебряного ручейка был богат серебром, и многие поколения дворфов Стальгорна черпали богатство из его жил.",
			full = "Когда-то Рудник у Серебряного ручейка был богат серебром, и многие поколения дворфов Стальгорна черпали богатство из его жил. Когда руда иссякла, Лига рудокопов не стала бросать туннели, а превратила их в склад.\n\nОдно сокровище в руднике все же осталось: заряженные самоцветы Расселины, которых больше нигде не найти. Они очень ценятся у тех, кто шьет одеяния для магов.\n\nНо дворфы больше не хозяева этих туннелей. Рудник наводнили кобольды-туннельщики, жаждущие прибрать к рукам все, что в нем осталось.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "Южные врата",
			short = "Южные врата прорезают горы, соединяя заснеженные высоты Дун Морога с низинными долинами Лок Модана. Это кратчайший путь вниз, к Телсамару, и дорогу здесь протоптали путники, снующие между двумя краями.",
			full = "Южные врата прорезают горы, соединяя заснеженные высоты Дун Морога с низинными долинами Лок Модана. Это кратчайший путь вниз, к Телсамару, и дорогу здесь протоптали путники, снующие между двумя краями.\n\nЗдесь стоит Форт у Южных врат, сторожевой пост, поставленный следить за перевалом.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Долина Камнедробов",
			short = "Долина Камнедробов лежит среди гор юго-западного Лок Модана. Когда-то нетронутая, теперь она принадлежит троггам из племени Камнедробов, которые заполонили и ее дно, и склоны.",
			full = "Долина Камнедробов лежит среди гор юго-западного Лок Модана. Когда-то нетронутая, теперь она принадлежит троггам из племени Камнедробов, которые заполонили и ее дно, и склоны. Дворфы Лок Модана считают их паразитами, которых нужно истреблять. В самой глубине долины обитает Громаг — вождь, вокруг которого сплачиваются трогги.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Каменная Плотина",
			short = "Каменная Плотина высится к востоку от перевала Дун Альгаз, вдоль северного края Лок Модана.",
			full = "Каменная Плотина высится к востоку от перевала Дун Альгаз, вдоль северного края Лок Модана.\n\nЕе строителем был дворф Черного Железа. Франклорн Искусник, зодчий этого клана, придумал тот самый способ тесать камень, которым была возведена плотина, хотя мало кто из проходящих по ней знает, что ее построила рука дворфа Черного Железа.\n\nПлотина сдерживает воды озера, и оно разлилось более чем вдвое против прежнего. Вызванное ею наводнение породило болотистые земли за ней, прежде большей частью скрытые под водой.\n\nКлан Черного Железа нанес удар по плотине, и Стальгорн в ответ усилил охрану. Теперь за нее отвечает главный инженер Плотиннер VII.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Таверна \"Крепкое пойло\"",
			short = "Таверна «Крепкое пойло» стоит в Телсамаре, и очаг в ней почти никогда не остывает. Дворфы и путники собираются здесь, чтобы выпить и обменяться новостями с озера, и мало какое место в округе может похвастаться таким постоянным потоком гостей.",
			full = "Таверна «Крепкое пойло» стоит в Телсамаре, и очаг в ней почти никогда не остывает. Дворфы и путники собираются здесь, чтобы выпить и обменяться новостями с озера, и мало какое место в округе может похвастаться таким постоянным потоком гостей.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Телсамар",
			short = "Телсамар лежит на западном берегу озера Лок Модан, к северу от Хребта Седых Лап и к северо-востоку от Долины Камнедробов. Чуть западнее города проходит дорога, которая поднимается через перевалы к Дун Морогу и Болотине.",
			full = "Телсамар лежит на западном берегу озера Лок Модан, к северу от Хребта Седых Лап и к северо-востоку от Долины Камнедробов. Чуть западнее города проходит дорога, которая поднимается через перевалы к Дун Морогу и Болотине. На местной площадке гнездятся грифоны, а таверна дает приют путникам, пересекающим высокогорье.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Долина Королей",
			short = "Долина Королей лежит в юго-западной части Лок Модана, там, где зеленые земли сужаются к вратам, ведущим вниз, в почерневшее Тлеющее ущелье.",
			full = "Долина Королей лежит в юго-западной части Лок Модана, там, где зеленые земли сужаются к вратам, ведущим вниз, в почерневшее Тлеющее ущелье. Врата заперты и охраняются: за ними присматривает горный пехотинец Щебеночка, который пропускает лишь тех, кто докажет, что достоин пройти.\n\nВзгляд здесь притягивают две огромные статуи, возвышающиеся над перевалом: Мадоран Бронзобород и Кардрос Громовой Молот, высеченные из камня, чтобы вечно стеречь дорогу на юг. Когда оба короля умерли, их сыновья вместе воздвигли эти статуи, навеки связав Бронзобородов и Громовых Молотов в камне, как их отцы были связаны при жизни. Южные земли за перевалом Рагнарос обратил в огонь и пепел, и статуи смотрят прямо на это пепелище: как предостережение всякому, кто посмеет выступить против дворфийских королевств, и как напоминание о цене, которую дворфы Черного Железа заплатили за содеянное.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Красногорье: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Лесопилка Альтера",
			short = "Лесопилка к северо-востоку от Приозерья стоит заброшенной, и колесо ее давно замерло. Когда-то она была лишь остановкой на пути к Крепости Каменной Стражи, а теперь в ее развалинах живут пауки, стервятники да изредка забредшие орки.",
			full = "Лесопилка к северо-востоку от Приозерья стоит заброшенной, и колесо ее давно замерло. Когда-то она была лишь остановкой на пути к Крепости Каменной Стражи, а теперь в ее развалинах живут пауки, стервятники да изредка забредшие орки.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Долина Галарделл",
			short = "Долина Галарделл на северо-востоке Красногорья кишит гноллами под началом лейтенанта Фангора, чей вой созывает стаи на всякого, кто вышел против него неподготовленным.",
			full = "Долина Галарделл на северо-востоке Красногорья кишит гноллами под началом лейтенанта Фангора, чей вой созывает стаи на всякого, кто вышел против него неподготовленным.\n\nНад долиной высится Башня Илгалара, обиталище злобного Морганта, и одно его имя внушает страх перед этим местом.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Озеро Безмолвия",
			short = "Озеро Безмолвия лежит в самом сердце Красногорья, и его широкие синие воды — единственная причина, по которой существует сонный городок Приозерье.",
			full = "Озеро Безмолвия лежит в самом сердце Красногорья, и его широкие синие воды — единственная причина, по которой существует сонный городок Приозерье. Озеро стекает на восток, и его река бежит к темным камням Крепости Каменной Стражи.\n\nКогда-то это было озеро рыбаков, тихое и надежное, но все изменилось. Племена мурлоков заполонили и отмели, и глубины, а где-то в темной воде до сих пор кружит крепкозуб, такой старый и огромный, что даже бывалые охотники из мурлочьих племен обходят его стороной. Мост Безмолвия по-прежнему переносит путников через воду, над стойбищами мурлоков и над тем, что следит за ними снизу.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Озерный тракт",
			short = "Когда-то по Озерному тракту вдоль южного берега озера Безмолвия шли непрерывным потоком путники, но потом орки захватили Крепость Каменной Стражи, и дорога опустела.",
			full = "Когда-то по Озерному тракту вдоль южного берега озера Безмолвия шли непрерывным потоком путники, но потом орки захватили Крепость Каменной Стражи, и дорога опустела. Теперь почти по всей ее длине рыщут гноллы, а дальше в засаде таятся хорошо укрытые охотники Черной горы. Путешествовать по ней никто не посоветует.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Приозерье",
			short = "Озеро Безмолвия лежит тихое и холодное под вершинами Красногорья, и городок на его берегу не раз проливал кровь за эту землю.",
			full = "Озеро Безмолвия лежит тихое и холодное под вершинами Красногорья, и городок на его берегу не раз проливал кровь за эту землю. Когда вождь Чернорук впервые повел орков в эти горы, сэр Андуин Лотар и рыцари Штормграда устроили им засаду на склонах и едва не разбили их, но два чернокнижника из Совета Теней переломили ход битвы и заставили Лотара отступить. Спустя несколько недель Чернорук вернулся с куда большим войском и взял Приозерье. Лишь после Второй войны Альянс Лордерона отвоевал городок, и главнокомандующий Туралион сам следил за возвращением его рассеянных жителей.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
