		["renders rock"] = {
			name = "Скала Ренда",
			short = "Скала Ренда — просторная пещера на северо-западе Красногорья, близ Пылающих степей. Ее удерживают крупные силы орков Черной горы.",
			full = "Скала Ренда — просторная пещера на северо-западе Красногорья, близ Пылающих степей. Ее удерживают крупные силы орков Черной горы.\n\nЗдесь лежит раненый капрал Кеешан: он отрезан от своих, и ему нужно добраться до Приозерья живым.",
