			short = "Долина Ренда лежит на юго-востоке Красногорья. Некогда здесь был аванпост орков Черной горы, а теперь это укрепленная твердыня, окруженная башнями и охраняемая отборными воинами.",
			full = "Долина Ренда лежит на юго-востоке Красногорья. Некогда здесь был аванпост орков Черной горы, а теперь это укрепленная твердыня, окруженная башнями и охраняемая отборными воинами.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Пещеры Ретбана",
			short = "Пещеры Ретбана уходят глубоко в северо-западные горы Красногорья. Туннели удерживают гноллы под началом хитрого Ардо Грязной Лапы, которые копят ретбанскую руду, вырванную из камня.",
			full = "Пещеры Ретбана уходят глубоко в северо-западные горы Красногорья. Туннели удерживают гноллы под началом хитрого Ардо Грязной Лапы, которые копят ретбанскую руду, вырванную из камня. Возможно, пещеры названы в честь человека по имени Барт Ретбан, хотя больше о нем почти ничего не помнят.",
