		["stonewatch"] = {
			name = "Водопад Каменной Стражи",
			short = "Когда-то Каменная Стража принадлежала людям Приозерья: твердыня, прильнувшая к скалам, у подножия которых низвергается водопад, стерегла Красногорье от орочьей угрозы из Пылающих степей.",
			full = "Когда-то Каменная Стража принадлежала людям Приозерья: твердыня, прильнувшая к скалам, у подножия которых низвергается водопад, стерегла Красногорье от орочьей угрозы из Пылающих степей.\n\nЭтот дозор был сломлен предательством. Чернокнижник Моргант заключил союз с Гат'Илзоггом и его орками Черной горы, и их объединенные силы обрушились на Крепость Каменной Стражи с такой яростью, что гарнизон дрогнул. Орки взяли крепость, но недолго длилось их торжество и доверие: Моргант обратился против союзников, завоевавших ее для него. Он воздвиг для себя Башню Илгалара и подчинил своим целям отряд гноллов из стаи Темношкуров под началом лейтенанта Фангора. С тех пор и орки, и люди, оказавшиеся на пути гноллов, платят за это дорогой ценой.\n\nБрошенные чернокнижником, который их использовал, орки Черной горы удержали крепость своими силами. Правит ею Гат'Илзогг, а рядом с ним его лейтенант Тарил'зун.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Водопад Каменной Стражи",
			short = "Ниже Каменной Стражи восточная река, вытекающая из озера Безмолвия, долгим каскадом срывается по склону и собирается в глубокое озеро в укромном уголке Красногорья.",
			full = "Ниже Каменной Стражи восточная река, вытекающая из озера Безмолвия, долгим каскадом срывается по склону и собирается в глубокое озеро в укромном уголке Красногорья. На его берегах поселилось небольшое племя мурлоков: они ловят рыбу и сооружают грубые укрытия под водопадом.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Крепость Каменной Стражи",
			short = "Когда-то Крепость Каменной Стражи принадлежала людям Приозерья и стерегла Красногорье.",
			full = "Когда-то Крепость Каменной Стражи принадлежала людям Приозерья и стерегла Красногорье. Она пала, когда чернокнижник Моргант заключил союз с военачальником орков Черной горы Гат'Илзоггом, и их объединенные силы бросились на крепость с яростью, которую подпитывала темная магия Морганта. Защитники дрогнули, и крепость была взята.\n\nСоюз продлился недолго. Едва Каменная Стража пала, как Моргант обратился против орков, что проливали за нее кровь рядом с ним. Он воздвиг неподалеку Башню Илгалара и наполнил ее гноллами из стаи Темношкуров под началом лейтенанта Фангора — тварями, покорными лишь его воле. С тех пор от спущенных им зверюг пали и орки, и люди.\n\nБрошенные союзником-чернокнижником, орки Черной горы удержали крепость своими силами, и теперь Гат'Илзогг и его лейтенант Тарил'зун правят тем, что от нее осталось. Во время битвы они взяли в плен капрала Кеешана из армии Штормграда и увели его на север, в свои лагеря. Мировой судья Соломон назначил за это награду за голову Гат'Илзогга, а маршал Маррис из Приозерья поклялся, что и Тарил'зун ответит за свои преступления.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Башня Каменной Стражи",
			short = "Когда-то Башня Каменной Стражи стояла рядом с Крепостью Каменной Стражи, и обе принадлежали людям Приозерья, пока твердыню не захватил клан Черной горы.",
			full = "Когда-то Башня Каменной Стражи стояла рядом с Крепостью Каменной Стражи, и обе принадлежали людям Приозерья, пока твердыню не захватил клан Черной горы. Теперь башня служит дозорным постом для приспешников Гат'Илзогга: орки клана Черной горы стерегут отсюда твердыню, которую их сородичи отняли у жителей Приозерья.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Три Угла",
			short = "У Трех Углов дорога расходится натрое: на запад — к Златоземью в Элвиннском лесу, на восток — к Приозерью, на юг — к Темнолесью в Сумеречном лесу.",
			full = "У Трех Углов дорога расходится натрое: на запад — к Златоземью в Элвиннском лесу, на восток — к Приозерью, на юг — к Темнолесью в Сумеречном лесу. Стоя здесь, путник оказывается на стыке трех земель, и лишь перекресток отмечает переход между ними. С окрестных холмов наседают гноллы.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Башня Илгалара",
			short = "Башня Илгалара высится на востоке Красногорья.",
			full = "Башня Илгалара высится на востоке Красногорья. Правит ею Моргант, колдун, изгнанный из Квартала Магов Штормграда за занятия темными искусствами. Он сделал башню своим убежищем и подчинил своей воле гноллов из стаи Темношкуров.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Тернистая долина: 38 subzones
	[1434] = {
