		["ballal ruins"] = {
			name = "Руины Бал'лал",
			short = "Близ Коварного рифа, к северу от Лагеря Гром'гол, высятся обломки колонн — все, что осталось от поселения, которое давным-давно возвели тролли. Мало что сохранилось от его былого облика.",
			full = "Близ Коварного рифа, к северу от Лагеря Гром'гол, высятся обломки колонн — все, что осталось от поселения, которое давным-давно возвели тролли. Мало что сохранилось от его былого облика. Теперь руины занимают тролли из племени Кровавого Скальпа, поселившиеся среди камней, оставленных их предками.",
