		["bloodsail compound"] = {
			name = "Лагерь Кровавого Паруса",
			short = "Пираты Кровавого Паруса держат беспорядочный лагерь на западном побережье Тернистой долины, укрывшийся ближе к середине берега.",
			full = "Пираты Кровавого Паруса держат беспорядочный лагерь на западном побережье Тернистой долины, укрывшийся ближе к середине берега. Здесь не реют знамена порядка и нет дисциплины настоящего порта — лишь разрозненное сборище пиратов, которые считают это место своим.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Пиратская бухта",
			short = "Пиратская бухта лежит в синей лагуне на южной оконечности Тернистой долины, и пеший путник входит в нее через выбеленные челюсти гигантской акулы.",
			full = "Пиратская бухта лежит в синей лагуне на южной оконечности Тернистой долины, и пеший путник входит в нее через выбеленные челюсти гигантской акулы. Жизнь здесь дешева, и доверять нельзя никому: это рай для проходимцев, где полно осведомителей и торговцев всех мастей.\n\nПрежде чем получить свое нынешнее имя, бухта звалась Бухтой Черноводья и была небольшим людским портом, пока ее не захватили тролли джунглей. Гоблины из картеля Хитрая Шестеренка отбросили троллей от берега и забрали бухту себе еще до Первой войны, а затем построили здесь свой главный центр в Восточных королевствах.\n\nТеперь портом заправляют Разбойники Черноводья в тесном союзе с картелем, и двери его открыты любому путнику, под каким бы знаменем тот ни ходил. Барон Ревилгаз правит с верхнего этажа таверны вместе с командиром флота Морским Рогом из Разбойников. Он не скупится, нанимая мечи против пиратов Кровавого Паруса, которые не раз замышляли, пока безуспешно, захватить саму бухту.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Мыс Тернистой долины",
			short = "Южные земли Тернистой долины полны тролльих руин, наполовину поглощенных джунглями, и длинных песчаных берегов, где деревья уступают место морю.",
			full = "Южные земли Тернистой долины полны тролльих руин, наполовину поглощенных джунглями, и длинных песчаных берегов, где деревья уступают место морю.\n\nНа побережье стоит Пиратская бухта — портовый город, которым заправляют гоблины-пираты. Его причалы и рынок открыты всякому, у кого есть монеты, под каким бы знаменем он ни ходил.\n\nНо нейтралитет — это не мир. Гоблины Пиратской бухты удерживают гавань торговлей и силой, а их соперники — пираты Кровавого Паруса, которые обратились против них и совершают набеги на воды и берега, что гоблины считают своими. Вражда между ними лишь разгорается, корабль против корабля и лагерь против лагеря: гоблины стерегут то, что построили, а Кровавые Паруса наседают, чтобы это отнять.\n\nЗа гаванью и руинами земля безмолвна: песок, старые камни и море вдали.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Хрустальное взморье",
			short = "Хрустальное взморье — песчаное побережье на юго-востоке Тернистой долины, где волны Южных морей разбиваются о материк и о восточные пляжи острова Жагуаро.",
			full = "Хрустальное взморье — песчаное побережье на юго-востоке Тернистой долины, где волны Южных морей разбиваются о материк и о восточные пляжи острова Жагуаро. Оно тянется от Пустынного берега до скал, где земля поднимается к северу, и отрезано от глубинных земель крутым хребтом, через который ведут лишь две тропы; одна из них поднимается к Мглистой долине.\n\nНа северном конце взморья лежат Руины Абораза.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
