		["crystalvein mine"] = {
			name = "Хрустальная шахта",
			short = "Шиззи Пуззырикс называл их Поющими кристаллами: такие встречаются только в Тернистой долине и стоят целое состояние.",
			full = "Шиззи Пуззырикс называл их Поющими кристаллами: такие встречаются только в Тернистой долине и стоят целое состояние. Их жилы пронизывают породу Хрустальной шахты близ Зул'Мамбве, и гнездящиеся там василиски поедают их прямо так, отчего их шкуры твердеют, словно камень. Торговая компания сунулась сюда в надежде выпотрошить шахту, но василиски отбили все попытки. У входа стоят тролли и люди, обратившиеся в кристалл там, где их настигла смерть.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Лагерь Гром'гол",
			short = "Лагерь Гром'гол стоит укрепленным на юго-западном побережье Тернистой долины. Его частоколы возведены против прибрежных троллей джунглей, против наг, поднимающихся из прибоя, и против Альянса, пробирающегося сюда из Пиратской бухты и Сумеречного леса.",
			full = "Лагерь Гром'гол стоит укрепленным на юго-западном побережье Тернистой долины. Его частоколы возведены против прибрежных троллей джунглей, против наг, поднимающихся из прибоя, и против Альянса, пробирающегося сюда из Пиратской бухты и Сумеречного леса. Лагерем командует командир Агро'гош, который бережет его как надежное звено в цепи снабжения, тянущейся к Каменору на Болоте Печали.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Арена Гурубаши",
			short = "Арена Гурубаши стоит на северо-западе Тернистой долины — реликвия тех дней, когда империя Гурубаши правила обширными землями на юге Восточных королевств.",
			full = "Арена Гурубаши стоит на северо-западе Тернистой долины — реликвия тех дней, когда империя Гурубаши правила обширными землями на юге Восточных королевств.\n\nВ давние времена бои здесь были не забавой, а бойней. Песок превращался в грязь от тролльей крови, а бойцы сражались насмерть. Теперь Коротышка Джон Мифрил устраивает поединки помягче, суля славу и добычу, а не смерть. Старые предания до сих пор предостерегают: кто найдет в полночь кроваво-красный амулет, того еще до рассвета пожрет демон.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Остров Жагуаро",
			short = "У Пустынного берега лежит остров Жагуаро — джунгли, где властвуют пантеры и гориллы, не подчиняющиеся никому.",
			full = "У Пустынного берега лежит остров Жагуаро — джунгли, где властвуют пантеры и гориллы, не подчиняющиеся никому. Главный среди них — Король Мукла, огромная обезьяна. Он правит островом и держит в плену принцессу Пубу, таурена, удерживаемую против ее воли.\n\nВдоль берега, наполовину зарывшись в песок, лежат выброшенные морем бутылки, и в одной из них — сложенная записка.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
