		["janeiros point"] = {
			name = "Остров Жанейро",
			short = "Остров Жанейро — маленький островок у Пиратской бухты, отмеченный огромной каменной статуей гоблина с широко раскинутыми руками. Ее воздвигли как маяк, чтобы встречать корабли, входящие в гавань.",
			full = "Остров Жанейро — маленький островок у Пиратской бухты, отмеченный огромной каменной статуей гоблина с широко раскинутыми руками. Ее воздвигли как маяк, чтобы встречать корабли, входящие в гавань. Никто уже не помнит, чье подобие она запечатлела. Морской великан Мок'раш Рассекатель сделал этот остров своим обиталищем.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Руины Кал'аи",
			short = "Руины Кал'аи наполовину поглощены морем в Тернистой долине: древняя кладка троллей, источенная приливами и временем.",
			full = "Руины Кал'аи наполовину поглощены морем в Тернистой долине: древняя кладка троллей, источенная приливами и временем. Теперь среди поваленных колонн гнездится мурлочье племя Мутных Жабр, объявившее затонувшие залы своими.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Лагерь Курцена",
			short = "Лагерь Курцена стоит к востоку от Лагеря Повстанцев, и здесь располагается штаб экспедиции Курцена. Ею командует полковник Курцен, хотя его разум поглотило безумие.",
			full = "Лагерь Курцена стоит к востоку от Лагеря Повстанцев, и здесь располагается штаб экспедиции Курцена. Ею командует полковник Курцен, хотя его разум поглотило безумие. О том, во что он превратился, не говорят — известен лишь итог: его люди раскололись. Те, кто отказался следовать за ним дальше, ушли и стали лесными бойцами Лагеря Повстанцев, и с тех пор лагерь воюет с ними. Люди, некогда служившие под одним началом, теперь убивают друг друга среди деревьев.\n\nСам Курцен теперь редко показывается своим людям: говорят, он не покидает Схрон в глубине лагеря, где бойцы хранят оружие. Возле стойл в клетках держат пантер и тернистодольских тигров, которых ломают и приучают становиться боевыми зверями экспедиции.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Озеро Назферити",
			short = "Воды озера Назферити кишат хищными рыбами и кроколисками, а на его берегу теснится большая база Торговой компании.",
			full = "Воды озера Назферити кишат хищными рыбами и кроколисками, а на его берегу теснится большая база Торговой компании.\n\nОзеро питает река Назферити, которую некоторые считают самой длинной на юге Восточных королевств. Она берет начало у водопада в Красногорье, а может быть, и еще дальше — на Перевале Мертвого Ветра.",
