		["pool of tears"] = {
			name = "Озеро Слез",
			short = "Озеро Слез лежит широким и неподвижным на восточном краю Болота Печали. Под его спокойной гладью скрыт Храм Атал'Хаккара: его возвели тролли, а Изера погрузила его на дно, спрятав от мира.",
			full = "Озеро Слез лежит широким и неподвижным на восточном краю Болота Печали. Под его спокойной гладью скрыт Храм Атал'Хаккара: его возвели тролли, а Изера погрузила его на дно, спрятав от мира. Зеленые драконы долго стерегли затонувшее место, не давая ничему пробудить то, что спит внизу.\n\nТеперь в воде снуют кровожадные хищные рыбы, а на берегу валяются обломки кладки Атал'ай.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
