		["shifting mire"] = {
			name = "Ползучая трясина",
			short = "Ил Ползучей трясины никогда не лежит спокойно. Он собирается по земле тонкими наносами и ползет по болоту, словно его тащит что-то невидимое, свиваясь и скапливаясь, будто живое существо.",
			full = "Ил Ползучей трясины никогда не лежит спокойно. Он собирается по земле тонкими наносами и ползет по болоту, словно его тащит что-то невидимое, свиваясь и скапливаясь, будто живое существо.\n\nНекоторые говорят, что сила, движущая им, не злая: это некая благая энергия, которая шевелит ил без всякого намерения навредить.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
