		["stonard"] = {
			name = "Каменор",
			short = "Каменор поднимается из трясины Болота Печали, и его большой зал все еще стоит там, где многие другие орочьи залы давно пали.",
			full = "Каменор поднимается из трясины Болота Печали, и его большой зал все еще стоит там, где многие другие орочьи залы давно пали. Подступы охраняют две землянки, а орочьи дозоры выходят удерживать небольшие лагеря поблизости — каждый из них еще одна заявка на эту землю, отвоеванная у болота.\n\nАванпост стар, старше почти любого другого орочьего оплота по эту сторону мира. Он брат крепости, некогда известной как Рокард. Его возвела Старая Орда в Черных топях в те дни, когда Темный портал только открылся. Когда пришла Вторая война и Орда была разбита, Каменор затих: вероятно, его бросили или разрушили вместе с многим другим, что построили орки.\n\nНо пустовал он недолго. С возвышением новой Орды и вновь окрепшей решимостью удержать эту землю Каменор был отстроен: зал восстановлен, землянки вырыты заново. Рокарду повезло меньше: огры Молота Ужаса захватили старую крепость и переименовали ее в Форт Молота Ужаса. Так Каменор остался единственным аванпостом Орды на болоте, последним залом такого рода, где в этих низинах еще горит огонь.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Храм Атал'Хаккара",
			short = "Более тысячи лет назад империя Гурубаши разорвала себя на части в междоусобной войне. В ее сердце стояли Атал'ай — жрецы-тролли, стремившиеся вернуть в мир бога крови Хаккара Свежевателя Душ.",
			full = "Более тысячи лет назад империя Гурубаши разорвала себя на части в междоусобной войне. В ее сердце стояли Атал'ай — жрецы-тролли, стремившиеся вернуть в мир бога крови Хаккара Свежевателя Душ. Побежденные и изгнанные, они бежали на север, на Болото Печали, и воздвигли там храм, чтобы готовиться к его возвращению.\n\nДраконья Аспект Изера узнала об их замысле и погрузила храм в трясину, намереваясь навеки похоронить их труды. Но вышло иначе. Никем не тревожимые в затопленной тьме, укрытые от любого взгляда, который мог бы их остановить, Атал'ай спокойно продолжали свои обряды. Зеленые драконы, которых Изера поставила стеречь руины, несут дозор и поныне, удерживая закрытой дверь, что никогда не была запечатана по-настоящему.\n\nИ все так же храм лежит затонувшим и наполовину затопленным, алтари Хаккара в нем целы, а входящих туда ждет участь хуже смерти. Лоа крови причитаются не только плоть, но и души, и каждая отданная ему душа приближает день, когда он не потерпит поражения.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
