	-- Западный Край: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Поместье Алекстона",
			short = "Поля Поместья Алекстона когда-то кормили семьи, пока Братство Справедливости не забрало эту землю себе.",
			full = "Поля Поместья Алекстона когда-то кормили семьи, пока Братство Справедливости не забрало эту землю себе. Теперь среди борозд движутся лишь механические дозорные полей — неутомимые, никем не управляемые, они стерегут ряды, которые больше никто не засевает.\n\nБарос Алекстон, ставший впоследствии архитектором Штормграда, родился на этой земле. Мальчиком он трудился здесь, на тех самых полях, по которым теперь ходят дозорные, прежде чем земля, взрастившая его, перешла в чужие руки.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Холмы Разбойничьих Кинжалов",
			short = "Холмы Разбойничьих Кинжалов поднимаются грядой позади Луноречья, на юге Западного Края. Теперь здесь мало что шевелится.",
			full = "Холмы Разбойничьих Кинжалов поднимаются грядой позади Луноречья, на юге Западного Края. Теперь здесь мало что шевелится. Среди холмов обосновался Мрачнобух Громовар — одна из немногих живых душ в этом тихом краю, а еще известно, что здесь из земли поднимается упырь Лепритус.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "Мертвая пашня",
			short = "Когда-то Мертвая пашня была одной из ферм на юго-востоке Западного Края, близ моста в Сумеречный лес. Когда Братство Справедливости захватило этот край, оно забрало и стоявшую здесь ферму вместе с полями.",
			full = "Когда-то Мертвая пашня была одной из ферм на юго-востоке Западного Края, близ моста в Сумеречный лес. Когда Братство Справедливости захватило этот край, оно забрало и стоявшую здесь ферму вместе с полями.\n\nТеперь по ней не ходит ни один фермер. Вместо них по земле вышагивают механические дозорные полей, бродя там, где когда-то рос урожай.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Мертвые копи",
			short = "Под Луноречьем глубоко тянутся туннели, и некогда они были полны золота. Еще до того, как орки вторглись в людские земли, Мертвые копи пополняли казну Штормграда — по некоторым сведениям, треть ее добывалась из этой породы.",
			full = "Под Луноречьем глубоко тянутся туннели, и некогда они были полны золота. Еще до того, как орки вторглись в людские земли, Мертвые копи пополняли казну Штормграда — по некоторым сведениям, треть ее добывалась из этой породы. Первая война лишила рудники рудокопов, а после их бросили, сочли населенными призраками, и долгое время к ним никто не прикасался.\n\nВ эту тишину пришел Эдвин ван Клиф. Он собрал Братство Справедливости — бывших работников, ставших разбойниками, — и с помощью гоблинов заставил их строить в глубинах исполинский боевой корабль.\n\nВ тех глубинах ван Клиф остается и поныне под охраной своего Братства, а Гриан Камнегрив тем временем собирает на Сторожевом холме людей, поклявшихся добыть его голову.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Участок Демонта",
			short = "От Участка Демонта к западу от Луноречья мало что осталось, кроме переломанных бревен и заросших полей. Когда-то это была жилая ферма, а теперь ее заняли агенты Братства Справедливости, считающие ее своей.",
			full = "От Участка Демонта к западу от Луноречья мало что осталось, кроме переломанных бревен и заросших полей. Когда-то это была жилая ферма, а теперь ее заняли агенты Братства Справедливости, считающие ее своей.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Пыльные равнины",
			short = "Пыльные равнины раскинулись по югу Западного Края — сухая земля, отданная гноллам, которые разбили здесь несколько лагерей и угрожают каждому, кто пересекает их территорию.",
			full = "Пыльные равнины раскинулись по югу Западного Края — сухая земля, отданная гноллам, которые разбили здесь несколько лагерей и угрожают каждому, кто пересекает их территорию.\n\nНа восточном краю стоит Башня Мортвейка — старая башня мага, первоначальное назначение которой давно забыто под властью новых хозяев.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Тыквенная ферма Хмуроброва",
			short = "Когда-то за Тыквенной фермой Хмуроброва ухаживали фермер Хмуробров и его жена Верна, но когда Братство Справедливости прокатилось по Западному Краю со своими механическими полевыми големами, ферма пала, как и многие другие в этом краю.",
			full = "Когда-то за Тыквенной фермой Хмуроброва ухаживали фермер Хмуробров и его жена Верна, но когда Братство Справедливости прокатилось по Западному Краю со своими механическими полевыми големами, ферма пала, как и многие другие в этом краю. Хмуробров и Верна бежали и нашли приют у дороги близ Владения Янсена на севере, оставив позади и свои тыквы, и свое имя.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Прииск на Золотом Берегу",
			short = "Когда-то Прииск на Золотом Берегу давал Штормграду золото и руду, пока Западный Край не пришел в упадок. Теперь им владеет Братство Справедливости, разрабатывающее карьеры под собственным знаменем.",
			full = "Когда-то Прииск на Золотом Берегу давал Штормграду золото и руду, пока Западный Край не пришел в упадок. Теперь им владеет Братство Справедливости, разрабатывающее карьеры под собственным знаменем. Народное ополчение и его бойцы не раз сталкивались здесь с Братством, попадая в засады, устроенные разбойниками среди камней, которые они до сих пор патрулируют.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Рудник Янго",
			short = "Когда-то Рудник Янго поставлял руду в Штормград и был одним из самых надежных источников подземных богатств Западного Края.",
			full = "Когда-то Рудник Янго поставлял руду в Штормград и был одним из самых надежных источников подземных богатств Западного Края.\n\nЭтой надежности пришел конец, когда рудник захватило Братство Справедливости. С тех пор в его шахты пробрались кобольды и объявили их своими.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "Владение Янсена",
			short = "Владение Янсена стоит на северной окраине Западного Края, возле моста в Элвиннский лес. Как и другие фермы края, оно лишилось законных хозяев, когда их изгнало Братство Справедливости.",
			full = "Владение Янсена стоит на северной окраине Западного Края, возле моста в Элвиннский лес. Как и другие фермы края, оно лишилось законных хозяев, когда их изгнало Братство Справедливости.\n\nНеподалеку живут фермер Хмуробров и его жена: они бежали из собственного дома на Тыквенной ферме Хмуроброва и теперь ютятся у этого владения.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Бескрайний берег",
			short = "Побережье Западного Края тянется длинное и пустынное — один из самых широких пляжей Азерота.",
			full = "Побережье Западного Края тянется длинное и пустынное — один из самых широких пляжей Азерота. Вдоль него снуют мурлоки, и их слишком много, чтобы сдержать. Среди них плавает Старый Мутноглаз — тварь, которую прибрежные рыбаки научились бояться и называть по имени. За полосой прибоя лежат остовы кораблей, так и не добравшихся до берега, и среди них эльфийские эсминцы, отданные на волю прилива.\n\nНа дальнем юго-западном краю пляжа стоит ферма Дафны Стилвелл. Братство Справедливости не раз приходило за ней, намереваясь выжечь ее, как выжгло многое другое в Западном Краю. Весть о ее беде дошла до Даториана Ралла, и он отправил на побережье претендентов в рыцари Серебряной Длани, чтобы те стерегли ее землю, и они ее отстояли.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "Ферма Мольсена",
			short = "Ферма Мольсена — одна из многих ферм Западного Края, которые удерживает Братство Справедливости.",
			full = "Ферма Мольсена — одна из многих ферм Западного Края, которые удерживает Братство Справедливости. Ее грядки отданы ржавчине и машинам, а по полям бродят механические дозорные полей, сражая всякого, кто подойдет слишком близко.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Луноречье",
			short = "Под полями Луноречья когда-то пролегала треть казны Штормграда — золото, добытое в туннелях, которые позже назвали Мертвыми копями.",
			full = "Под полями Луноречья когда-то пролегала треть казны Штормграда — золото, добытое в туннелях, которые позже назвали Мертвыми копями. Городок был житницей королевства, пока роспуск Гильдии каменщиков не вызвал беспорядки, в которых погибла королева Тиффин Ринн. Месть короля Вариана за ее смерть тяжелее всего обрушилась на гильдию, и каменщики бежали в фермерские угодья Западного Края, спасаясь от него. Их гнев, раздуваемый из тени, породил Братство Справедливости. Под предводительством Эдвина ван Клифа они занялись разбоем, прогнали фермеров из Луноречья и превратили заброшенные рудничные туннели под городком в свою штаб-квартиру, где втайне строили оружие, которое должно было уничтожить Штормград с моря.\n\nГодами ни одно войско не приходило призвать их к ответу. Братство по-прежнему удерживает Луноречье, и лишь Народное ополчение Гриана Камнегрива противостоит ему, набираясь сил на Сторожевом холме для грядущей расплаты.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Ферма Сальдена",
			short = "Ферма Сальдена — единственная в Западном Краю, которую Братство Справедливости так и не захватило. По ее полям бродят полевые големы Братства, но фермер Сальден и его жена Сальма отказались уходить.",
			full = "Ферма Сальдена — единственная в Западном Краю, которую Братство Справедливости так и не захватило. По ее полям бродят полевые големы Братства, но фермер Сальден и его жена Сальма отказались уходить. Их дом уже много лет служит пристанищем для путников, и супруги делают все, что в их силах, чтобы их гости остались живы.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Сторожевой холм",
			short = "Сторожевой холм возвышается над фермерскими угодьями Западного Края, и его башня присматривает за домиками, кузницей и мельницей, выстроенными на склоне ниже.",
			full = "Сторожевой холм возвышается над фермерскими угодьями Западного Края, и его башня присматривает за домиками, кузницей и мельницей, выстроенными на склоне ниже.\n\nИ гноллы из стаи Речной Лапы, и Братство Справедливости не раз нападали на холм и земли под его защитой.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Пруд Стенделя",
			short = "К юго-западу от Сторожевого холма лежит небольшой пруд, и вода его замерла в кольце гноллов.",
			full = "К юго-западу от Сторожевого холма лежит небольшой пруд, и вода его замерла в кольце гноллов. На берегу покоятся две могилы и разбросаны старые кости, а с водой что-то не так, словно пить ее больше никогда не полагалось.\n\nРыбаки, пытающие здесь удачу, в основном вылавливают обычных шалфокуней. Но говорят, что под поверхностью плавает кое-что еще — рыба под названием Погибель Стенделя, которую редко видят и еще реже ловят.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Маяк в Западном Крае",
			short = "Маяк стоит на крайнем юге Западного Края, и по ночам его луч все так же обходит воду, хотя рука, что его зажигает, теперь принадлежит мертвецу.",
			full = "Маяк стоит на крайнем юге Западного Края, и по ночам его луч все так же обходит воду, хотя рука, что его зажигает, теперь принадлежит мертвецу.\n\nКогда-то за огнем присматривала одна семья, пока из прибоя не вылез мурлок Старый Мутноглаз и не прогнал их в ужасе. Они вернулись и снова зажгли огонь, но Старый Мутноглаз пришел опять, и на этот раз привел с собой мурлоков со всего побережья, чтобы напасть на маяк. Семья не пережила этого набега. Грейсон видел, как они погибли у него на глазах, и не смог этому помешать. Теперь огонь поддерживает его призрак, стоящий на страже у башни, и некому его сменить.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Болотина: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Лагерь Злого Клыка",
			short = "Лагерь Злого Клыка раскинулся в центральной части Болотины. Это крупнейший лагерь клана Драконьей Пасти в здешних краях, где живут орки Злого Клыка.",
			full = "Лагерь Злого Клыка раскинулся в центральной части Болотины. Это крупнейший лагерь клана Драконьей Пасти в здешних краях, где живут орки Злого Клыка.\n\nПод началом Нек'роша Черепобоя, сына Некросса Черепобоя, лагерь превратился в место сбора сил: здесь стягивают катапульты для штурма Гавани Менетилов. Угроза столь реальна, что капитан Крепкий Кулак поклялся увидеть Нек'роша мертвым, а боевые знамена клана сорванными прежде, чем катапульты сдвинутся с места.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Бухта Барадин",
			short = "Воды Бухты Барадин омывают побережье там, где Каз Модан сходится с Лордероном, касаясь берегов Гавани Менетилов и Крепости Стромгард.",
			full = "Воды Бухты Барадин омывают побережье там, где Каз Модан сходится с Лордероном, касаясь берегов Гавани Менетилов и Крепости Стромгард. На ее мелководье снуют мурлоки и кроколиски, а в глубоких водах хозяйничают акулы и крабы.\n\nПодлинная история бухты лежит разбитой на ее дне. Во время Второй войны армада Кул Тираса патрулировала эти воды, защищая побережье от войны, охватившей Восточные королевства. Но Кул Тирас дорого заплатил за эту бдительность: в боях погибла Третья флотилия королевства. Часть ее обломков до сих пор лежит вдоль побережья Болотины, и их видно на мелководье, где корабли разбились, а другие затонули целиком и опустились во тьму, откуда их с тех пор никто не поднимал.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Черная трясина",
			short = "Дорога к Гавани Менетилов огибает Черную трясину на юго-западе Болотины.",
			full = "Дорога к Гавани Менетилов огибает Черную трясину на юго-западе Болотины. По всей топи гнездятся ящеры, и самые голодные из них подходят близко к обочине, так что путникам на этом отрезке пути стоит быть начеку.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Болота Синежабрых",
			short = "В водах Болот Синежабрых на западе Болотины стоят стойбища мурлоков-синежабров, которые никогда не ходят поодиночке, а бродят среди тростника по двое и по трое.",
			full = "В водах Болот Синежабрых на западе Болотины стоят стойбища мурлоков-синежабров, которые никогда не ходят поодиночке, а бродят среди тростника по двое и по трое. Во главе их стоит Жрун, мурлок свирепее прочих, и из-за него на болото лучше входить с осторожностью.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Таверна \"Большая вода\"",
			short = "Таверна «Большая вода» стоит в Гавани Менетилов, и ее общий зал полон разговоров проезжих моряков.",
			full = "Таверна «Большая вода» стоит в Гавани Менетилов, и ее общий зал полон разговоров проезжих моряков. Это грубое место: стулья здесь летают так же часто, как наливается эль, а драки нередко начинаются с подначки Яна «Проныры» Тапоке.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Зловещий холм",
			short = "Когда-то Зловещий холм служил крупным лагерем дворфов Черного Железа, которых возглавлял чернокнижник Балгарас Нечистый.",
			full = "Когда-то Зловещий холм служил крупным лагерем дворфов Черного Железа, которых возглавлял чернокнижник Балгарас Нечистый.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Врата Драконьей Пасти",
			short = "Врата Драконьей Пасти стерегут красные драконы под началом дракона Акстроза, который преграждает путь тем, кто стремится попасть в Грим Батол.",
			full = "Врата Драконьей Пасти стерегут красные драконы под началом дракона Акстроза, который преграждает путь тем, кто стремится попасть в Грим Батол.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "Дун Альгаз",
			short = "Туннель через Дун Альгаз старше раздора, расколовшего дворфов. Когда Война Трех Кланов изгнала Громовых Молотов из Стальгорна, именно через этот перевал они отступили.",
			full = "Туннель через Дун Альгаз старше раздора, расколовшего дворфов. Когда Война Трех Кланов изгнала Громовых Молотов из Стальгорна, именно через этот перевал они отступили.\n\nЧерез него же отступала и Орда. Отброшенные от Дун Модра, орки ушли на юг через долину Тандола и закрепились в здешнем форте, и Андуин Лотар, желая вышвырнуть их из Каз Модана окончательно, послал свои войска разрушить эту твердыню. Штурм провалился. Орки удержались, и Дун Альгаз стал последним клочком земли, который Орда сохранила в этом краю, — плацдармом, который так и не удалось отвоевать.\n\nГорные пехотинцы дворфов, охранявшие этот перевал, большей частью держались на холмах над ним, но клан Драконьей Пасти захватил их пост и оттеснил их к верхнему туннелю, где они держатся до сих пор. С потерей нижнего перевала дорога между дворфийскими землями и Гаванью Менетилов стала куда опаснее.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Дун Модр",
			short = "Дун Модр стоит к югу от Моста Тандола. Это старый дворфийский город, давно лежащий в руинах: среди обломков, которые теперь присвоили дворфы Черного Железа, все еще стоят его кузница и таверна с пивоварней.",
			full = "Дун Модр стоит к югу от Моста Тандола. Это старый дворфийский город, давно лежащий в руинах: среди обломков, которые теперь присвоили дворфы Черного Железа, все еще стоят его кузница и таверна с пивоварней.\n\nВо время Второй войны орочья Орда захватила руины и построила там аванпост, откуда отбрасывала войска Альянса и совершала набеги на окрестные фермерские угодья; для ее армий это было жизненно важное место сбора. Воины Стромгарда выступили из островной цитадели Тол Барад, чтобы уничтожить этот аванпост: они осадили его и отбросили орков на юг, к их запасной крепости в Дун Альгазе. Орда нанесла ответный удар, отбила Дун Модр и обратила свою мощь даже против самого Тол Барада. Лишь когда Орда была разбита у Столицы, Андуин Лотар отбросил ее через Мост Тандола в Каз Модан, и Дун Модр перешел к Альянсу.\n\nНо мир длился недолго. Когда солдаты Стальгорна истощили силы в войнах вдали от дома, дворфы Черного Железа прорвались через Мост Тандола, и вскоре Дун Модр пал под натиском чернокнижника Балгараса Нечистого, который теперь владеет городом, объявленным его народом своим.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "Зеленый Пояс",
			short = "Зеленый Пояс кишит кроколисками, болотными тварями и слизнями, и здесь несет дозор Ретиэль Зеленый Страж, разгневанный тем, что земля стала странной и неспокойной.",
			full = "Зеленый Пояс кишит кроколисками, болотными тварями и слизнями, и здесь несет дозор Ретиэль Зеленый Страж, разгневанный тем, что земля стала странной и неспокойной.\n\nНа западе болотные чудища сделались злобными. На северо-востоке из Зловещего холма нежданно поднимаются огненные элементали. И то и другое — раны на теле земли, которую охраняет Ретиэль, и ни одна из них не затянулась.\n\nВ пределах Пояса лежит разбитый караван клана Драконьей Пасти, среди обломков которого теперь устроили логово красные дракончики. Это все, что осталось от попытки похитить детенышей черных драконов: она закончилась здесь, поглощенная болотом.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Грим Батол",
			short = "Грим Батол — горная крепость на востоке Болотины. Ее могучие стены и шпили тянутся к стально-серому небу, но большая часть твердыни скрыта под землей.",
			full = "Грим Батол — горная крепость на востоке Болотины. Ее могучие стены и шпили тянутся к стально-серому небу, но большая часть твердыни скрыта под землей. Ее основали дворфы из клана Громового Молота, но во время Войны Трех Кланов на нее пало проклятие. Позже ее захватили орки и сделали темницей для драконьей Аспектессы Алекстразы, пока ту не освободили в Битве за Грим Батол.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Гробница Железноборода",
			short = "Гробница Железноборода лежит к западу от дороги на Дун Модр, в северной части центральной Болотины. Над кладбищем здесь стоит статуя дворфа, изваянная, по всей видимости, по образу самого Железноборода.",
			full = "Гробница Железноборода лежит к западу от дороги на Дун Модр, в северной части центральной Болотины. Над кладбищем здесь стоит статуя дворфа, изваянная, по всей видимости, по образу самого Железноборода.\n\nМертвые больше не покоятся здесь с миром. Слизни черных, багровых и чудовищных оттенков проползли в склеп и осквернили его, расползлись по кладбищу, и теперь никто, кто хотел бы похоронить своих близких, и близко не подходит к этому месту.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "Погибший Флот",
			short = "Остовы «Владычицы» и «Отважного» лежат на дне Бухты Барадин у побережья северной части Болот Синежабрых.",
			full = "Остовы «Владычицы» и «Отважного» лежат на дне Бухты Барадин у побережья северной части Болот Синежабрых.\n\nОни входили в Третью флотилию Кул Тираса, которой во время Второй войны командовал Дерек Праудмур, старший сын лорда-адмирала Даэлина Праудмура. В битве при Крестфолле красные драконы, порабощенные кланом Драконьей Пасти, обрушились с неба и подожгли флотилию. Дерек взобрался в воронье гнездо, чтобы предупредить отца об опасности. Там его и убил дракон, прежде чем предупреждение успело что-либо изменить, а вскоре его корабль пошел ко дну вместе с остальной флотилией. Выжил лишь один человек — первый помощник Фитсиммонс с «Владычицы».\n\nМертвые не обрели покоя. Глубоко в трюме «Отважного» его командир, капитан Халиндор, из жадности спрятал почерневшую сферу — Проклятое Око Палета. Спустя годы проклятие добралось до утонувшей команды и обрекло ее на нежизнь. Лишь первый помощник Снеллиг сохранил при этом рассудок, и его призрак до сих пор бродит по ближнему берегу.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Бухта Менетил",
			short = "Бухта Менетил лежит между гаванью и утесами Дун Морога, укрывшись в заливе Бухты Барадин.",
			full = "Бухта Менетил лежит между гаванью и утесами Дун Морога, укрывшись в заливе Бухты Барадин.\n\nБлиз входа в бухту покоятся обломки «Орлика», и его разбитый корпус осел в воду.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Гавань Менетилов",
			short = "Первое, что бросается в глаза, — это стена: толстая каменная кладка, возведенная вокруг портового городка, который стоит наполовину на скале, наполовину на море.",
			full = "Первое, что бросается в глаза, — это стена: толстая каменная кладка, возведенная вокруг портового городка, который стоит наполовину на скале, наполовину на море. Над ней поднимаются четыре башни, следящие и за водой, и за дорогой, а попасть внутрь можно лишь по мосту, с приливом или по потайному подземному ходу, ведущему на большую землю.\n\nПервую верфь здесь построили орки. После Первой войны вождь Оргрим Молот Рока выбрал этот берег, чтобы построить флот, который должен был пронести Орду мимо сухопутных укреплений Лордерона, и ради этого орки выгребали железо и лес из дворфийских рудников Каз Модана. Когда Вторая война закончилась, Альянс занял это место и отстроил его заново, а великий адмирал Даэлин Праудмур назвал его Гаванью Менетилов в честь Теренаса Менетила II, короля Лордерона.\n\nДолгие годы после этого из холмов выходили ящеры и нападали на городок — никогда большими силами, но достаточно часто.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Крепость Менетил",
			short = "Над Гаванью Менетилов поднимаются четыре башни, взирающие на городок внизу, словно суровые стражи. Это Крепость Менетил.",
			full = "Над Гаванью Менетилов поднимаются четыре башни, взирающие на городок внизу, словно суровые стражи. Это Крепость Менетил.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
