		["mosshide fen"] = {
			name = "Болото Мохошкуров",
			short = "Болото Мохошкуров — залитый водой край на востоке Болотины, земля которого изрыта лагерями гноллов-мохошкуров. Племя владеет топью, хватая и пожирая всякого, кто забредет слишком далеко в болото.",
			full = "Болото Мохошкуров — залитый водой край на востоке Болотины, земля которого изрыта лагерями гноллов-мохошкуров. Племя владеет топью, хватая и пожирая всякого, кто забредет слишком далеко в болото.",
