		["raptor ridge"] = {
			name = "Гряда Ящеров",
			short = "Гряда Ящеров поднимается на востоке Болотины, к северо-западу от Врат Драконьей Пасти, и ее склоны и пещера кишат ящерами. В глубине Острозуб-матриарх высиживает свою кладку.",
			full = "Гряда Ящеров поднимается на востоке Болотины, к северо-западу от Врат Драконьей Пасти, и ее склоны и пещера кишат ящерами. В глубине Острозуб-матриарх высиживает свою кладку.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
