		["saltspray glen"] = {
			name = "Долина Солевого Тумана",
			short = "Долина Солевого Тумана лежит там, где Болотина встречается с Бухтой Барадин, между Болотами Синежабрых и Гробницей Железноборода.",
			full = "Долина Солевого Тумана лежит там, где Болотина встречается с Бухтой Барадин, между Болотами Синежабрых и Гробницей Железноборода. Свое имя она получила от ветра: когда он сильно дует с бухты, океан забрасывает брызги далеко вглубь суши — дальше, чем где-либо еще на этом побережье, — пока сама земля не покрывается соленым налетом. По всей долине гнездится множество ящеров, как и на соседних болотах и гряде.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Закатное болото",
			short = "В глубине северо-запада Болотины лежит Закатное болото, кишащее кроколисками, гноллами, ящерами, болотными тварями и слизнями, которые отпугивают большинство путников.",
			full = "В глубине северо-запада Болотины лежит Закатное болото, кишащее кроколисками, гноллами, ящерами, болотными тварями и слизнями, которые отпугивают большинство путников. В самом его сердце стоит Станция Быстрошеста — небольшой каменный дом с ветряной мельницей, где поселились Фрадд Быстрошест и Венна Шелкобородая. Эта пара торгует тем, что дает болото: диковинными вещицами, вытащенными из грязи, и рецептами, которые редко где встретишь.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Мост Тандола",
			short = "Две огромные каменные арки перекинуты через пропасть между Болотиной и Нагорьем Арати. Их возвели руки дворфов, и три поколения рода Старой Наковальни охраняли их.",
			full = "Две огромные каменные арки перекинуты через пропасть между Болотиной и Нагорьем Арати. Их возвели руки дворфов, и три поколения рода Старой Наковальни охраняли их. Их построили после Войны Трех Кланов, когда Стальгорн стремился сохранить верность сородичам из клана Громового Молота в Заоблачном Пике, и мосты стали и дорогой, и символом, связывающим два дворфийских королевства, а по ним шла торговля, обогащавшая обоих.\n\nТеперь мосты покрыты шрамами. Кам Темная Ярость и Балгарас Нечистый повели дворфов Черного Железа на Мост Тандола: они полностью обрушили одну из двух арок и едва не захватили вторую. Дворфы яростно сражались, защищая то, что осталось, и пытаясь отбить соседний город Дун Модр, и многие пали в тех боях, среди них Салли Баллу, Эбенезер Ржавый Засов и брат Длиннокоса Мрачного. Дворфы Черного Железа до сих пор удерживают руины, и Балгарас Нечистый все еще жив среди них.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Пещера Тельгена",
			short = "Пещера Тельгена поднимается на юге Болотины. Ее пещеры уходят глубоко в гору и кишат ядовитыми пауками, оплетающими шелком каждую расщелину.",
			full = "Пещера Тельгена поднимается на юге Болотины. Ее пещеры уходят глубоко в гору и кишат ядовитыми пауками, оплетающими шелком каждую расщелину. Где-то в глубоких туннелях залегают жилы огневита, и охраняют их полчища пауков.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
