		["whelgars excavation site"] = {
			name = "Раскопки Вельгара",
			short = "Раскоп к востоку от Гавани Менетилов когда-то был местом тихой работы дворфов, вгрызавшихся в землю древнее самой памяти. Потом его заполонили крапчатые ящеры, прижав копателей к гряде над их собственным раскопом.",
			full = "Раскоп к востоку от Гавани Менетилов когда-то был местом тихой работы дворфов, вгрызавшихся в землю древнее самой памяти. Потом его заполонили крапчатые ящеры, прижав копателей к гряде над их собственным раскопом. Удержаться дворфы не смогли и бросили раскоп ради лагеря, который сами разбили в стороне от главной дороги, — Приюта Вельгара.\n\nТо, что они оставили, до сих пор лежит наполовину раскопанным. Теперь по ямам бродят живые окаменелости и древние элементали, и им нет дела до кирок, что ржавеют там.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
