	-- Тельдрассил: 17 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Альдрассил",
			short = "Альдрассил высится в самом сердце Тенистой долины — дерево, выросшее настолько огромным, что в его ветвях поместилась целая деревня.",
			full = "Альдрассил высится в самом сердце Тенистой долины — дерево, выросшее настолько огромным, что в его ветвях поместилась целая деревня. На самой его вершине, выше поселения внизу, обосновался Тенарон Хватка Бури, который присматривает за долиной с кроны великого дерева.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
