		["banethil barrow den"] = {
			name = "Обитель Бен'этиль",
			short = "Обитель Бен'этиль была возведена ночными эльфами как священный курган, где их спящие друиды-вороны могли бы покоиться в мире.",
			full = "Обитель Бен'этиль была возведена ночными эльфами как священный курган, где их спящие друиды-вороны могли бы покоиться в мире.\n\nТеперь этот покой нарушен. Оскверненные фурболги из племени Кривой Сосны заполонили ее Нижнюю и Верхнюю обитель, и то, что некогда было освященной землей, больше не место для одинокого ночного эльфа.",
