		["lake alameth"] = {
			name = "Озеро Аль'Амет",
			short = "Озеро Аль'Амет широко раскинулось к югу от Доланаара, одно из великих озёр Тельдрассила. На его берегах почти ничего нет, кроме маленькой пристани.",
			full = "Озеро Аль'Амет широко раскинулось к югу от Доланаара, одно из великих озёр Тельдрассила. На его берегах почти ничего нет, кроме маленькой пристани.\n\nВ последнее время его покой нарушен: по берегу бродят разъярённые древесники, и гулять у озера в одиночку больше небезопасно.",
