		["oracle glade"] = {
			name = "Поляна Оракула",
			short = "Поляна Оракула лежит на северо-западе Тельдрассила и хранит первый и самый могущественный из лунных колодцев великого древа.",
			full = "Поляна Оракула лежит на северо-западе Тельдрассила и хранит первый и самый могущественный из лунных колодцев великого древа. Здесь стоит Древо-оракул, чей широкий ствол поднимается к ветвям, очертаниями похожим на орла, сидящего на медведе. Многие шепчут, что обычное дерево не могло бы принять такую форму и что его вылепила одна лишь магия природы.\n\nВместе с друидами это древо присматривало за тем, как рос Тельдрассил.\n\nПоблизости свили гнёзда гарпии Кровавого Пера, угрожающие древу, и небольшой отряд Часовых был послан, чтобы сдерживать их.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Пруды Арлитриэна",
			short = "К югу от Дарнасса, на западе Тельдрассила, лежат Пруды Арлитриэна, некогда мирные. Ночные эльфы покинули здешний лунный колодец, когда эти края захватили фурболги Кривой Сосны.",
			full = "К югу от Дарнасса, на западе Тельдрассила, лежат Пруды Арлитриэна, некогда мирные. Ночные эльфы покинули здешний лунный колодец, когда эти края захватили фурболги Кривой Сосны. Колодец по-прежнему стоит среди прудов, заброшенный, и теперь вокруг него обитают враждебные звери.",
