		["ruttheran village"] = {
			name = "Деревня Рут'теран",
			short = "Деревня Рут'теран лежит у корней Тельдрассила, там, где Древо Жизни встречается с водой, далеко под Дарнассом.",
			full = "Деревня Рут'теран лежит у корней Тельдрассила, там, где Древо Жизни встречается с водой, далеко под Дарнассом. Её постройки скромны рядом со зданиями столицы, но содержатся в безупречной свежести, словно здесь гордятся простотой, а не размерами.\n\nЗдесь калдорай ухаживают за гнездовьем гиппогрифов: собирают яйца, заботятся о них и растят птенцов, пока те не встанут на крыло. Это тихий труд, и выполняют его те же жители, что в остальное время трудятся ради того, чтобы деревня служила опорой городу наверху, почти не прося за это признания.\n\nВпрочем, жизнь деревни состоит не из одного труда. Когда приходит Огненный солнцеворот, здесь зажигают жаровни, и те же руки, что ухаживали за яйцами гиппогрифов и грузили лодки, обращаются к празднику.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Тенистая долина",
			short = "Под ветвями Тельдрассила, в северо-восточной части острова, укрылась поляна, которая никогда не видит полного дневного света. В Тенистой долине царят вечные сумерки, и со всех сторон, кроме одной, её окружают горы.",
			full = "Под ветвями Тельдрассила, в северо-восточной части острова, укрылась поляна, которая никогда не видит полного дневного света. В Тенистой долине царят вечные сумерки, и со всех сторон, кроме одной, её окружают горы. Лишь на юге камень расступается, пропуская тропу к Доланаару.\n\nВ сердце долины стоит Альдрассил, огромное древо, которое целиком господствует над поляной, будто вся долина устроена вокруг него. На северо-западе земля раскрывается входом в Паучье логово, тёмную расщелину в холмах, опоясывающих долину.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Паучье логово",
			short = "Паучье логово лежит в северо-западном углу Тенистой долины, среди корней Тельдрассила. Оно всегда принадлежало огромным паукам острова, но в последнее время они стали беспокойны, а пещера сделалась опаснее.",
			full = "Паучье логово лежит в северо-западном углу Тенистой долины, среди корней Тельдрассила. Оно всегда принадлежало огромным паукам острова, но в последнее время они стали беспокойны, а пещера сделалась опаснее.\n\nВ самой глубине обитает Гитьис Зловещая, самая крупная из выводка, погубившая не одного юного калдорай, забредшего слишком далеко.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Деревня Звездного Ветра",
			short = "Деревня Звёздного Ветра некогда принадлежала ночным эльфам: несколько небольших домов к юго-востоку от Тенистой долины. Теперь эльфов здесь нет, а их дома заняли осквернённые фурболги Кривой Сосны.",
			full = "Деревня Звёздного Ветра некогда принадлежала ночным эльфам: несколько небольших домов к юго-востоку от Тенистой долины. Теперь эльфов здесь нет, а их дома заняли осквернённые фурболги Кривой Сосны. По её тропам расхаживает Урусон, а на окраинах таится Фероситас Пожиратель Снов, зверь, одно присутствие которого показывает, как низко пала деревня по сравнению с тем, чем она была прежде.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Родниковое озеро",
			short = "Родниковое озеро питается водой из источника, бьющего глубоко в недрах самого Тельдрассила, а излишки её стекают Родниковой рекой. Когда-то эти тихие воды любили рыбаки из ночных эльфов.",
			full = "Родниковое озеро питается водой из источника, бьющего глубоко в недрах самого Тельдрассила, а излишки её стекают Родниковой рекой. Когда-то эти тихие воды любили рыбаки из ночных эльфов. Теперь живущие здесь древесники поражены порчей, а в окрестные земли проникли ночные саблезубы и пауки, и некогда мирное место для рыбалки стало опасным.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Родниковая река",
			short = "Родниковая река берёт начало в источнике глубоко внутри Тельдрассила и течёт от Родникового озера на север, к краю древа, где огромным водопадом обрушивается в море далеко внизу.",
			full = "Родниковая река берёт начало в источнике глубоко внутри Тельдрассила и течёт от Родникового озера на север, к краю древа, где огромным водопадом обрушивается в море далеко внизу.\n\nТеперь по её берегам рыщут обезумевшие древесники, нападающие на всякого, кто подойдёт близко.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Темные берега: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Амет'Аран",
			short = "Руины Амет'Арана лежат к юго-востоку от Аубердина на Тёмных берегах, и кое-что от этого города по-прежнему бродит там.",
			full = "Руины Амет'Арана лежат к юго-востоку от Аубердина на Тёмных берегах, и кое-что от этого города по-прежнему бродит там.\n\nНекогда королева Азшара возвела Амет'Аран как близнеца Башал'Арана и поселила своих любимых высокорождённых среди его базаров и храмов Элуны. Правителем над ним она поставила Атрикуса Нарассина, могущественного мага, который жил в своей Башне Алталакса.\n\nКогда пришёл Раскол и город уже рушился, его жители жались к земле, словно одно это могло их спасти. Атрикус Нарассин явился среди них и пообещал заклинание, которое убережёт их от грядущего разрушения, даровав им вечную жизнь в камнях душ, что он носил с собой. Пока он произносил его, эльфы вокруг него умирали. Вечность, которую он им дал, оказалась темницей, а не спасением, и с тех пор в Амет'Аране задерживаются их духи, а не их жизни.\n\nСреди руин всё ещё стоят две огромные каменные скрижали, на которых высечена история падения города. Часовая, пришедшая прочесть их, не успела закончить: на неё напали неупокоенные высокорождённые, и она бежала.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Аубердин",
			short = "Аубердин стоит там, где Раскол разломил землю, на берегу, поглотившем великие города древней империи калдорай. Все поселения, что пытались основать на Тёмных берегах с тех пор, погибли, кроме этого единственного городка на берегу Сокрытого Моря.",
			full = "Аубердин стоит там, где Раскол разломил землю, на берегу, поглотившем великие города древней империи калдорай. Все поселения, что пытались основать на Тёмных берегах с тех пор, погибли, кроме этого единственного городка на берегу Сокрытого Моря.\n\nОн вырос непохожим на остальное общество ночных эльфов. Его порт привлекает корабли и торговцев из Восточных королевств, а по улицам ходят дворфы, гномы, люди и даже высшие эльфы, так что Аубердин освещён ярче, чем подобает городу ночных эльфов, а указатели на нём написаны на двух языках ради чужеземцев. За это Дарнасс смотрит на него свысока. Бролл Медвежья Шкура, однажды побывавший здесь, считает местных жителей немногим лучше изгоев и отщепенцев, а Часовые из здешнего гарнизона держатся в стороне от тех, кого охраняют. И всё же Шандриса Оперённая Луна, когда-то служившая здесь, вспоминает Аубердин как место, где звенел смех.\n\nВозле маяка на скалах до сих пор виден остов корабля, которым некогда командовала эльфийка Элура. Груз элунитовой руды пропал, когда судно пошло ко дну.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Башал'Аран",
			short = "Прежде чем море поднялось над миром и раскололо его, королева Азшара возвела на севере Тёмных берегов два города-близнеца для своих любимых высокорождённых: Амет'Аран и Башал'Аран.",
			full = "Прежде чем море поднялось над миром и раскололо его, королева Азшара возвела на севере Тёмных берегов два города-близнеца для своих любимых высокорождённых: Амет'Аран и Башал'Аран. Править ими она поставила Атрикуса Нарассина, эльфа великой магической силы, а под его началом служил Астерион, маг, столь же искусный в тайных науках, сколь и во владении оружием. Он жил среди жителей Башал'Арана и часто ездил в Амет'Аран, чтобы заботиться о его народе. В те дни в городах-близнецах были базары и храмы Элуны, осенённые милостью самой королевы.\n\nКогда первый Источник Вечности был уничтожен, оба города обратились в руины. Но в какой-то момент Атрикус Нарассин обратил своё искусство против собственного помощника: он заключил Астериона в печать из лунного камня и заточил его среди камней Башал'Арана. Почему господин ополчился на своего слугу, не может сказать никто из ныне живущих. Астерион долгие годы терпел свою темницу в муках, а когда наконец умер, то понял, что смерть не принесла ему свободы. Его дух остался скован так же крепко, как прежде его плоть.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Берлога в Чернолесье",
			short = "На дальнем юге Тёмных берегов, у границы Ясеневого леса, несколько лагерей фурболгов и небольшая пещера образуют место под названием Берлога в Чернолесье, которое иногда называют Твердыней Чернолесья.",
			full = "На дальнем юге Тёмных берегов, у границы Ясеневого леса, несколько лагерей фурболгов и небольшая пещера образуют место под названием Берлога в Чернолесье, которое иногда называют Твердыней Чернолесья. Фурболги, которые владеют ею, осквернены и искажены до неузнаваемости.\n\nВ пещере сидит одинокий ночной эльф по имени Волкор, пленник фурболгов.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Водопад Скалистый",
			short = "Водопад Скалистый дает начало реке Скалистой. Некогда его вода была самой чистой в ней и поила все Тёмные берега. Теперь эта вода уже не чиста.",
			full = "Водопад Скалистый дает начало реке Скалистой. Некогда его вода была самой чистой в ней и поила все Тёмные берега. Теперь эта вода уже не чиста. Пещера, из которой низвергается водопад, стала мерзкой, и порча расходится по течению в края, которые эта вода когда-то питала.\n\nНикто не может сказать наверняка, в чём причина. Одни винят Оскверненный лес и говорят, что скверна попросту просачивается из этого погубленного леса. Другие указывают на то, что нашли в глубине самой пещеры, где у истока теперь ползают во тьме наги.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Река Скалистая",
			short = "Река Скалистая течёт от водопада Скалистого к морю на севере Тёмных берегов. Её воды отравлены нагами Штормовой Чешуи, и звери, что пьют из неё, часто заболевают.",
			full = "Река Скалистая течёт от водопада Скалистого к морю на севере Тёмных берегов. Её воды отравлены нагами Штормовой Чешуи, и звери, что пьют из неё, часто заболевают.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Роща Древних",
			short = "Роща Древних — это старый храм ночных эльфов, чьи камни раскинулись вокруг бурной Петляющей реки в горах Тёмных берегов.",
			full = "Роща Древних — это старый храм ночных эльфов, чьи камни раскинулись вокруг бурной Петляющей реки в горах Тёмных берегов. Здесь обитает Ону, Древо Мудрости, вместе со спящим друидом и парой торговцев, и здесь по-прежнему собирается Круг Древних.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Длинный пролив",
			short = "Длинный пролив тянется на юг от Аубердина до вод к западу от Амет'Арана. Несмотря на своё название, это самый короткий участок побережья на Тёмных берегах.",
			full = "Длинный пролив тянется на юг от Аубердина до вод к западу от Амет'Арана. Несмотря на своё название, это самый короткий участок побережья на Тёмных берегах. Серый песок лежит под сплошь затянутым тучами небом. Прилив оставляет после себя лишь плавник да туши мёртвых морских созданий. Вдоль берега встречаются мурлоки.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "Меч Властителя",
			short = "На юго-западе Тёмных берегов лежит исполинский череп, наполовину поглощённый землёй, и в кости его до сих пор торчит адамантитовая глефа.",
			full = "На юго-западе Тёмных берегов лежит исполинский череп, наполовину поглощённый землёй, и в кости его до сих пор торчит адамантитовая глефа. Это был Соггот Ползучий, вестник Древних Богов, а клинок зовётся Мечом Властителя.\n\nСкрижали, найденные на Раскопках рассеянного геолога, поведали о том, что здесь произошло. Титаны послали против Соггота двадцать каменных великанов, и битва была столь ужасна, что лишь один из них дожил до её конца: Кронн, самый большой из двадцати. Когда щупальца Соггота сомкнулись вокруг него, Кронн не стал вырываться. Он позволил затащить себя внутрь, всё ближе и ближе к черепу чудовища, пока не оказался достаточно близко, чтобы нанести удар. Удар, сразивший Соггота, был нанесён из его собственных объятий, и меч, оставшийся в его черепе, получил имя этой победы.\n\nС тех пор это место захватил Сумеречный Молот. Культисты раскапывают останки Соггота, стремясь уничтожить то, чего добился меч Кронна, и призвать вестника Древнего Бога обратно в мир.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Туманный Предел",
			short = "Побережье, называемое Туманным Пределом, тянется вдоль всех Тёмных берегов, и это самая длинная береговая линия в этом краю.",
			full = "Побережье, называемое Туманным Пределом, тянется вдоль всех Тёмных берегов, и это самая длинная береговая линия в этом краю.\n\nЭто мрачные места: серые пляжи и угрюмые бухты, усеянные огромными тушами мёртвых морских животных и обломками затонувших кораблей.\n\nПо всему побережью снуют крабы, а в мелких бухтах таятся мурлоки, постоянная угроза для всякого, кто идёт по берегу.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Раскопки рассеянного геолога",
			short = "Геолог Сомнамбулер дал своё имя этим раскопкам на Тёмных берегах.",
			full = "Геолог Сомнамбулер дал своё имя этим раскопкам на Тёмных берегах. Копая, он нашёл окаменелость, не похожую ни на одну другую и гудящую мистической силой, но рассеянный геолог с тех пор забыл, куда её положил.\n\nСами раскопки стали опасны: их туннели захватили трогги Гравийного Кремня, а внутри шевелятся огромные големы, вырытые из земли в ходе работ.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Руины Матистры",
			short = "За Башней Алталакса, на севере Тёмных берегов, лежат руины Матистры. До Великого Раскола здесь стоял город ночных эльфов, возведённый в эпоху высокорождённых.",
			full = "За Башней Алталакса, на севере Тёмных берегов, лежат руины Матистры. До Великого Раскола здесь стоял город ночных эльфов, возведённый в эпоху высокорождённых. Когда Источник Вечности разорвал сам себя и мир раскололся под ним, Матистра была разрушена, как и многое другое, и уцелевшие ночные эльфы не вернулись, чтобы отстроить её. Вместо этого они ушли в небольшие деревни дальше к югу вдоль побережья, оставив руины позади.\n\nСреди упавших камней до сих пор разбросаны реликвии древних высокорождённых, и юные ночные эльфы порой приходят искать их в Матистре, остерегаясь призрачных саблезубов, что рыщут среди руин того, что некогда построил их народ.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Башня Алталакса",
			short = "В эпоху Великого Раскола, когда королева Азшара возвысила высокорождённых над всеми прочими, она поставила эльфа по имени Атрикус Нарассин править городами-близнецами Амет'Араном и Башал'Араном.",
			full = "В эпоху Великого Раскола, когда королева Азшара возвысила высокорождённых над всеми прочими, она поставила эльфа по имени Атрикус Нарассин править городами-близнецами Амет'Араном и Башал'Араном. Поначалу Атрикус служил ей достаточно исправно, но эта работа ему наскучила, и он стал проводить дни вдали от городов, в собственной башне под названием Алталакс.\n\nДесять тысяч лет спустя то, о чём давно шептались насчёт этой башни, оказалось правдой. Там собрался культ, называвший себя кланом Тёмной Нити, среди них были чернокнижники и сатир, а во главе стоял сам Атрикус Нарассин. Цель их оставалась неясной, пока не выяснилось, что культ подчиняется Совету Теней и что Алталакс стал ещё одной нитью в паутине этого древнего заговора.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Сумеречная долина",
			short = "Леса к югу от Амет'Арана, простирающиеся до границы Ясеневого леса, зовутся Сумеречной долиной.",
			full = "Леса к югу от Амет'Арана, простирающиеся до границы Ясеневого леса, зовутся Сумеречной долиной. В этих лесах бродят осквернённые фурболги, одичавшие ночные саблезубы и бешеные медведи, и путникам советуют держаться дорог, а не блуждать под деревьями.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Петляющая река",
			short = "Петляющая река несёт свою хворь с гор. Она продолжает реку Отравленной Крови, что вытекает из Оскверненного леса на юг Тёмных берегов неподалёку от Рощи Древних.",
			full = "Петляющая река несёт свою хворь с гор. Она продолжает реку Отравленной Крови, что вытекает из Оскверненного леса на юг Тёмных берегов неподалёку от Рощи Древних. Её воды отравлены, и порча Оскверненного леса следует за течением в эти низинные земли.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Ясеневый лес: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Астранаар",
			short = "Астранаар поднимается на острове в самом сердце Ясеневого леса. Это крупнейшее поселение ночных эльфов в этом краю, и попасть в него можно лишь по двум мостам, по которым дорога пересекает воду.",
			full = "Астранаар поднимается на острове в самом сердце Ясеневого леса. Это крупнейшее поселение ночных эльфов в этом краю, и попасть в него можно лишь по двум мостам, по которым дорога пересекает воду. Озеро отделяет его от окружающего леса, делая тихим, удобным для обороны местом посреди спорной земли.\n\nНа берегу лежит кладбище, где среди тихих рядов надгробий покоятся умершие жители города.\n\nЗа пределами города на севере набрались сил фурболги Колючего Меха, и в Астранааре боятся, что однажды у них хватит смелости обратить эту силу против самого города.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Убежище Батрана",
			short = "Колонны Убежища Батрана некогда были частью руин калдорай, возведённых в ту эпоху, когда ночные эльфы ещё жили в этой части Ясеневого леса.",
			full = "Колонны Убежища Батрана некогда были частью руин калдорай, возведённых в ту эпоху, когда ночные эльфы ещё жили в этой части Ясеневого леса. Та эпоха прошла, эльфы ушли, и мрамор остался трескаться и рушиться.\n\nТеперь здесь не пусто. Среди поваленных колонн обосновались агенты Отрекшихся, травники и охраняющие их головорезы, и где бы они ни поселились, земля отвечает им тем же: трава побурела, цветы завяли. Среди упавших камней они устроили временную лабораторию, где обрабатывают местные травы ради собственных целей.\n\nПрежде всего их влечёт сюда растение, которое больше нигде поблизости не встречается: Батранов волос, целебная трава, достаточно редкая, чтобы ради неё одной удерживать это место.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Непроглядная Пучина",
			short = "Под Зорамским взморьем, где древний город Зорам погрузился в море, лежат затопленные залы Латар'Лазала, некогда храма Элуны.",
			full = "Под Зорамским взморьем, где древний город Зорам погрузился в море, лежат затопленные залы Латар'Лазала, некогда храма Элуны. Считалось, что Раскол уничтожил его без следа, и тысячелетиями его хранил океан.\n\nЗатем пришёл Сумеречный Молот, привлечённый шёпотом и дурными снами в подводные пещеры, в которые превратился храм. Культ принёс в этих глубинах в жертву бессчётное множество невинных и получил в награду поручение: взращивать и оберегать драгоценное создание Древних Богов, чудовищную гидру Аку'май Пожирательницу, до того дня, когда её выпустят в мир. Теперь это место зовётся Непроглядной Пучиной, и название ему подходит.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Лагерь Кровавого Клыка",
			short = "Лагерь Кровавого Клыка лежит к западу от реки Фалфаррен, к юго-западу от южного лунного колодца Ясеневого леса. Он назван в честь Рана Кровавого Клыка, вождя племени фурболгов, которое им владеет.",
			full = "Лагерь Кровавого Клыка лежит к западу от реки Фалфаррен, к юго-западу от южного лунного колодца Ясеневого леса. Он назван в честь Рана Кровавого Клыка, вождя племени фурболгов, которое им владеет.\n\nКогда-то эти фурболги были такими же, как и прочие их сородичи, но порча поразила их всех до единого, и теперь лагерь встречает враждой любого чужака, который подойдёт близко.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Тенистая Крона",
			short = "За Лесной Песнью, где деревья Ясеневого леса растут густо и стоят веками, Тенистая Крона хранит один из порталов в Изумрудный Сон.",
			full = "За Лесной Песнью, где деревья Ясеневого леса растут густо и стоят веками, Тенистая Крона хранит один из порталов в Изумрудный Сон.\n\nЕго охраняет зелёная стая драконов. Драконы Фантим и Преследователь Снов стерегут проход, а по окрестным лесам тройками ходят драконорождённые: изумрудный оракул в сопровождении стражей ветвей и древесных стражей, снова и снова проходящих одной и той же дорогой в своём долгом дозоре.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Каньон Гибели Демона",
			short = "Каньон Гибели Демона хранит шрам того мгновения, когда орки сбросили с себя древнее рабство.",
			full = "Каньон Гибели Демона хранит шрам того мгновения, когда орки сбросили с себя древнее рабство.\n\nЗдесь владыка преисподней Маннорот сошёлся в схватке с Громмашем Адским Криком и Траллом. Демон сразил Тралла, но не успел увернуться от топора Грома, вонзившегося ему в грудь. Смерть Маннорота вырвалась наружу огнём и светом, и тот же огонь, поглотив демона, отнял жизнь у Грома. Орки назвали место его жертвы в его честь, ибо именно здесь было разрушено проклятие, наложенное Пылающим Легионом на их народ.\n\nМногие орки и сейчас приходят сюда, чтобы почтить воина, заплатившего за эту свободу, и в память о нём здесь стоит памятник. Но земля по-прежнему отмечена Скверной, и теперь в каньоне обитают низшие демоны.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Гряда Гибели Демона",
			short = "Над Каньоном Гибели Демона вздымается изломанная гряда, склоны которой и прорытая в них обитель заполонили низшие демоны.",
			full = "Над Каньоном Гибели Демона вздымается изломанная гряда, склоны которой и прорытая в них обитель заполонили низшие демоны. Глубже, куда не достаёт дневной свет, ждёт Диаторус Искатель, повелитель ужаса, правящий сборищем демонов в Ясеневом лесу. Он держит свой двор во тьме, а низшие исчадия стерегут гряду наверху.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Обитель Дор'Данил",
			short = "Обитель Дор'Данил издавна служила местом упокоения друидов из ночных эльфов, чьи тела спят здесь, пока их духи свободно странствуют.",
			full = "Обитель Дор'Данил издавна служила местом упокоения друидов из ночных эльфов, чьи тела спят здесь, пока их духи свободно странствуют. Именно Отрекшиеся обратили внимание на спящих и разлучили друидов с их странствующими духами. Этот опыт не убил их. Он свёл их с ума.\n\nТеперь в обители нет мирно спящих. Невидимые убийцы Отрекшихся бродят по ней, а разъярённые души отсечённых друидов мечутся по кургану, и им некуда больше вернуться. Среди них обитают три духа, более сильные, чем остальные: Этиль Зов Луны, Маворис Проблеск Солнца и Таниэль Темный Лес.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Река Фалфаррен",
			short = "Фалфаррен рассекает Ясеневый лес почти надвое. К западу от неё живут ночные эльфы под защитой Астранаара, к востоку орки удерживают Заставу Расщепленного Дерева.",
			full = "Фалфаррен рассекает Ясеневый лес почти надвое. К западу от неё живут ночные эльфы под защитой Астранаара, к востоку орки удерживают Заставу Расщепленного Дерева. Река достаточно мелка, чтобы перейти её вброд, и достаточно узка, чтобы переправиться без особого труда, если только дожди не выводят её из берегов, но всё же она обозначает границу, которую оба народа понимают без слов.\n\nЕё воды берут начало на склонах горы Хиджал и каскадами спускаются в озеро у Ксавиана, затем текут между Заставой Расщепленного Дерева и Ночной поляной, под большим мостом, по которому пересекает Ясеневый лес большинство путников, мимо Аванпоста Среброкрылых и Лунного колодца Очищения, а потом уходят под землю под северными горами, в сторону Степей.\n\nВозле Холма Демонического Огня река таит ещё одну опасность. Там под её поверхностью скрываются болотные чудища, нападающие на всякого, кто слишком долго задерживается в воде.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Зеркало Небес",
			short = "К югу от Аванпоста Среброкрылых в Ясеневом лесу лежит небольшое озеро, воды которого окружают одинокий остров.",
			full = "К югу от Аванпоста Среброкрылых в Ясеневом лесу лежит небольшое озеро, воды которого окружают одинокий остров. На этом острове живёт Чащобный Оракул, старейшина чащобников, которые в меньшем числе обитают вдоль берега и следят за водой из окрестных камышей и зарослей.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Холм Демонического Огня",
			short = "Холм Демонического Огня до сих пор хранит шрамы Третьей войны, когда инферналы, пылая, падали с неба и врезались здесь в землю. С тех пор здесь задержались демоны, мерзкие твари, устроившие логова среди камней.",
			full = "Холм Демонического Огня до сих пор хранит шрамы Третьей войны, когда инферналы, пылая, падали с неба и врезались здесь в землю. С тех пор здесь задержались демоны, мерзкие твари, устроившие логова среди камней.\n\nОрда укрепила оба моста, ведущие на холм, и удерживает их, чтобы демоны не хлынули к соседним поселениям.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Святилище Огненной Расщелины",
			short = "Святилище Огненной Расщелины стоит на юго-западе Ясеневого леса. Демоническое влияние Совета Теней осквернило его, и оно стало местом великого зла.",
			full = "Святилище Огненной Расщелины стоит на юго-западе Ясеневого леса. Демоническое влияние Совета Теней осквернило его, и оно стало местом великого зла. Некогда здесь жил орочий чернокнижник Илкруд Магтрулл, служивший Атрикусу Нарассину, предводителю клана Тёмной Нити.\n\nТеперь святилище кишит демонами, которых влечёт скверна, оставшаяся в камне. Известно, что среди них время от времени появляется в этих краях страж ужаса по имени Аккрилус, редкий и опасный знак того, как глубоко зашла порча.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Лесная Песнь",
			short = "Лесная Песнь — это древние руины ночных эльфов в лесах Ясеневого леса, давно отданные мху и воспоминаниям. Какое-то время здесь почти никто не жил.",
			full = "Лесная Песнь — это древние руины ночных эльфов в лесах Ясеневого леса, давно отданные мху и воспоминаниям. Какое-то время здесь почти никто не жил.\n\nЗатем друид Кайнет Штиль сделал их своим домом и стал единственным обитателем руин, руководя из-под их камней борьбой с Отрекшимися в этом краю. Забытое место превратилось в сторожевой пост, который держится не числом, а упорным нежеланием одного друида покидать его.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Деревня Зеленой Лапы",
			short = "Деревня Зелёной Лапы — дом племени Гиблой Чащи, фурболгов, которыми предводительствуют вождь Мургут и шаман Дубовая Лапа. Здешние медвежьи люди осквернены.",
			full = "Деревня Зелёной Лапы — дом племени Гиблой Чащи, фурболгов, которыми предводительствуют вождь Мургут и шаман Дубовая Лапа. Здешние медвежьи люди осквернены.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Воющая долина",
			short = "В долину, где стоит святилище Мел'Тандрис, выходит пещера. На камне святилища высечена древняя надпись во славу Элуны, а над ней, на дарнасском языке: истина — путеводный свет.",
			full = "В долину, где стоит святилище Мел'Тандрис, выходит пещера. На камне святилища высечена древняя надпись во славу Элуны, а над ней, на дарнасском языке: истина — путеводный свет.\n\nСвятилище возвела мать Велинды Песни Звёзд в честь Мел'Тандрис, которой была доверена Коса Элуны. Когда Мел'Тандрис умерла, косу упокоили здесь, спрятав в святилище. Она оставалась забытой, пока Велинда не нашла в Дарнассе книгу, повествующую об этой истории, не пришла в долину и не отыскала косу сама.\n\nСо временем святилище обратилось в руины, и его захватило племя воргенов, называемых Терроволками, сделав пещеру своим логовом. Их вой, эхом отдающийся в камне, и дал долине имя, которое она носит сейчас.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Озеро Ирис",
			short = "Озеро Ирис лежит в северной части центрального Ясеневого леса, к востоку от Астранаара и к западу от лунного колодца Шаэлдрин.",
			full = "Озеро Ирис лежит в северной части центрального Ясеневого леса, к востоку от Астранаара и к западу от лунного колодца Шаэлдрин. Некогда часть нетронутого леса ночных эльфов, оно пало жертвой порчи, расползающейся из Оскверненного леса, и его вода приобрела болезненный жёлто-зелёный цвет. Теперь у его берегов бродят искажённые болотные чудища, нападающие на всякого, кто приходит за Слезами Элуны.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Крепость Каргатия",
			short = "Крепость Каргатия поднимается среди утыканных кольями заграждений на Лесозаготовках Песни Войны в восточной части Ясеневого леса, неподалёку от реки Строптивой.",
			full = "Крепость Каргатия поднимается среди утыканных кольями заграждений на Лесозаготовках Песни Войны в восточной части Ясеневого леса, неподалёку от реки Строптивой. Здесь располагаются командиры клана Песни Войны, и место для неё выбрано так, чтобы можно было вызвать подкрепление из Оргриммара, если Альянс крупными силами двинется на лагерь.\n\nКрепость названа в честь Каргата Острорука, героя орков, в честь которого названы также Каргат в Бесплодных землях и Бухта Острорука в Дуротаре. Надсмотрщик Гортак командует лагерем из её стен, руководя вырубкой леса в Ясеневом лесу.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Озеро Фалатим",
			short = "Озеро Фалатим лежит на западе Ясеневого леса, где лунный свет богини всегда касается воды, днём и ночью. Когда-то ночные эльфы свободно приходили сюда купаться и рыбачить, пока озеро не заполонили мурлоки, сделав его диким.",
			full = "Озеро Фалатим лежит на западе Ясеневого леса, где лунный свет богини всегда касается воды, днём и ночью. Когда-то ночные эльфы свободно приходили сюда купаться и рыбачить, пока озеро не заполонили мурлоки, сделав его диким. Учёного Терониса в последний раз видели у его берегов, и он так и не вернулся.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Застава Мейстры",
			short = "Здесь тихо стоят башня и единственный зал ночных эльфов, где несут службу несколько защитников и, что для Ясеневого леса страннее всего, двое людей среди эльфов: Фиро Железнорук и Делгрен Очиститель, единственные представители своего народа на этой заставе.",
			full = "Здесь тихо стоят башня и единственный зал ночных эльфов, где несут службу несколько защитников и, что для Ясеневого леса страннее всего, двое людей среди эльфов: Фиро Железнорук и Делгрен Очиститель, единственные представители своего народа на этой заставе.\n\nЗащитников немного, ибо порча, расползающаяся среди окрестных фурболгов, отвлекает тех, кто иначе мог бы нести здесь дозор, и силы заставы растянуты до предела.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "Озеро Мистраль",
			short = "Воды озера Мистраль некогда хранили духи, верные ночным эльфам и привязанные к озеру как его стражи.",
			full = "Воды озера Мистраль некогда хранили духи, верные ночным эльфам и привязанные к озеру как его стражи. Сарилус Грязнорождённый переманил их, осквернив элементалей так, что они стали подчиняться ему, а не эльфам, которым прежде служили. То, что ждёт в озере теперь, уже не то, чем было.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Ночная поляна",
			short = "Ночная поляна лежит на выступе, врезающемся в сушу. Её утёсы слишком отвесны, чтобы на них взобраться, поэтому путнику приходится идти вдоль Фалфаррена почти до вод Ксавиана, прежде чем свернуть на запад, или же отыскать узкий уступ к северу от Приюта в Ночных Лесах.",
			full = "Ночная поляна лежит на выступе, врезающемся в сушу. Её утёсы слишком отвесны, чтобы на них взобраться, поэтому путнику приходится идти вдоль Фалфаррена почти до вод Ксавиана, прежде чем свернуть на запад, или же отыскать узкий уступ к северу от Приюта в Ночных Лесах. Внутри почти ничего нет: лишь разбросанные обломки колонн и развалины каменной кладки. Это самая маленькая и бедная из трёх твердынь сатиров в Ясеневом лесу, и Ксавиан, и Сатирнаар намного превосходят её. Сатирам Скверномуска, что укрываются среди этих руин, стены почти не нужны, когда их охраняет сама земля. Среди обломков лежит один из камней душ клана Тёмной Нити, союзником которого являются сатиры Скверномуска.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Леса Ночной Песни",
			short = "Река Фалфаррен рассекает восточные леса надвое, и черта, которую она проводит, — это линия войны, которая никогда не кончается.",
			full = "Река Фалфаррен рассекает восточные леса надвое, и черта, которую она проводит, — это линия войны, которая никогда не кончается. К западу от её берегов Среброкрылые Часовые удерживают землю для Альянса, к востоку клан Песни Войны вбил свои колья в землю, и здесь бои между двумя народами самые жаркие и не прекращаются ни на миг.\n\nДальше к востоку другая, безымянная река обозначает ещё одну границу. На одном её берегу стоит Застава Расщепленного Дерева, сердце могущества Орды в этих лесах, на другом за Альянс отвечает Роща Среброкрылых. За этой рекой лежит земля, которая никому не принадлежит подолгу: по частям её оспаривают ночные эльфы Лесной Песни, сатиры Сатирнаара и Ксавиана, орки Песни Войны и сам Пылающий Легион. Ни одно знамя никогда не реяло там, не встречая вызова.\n\nК югу от линии боёв лес заплатил цену войны. Клан Песни Войны оголил эти края, вырубая старые деревья на древесину для своих поселений, и там, где некогда стоял нетронутый древний лес, осталась открытая, израненная земля.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Приют в Ночных Лесах",
			short = "Высоко в ветвях Великого Древа, давшего этому месту имя, скрывается Орданус, хранитель рощи и один из старших сыновей Кенария.",
			full = "Высоко в ветвях Великого Древа, давшего этому месту имя, скрывается Орданус, хранитель рощи и один из старших сыновей Кенария. Он пришёл сюда, чтобы укрыться от Совета Теней, чьи агенты приговорили его к смерти. Главной среди них была Брэлин Огненная Рука, сделавшая его смерть своей единственной целью и подославшая к нему убийц. Орданус пережил покушение и по-прежнему скрывается в высоких ветвях древа.\n\nПод ним кенарийские защитники, мерцающие драконы и Смеющиеся сестры несут дозор на заставе, охраняя северную тропу в оскверненные пределы Оскверненного леса.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Руины Ордил'Арана",
			short = "От Ордил'Арана теперь почти ничего не осталось, кроме разбитых камней. Некогда эти руины занял клан Тёмной Нити, готовый наброситься на всякого, кто подойдёт слишком близко.",
			full = "От Ордил'Арана теперь почти ничего не осталось, кроме разбитых камней. Некогда эти руины занял клан Тёмной Нити, готовый наброситься на всякого, кто подойдёт слишком близко. Кончилось это кровью: фурболги Колючего Меха изгнали культистов и забрали руины себе, и тела культистов до сих пор лежат там, где их настигла смерть.\n\nСреди развалин стоит Сердцедрево, укоренившееся там, где некогда был город, носивший какое-то имя и пользовавшийся каким-то положением. Ничего больше от него не уцелело, чтобы рассказать, каким он был.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Руины Звездной Пыли",
			short = "Руины Звёздной Пыли лежат на острове посреди озера. Некогда здесь царила святость, а теперь — гниль. Демоническая скверна, просачивающаяся из Оскверненного леса, проникла и в воду, и в камень, окрасив остров в болезненный жёлто-зелёный цвет.",
			full = "Руины Звёздной Пыли лежат на острове посреди озера. Некогда здесь царила святость, а теперь — гниль. Демоническая скверна, просачивающаяся из Оскверненного леса, проникла и в воду, и в камень, окрасив остров в болезненный жёлто-зелёный цвет. Теперь среди развалин бродят болотные чудища, искажённые отравленным озером.\n\nИ всё же кусты звёздной пыли по-прежнему растут там, не тронутые окружающей порчей. Говорят, их листья обладают целебной силой. Это единственное, что в руинах ещё напоминает о том, каким это место было до прихода гнили.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Сатирнаар",
			short = "Сатирнаар лежит в руинах среди деревьев северо-восточной части Ясеневого леса. Его постройки давно разрушены, но теперь среди обломков теснятся шатры: здесь обосновались сатиры Каменного Сердца.",
			full = "Сатирнаар лежит в руинах среди деревьев северо-восточной части Ясеневого леса. Его постройки давно разрушены, но теперь среди обломков теснятся шатры: здесь обосновались сатиры Каменного Сердца. Из трёх твердынь сатиров в лесу лишь Сатирнаар сохранился почти целиком, а его положение у дороги, ведущей от Заставы Расщепленного Дерева к Азшаре, сделало его самой доступной из трёх и самой ожесточённо оспариваемой.\n\nСатиры Каменного Сердца хранят здесь нечто большее, чем кров. В Сатирнааре покоится один из камней душ клана Тёмной Нити, знак договора, связывающего сатиров с тёмными замыслами этого культа.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Тенистый закоулок",
			short = "Тенистый закоулок лежит к югу от Приюта в Ночных Лесах и к востоку от Деревни Зелёной Лапы, небольшая долина, тихо укрывшаяся в складках Ясеневого леса.",
			full = "Тенистый закоулок лежит к югу от Приюта в Ночных Лесах и к востоку от Деревни Зелёной Лапы, небольшая долина, тихо укрывшаяся в складках Ясеневого леса. В склоне холма открывается пещера, где живёт небольшое медвежье семейство, держащееся особняком среди деревьев и теней.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Святилище Эссины",
			short = "Святилище Эссины стоит на юго-западе Ясеневого леса, укрывшись между Заставой Мейстры и Астранааром.",
			full = "Святилище Эссины стоит на юго-западе Ясеневого леса, укрывшись между Заставой Мейстры и Астранааром.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Приют Серебряного Ветра",
			short = "Приют Серебряного Ветра принадлежит ночным эльфам и находится под охраной Часовых и служащих вместе с ними элементалей воды.",
			full = "Приют Серебряного Ветра принадлежит ночным эльфам и находится под охраной Часовых и служащих вместе с ними элементалей воды. Вместе с Астранааром он является одним из главных аванпостов Ясеневого леса, и своё название он заслужил по праву: это гостеприимное место, а его таверна считается одной из самых уютных в этом краю.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Роща Среброкрылых",
			short = "Роща Среброкрылых находится в южной части центрального Ясеневого леса. Это купа деревьев, которую удерживают Среброкрылые Часовые, к юго-западу от их аванпоста и к западу от озера Зеркало Небес.",
			full = "Роща Среброкрылых находится в южной части центрального Ясеневого леса. Это купа деревьев, которую удерживают Среброкрылые Часовые, к юго-западу от их аванпоста и к западу от озера Зеркало Небес. Часовой Дальняя Песня несёт здесь дозор среди тех, кто поклялся защищать рощу.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Аванпост Среброкрылых",
			short = "Аванпост Среброкрылых стоит не на том берегу реки Фалфаррен, глубоко в краях, которые орки с Заставы Расщеплённого Дерева намерены очистить.",
			full = "Аванпост Среброкрылых стоит не на том берегу реки Фалфаррен, глубоко в краях, которые орки с Заставы Расщеплённого Дерева намерены очистить. Им командует Дариэль Лунное Пламя, а командовать здесь означает вести непрерывную войну: орки совершают набеги не ради добычи, а для того, чтобы стереть аванпост с лица земли и навсегда изгнать из этих лесов всех до единой Часовых.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Река Строптивая",
			short = "Строптивая берёт начало высоко на горе Хиджал: она вытекает из горного озера и с грохотом обрушивается водопадом в низины.",
			full = "Строптивая берёт начало высоко на горе Хиджал: она вытекает из горного озера и с грохотом обрушивается водопадом в низины. Оттуда она течёт широко и стремительно, разрезая землю надвое: по ней проходит граница, где Ясеневый лес сменяется Азшарой, а дальше к югу — где кончаются Степи и начинается Дуротар. В устье река последним каскадом низвергается в Великое море, чуть к северо-востоку от гоблинского порта Кабестан.\n\nЧерез неё перекинуты мосты: один соединяет Азшару с Ясеневым лесом, другой связывает Дуротар со Степями. Чуть к северу от самого западного из них есть участок воды, который касается сразу всех четырёх земель, — единственное место, где сходятся Ясеневый лес, Азшара, Дуротар и Степи.\n\nРека по-прежнему питает поля вдоль своих берегов и по-прежнему дарит зелень земле, по которой течёт. Но пить из неё больше нельзя.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Застава Расщепленного Дерева",
			short = "Брёвна Заставы Расщеплённого Дерева до сих пор хранят следы топоров, которыми её возводили, ведь эту заставу построили Громмаш Адский Крик и его клан Песни Войны, когда орки впервые вторглись в Ясеневый лес во время Третьей войны и валили древние деревья ради своей дороги и своих лагерей.",
			full = "Брёвна Заставы Расщеплённого Дерева до сих пор хранят следы топоров, которыми её возводили, ведь эту заставу построили Громмаш Адский Крик и его клан Песни Войны, когда орки впервые вторглись в Ясеневый лес во время Третьей войны и валили древние деревья ради своей дороги и своих лагерей.\n\nНочные эльфы так и не смирились с тем, что клан Песни Войны сделал с их лесами, и старые раны тревожно ноют под напряжённым перемирием между Ордой и Альянсом. Поэтому Застава Расщеплённого Дерева навлекает на себя больше ответных ударов, чем большинство поселений в этих лесах, и набеги на соседний Астранаар и обратно случаются часто.\n\nТеперь это гарнизон, а не поселение: орки и таурены несут здесь разведку и охрану, следя за опушкой в ожидании налётчиков, появления которых они научились ждать.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "Туннель Когтя",
			short = "Туннель Когтя — извилистый проход, соединяющий Ясеневый лес с Когтистыми горами. Он неровен, полон небольших тупиков и странных пустот, выточенных в скале.",
			full = "Туннель Когтя — извилистый проход, соединяющий Ясеневый лес с Когтистыми горами. Он неровен, полон небольших тупиков и странных пустот, выточенных в скале. Один его выход открывается к западу от озера Мистраль, а другой — в северо-западной части Утёса Ветрорезов. Никто здесь не живёт: это просто путь сквозь горы.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Деревня Колючего Меха",
			short = "Деревня Колючего Меха лежит в западной части центрального Ясеневого леса, к северу от Астранаара. Это дом племени Колючего Меха — фурболгов, поражённых порчей и ставших враждебными, которые нападают на всякого, кто забредёт поблизости.",
			full = "Деревня Колючего Меха лежит в западной части центрального Ясеневого леса, к северу от Астранаара. Это дом племени Колючего Меха — фурболгов, поражённых порчей и ставших враждебными, которые нападают на всякого, кто забредёт поблизости. Двое свирепых воинов, Дал Кровавый Коготь и Роргиш Челюсть, возглавляют племя и защищают деревню от всех, кто к ней приближается.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Рабочий лагерь Песни Войны",
			short = "На юго-востоке Ясеневого леса, к востоку от озера Зеркало Небес, клан Песни Войны содержит рабочий лагерь, где лесорубы и сборщики трудятся под охраной орков, заготавливая лес для владений клана.",
			full = "На юго-востоке Ясеневого леса, к востоку от озера Зеркало Небес, клан Песни Войны содержит рабочий лагерь, где лесорубы и сборщики трудятся под охраной орков, заготавливая лес для владений клана.\n\nЛагерь стоит вдали от главных сил клана Песни Войны, и его стражи отрезаны от своих, без всякой надежды на подкрепление.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Лесозаготовки Песни Войны",
			short = "Леса Ясеневого леса звенят от ударов топоров на Лесозаготовках Песни Войны, где клан Песни Войны вырубает древние деревья на древесину.",
			full = "Леса Ясеневого леса звенят от ударов топоров на Лесозаготовках Песни Войны, где клан Песни Войны вырубает древние деревья на древесину. Опорой лагеря служат псарня с боевыми зверями и Крепость Каргатия, твердыня, возведённая для охраны вырубки.\n\nЖадность клана до древесины не осталась без ответа. Иллиана и её сёстры вышли в здешние леса и обращают магию природы против крошшеров, вгрызающихся в стволы, и земля между штабелями брёвен стала полем боя между Альянсом и Ордой.\n\nИ всё же лагерь по-прежнему выполняет своё назначение: отсюда непрерывно тянутся обозы с лесом на Заставу Расщеплённого Дерева, чьи стены и жители зависят от того, что присылают им Лесозаготовки Песни Войны.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Ксавиан",
			short = "Ксавиан поднимается там, где некогда стоял храм ночных эльфов, а его камни теперь отданы сатирам.",
			full = "Ксавиан поднимается там, где некогда стоял храм ночных эльфов, а его камни теперь отданы сатирам. Из трёх твердынь сатиров в Ясеневом лесу именно здесь сосредоточена власть: в этих руинах обосновались и принц Рейз, и Гельтарис, и именно здесь сатиры используют в своих ритуалах похищенное масло Песни Войны.\n\nМесто названо в честь Ксавия, который давным-давно помог открыть путь Пылающему Легиону через портал, созданный силой Источника Вечности в Зин-Азшари. Саргерас, недовольный тем, как медленно продвигалась эта работа, превратил Ксавия в самого первого из сатиров. Ксавиан лежит достаточно близко к Азшаре, чтобы это название казалось неслучайным.\n\nПротив Ксавиана выступали дриады. Одну из них, Анилию, нашли здесь смертельно раненой: она искала ветвь Кенария, которую сатиры присвоили себе, и осталась лежать на земле среди руин, которые не смогла очистить.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "Зорамское взморье",
			short = "Волны у Зорамского взморья разбиваются о то, что некогда было городом.",
			full = "Волны у Зорамского взморья разбиваются о то, что некогда было городом. До того как мир был разорван Великим Расколом, здесь стоял Зорам, город ночных эльфов, и когда море поднялось, чтобы забрать свою долю расколотого мира, Зорам ушёл под воду вместе с ним. Над водой теперь не осталось ничего, кроме названия.\n\nСегодня по взморью ходят не эльфы, а наги. Они сделали берег своим, и обломки, разбросанные по песку, — разбитые корабли, туши выброшенных на берег морских созданий — показывают, насколько безраздельно побережье перешло в их руки. Среди скал и затопленных впадин неподалёку лежит Непроглядная Пучина, ушедшая в землю, как некогда Зорам ушёл в море.\n\nОрда держит здесь небольшой плацдарм — Форт Зорам'гар, занятый скорее по необходимости, чем по выбору, и истощила свои силы в борьбе с нагами Гневного Хвоста, оспаривающими каждую пядь взморья. Эти же наги напали на Тален, и теперь враги наседают на форт не с одной стороны. Это суровый, сырой и спорный участок побережья, принадлежавший империи, что утонула, а ныне удерживаемый созданиями, рождёнными морем, которое её поглотило.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Форт Зорам'гар",
			short = "Форт Зорам'гар — порт Орды на Зорамском взморье в Ясеневом лесу, чьи причалы уходят в воды внизу.",
			full = "Форт Зорам'гар — порт Орды на Зорамском взморье в Ясеневом лесу, чьи причалы уходят в воды внизу.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
