			full = "Лагерь Э'Ток — стоянка кентавров племени Галак на северо-западе Тысячи Игл. Здешние кентавры напали на караван, в котором ехал гоблин Визло Фингалет, но так и не смогли украсть его самое драгоценное устройство, надёжно спрятанное на шее его свирепой ручной пантеры.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Пик Темного Облака",
			short = "Пик Тёмного Облака раскинулся на трёх небольших столовых горах к востоку от Великого Подъёмника, вершины которых связаны верёвочными мостами, натянутыми над пустотой.",
			full = "Пик Тёмного Облака раскинулся на трёх небольших столовых горах к востоку от Великого Подъёмника, вершины которых связаны верёвочными мостами, натянутыми над пустотой. Наверх ведут лишь два пути, и оба хорошо охраняются: естественный склон через четвёртую гору или мост, переброшенный со стороны Курганов Иглошкурых.\n\nЭти высоты удерживают таурены из племени Зловещего Тотема во главе с Арнаком Зловещим Тотемом и Харбом Гнилой Горой. За охраняемыми мостами оба вождя ведут тайную переписку с некой тёмной силой, природа которой неизвестна. О том, что происходит между ними, открыто не говорят, но то, как старательно отрезаны столовые горы, показывает, насколько тщательно хранится эта тайна.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Застава Вольного Ветра",
			short = "Застава Вольного Ветра стоит высоко на столовой горе в Тысяче Игл, вне досягаемости кентавров, что бродят внизу.",
			full = "Застава Вольного Ветра стоит высоко на столовой горе в Тысяче Игл, вне досягаемости кентавров, что бродят внизу. Деревянные подъёмники поднимают её жителей со дна каньона, а верёвочные мосты протянуты между соседними скалами, взбираясь от вершины к вершине, пока не достигнут деревни. Внизу кентавры Галак собирают свои боевые отряды, а над равнинами кружат и кричат гарпии, но настоящая защита заставы — сама высота.\n\nБолее серьёзная беда пришла с северо-запада, с Пика Тёмного Облака, где племя Зловещего Тотема удерживало свои высоты. На Заставе Вольного Ветра стали опасаться их задолго до открытой войны: пропадали таурены, на пике видели посланцев неведомого и тёмного происхождения, а в убийствах обвиняли Зловещий Тотем. Больше всех вины лежало на вожде Арнаке Зловещем Тотеме. Когда Лакота Песня Ветра с Заставы Вольного Ветра отвергла его ухаживания, он велел похитить её силой, а когда её брат пришёл ей на защиту, воины Зловещего Тотема убили его.",
