			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Виражи на Миражах",
			short = "Гоблин по имени Поззик и гном по имени Пшикс Медноштиф были уверены, что именно их народ даёт миру лучших инженеров, и ни один не желал уступать.",
			full = "Гоблин по имени Поззик и гном по имени Пшикс Медноштиф были уверены, что именно их народ даёт миру лучших инженеров, и ни один не желал уступать. Поэтому они решили спор так, как это делают изобретатели: построили трассу и соорудили реактивные машины, чтобы по ней гонять.\n\nЭто соперничество привлекает толпы, далеко не ограничиваясь ими двумя. И Орда, и Альянс приходят болеть за своих любимцев, когда гномские и гоблинские машины каждый день мчатся наперегонки, а после каждая команда спешно перебирает двигатели, чтобы добиться нового преимущества. Настоящее состязание всегда одно и то же: чей народ построит лучшую машину, и оно никогда не заканчивается.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Курганы Иглошкурых",
			short = "В глубине зарослей Тысячи Игл лежит лабиринт из шипов и костей. Говорят, его вход повторяет очертания пасти самого Агамаггана: это арочный проём во внешнем куполе, скрытый так, что найти его может лишь тот, кто уже знает, как он выглядит.",
			full = "В глубине зарослей Тысячи Игл лежит лабиринт из шипов и костей. Говорят, его вход повторяет очертания пасти самого Агамаггана: это арочный проём во внешнем куполе, скрытый так, что найти его может лишь тот, кто уже знает, как он выглядит. Это Курганы Иглошкурых, древнее место погребения и исконная столица свинобразов, созданная из тех же могучих лоз, что и Лабиринты Иглошкурых. Большую часть огромного тернистого купола, накрывающего их, сплела Чарлга Остробок.\n\nМногие поколения Курганы оставались обителью мёртвых свинобразов, за которой присматривали верховные жрецы племени Мёртвой Головы. Но после Третьей войны лич Амненнар Хладовей обратил своих приспешников против свинобразов и захватил их священный город, превратив его в оплот Плети. Свинобразы яростно сражались, чтобы вернуть своё, прежде чем чума Амненнара распространится дальше по Степям, и в этой борьбе живые были повержены и заперты среди шипов вместе с мёртвыми.\n\nАмненнар по-прежнему пребывает в лабиринте, властвуя над подчинёнными его воле свинобразами, и его власть над Курганами не поколеблена.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
