		["rustmaul dig site"] = {
			name = "Карьер Ржавой Кувалды",
			short = "Карьер Ржавой Кувалды лежит на Мерцающей равнине, и его траншеи брошены посреди работ. Лига исследователей пришла сюда, чтобы раскопать древние руины, и работала в тени пещеры, где гнездились силитиды.",
			full = "Карьер Ржавой Кувалды лежит на Мерцающей равнине, и его траншеи брошены посреди работ. Лига исследователей пришла сюда, чтобы раскопать древние руины, и работала в тени пещеры, где гнездились силитиды.\n\nРаскопки прекратились, так и не завершившись. Траншеи стоят открытыми и пустыми, инструменты дворфов брошены там, где их оставили, а в пещере под карьером по-прежнему живут силитиды.",
