			full = "Каньон Визга прорезает юг Тысячи Игл, и его стены отзываются эхом криков гарпий Визга, которые его заполонили. В глубине каньона лежит Логово Легкоперых, твердыня гарпий.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "Мерцающая равнина",
			short = "Мерцающая равнина лежит на юго-восточной окраине Тысячи Игл, где земля плоско и голо тянется до границы с Танарисом.",
			full = "Мерцающая равнина лежит на юго-восточной окраине Тысячи Игл, где земля плоско и голо тянется до границы с Танарисом. Здесь ничего не растёт. Почва — спёкшаяся соль, и живут на ней лишь василиски, скорпиды, черепахи и стервятники. Некогда здесь было дно озера: разбитый корпус парусного судна до сих пор лежит, наполовину занесённый, в северной части равнины. Корабль, застрявший вдали от всякой воды, свидетельствует о том, чем было это место, прежде чем высохнуть до соли и растрескавшейся земли.\n\nЭта гладкая равнина привлекла гоблинов и гномов, стоящих по разные стороны их давнего соперничества. Они построили здесь Виражи на Миражах и наперегонки строили машины, стремясь обогнать друг друга. Эти устройства редко выдерживали испытания. Равнину усеивают воронки там, где двигатели выходили из строя, а обломки неудачных гоночных машин разбросаны по соли и остаются печься там, где упали.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Утес Треснувшего Копыта",
