		["splithoof hold"] = {
			name = "Оплот Треснувшего Копыта",
			short = "Кентавры Галак сделали Оплот Треснувшего Копыта своей твердыней в пещерах Утёса Треснувшего Копыта. Внутри на Древней жаровне горит Священное пламя, огонь, который, как говорят, не гаснет даже под водой.",
			full = "Кентавры Галак сделали Оплот Треснувшего Копыта своей твердыней в пещерах Утёса Треснувшего Копыта. Внутри на Древней жаровне горит Священное пламя, огонь, который, как говорят, не гаснет даже под водой.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Руины Тахонды",
			short = "Там, где теперь лежит Мерцающая равнина, некогда стояла деревня тауренов, давно обратившаяся в руины и поглощённая песком. Теперь среди камней гнездятся василиски Солекамня, и некоторые говорят, что именно они изгнали тауренов.",
			full = "Там, где теперь лежит Мерцающая равнина, некогда стояла деревня тауренов, давно обратившаяся в руины и поглощённая песком. Теперь среди камней гнездятся василиски Солекамня, и некоторые говорят, что именно они изгнали тауренов.\n\nОсталась лишь одна подсказка: на кожаной стене одного из строений — два ряда по три параллельных разрыва, следы когтей, а не ветра или времени. Что-то пришло в эту деревню с определённой целью.\n\nИмён не сохранилось. Остались лишь руины у горной тропы, ведущей в Танарис.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "Угол Семи Ветров",
			short = "В северной стене Тысячи Игл скрывается небольшая пещера, известная как Угол Семи Ветров, мимо которой легко пройти, если не знать, что её нужно искать.",
			full = "В северной стене Тысячи Игл скрывается небольшая пещера, известная как Угол Семи Ветров, мимо которой легко пройти, если не знать, что её нужно искать. Здесь обосновались Дорн Вольный Ловчий и Пратта Заклинательница Туч, укрывшись от ветров и пыли каньона внизу.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Кратер Криворука",
			short = "В северной части Мерцающей равнины зияет огромный шрам, настолько глубокий, что даже в полдень поглощает свет. Никто не знает, откуда он взялся, хотя название намекает на некоего Криворука — то ли того, кто его нашёл, то ли того, кто его создал.",
			full = "В северной части Мерцающей равнины зияет огромный шрам, настолько глубокий, что даже в полдень поглощает свет. Никто не знает, откуда он взялся, хотя название намекает на некоего Криворука — то ли того, кто его нашёл, то ли того, кто его создал. Разбросанные вокруг обломки и воронки поменьше наводят на мысль о гоблинском или гномском изобретательстве, пошедшем не так, о каком-то изобретении, которое довели до крайности.\n\nС тех пор яму облюбовали василиски Солекамня.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Застава Белого Плеса",
			short = "Застава Белого Плёса — небольшой лагерь Орды у дороги неподалёку от Лагеря Э'Ток в Тысяче Игл.",
			full = "Застава Белого Плёса — небольшой лагерь Орды у дороги неподалёку от Лагеря Э'Ток в Тысяче Игл.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Безветренный каньон",
			short = "Безветренный каньон лежит между Заставой Вольного Ветра и Мерцающей равниной, и его стены изрыты гнёздами. Здесь хозяйничают крылатые змеи, взмывающие на воздушных потоках, которые и дали каньону его название.",
			full = "Безветренный каньон лежит между Заставой Вольного Ветра и Мерцающей равниной, и его стены изрыты гнёздами. Здесь хозяйничают крылатые змеи, взмывающие на воздушных потоках, которые и дали каньону его название. Отсюда тропа ведёт к Углу Семи Ветров.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
