		["boulderslide ravine"] = {
			name = "Ущелье Камнепадов",
			short = "Ущелье Камнепадов тихо лежит вдоль Паучьего тракта, не тронутое войнами, что терзают окрестные земли. По его склонам осторожно пробираются горные бараны, а над головой кружат скальные буревестники.",
			full = "Ущелье Камнепадов тихо лежит вдоль Паучьего тракта, не тронутое войнами, что терзают окрестные земли. По его склонам осторожно пробираются горные бараны, а над головой кружат скальные буревестники.\n\nНапротив пещеры ущелья находится заброшенный грот: бочки в нём всё ещё стоят штабелями, грубые факелы всё ещё торчат на местах, хотя зажечь их больше некому. На его стенах сохранились племенные рисунки, выполненные в стиле, похожем на работу тауренов.",
