			full = "Лагерь Апарахе был деревней тауренов на востоке Когтистых гор. На него напали воины Зловещего Тотема с Заставы Зловещего Тотема под предводительством Грундига Тёмное Облако. До нападения здесь жил Макаба Плоское Копыто со своей дочерью Кайей.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Обугленная долина",
			short = "Обугленная долина некогда была зелёной. В этой долине на юго-западе Когтистых гор гнездились гарпии Кровавой Ярости, а по лесу ходили древни, его стражи.",
			full = "Обугленная долина некогда была зелёной. В этой долине на юго-западе Когтистых гор гнездились гарпии Кровавой Ярости, а по лесу ходили древни, его стражи.\n\nЗатем пришли гоблины из Торговой компании, чтобы выпотрошить долину ради древесины и руды. Древни восстали против них и отбросили машины, но духи долины так и не успокоились. Раскопки пробудили что-то под землёй, и через разломы там, где прежде стоял лес, наружу хлынули огонь и элементали. Древни, прогнавшие гоблинов, не вернулись невредимыми: то, чем их коснулось гоблинское оружие, осталось в них, и теперь их причисляют к опасностям долины, а не к её стражам.\n\nОсталась долина огня и лавы, где чёрные деревья стоят в пепле на месте прежних зелёных. Друиды Приюта у Солнечного Камня взяли на себя труд, который некогда выполняли древни, пробуждая новую поросль на выжженной земле в надежде, что долина снова станет лесом, а не раной в горах.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Скалистое озеро",
			short = "Скалистое озеро лежит под огромным деревянным сооружением, которое Торговая компания возвела над Утёсом Ветрорезов. Отсюда за работами следит Геренцо Терминатрикс.",
			full = "Скалистое озеро лежит под огромным деревянным сооружением, которое Торговая компания возвела над Утёсом Ветрорезов. Отсюда за работами следит Геренцо Терминатрикс.\n\nВ само озеро соваться не стоит: его присвоил Скалочелюст, рыба, выросшая до чудовищных размеров в его стоячей воде.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Долина Высокого леса",
			short = "Лесистая Долина Высокого леса лежит в предгорьях Когтистых гор. Попасть в неё можно по Паучьему тракту, а к югу от неё находится Малака'джин.",
			full = "Лесистая Долина Высокого леса лежит в предгорьях Когтистых гор. Попасть в неё можно по Паучьему тракту, а к югу от неё находится Малака'джин.\n\nПокой долины нарушился, когда племя Зловещего Тотема под предводительством Грундига Тёмное Облако обрушилось на Лагерь Апарахе и перебило почти всех его жителей. Макаба Плоское Копыто выжил и в ответ призвал выследить воинов Зловещего Тотема в долине.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
