			full = "Мутное озеро лежит в самом сердце Когтистых гор. Это дикая котловина, где в водах и на берегах кишат виверны, слизни и громоящеры. Посреди озера поднимается холм, а над ним, на Высотах Ветрорезов, до сих пор гнездятся оставшиеся в округе виверны.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Сиширский каньон",
			short = "Каньон ведёт от главной дороги в Когтистых горах к Руинам Эльдре'тара, но никому не удаётся пройти через него легко.",
			full = "Каньон ведёт от главной дороги в Когтистых горах к Руинам Эльдре'тара, но никому не удаётся пройти через него легко. Сиширский каньон целиком отдан моховым паукам, чудовищному выводку, чьи яйца и паутина заполонили каждый уступ и каждую впадину в камне. В его глубине среди своих сородичей ждёт самая огромная из них, Бесселет.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Пик Каменного Когтя",
			short = "Пик Каменного Когтя лежит в зелёной долине на крайнем северо-западе гор, носящих схожее имя, и за ним ухаживают друиды из соседней Пещеры Когтей.",
			full = "Пик Каменного Когтя лежит в зелёной долине на крайнем северо-западе гор, носящих схожее имя, и за ним ухаживают друиды из соседней Пещеры Когтей. Эта гора считается священной, и её камень пронизан магией.\n\nВо время Третьей войны сюда пришла Джайна Праудмур со своей экспедицией и разбила лагерь у входа в пещеры под пиком. Вслед за ней пришли Тралл и его Орда в поисках Оракула.\n\nС тех пор это место стало средоточием ночных эльфов и Альянса, а его друиды присматривают за долиной.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Приют у Солнечного Камня",
			short = "Приют у Солнечного Камня скрыт среди вершин к югу от Мутного озера в Когтистых горах. Здесь мир духов вплотную подступает к миру живых.",
			full = "Приют у Солнечного Камня скрыт среди вершин к югу от Мутного озера в Когтистых горах. Здесь мир духов вплотную подступает к миру живых. Задолго до того, как Орда подняла здесь свои знамёна, таурены совершали паломничества к этому камню, чтобы проводить обряды перехода в царство духов. Говорят, что Ан'ше, солнце, некогда поцеловал гору, на которой сейчас стоит приют.\n\nТеперь орки и таурены вместе удерживают Приют у Солнечного Камня. Это самое оживлённое место сбора сил Орды в этих горах, средоточие торговли и труда, где исцеляют то, что Торговая компания и другие злые силы отняли у земли.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "Пещера Когтей",
			short = "Высоко на Пике Каменного Когтя земля раскрывается входом в Пещеру Когтей — подземную обитель, где живут дриады Мутного озера и одноимённые хранители, а присматривают за ними кенарийские смотрители из ночных эльфов.",
			full = "Высоко на Пике Каменного Когтя земля раскрывается входом в Пещеру Когтей — подземную обитель, где живут дриады Мутного озера и одноимённые хранители, а присматривают за ними кенарийские смотрители из ночных эльфов.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "Туннель Когтя",
			short = "Туннель Когтя — извилистый проход, соединяющий Ясеневый лес с Когтистыми горами. Он неровен, полон небольших тупиков и странных пустот, выточенных в скале.",
			full = "Туннель Когтя — извилистый проход, соединяющий Ясеневый лес с Когтистыми горами. Он неровен, полон небольших тупиков и странных пустот, выточенных в скале. Один его выход открывается к западу от озера Мистраль, а другой — в северо-западной части Утёса Ветрорезов. Никто здесь не живёт: это просто путь сквозь горы.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Паучий тракт",
			short = "Паучий тракт пролегает между Малака'джином и Мутным озером, по земле, которая с обеих сторон низко просела.",
			full = "Паучий тракт пролегает между Малака'джином и Мутным озером, по земле, которая с обеих сторон низко просела. К западу от Малака'джина Орда перегородила дорогу баррикадой, чтобы не дать Альянсу продвинуться дальше на восток.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Утес Ветрорезов",
			short = "Утёс Ветрорезов некогда был древним лесом, густым и зелёным, в своей долине среди Когтистых гор. Теперь это не так. Здесь остались лишь пни, грязная вода и машины, скрип которых почти никогда не стихает.",
			full = "Утёс Ветрорезов некогда был древним лесом, густым и зелёным, в своей долине среди Когтистых гор. Теперь это не так. Здесь остались лишь пни, грязная вода и машины, скрип которых почти никогда не стихает.\n\nУ этого разорения есть имя: Геренцо Терминатрикс, гном-лепер, которому под знаменем Торговой компании поручили руководить всей лесозаготовительной экспедицией. Он построил Супер-дровосек 6000, машину, способную превратить в опилки самые старые деревья утёса, и наблюдает за своей работой с помоста, возведённого над Скалистым озером, — властелин всего, что расчистила машина. Однако власть над этим местом сделала его лишним для тех, кто стоит над ним: директор Ридлвокс из Союза ремонтников Нижней шахты желает его смерти, а гоблин Зиз Физзикс затаился на утёсе, дожидаясь, когда приказ будет исполнен.\n\nВ юго-восточном углу утёса кобольды Ветрорезов захватили Рудник Ветрорезов и роют туннели в поисках дымчатой железной руды.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Рудник Ветрорезов",
			short = "Рудник Ветрорезов лежит в конце Волчьей реки, на Утёсе Ветрорезов. Некогда Торговая компания разрабатывала здесь оловянные жилы, заставляя копать кобольдов.",
			full = "Рудник Ветрорезов лежит в конце Волчьей реки, на Утёсе Ветрорезов. Некогда Торговая компания разрабатывала здесь оловянные жилы, заставляя копать кобольдов.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
