	-- Пустоши: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Пещера Болгана",
			short = "В Деревне Гелкис пещера под названием Пещера Болгана служит убежищем для самых видных членов племени, и среди них — его хан Шака.",
			full = "В Деревне Гелкис пещера под названием Пещера Болгана служит убежищем для самых видных членов племени, и среди них — его хан Шака.\n\nВ её глубине растут синие кристаллы, слёзы Терадрас, которые копят шаманы Гелкис, верящие, что эти камни несут защиту принцессы.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Этель-Ретор",
			short = "У северо-западного побережья Пустошей море поглотило большую часть Этель-Ретора. Над водой возвышается лишь одинокая башня, соединённая с берегом узким мостом, ведущим к двери, которая всегда остаётся закрытой.",
			full = "У северо-западного побережья Пустошей море поглотило большую часть Этель-Ретора. Над водой возвышается лишь одинокая башня, соединённая с берегом узким мостом, ведущим к двери, которая всегда остаётся закрытой. Наги присвоили себе эти затопленные руины.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Деревня Гелкис",
			short = "Деревня Гелкис раскинулась кольцом вокруг широкого ущелья на юго-западе Пустошей и служит оплотом племени Гелкис.",
			full = "Деревня Гелкис раскинулась кольцом вокруг широкого ущелья на юго-западе Пустошей и служит оплотом племени Гелкис. Мосты, натянутые между скалами и обрывами ущелья, ведут вниз к Пещере Болгана, высеченной в южном склоне горы, где живёт хан Гелкис.\n\nДеревня вплотную примыкает к главной дороге Пустошей, идущей с севера на юг, так близко, что сама дорога стала опасной для путников. Гелкис выстроили новые хижины к востоку от дороги, ведущей к Фераласу, вдоль озера, распространившись за пределы ущелья, которое когда-то их укрывало.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Застава Скитающихся Духов",
			short = "Застава Скитающихся Духов стоит рядом с Кладбищем кодо в центральной части Пустошей, и мёртвые определяют здесь всё.",
			full = "Застава Скитающихся Духов стоит рядом с Кладбищем кодо в центральной части Пустошей, и мёртвые определяют здесь всё. Шаманы тауренов охраняют кости, помогая духам павших кодо перейти в следующую жизнь, а при необходимости беседуя с теми, кто уже ушёл. Во главе их стоит Гурда Буйногривая, удерживающая эту незащищённую заставу, располагая лишь самым необходимым.\n\nВ отличие от Деревни Ночных Охотников, находящейся в безопасности в другой части края, Застава Скитающихся Духов такой защиты лишена. Это передовой лагерь, построенный для войны, а не для удобства: здесь нет ни таверны, ни места для отдыха. Он существует ради одной цели — вести борьбу Орды против культистов Пылающего Клинка и племён кентавров, рыщущих по Пустошам.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Кладбище кодо",
			short = "Кодо Пустошей приходят сюда умирать, и их кости, сваленные в груды, белеют на растрескавшейся земле. Потревожь их — и мёртвые не останутся в покое: из земли поднимаются призраки кодо, чтобы охранять то, что осталось от их сородичей.",
			full = "Кодо Пустошей приходят сюда умирать, и их кости, сваленные в груды, белеют на растрескавшейся земле. Потревожь их — и мёртвые не останутся в покое: из земли поднимаются призраки кодо, чтобы охранять то, что осталось от их сородичей.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Деревня Колкар",
			short = "Деревня на восточной окраине Пустошей — оплот племени Колкар, самого многочисленного из племён кентавров Калимдора, чьи стоянки встречаются даже в Степях и Дуротаре.",
			full = "Деревня на восточной окраине Пустошей — оплот племени Колкар, самого многочисленного из племён кентавров Калимдора, чьи стоянки встречаются даже в Степях и Дуротаре. Соперники из племени Маграм постоянно теснят их, ибо вражда между племенами никогда не утихает.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Хижина Кормека",
			short = "Обветшалая хижина стоит в северной части центральных Пустошей. В ней живёт Ива, член Сумеречного Молота, которая ухаживает за этим местом с теплотой, неожиданной для последователей этого культа.",
			full = "Обветшалая хижина стоит в северной части центральных Пустошей. В ней живёт Ива, член Сумеречного Молота, которая ухаживает за этим местом с теплотой, неожиданной для последователей этого культа. Снаружи, в загоне, усыпанном костями кодо, среди останков пляшет Биббли Скобкофуз, радуясь барышу, который могут принести такие кости.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Деревня Маграм",
			short = "Деревня Маграм поднимается на россыпи островков среди грязно-жёлтых отравленных прудов на юго-востоке Пустошей, и её хижины соединены грубыми мостами, переброшенными через воду.",
			full = "Деревня Маграм поднимается на россыпи островков среди грязно-жёлтых отравленных прудов на юго-востоке Пустошей, и её хижины соединены грубыми мостами, переброшенными через воду. Здесь живёт племя Маграм, один из народов кентавров, ведущих войну с племенем Гелкис за господство над этими бесплодными землями.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Поле Маннорок",
			short = "Среди руин ночных эльфов, разбросанных по Пустошам, есть место, чьё название ни один путник не произносит легкомысленно.",
			full = "Среди руин ночных эльфов, разбросанных по Пустошам, есть место, чьё название ни один путник не произносит легкомысленно. Поле Маннорок названо в честь Маннорота, грозного владыки преисподней, и земля здесь помнит его. Земля была мертва задолго до прихода демонов, но магия Скверны опустошила её ещё сильнее, и теперь сам воздух густо пропитан порчей, а на всякого, кто сюда ступает, ложится смертоносная пелена.\n\nПуть открыли культисты Пылающего Клинка: они прорвали в мир несколько порталов, чтобы призвать через них слуг Пылающего Легиона — инферналов, суккубов, гончих Скверны и стражей Скверны, которые теперь рыщут среди руин. Этими демонами командует лорд Азреток, а орк-чернокнижник Джугкар Грим'род стоит среди них как голос самого Пылающего Клинка. Вместе они собрали здесь крупнейшее скопление демонов во всём центральном Калимдоре — доказательство того, что замысел культистов удался куда больше, чем можно было опасаться.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Высота Найджела",
			short = "Высота Найджела несёт дозор в северных горах Пустошей. Это застава, которую удерживают Альянс и Круг Кенария.",
			full = "Высота Найджела несёт дозор в северных горах Пустошей. Это застава, которую удерживают Альянс и Круг Кенария.\n\nСюда пришёл хранитель Марандис со своими сёстрами-дриадами, сделав заставу своей базой, пока они преследовали принцессу Терадрас. Их целью было извлечь тело Зейтара из глубин Мародона и отнести его домой, в Когтистые горы.\n\nВ то же время армия Штормграда разместила здесь стражу Высоты Найджела под командованием капитана Пентигаста, чтобы противостоять угрозе со стороны племён кентавров, владевших этим краем. Пентигаст следил за соперничеством Гелкис и Маграм с настороженностью солдата, уверенный, что победившее племя осмелеет настолько, что обратится против соседних владений Альянса, и потому стремился понять, как одолеть кентавров, натравливая одно племя на другое.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Остров Раназьяр",
			short = "Остров Раназьяр — небольшой скалистый остров у северо-западного побережья Пустошей, где обитают змееподобные наги.",
			full = "Остров Раназьяр — небольшой скалистый остров у северо-западного побережья Пустошей, где обитают змееподобные наги. Среди камней стоят руины ночных эльфов, часть того же древнего города, что и Этель-Ретор, ныне безмолвные над живущими здесь нагами.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Саргерон",
			short = "Некогда стоявший здесь город носил эльфийское имя, утраченное с тех пор, как Война Древних расколола мир.",
			full = "Некогда стоявший здесь город носил эльфийское имя, утраченное с тех пор, как Война Древних расколола мир. От него остались лишь руины, которые сатиры из племени Ярой Ненависти, обитающие здесь, называют теперь Саргероном в честь своего демонического повелителя Саргераса.\n\nКогда-то среди этих руин было три святых места Элуны: ее собор, ее храм и ее святилище. Реликвии той древней веры до сих пор лежат среди камней: Жаровня Элуны, ее Служительница, ее Чаша и Древний рунический камень Вихря.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Побережье Сар'Терис",
			short = "Побережье, где Пустоши встречаются с морем, совсем не похоже на лежащие за ним земли. Если в глубине края все серо и безжизненно, то на побережье Сар'Терис светит солнце и зеленеют травы.",
			full = "Побережье, где Пустоши встречаются с морем, совсем не похоже на лежащие за ним земли. Если в глубине края все серо и безжизненно, то на побережье Сар'Терис светит солнце и зеленеют травы. По его отмелям бродят морские великаны, в водах извиваются наги, а по пескам снуют макруры.\n\nПод Этель-Ретором на берегу лежит разбитая лодка: доски ее расщеплены, а команда, что была на ней, бесследно исчезла.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Лагерь Заржавня",
			short = "Неподалеку от Кладбища кодо в Пустошах стоит небольшой гоблинский лагерь.",
			full = "Неподалеку от Кладбища кодо в Пустошах стоит небольшой гоблинский лагерь. Он принадлежит Смиду Заржавню, предприимчивому гоблину, который держит караван кодо и гонит этих огромных зверей через пустоши ради той прибыли, какую только может дать этот край.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Лощина Тьмы",
			short = "Лощина Тьмы укрыта в горах к юго-востоку от Шок'Токара — это уголок Пустошей, на который мало кто наткнется случайно.",
			full = "Лощина Тьмы укрыта в горах к юго-востоку от Шок'Токара — это уголок Пустошей, на который мало кто наткнется случайно. Среди ее скал высятся гигантские грибы, а в самом сердце лощины находится круг призыва, скованный массивными цепями. Его построили сектанты Пылающего Клинка, избравшие лощину своим убежищем.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Деревня Ночных Охотников",
			short = "Деревня Ночных Охотников стоит там, где побережье Сар'Терис встречается с южным берегом Пустошей. Это рыбацкое поселение троллей.",
			full = "Деревня Ночных Охотников стоит там, где побережье Сар'Терис встречается с южным берегом Пустошей. Это рыбацкое поселение троллей. Ее жители кормятся морем, и именно их улов снабжает пищей Заставу Скитающихся Духов, что лежит дальше в глубине края.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Тефрис-Аран",
			short = "На севере Пустошей, к северу от Крепости Громового Топора, разбросаны руины ночных эльфов — остатки поселения, которое, как считается, было уничтожено во время Великого Раскола.",
			full = "На севере Пустошей, к северу от Крепости Громового Топора, разбросаны руины ночных эльфов — остатки поселения, которое, как считается, было уничтожено во время Великого Раскола. Здесь так ничего и не отстроили. Теперь среди разбитых камней бродят лишь дикие твари Пустошей.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Крепость Громового Топора",
			short = "Крепость Громового Топора стоит на северо-западе Пустошей и отдана во власть культа Пылающего Клинка.",
			full = "Крепость Громового Топора стоит на северо-западе Пустошей и отдана во власть культа Пылающего Клинка. За ее стенами, среди цитадели, казарм, пещеры и сторожевых башен, сектанты под началом Кохора готовятся призвать демона Назаргена во всей его силе, опасаясь вызвать его слишком рано, когда он будет настолько слаб, что его можно будет уничтожить.\n\nНекогда в крепости хранился Скипетр Света — артефакт чудовищной мощи, похищенный Пылающим Клинком у наг. Азор Альдаморт, служащий Серебряному Рассвету, взялся вернуть его и с чужой помощью сумел вырвать скипетр из рук культа.\n\nВ этих стенах жил и Тиранис Малем — имя, которое его собственный народ произносит с презрением, ведь он предал своих и предался изучению демонической магии, избрав Крепость Громового Топора убежищем для своих темных занятий.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Долина Костей",
			short = "Долина Костей — это ущелье на южной окраине Пустошей, где бродят скелеты, кентавры-некроманты и призраки погибших кентавров племени Маграм.",
			full = "Долина Костей — это ущелье на южной окраине Пустошей, где бродят скелеты, кентавры-некроманты и призраки погибших кентавров племени Маграм. У отвесных скал покоятся два огромных скелета — Мертвые Гиганты, происхождение которых неизвестно.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Долина Копий",
			short = "Долина Копий на западе Пустошей — родной край кентавров племени Мародин. Пешком сюда можно добраться лишь по узким горным перевалам с юга и востока.",
			full = "Долина Копий на западе Пустошей — родной край кентавров племени Мародин. Пешком сюда можно добраться лишь по узким горным перевалам с юга и востока. В юго-западной оконечности долины находится вход в Мародон. У кентавров в плену томится Мелицца Жужжалит.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Фералас: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Лагерь Мохаче",
			short = "Лагерь Мохаче стоит там, где быстрый ручей впадает в Штормовое озеро.",
			full = "Лагерь Мохаче стоит там, где быстрый ручей впадает в Штормовое озеро. Таурены, что держат эту землю, славятся толстой шкурой и отвагой своих воинов, которые охраняют путников от опасностей Фераласа.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Забытый Город",
			short = "Двенадцать тысяч лет назад тайная секта ночных эльфов-чародеев воздвигла Эльдре'Талас, чтобы хранить самые драгоценные магические тайны королевы Азшары.",
			full = "Двенадцать тысяч лет назад тайная секта ночных эльфов-чародеев воздвигла Эльдре'Талас, чтобы хранить самые драгоценные магические тайны королевы Азшары. Среди высокорожденных этого города в тихом великолепии жили волшебники, известные как Шен'дралар, и одна из них, Миллисента Безмятежная, создала Плод Изобилия — лозу, чья аура роста и защиты позволила процветать всему городу.\n\nОтрезанные от Источника Вечности после Великого Раскола, высокорожденные сковали демона Бессмер'тера и черпали силу из его заточения. Этой силы им хватало на тысячи лет, пока цена удержания демона не превысила того, что он давал. Их предводитель, принц Тортелдрин, ответил на это тем, что обратился против собственного народа и перебил многих, чтобы высвободить достаточно силы и сохранить жизнь остальным. Выжившие укрылись в глубине руин, которыми некогда правили, оставив прочие части города всякому, кто придет туда жить.\n\nКамни Эльдре'Таласа стоят до сих пор, и в них заключена магическая энергия, связанная искусством, которого ныне никто не помнит. Они хранят облик города, который ради выживания пожирал собственный народ.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Сонные Ветви",
			short = "Посреди Нефритового озера на маленьком острове высится огромное дерево, в корнях и ветвях которого скрыт один из порталов в Изумрудный Сон.",
			full = "Посреди Нефритового озера на маленьком острове высится огромное дерево, в корнях и ветвях которого скрыт один из порталов в Изумрудный Сон. Зеленые драконы несут здесь дозор, охраняя порог от всякого, кто вздумает вмешаться в Сон.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Крепость Оперенной Луны",
			short = "У западного побережья Фераласа, на острове Сардор, посреди моря стоит крепость, возведенная генералом Шандрисой Оперенной Луной, которая уже десять тысяч лет остается правой рукой Тиранды Шелест Ветра среди Часовых.",
			full = "У западного побережья Фераласа, на острове Сардор, посреди моря стоит крепость, возведенная генералом Шандрисой Оперенной Луной, которая уже десять тысяч лет остается правой рукой Тиранды Шелест Ветра среди Часовых. Шандриса дала крепости свое имя, и та по-прежнему держит этот участок побережья Калимдора для ночных эльфов.\n\nС большой землей ее связывает лишь море: от Забытого берега к причалу на острове ходит лодка.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
