			short = "В Высокогорных дебрях на западе Фераласа лежит Долина Свирепого Утеса, занятая йети Свирепого Утеса, которые и дали ей имя.",
			full = "В Высокогорных дебрях на западе Фераласа лежит Долина Свирепого Утеса, занятая йети Свирепого Утеса, которые и дали ей имя.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "Забытый берег",
			short = "Забытый берег тянется вдоль всей западной окраины Фераласа, там, где суша встречается с Сокрытым Морем. Здесь из прибоя поднимаются элементали воды, а по берегу бродят морские великаны.",
			full = "Забытый берег тянется вдоль всей западной окраины Фераласа, там, где суша встречается с Сокрытым Морем. Здесь из прибоя поднимаются элементали воды, а по берегу бродят морские великаны.\n\nНа этом берегу ютится рыбацкая деревушка мурлоков. Бывало, что птицы налетали и уносили головастиков, а на деревню по очереди совершали набеги то люди, то гноллы. Но хуже всех огры Гордунни, которые годами охотятся на мурлоков и уводят их в плен в руины Забытого Города. Так были похищены уже больше дюжины мурлоков, среди них двое по имени Муррл и Мурргли.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Высокогорье Блеклых Перьев",
			short = "Высокогорье Блеклых Перьев принадлежит блеклоперым гиппогрифам, которые гнездятся здесь на высотах и дали этой земле имя.",
			full = "Высокогорье Блеклых Перьев принадлежит блеклоперым гиппогрифам, которые гнездятся здесь на высотах и дали этой земле имя. Среди скал в разбросанных гнездах спрятаны их яйца, и охраняют их кружащие в небе стаи, для которых высокогорье стало домом.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Поселение Гордунни",
			short = "В горах к северу от Павильона Лорисс земля несет на себе печать Гордунни. Тогда как повсюду в Фераласе царит зелень, поселение огров лежит иссохшим и бурым.",
			full = "В горах к северу от Павильона Лорисс земля несет на себе печать Гордунни. Тогда как повсюду в Фераласе царит зелень, поселение огров лежит иссохшим и бурым.\n\nХолмы отмечены двумя пещерами — маленькой у входа и огромным курганом в глубине, — и обе удерживают огры Гордунни, заявившие права на эту оскверненную землю.",
