		["isle of dread"] = {
			name = "Остров Ужаса",
			short = "Остров Ужаса лежит у побережья Фераласа, к югу от острова Сардор. Его центральную долину со всех сторон окружают неприступные скалы, и лишь на юго-востоке есть единственный проход.",
			full = "Остров Ужаса лежит у побережья Фераласа, к югу от острова Сардор. Его центральную долину со всех сторон окружают неприступные скалы, и лишь на юго-востоке есть единственный проход. В этой скрытой котловине обитают химеры — и тронутые магией звери, и пожиратели, — а правит ими лорд Лакмерен. Его плоть искали для целей куда более странных, чем пропитание: вытопленная и переделанная, она превратилась в чудовищную пятисотфунтовую птицу, которую целиком съел гном-волшебник Нарайн Причудень.\n\nВ северной части острова в скалу уходит пещера, не похожая ни на что иное в этих краях, — глубокая и странная по своему устройству. Тайный подводный ход ведет во внутренний зал, у которого, насколько известно, нет иного назначения, кроме как укрывать в своих глубинах леди Шаллах. Пещерой и ее нагами повелевает лорд Шалзару, чье присутствие привлекло внимание Крепости Оперенной Луны, настороженно следящей за нагами у самых своих берегов.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Нефритовое озеро",
			short = "Посреди Нефритового озера на севере Фераласа лежит маленький остров Сонные Ветви. Там находится портал в Изумрудный Сон, который охраняют Летлас и несколько зеленых драконидов.",
			full = "Посреди Нефритового озера на севере Фераласа лежит маленький остров Сонные Ветви. Там находится портал в Изумрудный Сон, который охраняют Летлас и несколько зеленых драконидов. Вдоль северо-западного берега озера бродят зараженные зеленые дракончики.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Павильон Лорисс",
			short = "Павильон Лорисс, сложенный из камня в духе ночных эльфов, стоит к северу от Лагеря Мохаче в Фераласе. Некогда здешние дриады были миролюбивы, но Изумрудный Кошмар осквернил их, и теперь они нападают на всякого, кто приблизится.",
			full = "Павильон Лорисс, сложенный из камня в духе ночных эльфов, стоит к северу от Лагеря Мохаче в Фераласе. Некогда здешние дриады были миролюбивы, но Изумрудный Кошмар осквернил их, и теперь они нападают на всякого, кто приблизится.\n\nПод Павильоном скрыт потайной спуск, известный Аж'Тордину — высокорожденному, который порвал с принцем Тортелдрином и бежал этим путем из Забытого Города. Бежал он почти ни с чем: бес по имени Пузиллин украл его книгу заклинаний прежде, чем он успел скрыться внизу, и с тех пор Аж'Тордин не покидает этого прохода.",
