		},
		["twin colossals"] = {
			name = "Два Колосса",
			short = "Два Колосса высятся на западной окраине Фераласа. Эти отвесные горы так высоки, что являются самой высокой точкой края, а дорога в Пустоши проходит через ущелье между ними.",
