		["wildwind lake"] = {
			name = "Штормовое озеро",
			short = "Штормовое озеро лежит неподалеку от Лагеря Мохаче в Фераласе. Его воды спокойны среди окружающих дебрей, и нет в нем ничего примечательного, кроме того, что плавает под его поверхностью, да тишины, что висит над соседним лагерем.",
			full = "Штормовое озеро лежит неподалеку от Лагеря Мохаче в Фераласе. Его воды спокойны среди окружающих дебрей, и нет в нем ничего примечательного, кроме того, что плавает под его поверхностью, да тишины, что висит над соседним лагерем.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Логово Древолапов",
			short = "В самом сердце Фераласа находится Логово Древолапов — нора гноллов из стаи Древолапов. Здесь вожаки Древолапов властвуют над сородичами, которых так много, что мало кто из чужаков решится испытать их силу.",
			full = "В самом сердце Фераласа находится Логово Древолапов — нора гноллов из стаи Древолапов. Здесь вожаки Древолапов властвуют над сородичами, которых так много, что мало кто из чужаков решится испытать их силу. К югу от логова стоят Руины Темной Мглы — безмолвные соседи шумных гноллов.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Холмы Древолапов",
			short = "Холмы Древолапов покрыты густым лесом, и живут здесь гноллы из стаи Древолапов.",
			full = "Холмы Древолапов покрыты густым лесом, и живут здесь гноллы из стаи Древолапов. Однако их власть над этой землей слабеет: на крайнем юго-востоке земля разверзлась, образовав то, что теперь зовется Гудящей Бездной, и кишащие твари, вырвавшиеся из-под земли, вытесняют гноллов с их собственной территории. Если прежде вожаки Древолапов водили свое племя из многих стоянок, то теперь они держатся лишь в Логове Древолапов.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Гудящая Бездна",
			short = "Гудящая Бездна на юго-востоке Фераласа отдана во власть улья Зукк'аш. Обитающие там силитиды отравили окрестную землю, и соседние гноллы, обезумев, двинулись на север, против Лагеря Мохаче.",
			full = "Гудящая Бездна на юго-востоке Фераласа отдана во власть улья Зукк'аш. Обитающие там силитиды отравили окрестную землю, и соседние гноллы, обезумев, двинулись на север, против Лагеря Мохаче.\n\nВоины из лагеря перебили силитидов на поверхности, но сердце улья под землей, полное яиц, так никто и не тронул. Рексар предупреждает, что вылупление следующего поколения — лишь вопрос времени.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Пылевые топи: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Остров Алькац",
			short = "Остров Алькац поднимается из моря у Пылевых топей. Он покрыт густой тропической зеленью, которой вроде бы нечего делать так близко от серой болотной грязи, словно некая древняя, более теплая сила когда-то завладела этой землей и так и не отпустила ее.",
			full = "Остров Алькац поднимается из моря у Пылевых топей. Он покрыт густой тропической зеленью, которой вроде бы нечего делать так близко от серой болотной грязи, словно некая древняя, более теплая сила когда-то завладела этой землей и так и не отпустила ее. Островом владеют наги клана Страшаз: мирмидоны и сирены теснятся вдоль его берегов.\n\nОднако во время войны с Ан'Киражем на остров прилетел на летательной машине доктор Жло. Он обосновался со своими прислужниками на вершине холма и превратил часть побережья в мастерскую технических изобретений.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Место крушения Бизиля",
			short = "Гоблинский дирижабль, летевший на юг с грузом припасов, рухнул в самой глуши Пылевых топей, к востоку от фермы Табеты.",
			full = "Гоблинский дирижабль, летевший на юг с грузом припасов, рухнул в самой глуши Пылевых топей, к востоку от фермы Табеты. Его разбитый корпус лежит в грязи, груз разбросан среди обломков, а сефориевые ускорители так и валяются там, где упали.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Логово Кровавой Топи",
			short = "В пещере на юго-западе Пылевых топей укрывается необычайно много ящеров Кровавой Топи. У входа лежат остатки какого-то поселения, разорванного этими тварями, а его жители сгинули в болотной грязи.",
			full = "В пещере на юго-западе Пылевых топей укрывается необычайно много ящеров Кровавой Топи. У входа лежат остатки какого-то поселения, разорванного этими тварями, а его жители сгинули в болотной грязи. Где-то внутри, среди обломков, ждет своего часа одна из частей Загадки Кортелло.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Синяя топь",
			short = "Синяя топь лежит на севере Пылевых топей. Ее низины густо заросли камышом и полны стоячей воды.",
			full = "Синяя топь лежит на севере Пылевых топей. Ее низины густо заросли камышом и полны стоячей воды. Пауки, кроколиски, ящеры и болотные птицы свободно бродят по трясине, а лазутчики Терамора незаметно пробираются сквозь камыши.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Деревня Гиблотопь",
			short = "Деревня Гиблотопь — скопление хижин и огрских курганов на северо-западе Пылевых топей. Здесь живут огры Каменного Молота, присягнувшие Орде.",
			full = "Деревня Гиблотопь — скопление хижин и огрских курганов на северо-западе Пылевых топей. Здесь живут огры Каменного Молота, присягнувшие Орде. Их домом она была не всегда. Прежде Каменный Молот жил в деревне южнее, пока на нее не обрушились черные драконы и не сожгли ее дотла. Верховный вождь Мок'Морокк, принявший власть после Рексара, увел выживших на север и возвел Гиблотопь на новом месте.\n\nВласть Мок'Морокка держалась на том, чтобы никуда не двигаться. Когда огр Драз'Зилб выяснил, что нападавшими были выводок Ониксии, и открыл ему правду, Мок'Морокк не пожелал ничего предпринимать. Гиблотопь была в безопасности, черные драконы здесь не жили, и ему этого было довольно. Драз'Зилб не собирается оставлять это дело и втихомолку прикидывает, что понадобится, чтобы свергнуть верховного вождя и вернуть Каменному Молоту утраченное.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Мглистая пещера",
			short = "На северо-западе Пылевых топей есть небольшой рудник, давно отданный во власть пауков, выросших во тьме до устрашающих размеров.",
			full = "На северо-западе Пылевых топей есть небольшой рудник, давно отданный во власть пауков, выросших во тьме до устрашающих размеров. Жители болот называют их пауками Мглистой пещеры, а саму пещеру — Мглистой, хотя никто не скажет, какое имя появилось первым: у места или у тварей, что его заняли.\n\nУ входа в рудник стоят развалины маленьких домов, наполовину ушедших в сырую землю, — все, что осталось от давно забытого поселения.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Огненное логово",
			short = "Огненное логово было возведено ограми Каменного Молота как их курган, и его каменная кладка до сих пор хранит следы их мастерства. Оно лежит к западу от руин Деревни Каменного Молота, на болотах, захваченных Ониксией.",
			full = "Огненное логово было возведено ограми Каменного Молота как их курган, и его каменная кладка до сих пор хранит следы их мастерства. Оно лежит к западу от руин Деревни Каменного Молота, на болотах, захваченных Ониксией.\n\nОгров здесь больше нет. Логово заполонили черные драконоиды, превратив его в гнездо черных драконов. Лишь старая кладка да знамя Каменного Молота, оставшееся внутри, напоминают о первых строителях.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "Земля Драконов",
			short = "На юге Пылевых топей лежит зловонная полоса земли, называемая Землей Драконов, где кишат дракончики и дракониды черной стаи.",
			full = "На юге Пылевых топей лежит зловонная полоса земли, называемая Землей Драконов, где кишат дракончики и дракониды черной стаи. Поблизости находятся Огненное логово и Руины Деревни Каменного Молота, также заполоненные черными драконидами.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Зловещий берег",
			short = "Берег между островом Терамор и Крепостью Северной Стражи кишит мурлоками из племени Болотного Плавника, которые считают побережье и разбросанные вдоль него островки своими.",
			full = "Берег между островом Терамор и Крепостью Северной Стражи кишит мурлоками из племени Болотного Плавника, которые считают побережье и разбросанные вдоль него островки своими. Эти воды они делят с морскими черепахами и другими созданиями.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
