		["dustwallow bay"] = {
			name = "Пылевая бухта",
			short = "Пылевая бухта — часть Великого моря, вдающаяся в восточный берег Пылевых топей к западу от острова Терамор.",
			full = "Пылевая бухта — часть Великого моря, вдающаяся в восточный берег Пылевых топей к западу от острова Терамор. На маленьком острове у бухты, в Заливе Яростных Волн, рыбак Нат Пэгл в одиночестве несет свою вахту над водой.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Логово Огнебора",
			short = "Широкая пещера открывается в зловонные Драконьи топи. Здесь живет черный дракон Огнебор.",
			full = "Широкая пещера открывается в зловонные Драконьи топи. Здесь живет черный дракон Огнебор. Он испытывает юных черных дракончиков на выносливость и жестокость, ведь лишь те, кто докажет, что достоин, смогут войти в Логово Ониксии.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Цитадель",
			short = "Цитадель стоит в самом сердце острова Терамор. Это штаб тераморской стражи.",
			full = "Цитадель стоит в самом сердце острова Терамор. Это штаб тераморской стражи.\n\nИменно здесь нашел свою смерть Даэлин Праудмур, когда войска Тралла штурмовали Терамор, а Рексар и его спутники провели их в крепость. В этих стенах пал адмирал, отвергший мир с орками, который заключила его дочь Джайна.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Разрушенная башня",
			short = "Разрушенная башня — обветшалая дозорная башня, которую Терамор когда-то возвел на западе Пылевых топей, — больше не служит своим строителям.",
			full = "Разрушенная башня — обветшалая дозорная башня, которую Терамор когда-то возвел на западе Пылевых топей, — больше не служит своим строителям. Теперь ее занимают тераморские дезертиры во главе с Балосом Хакеном, которому известно о причастности рядового Хендела к похищению очень важной особы.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "Северная башня",
			short = "Северная башня стоит на страже севера Пылевых топей у оживленной дороги. Ее удерживает немалый отряд тераморских стражников.",
			full = "Северная башня стоит на страже севера Пылевых топей у оживленной дороги. Ее удерживает немалый отряд тераморских стражников. С тех пор как дезертиры захватили Разрушенную башню, эта башня стала самой дальней заставой Терамора.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Логово Ониксии",
			short = "Вход в логово Ониксии похож на разверстую пасть самой Матери драконов. Дальше путь окаймлен магмой, а земля растрескалась и светится огнем, идущим из глубин.",
			full = "Вход в логово Ониксии похож на разверстую пасть самой Матери драконов. Дальше путь окаймлен магмой, а земля растрескалась и светится огнем, идущим из глубин. Каменный свод над головой стонет и движется, то и дело обрушивая камнепады, а стены сочатся лавой там, где жар невозможно сдержать. Ониксия сама вырыла это место глубоко под Землей Драконов — унылой топью в Пылевых топях.\n\nОна не похожа на своих сородичей. Если ее отец правит грубой силой, а брат создает уродливых чудовищ, чтобы те исполняли его волю, то Ониксия действует шепотом и обаянием: она наслаждается запутанной политикой смертных и тихо подчиняет ее своим целям. Какое-то время она носила чужое имя, называя себя Катраной Престор, и под этой личиной проникла в самое сердце двора Штормграда, стремясь разрушить его изнутри. Именно маршал Винздор разглядел, что скрывается под маской, и назвал ее истинное имя. Разоблаченная, она бежала из города и вернулась в свой огненный чертог под болотами, где пребывает и поныне под охраной своих сородичей — черных драконов.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "Трясина",
			short = "Трясина — это насквозь промокшее сердце Пылевых топей. Она лежит между Разрушенной башней и Пылевой бухтой, зажатая между Деревней Гиблотопь на севере и Землей Драконов на юге.",
			full = "Трясина — это насквозь промокшее сердце Пылевых топей. Она лежит между Разрушенной башней и Пылевой бухтой, зажатая между Деревней Гиблотопь на севере и Землей Драконов на юге.\n\nВ ее черной воде таятся кроколиски, по камышам ползают слизни и пауки, а таурены Зловещего Тотема удерживают здесь землю вдали от любых сородичей, которые могли бы признать их своими. Эти места лучше пересечь поскорее, чем задерживаться в них.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Сторожевой пост",
			short = "Сторожевой пост стоит сразу за мостом от Терамора. Эту дозорную башню построили в цитадели, чтобы следить за дорогой внизу. Она стоит нерушимо и несет безмолвную стражу над всеми, кто направляется в город.",
			full = "Сторожевой пост стоит сразу за мостом от Терамора. Эту дозорную башню построили в цитадели, чтобы следить за дорогой внизу. Она стоит нерушимо и несет безмолвную стражу над всеми, кто направляется в город.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Таверна \"Последний привал\"",
			short = "Таверна «Последний привал» когда-то стояла у границы Пылевых топей и Южных степей — придорожный постоялый двор, построенный людьми.",
			full = "Таверна «Последний привал» когда-то стояла у границы Пылевых топей и Южных степей — придорожный постоялый двор, построенный людьми.\n\nОна сгорела дотла без всякого предупреждения. Двое могли бы назвать виновных, Павал Рит и лейтенант Келдвелл, но оба были убиты прежде, чем кто-то из них успел сказать правду, и тайна пожара так и осталась нераскрытой.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Руины Деревни Каменного Молота",
			short = "Некогда в Пылевых топях стояла Деревня Каменного Молота, где жили огры клана Каменного Молота, пока полководец Кор'галл, завладев древним орочьим топором Сератилом, не подчинил себе клан и не стал править им жестокостью.",
			full = "Некогда в Пылевых топях стояла Деревня Каменного Молота, где жили огры клана Каменного Молота, пока полководец Кор'галл, завладев древним орочьим топором Сератилом, не подчинил себе клан и не стал править им жестокостью. Именно сюда пришел Рексар, и когда ему отказали во входе, он проложил себе путь силой. Кор'галл предложил ему место в клане, если тот выживет в Испытании — долине, полной смертоносных зверей. Рексар выдержал его, вернулся и стал одним из Каменного Молота. Когда Кор'галл отказался отдать клан в помощь Орде в войне против Кул Тираса, Рексар бросил ему вызов за право вести клан, убил его и сам повел Каменный Молот на войну. После этого он назначил Мок'Морокка править вместо себя и ушел.\n\nМок'Морокк правил иначе, чем Рексар. Он не служил своему народу, а обирал его, и когда выводок Ониксии обрушился на деревню и захватил ее, он увел выживших в безопасное место и довольствовался тем, чтобы оставаться там, вдали от драконов, вместо того чтобы сражаться за возвращение старого дома.\n\nТеперь руины стоят посреди Земли Драконов, и в них кишат дракониды Огненной Гривы.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Сторожка \"Болотный огонек\"",
			short = "Сторожка «Болотный огонек» — скромный дом на Ведьмином холме в Пылевых топях, где живет повар Ярл «Болотный Глаз».",
			full = "Сторожка «Болотный огонек» — скромный дом на Ведьмином холме в Пылевых топях, где живет повар Ярл «Болотный Глаз».\n\nВ саду перед домом куча перекопанной земли скрывает то, чего стряпня Ярла никак не объясняет: донесение, зарытое орочьим шпионом и спрятанное под землей, чтобы хранить свою тайну от любопытных глаз.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Остров Терамор",
			short = "После Третьей войны Джайна Праудмур привела уцелевших жителей Лордерона через море в Калимдор.",
			full = "После Третьей войны Джайна Праудмур привела уцелевших жителей Лордерона через море в Калимдор. На скалистом острове у Пылевых топей они возвели Терамор — город, обнесенный стенами, который должен был укрыть то, что осталось от Альянса, в чужой земле.\n\nГород окружает прямоугольная стена, усеянная пушечными башнями. Прерывается она лишь у гавани, которую вместо нее охраняют две дозорные башни. В сердце города возвышается Башня Джайны, Цитадель, — самое высокое здание Терамора. Ее многочисленные этажи с деревянными полами соединены винтовыми лестницами и защищены от нападения, а в ней находятся личные покои Джайны, ее библиотека и небольшой тронный зал города. Рядом стоит Цитадель стражи, казармы, где солдаты упражняются на тренировочных манекенах, а новобранцы сходятся в учебных поединках под присмотром жрецов, готовых воззвать к Свету, едва кто-нибудь получит рану.\n\nБолота дают скудную почву и плохую древесину, и тераморские моряки ворчат, что дубы, которые орки рубят выше Оргриммара, куда лучше всего, что может предложить Пылевая топь. И все же люди и орки обменивают рыбу на излишки дуротарского урожая, и пока в городе мало преступлений, а его жители по большей части живут в мире.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Залив Яростных Волн",
			short = "Залив Яростных Волн лежит в оконечности Пылевой бухты, к югу от острова Терамор. Его воды усеяны островками и скрытыми рифами. Плавать здесь опасно.",
			full = "Залив Яростных Волн лежит в оконечности Пылевой бухты, к югу от острова Терамор. Его воды усеяны островками и скрытыми рифами. Плавать здесь опасно. На его отмелях лежат два разбитых корабля, которые теперь облюбовали бродячие макруры.\n\nСреди островков находится Пристань Ната, где живет рыбак Нат Пэгл.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Ведьмин холм",
			short = "В центре Ведьминого холма стоит сторожка «Болотный огонек», дом Ярла «Болотный Глаз». Неподалеку, в трясине, разбили свои стоянки мурлоки из племени Болотного Плавника.",
			full = "В центре Ведьминого холма стоит сторожка «Болотный огонек», дом Ярла «Болотный Глаз». Неподалеку, в трясине, разбили свои стоянки мурлоки из племени Болотного Плавника.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Драконьи топи",
			short = "К югу от Земли Драконов в Пылевых топях трясина сгущается, превращаясь в Драконьи топи.",
			full = "К югу от Земли Драконов в Пылевых топях трясина сгущается, превращаясь в Драконьи топи. Здесь обитают черные драконы, а земля раскрывается в два потаенных места: вход в Логово Огнебора и логово самой Ониксии.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Танарис: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Безбрежные Пески",
			short = "Здешние пески лежат в Танарисе — пустыне, что простирается во все стороны.",
