		["broken pillar"] = {
			name = "Разбитая Колонна",
			short = "К югу от Прибамбасска, близ Безбрежных Песков, теснятся небольшие руины троллей, известные как Разбитая Колонна.",
			full = "К югу от Прибамбасска, близ Безбрежных Песков, теснятся небольшие руины троллей, известные как Разбитая Колонна. Здесь разбил свой лагерь гоблин-ученый Марвон Клепальщик, который ищет среди упавших камней ответы на собственные вопросы.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Пещеры Времени",
			short = "Пещеры Времени лежат под восточными песками Танариса — извилистый лабиринт, закрытый от мира наверху. Здесь бронзовые драконы несут дозор над ветвящимися тропами самого времени.",
			full = "Пещеры Времени лежат под восточными песками Танариса — извилистый лабиринт, закрытый от мира наверху. Здесь бронзовые драконы несут дозор над ветвящимися тропами самого времени. С тех пор как мир был юн, это их священный долг, возложенный на них титанами: охранять пещеры от вторжения смертных, ибо вмешательство низших существ может расплести ход истории. В самом сердце пещер стоят огромные песочные часы.\n\nЗдесь, среди своей стаи, обитает Ноздорму, Аспект Времени, который предается личному увлечению — собирает редкие артефакты. После Второй войны маг Крас проник в логово Ноздорму с помощью Розы Эонов — устройства, позволявшего в одно мгновение преодолеть любое расстояние. Ноздорму остался недоволен вторжением, ведь оно потревожило его посреди собирательских трудов, и не преминул выразить свое недовольство.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
