		["eastmoon ruins"] = {
			name = "Руины Восточной Луны",
			short = "Каменные террасы и растрескавшиеся колонны отмечают Руины Восточной Луны к западу от Зияющей бездны в Танарисе — все, что осталось от давно покинутого поселения троллей.",
			full = "Каменные террасы и растрескавшиеся колонны отмечают Руины Восточной Луны к западу от Зияющей бездны в Танарисе — все, что осталось от давно покинутого поселения троллей. После троллей осыпающиеся каменные постройки заняли огры Песчаного Молота, и они удерживают их до сих пор.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Прибамбасск",
			short = "Прибамбасск поднимается над северной пустыней Танариса под вечной пеленой черного дыма. Это столица картеля Хитрая Шестеренка, величайшего из гоблинских картелей.",
			full = "Прибамбасск поднимается над северной пустыней Танариса под вечной пеленой черного дыма. Это столица картеля Хитрая Шестеренка, величайшего из гоблинских картелей. Здесь всем правит гоблинский закон: выгода превыше верности. И Орда, и Альянс официально признают город нейтральной территорией, а по его улицам ходят гоблины-громилы, готовые превратить в лепешку любого глупца, который вздумает принести войну в место, построенное на торговле. Кому здесь рады, решают кошельки, а не знамена.\n\nТакой нейтралитет по душе далеко не всем. Разбойники-Скитальцы Пустыни захватили Руины Полуденной Тени и Родниковое поле на северо-востоке. Старые руины гоблинов нисколько не заботили, но с Родниковым полем дело обстояло иначе: водонапорные башни, которые Водная компания Прибамбасска возвела и обслуживала там под палящим пустынным солнцем, были жидким золотом, питавшим жизнь города. Гоблины вовсе не собирались уступать башни, в которые вложили столько пота, и потому наемники со всех концов света были втянуты в защиту воды Прибамбасска от разбойников, мечтавших увидеть его падение.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Зияющая бездна",
			short = "Зияющая бездна кишит силитидами Хаззали, чьи ульи пронизывают скалы на юго-востоке Танариса.",
			full = "Зияющая бездна кишит силитидами Хаззали, чьи ульи пронизывают скалы на юго-востоке Танариса.\n\nОднажды старший геодезист Рудознатец отправил своего помощника, младшего геодезиста Холстомера, в бездну на разведку. Холстомер так и не вернулся. Он погиб среди ульев, и позже удалось найти лишь его снаряжение, которое принесли Рудознатцу, — а тот так и не узнал, что сам послал его на смерть.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Пляж на Краю Света",
			short = "Пляж на Краю Света лежит в самой южной точке Танариса, там, где юго-восточный угол Калимдора встречается с морем. Берег здесь тих, и примечателен он главным образом бродящими по нему созданиями.",
			full = "Пляж на Краю Света лежит в самой южной точке Танариса, там, где юго-восточный угол Калимдора встречается с морем. Берег здесь тих, и примечателен он главным образом бродящими по нему созданиями. Прибойные скаты и крабы песчаного берега спокойно пробираются вдоль восточной полосы песка, и никто их не тревожит.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
