			full = "Руины Полуденной Тени лежат к востоку от Прибамбасска — выветренные камни, оставленные давно исчезнувшими троллями. Чему когда-то служили эти руины и что стало с их строителями, пески пустыни уже не расскажут.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Ядовитый улей",
			short = "На юго-западе Танариса в песке зияет рана там, где некогда стояла вода. Прежде чем сюда пришли силитиды, эту землю покрывало нечто широкое и мелкое — река или озеро, — и все, что нашел здесь рой Сентипаар, он осушил.",
			full = "На юго-западе Танариса в песке зияет рана там, где некогда стояла вода. Прежде чем сюда пришли силитиды, эту землю покрывало нечто широкое и мелкое — река или озеро, — и все, что нашел здесь рой Сентипаар, он осушил. Из-за этого запад Танариса остался без воды.\n\nПоверхность до сих пор хранит очертания утраченного. Земля проседает, впалая и изрытая, и смотрит на кратер Ун'Горо, словно помнит, что когда-то была берегом. То тут, то там из песка торчат огромные клешни, подергиваясь, будто погребенные твари застыли на середине удара. Вокруг каждой клешни почва черна и влажна от силитидской слизи — единственной влаги, что осталась там, где некогда было озеро.\n\nПод поверхностью Ядовитый улей ничем не отличается от других ульев, вырытых Сентипаар в Танарисе: влажный, теплый, жутковатый в своей неподвижности, с туннелями, покрытыми силитидской кислотой.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Застава Скорбных Песков",
			short = "Застава Скорбных Песков раскинулась к западу от Прибамбасска в сухой котловине Танариса. Ее удерживают тролли Фарраки и зомби, которых они подняли из собственных мертвецов.",
			full = "Застава Скорбных Песков раскинулась к западу от Прибамбасска в сухой котловине Танариса. Ее удерживают тролли Фарраки и зомби, которых они подняли из собственных мертвецов.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "Южные моря",
			short = "Воды к югу от известных континентов открываются в широкие просторы Великого моря, и течения несут их мимо островов, чьи имена знакомы в основном морякам.",
			full = "Воды к югу от известных континентов открываются в широкие просторы Великого моря, и течения несут их мимо островов, чьи имена знакомы в основном морякам. Из этих вод поднимается Зандалар, древняя родина империи троллей. Среди них лежит и Кезан — вулканический остров, чей народ держится в стороне от держав большой земли.\n\nБлиже к Тернистой долине море становится коварным из-за рифов и скрытых бухт — в таких водах капитан либо знает каждый камень по имени, либо теряет корабль. Эту полосу моря усеивают маленькие острова: одни не больше песчаной отмели, на других стоят руины, строители которых давно сгинули под волнами.\n\nЭто море стоит того, чтобы дать ему имя, не столько из-за какой-то одной битвы, разыгравшейся на нем, сколько из-за того, что оно поглотило и вновь наполовину явило миру: затонувшие храмы, утонувшие берега, руины, мелькающие сквозь прозрачную воду во время отлива. Это море окраин и межземелий, что тянется вдоль границ Тернистой долины, Танариса и Ульдума и несет к разделяемым им берегам все, что вздумается принести приливам.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Берег за Южной грядой",
			short = "Берег за Южной грядой тихо тянется вдоль южной окраины Танариса — плоская полоса пляжа, почти лишенная жизни. В прибое бродят черепахи и морские великаны.",
			full = "Берег за Южной грядой тихо тянется вдоль южной окраины Танариса — плоская полоса пляжа, почти лишенная жизни. В прибое бродят черепахи и морские великаны.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Руины Южной Луны",
