		["uldum"] = {
			name = "Ульдум",
			short = "Ульдум лежит на южном побережье Калимдора, огражденный кратером Ун'Горо с севера, Танарисом с востока и Силитусом с северо-запада.",
			full = "Ульдум лежит на южном побережье Калимдора, огражденный кратером Ун'Горо с севера, Танарисом с востока и Силитусом с северо-запада. Это место богато преданиями о титанах, а его горные перевалы окутаны завесой, чтобы ни один смертный глаз не отыскал путь внутрь.",
