		["waterspring field"] = {
			name = "Родниковое поле",
			short = "Родниковое поле получило свое имя от водонапорных башен, что поднимаются по всей его площади и выкачивают воду из запасов глубоко под землей.",
			full = "Родниковое поле получило свое имя от водонапорных башен, что поднимаются по всей его площади и выкачивают воду из запасов глубоко под землей. Их построили гоблины Прибамбасска, желая обеспечить водой свои предприятия в пустыне Танариса.\n\nЭтот замысел не пережил встречи со Скитальцами Пустыни. Кочевые разбойники нагрянули на поле и попросту забрали его, захватив башни и нимало не заботясь о гоблинах, которые их возвели. Они и сейчас сидят там, вполне довольные этой землей после того, от чего бежали прежде: о лагере огров, что был у них раньше, они говорить не любят и лишь твердят, что здесь лучше.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
