		["zalashjis den"] = {
			name = "Логово Залашьи",
			short = "Логово Залашьи до сих пор носит имя того, кто когда-то здесь обитал. Ни одно из уцелевших преданий не говорит, кем был Залашьи и что потом стало с этим местом.",
			full = "Логово Залашьи до сих пор носит имя того, кто когда-то здесь обитал. Ни одно из уцелевших преданий не говорит, кем был Залашьи и что потом стало с этим местом. Жив ли еще Залашьи, умер ли здесь или где-то в другом месте — никто не может сказать наверняка.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Зул'Фаррак",
			short = "Некогда Зул'Фаррак был городом в джунглях — в те времена, когда Танарис еще покрывали леса империи Гурубаши.",
			full = "Некогда Зул'Фаррак был городом в джунглях — в те времена, когда Танарис еще покрывали леса империи Гурубаши. Когда Великий Раскол разорвал древний мир на части, джунгли выгорели и обратились в пустыню, а тролли Фарраки, построившие здесь свой город, оказались посреди песков. Они выстояли и закалились, превратившись в Песчаную Бурю — племя, известное даже среди троллей своей безжалостностью и темной магией.\n\nВ стенах этого опаленного солнцем города тролли слагают легенды о Каре Суль-траза — клинке, который, как говорят, вселял страх и слабость в любого врага, которого касался. Давным-давно меч раскололся надвое, и шепчутся, что обе половины до сих пор лежат где-то в городе, затерянные среди его дворов и храмов.\n\nВ самом сердце Зул'Фаррака находится священный пруд, и говорят, что под его неподвижной водой Песчаная Буря держит в спячке нечто куда более древнее, чем они сами, — полубога, пробуждение которого обрушит гибель на город и всех, кто в нем обитает.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
