		["jagged reef"] = {
			name = "Острые рифы",
			short = "Острые рифы — это северное побережье Азшары, песчаный пляж, вновь и вновь прерываемый каменными выступами и небольшими морскими заливчиками. Под водой скрываются камни и отмели, и путь вдоль берега опасен.",
			full = "Острые рифы — это северное побережье Азшары, песчаный пляж, вновь и вновь прерываемый каменными выступами и небольшими морскими заливчиками. Под водой скрываются камни и отмели, и путь вдоль берега опасен. Это побережье удерживают мурлоки, гидры и макруры, которые плавают на мелководье или бредут по песку в поисках пищи.",
