		["ravencrest monument"] = {
			name = "Памятник Черному Ворону",
			short = "На утесах южной оконечности Азшары лежат останки колосса, хотя от него осталось слишком мало, чтобы оправдать это слово.",
			full = "На утесах южной оконечности Азшары лежат останки колосса, хотя от него осталось слишком мало, чтобы оправдать это слово. Стоят лишь разбитые ноги, возвышающиеся над морем, а остальная часть огромной фигуры разбросана по камням вокруг или соскользнула в волны внизу.\n\nТеперь руинами владеют наги из клана Бича Злобы. С воды сюда не добраться: всякий, кто ищет это место, должен прийти по суше и пересечь мост, ведущий мимо Руин Эльдарата, чтобы встать под опрокинутыми ногами того, что когда-то, несомненно, являло собой впечатляющее зрелище.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Святилище Ретресса",
			short = "Святилище Ретресса стоит разрушенным на Опустошенном берегу, к юго-западу от Памятника Черному Ворону. Теперь его никто не охраняет. Среди упавших камней бродят лишь мурлоки и макруры — единственные, кто вообще сюда приходит.",
			full = "Святилище Ретресса стоит разрушенным на Опустошенном берегу, к юго-западу от Памятника Черному Ворону. Теперь его никто не охраняет. Среди упавших камней бродят лишь мурлоки и макруры — единственные, кто вообще сюда приходит.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Опустошенный берег",
			short = "Южное побережье Азшары не скрывает своего запустения. Утесы и пляжи изрезаны заливами, а вода прячет отмели, погубившие больше кораблей, чем любой моряк возьмется сосчитать.",
			full = "Южное побережье Азшары не скрывает своего запустения. Утесы и пляжи изрезаны заливами, а вода прячет отмели, погубившие больше кораблей, чем любой моряк возьмется сосчитать. Разбитые суда лежат, наполовину занесенные песком, рядом с более древними и странными руинами, строителей которых давно нет. По побережью рыщут мурлоки, гидры и макруры, и даже те, кто знает этот берег, ступают по нему с осторожностью.\n\nНа западном берегу, над пляжем, на холме стоит гномья постройка, к которой ведет лишь крутая тропа с суши. Здесь обосновались и ведут торговлю Блимо и Джуби Пружиножик. Наверху, в их личных покоях, стоит третья кровать. Никто не знает, кому она принадлежит и спит ли в ней кто-нибудь вообще.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Руины Эльдарата",
			short = "До того как мир раскололся, Эльдарат был одной из великих твердынь высокорожденных — городом магической учености, где могущественнейшие маги высекали на камне руны и скрижали и оставляли их в людных местах, чтобы каждый проходящий мог поразмыслить над их прозрениями в тайны магии.",
			full = "До того как мир раскололся, Эльдарат был одной из великих твердынь высокорожденных — городом магической учености, где могущественнейшие маги высекали на камне руны и скрижали и оставляли их в людных местах, чтобы каждый проходящий мог поразмыслить над их прозрениями в тайны магии.\n\nГород пал не без боя. Во время Войны Древних Сопротивление калдорай дало здесь бой Пылающему Легиону. Когда Великий Раскол разорвал мир, Эльдарат не выдержал: большая часть города обрушилась и погрузилась в воды Залива Бурь внизу.\n\nТо, что осталось, цепляется за восточные утесы — разбитое скопление башен, которых давно сторонятся ночные эльфы, некогда называвшие его своим домом. Теперь руинами завладели наги, а полководец Креллиан правит уцелевшим из Храма Зин-Малор. Среди обломков до сих пор стоят рунические скрижали древних высокорожденных, и их магическая мудрость не тронута минувшими веками.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Пещера Чешуеборода",
			short = "Пещера на крошечном островке в Заливе Бурь носит имя Чешуеборода — редкой старой черепахи. Это его дом, хотя отдыхает он здесь нечасто: он предпочитает охотиться далеко в Великом море, оставляя логово пустым.",
			full = "Пещера на крошечном островке в Заливе Бурь носит имя Чешуеборода — редкой старой черепахи. Это его дом, хотя отдыхает он здесь нечасто: он предпочитает охотиться далеко в Великом море, оставляя логово пустым.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Святилище Песни Теней",
			short = "Святилище Песни Теней — усеянный руинами холм на западе Азшары, и никаких ясных свидетельств о том, почему оно носит это имя, не сохранилось.",
			full = "Святилище Песни Теней — усеянный руинами холм на западе Азшары, и никаких ясных свидетельств о том, почему оно носит это имя, не сохранилось. Оно носит то же имя, что и Джарод Песнь Теней, возглавлявший сопротивление в Войне Древних, и его сестра Майев — стражница, которую помнят за то, что она держала в заточении Иллидана Ярость Бури после его предательства у горы Хиджал. Какое отношение кто-либо из них имеет к этому холму, не может сказать никто.\n\nЗато можно сказать, кто бродит там. Среди камней блуждают призраки высокорожденных, жаждущие любого живого существа, что приблизится к ним.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "Разоренное побережье",
			short = "Разоренное побережье тянется вдоль северной стороны Залива Бурь в Азшаре. Здесь полно гидр, морских великанов, макрур и мурлоков, и каждые удерживают собственный участок песка.",
			full = "Разоренное побережье тянется вдоль северной стороны Залива Бурь в Азшаре. Здесь полно гидр, морских великанов, макрур и мурлоков, и каждые удерживают собственный участок песка. Храм Арккоран и Башня Эльдары поднимаются над берегом, несмотря на толчею клешней и щупалец.\n\nЗастолбили участки на этом побережье и гоблины, спекулирующие прибрежной недвижимостью среди зубов и приливов.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Река Строптивая",
			short = "Река Строптивая берет начало высоко на горе Хиджал, вытекая из горного озера водопадом, который с грохотом обрушивается в низины.",
			full = "Река Строптивая берет начало высоко на горе Хиджал, вытекая из горного озера водопадом, который с грохотом обрушивается в низины. Оттуда она течет широко и стремительно, рассекая землю надвое: отмечает место, где Ясеневый лес уступает Азшаре, а южнее — где кончаются Степи и начинается Дуротар. В устье река низвергается последним каскадом в Великое море, чуть к северо-востоку от гоблинского порта Кабестан.\n\nПо всей ее длине через реку перекинуты мосты: один соединяет Азшару с Ясеневым лесом, другой — Дуротар со Степями.\n\nРека по-прежнему питает поля на своих берегах и по-прежнему одевает зеленью землю там, где течет.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
