			short = "Некогда Храм Арккоран был посвящен поклонению Элуне, и его камни возвели на северо-восточном побережье Азшары. От той святости давно не осталось и следа.",
			full = "Некогда Храм Арккоран был посвящен поклонению Элуне, и его камни возвели на северо-восточном побережье Азшары. От той святости давно не осталось и следа. Теперь на его вершине обитает морской великан Арккорос, которого охраняют мурлоки и макруры, набрасывающиеся на всякого, кто приблизится. Окрестное побережье, Разоренное побережье, не сулит более безопасного пути: за ним следят гидры и морские великаны, не менее свирепые, чем сам Арккорос.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Храм Зин-Малор",
			short = "Храм Зин-Малор стоит среди Руин Эльдарата, и его камни сложены по образу соседнего Храма Арккоран и Храма Луны, возведенного позднее в Дарнассе.",
			full = "Храм Зин-Малор стоит среди Руин Эльдарата, и его камни сложены по образу соседнего Храма Арккоран и Храма Луны, возведенного позднее в Дарнассе. Он был построен во славу Элуны в те дни, когда ночные эльфы еще не обратились к тайной магии.\n\nКогда-то в нем хранился Кристалл Зин-Малора — дар, который должен был донести до высокорожденных весть: на самом деле тайная магия им вовсе не нужна. Теперь кристалла нет, его унесли давным-давно.\n\nС тех пор храм пал под натиском наг из племени Бича Злобы. Ныне там правит полководец Креллиан, присвоивший себе почетное место, некогда предназначенное для поклонения богине.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
