			name = "Джеденар",
			short = "Джеденар поднимается из земли, некогда принадлежавшей ночным эльфам, и его камни старше той порчи, что ныне завладела ими.",
			full = "Джеденар поднимается из земли, некогда принадлежавшей ночным эльфам, и его камни старше той порчи, что ныне завладела ими. Под его руинами лежат две друидские подземные обители, прежде священные, и именно на этом осквернённом основании Совет Теней выстроил свою власть, назвав само это место в честь Кил'джедена Искусителя, которому поклоняется.\n\nПосле Третьей войны руины перешли в руки лорда Гиблопуста и возглавляемого им Совета Теней. Его залы заполнили чернокнижники орков и Отрекшихся, и пришли они не одни: среди них бродили суккубы, охотники Скверны, стражи Скверны и сатиры. В самом сердце Джеденара стоит Оплот Теней, средоточие власти Совета на Азероте, а рядом с ним — Святилище Искусителя, воздвигнутое во имя Кил'джедена.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Морлос'Аран",
			short = "Некогда Морлос'Аран был большим поселением ночных эльфов, возведённым ещё до того, как Великий Раскол разорвал мир на части.",
			full = "Некогда Морлос'Аран был большим поселением ночных эльфов, возведённым ещё до того, как Великий Раскол разорвал мир на части. Теперь он лежит в руинах на южной окраине Оскверненного леса — одно из нескольких подобных мест, таких как Амет'Аран, Башал'Аран, Ордил'Аран и Тетрис'Аран. Все они были когда-то цветущими городами, и от всех остались лишь камни да память о давно утраченном золотом веке.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Руины Констелласа",
			short = "Эти разбитые колонны некогда принадлежали поселению ночных эльфов близ горы Хиджал. В его сердце по-прежнему покоится лунный колодец, но чистого света в нём больше нет.",
			full = "Эти разбитые колонны некогда принадлежали поселению ночных эльфов близ горы Хиджал. В его сердце по-прежнему покоится лунный колодец, но чистого света в нём больше нет. Его воды пропитала порча Скверны, и теперь сатир Ксаватрас ухаживает за колодцем по воле Ксаварика, взращивая скверну, словно сад, предназначенный отравлять. В глубине руин путь к нему преграждает огненная стена.\n\nДруиды не оставили демонов безнаказанными: они наносят им удары, пытаясь вырвать это место у Скверны, пустившей здесь корни.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Оплот Теней",
			short = "Под Джеденаром, на западе Оскверненного леса, раскинулся лабиринт, что когда-то был подземной обителью ночных эльфов. Совет Теней давно захватил его, и теперь по его туннелям бродят чернокнижники со своими демоническими прислужниками.",
			full = "Под Джеденаром, на западе Оскверненного леса, раскинулся лабиринт, что когда-то был подземной обителью ночных эльфов. Совет Теней давно захватил его, и теперь по его туннелям бродят чернокнижники со своими демоническими прислужниками. Там же обитают принц сатиров Ксавалис и повелитель ужаса лорд Гиблопуст.\n\nПаладин Трей Светогорн и ночная эльфийка Арко'нарина Старшейд пришли в Оскверненный лес, чтобы отыскать следы деяний Совета Теней. Культисты схватили обоих и заточили в клетках Оплота Теней. Трея замучили там до смерти, а его дух исказили и осквернили пленители. Арко'нарина по-прежнему томится в клетке в глубинах под присмотром своих мучителей и ждёт спасения, которое ещё не пришло.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Долина Рваных Ран",
			short = "Долина Рваных Ран — то место, куда падали инферналы, когда Пылающий Легион прорвался через Оскверненный лес во время Третьей войны. Оставленные ими воронки всё ещё тлеют, уродуя землю, а среди них до сих пор бродят демоны.",
			full = "Долина Рваных Ран — то место, куда падали инферналы, когда Пылающий Легион прорвался через Оскверненный лес во время Третьей войны. Оставленные ими воронки всё ещё тлеют, уродуя землю, а среди них до сих пор бродят демоны.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Святилище Искусителя",
			short = "Святилище Искусителя, осквернённая подземная обитель в Джеденаре, что в Оскверненном лесу, носит имя Кил'джедена Искусителя, владыки Пылающего Легиона.",
			full = "Святилище Искусителя, осквернённая подземная обитель в Джеденаре, что в Оскверненном лесу, носит имя Кил'джедена Искусителя, владыки Пылающего Легиона. Его глубины кишат чернокнижниками Совета Теней, и неподготовленному путнику здесь грозит большая опасность.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Поляна Когтистых Ветвей",
			short = "Поляна Когтистых Ветвей лежит в северной части Оскверненного леса, к югу от Крепости Древобрюхов, на пути, что ведёт дальше к Лунной поляне и Зимним Ключам.",
			full = "Поляна Когтистых Ветвей лежит в северной части Оскверненного леса, к югу от Крепости Древобрюхов, на пути, что ведёт дальше к Лунной поляне и Зимним Ключам.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Крепость Древобрюхов",
			short = "Крепость Древобрюхов на северо-востоке Оскверненного леса — столица фурболгов из племени Древобрюхов. Её туннели открывают проход к Лунной поляне и Зимним Ключам.",
			full = "Крепость Древобрюхов на северо-востоке Оскверненного леса — столица фурболгов из племени Древобрюхов. Её туннели открывают проход к Лунной поляне и Зимним Ключам.\n\nКогда порча Пылающего Легиона проникла в священные леса Калимдора, фурболги подпали под её влияние и обезумели. Лишь племя Древобрюхов избежало этой тьмы, укрывшись в своей крепости, пока любимый ими лес превращался в гноящееся, извращённое подобие самого себя. Даже спустя долгое время после того, как предводитель демонов был повержен, скверна в лесах осталась.\n\nФурболги Крепости Древобрюхов опасаются всех чужаков: они боятся, что их примут за осквернённых сородичей и нападут без раздумий. И всё же они знают, что в одиночку им не выстоять, и те, кому они начинают доверять, узнают, что Древобрюхи превыше всего ценят дружбу. Больше всего на свете они хотят положить конец страданиям своих осквернённых собратьев и найти исцеление для раны, которой стал Оскверненный лес.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Кратер Ун'Горо: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Вулкан Огненного Венца",
			short = "Вулкан Огненного Венца высится в самом сердце кратера Ун'Горо — гора опалённого камня, по склонам которой ползёт лава, а в жару пробуждаются огненные элементали.",
			full = "Вулкан Огненного Венца высится в самом сердце кратера Ун'Горо — гора опалённого камня, по склонам которой ползёт лава, а в жару пробуждаются огненные элементали. Под дном кратера тянутся неглубокие жилы магмы, питающие паровые озерца и гейзеры, что шипят повсюду в Ун'Горо, так что вся котловина словно дышит огнём этой горы.\n\nВ пещере на вершине обитает Яропламень, сильнейший из огненных элементалей, населяющих гору, владыка её пылающего сердца. Духи огня, что мерцают и пляшут здесь, рассказывают о веках, проведённых в горении, когда они угасали до углей и вспыхивали вновь, снова и снова, без конца.\n\nНе всем, кто приходит к вулкану, удаётся его покорить. Путешественник по имени Ринго отправился исследовать его склоны, сбился с пути и не выдержал жара. Его и сейчас можно найти в южной пещере — выбраться оттуда он так и не сумел.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
