		["golakka hot springs"] = {
			name = "Горячие источники Голакка",
			short = "Над Горячими источниками Голакка непрестанно поднимается пар: здесь, на западе кратера, вулканическое сердце Ун'Горо отдаёт свой жар озерцам и гейзерам.",
			full = "Над Горячими источниками Голакка непрестанно поднимается пар: здесь, на западе кратера, вулканическое сердце Ун'Горо отдаёт свой жар озерцам и гейзерам. По берегам расхаживают элементали ярости, рождённые этим паром и огнём, — их вызывают из земли те же силы, что заставляют источники кипеть.\n\nНекогда сюда приходил Кракл, чтобы выяснить, что связывает горячие источники с огнём соседнего Вулкана Огненного Венца, пока поиски не увели его в другие места.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
