		["lakkari tar pits"] = {
			name = "Смоляные ямы Лаккари",
			short = "Черные озера к северу от Укрытия Маршалла, густые и зловонные, лежат посреди зелени Ун'Горо. Из их поверхности сотнями торчат кости — останки зверей, которые ступали сюда, ожидая найти твёрдую землю, и не находили её.",
			full = "Черные озера к северу от Укрытия Маршалла, густые и зловонные, лежат посреди зелени Ун'Горо. Из их поверхности сотнями торчат кости — останки зверей, которые ступали сюда, ожидая найти твёрдую землю, и не находили её. По краям выжидают падальщики, дожидаясь, пока смола довершит начатое, а из самих ям поднялись смоляные чудища.",
