			full = "Укрытие Маршалла расположено на северной окраине кратера Ун'Горо; его возвела Экспедиция Маршалла под началом Виллидена и Холании Маршалл. Их поход в кратер оказался не готов к тому, что его там ждало: звери Ун'Горо были слишком свирепы, и базовые лагеря экспедиции один за другим оказались разорены. Уцелевшие участники отряда бежали на возвышенность и нашли спасение здесь, на краю кратера.\n\nУкрытие — это итог того отступления, клочок земли, который удалось едва удержать, а не завоевать.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "Топи",
			short = "Топи раскинулись в юго-восточной части кратера Ун'Горо — низкое раздолье стоячей воды и буйной поросли. Именно они встречают большинство тех, кто впервые спускается в кратер из Танариса, ведь любой другой путь сюда опасен.",
			full = "Топи раскинулись в юго-восточной части кратера Ун'Горо — низкое раздолье стоячей воды и буйной поросли. Именно они встречают большинство тех, кто впервые спускается в кратер из Танариса, ведь любой другой путь сюда опасен. В камышах бродит множество ящеров, и укус некоторых из них ядовит.\n\nЗдесь можно найти синие кристаллы силы, и их присутствие проникло в сами топи, просочившись в ящеров, что охотятся на сырой земле, и оставив на них свой след.\n\nНа холме, поднимающемся из воды, несёт дозор Землепроходец Торва, приплывший сюда на каноэ из другой части кратера.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
