	-- Лунная поляна: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Озеро Элуне'ара",
			short = "Кристально чистая вода заполняет сердце Лунной поляны, неподвижная, как стекло, под сенью деревьев. Под её гладью покоится Омен, безумный полубог, побеждённый много веков назад, но так и не покинувший эти глубины.",
			full = "Кристально чистая вода заполняет сердце Лунной поляны, неподвижная, как стекло, под сенью деревьев. Под её гладью покоится Омен, безумный полубог, побеждённый много веков назад, но так и не покинувший эти глубины. Озеро удерживает его в покое — тихий груз под спокойной водой.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Ночная Гавань",
			short = "На берегу озера Элуне'ара стоит Ночная Гавань, деревня с каменными постройками ночных эльфов и лунными колодцами, дом друидов Круга Кенария.",
			full = "На берегу озера Элуне'ара стоит Ночная Гавань, деревня с каменными постройками ночных эльфов и лунными колодцами, дом друидов Круга Кенария. Это тихое уединённое место, закрытое для большинства чужаков; его жители посвятили себя друидизму и заботе о дикой природе.\n\nЛишь раз в году Ночная Гавань открывает свои ворота — когда празднуется Лунный фестиваль и над озером в честь могущества Элуны зажигаются фейерверки. Тогда здесь привечают чужаков, которых в иное время здесь никогда бы не приняли.\n\nНо деревня знала ночи темнее любого праздника. Именно здесь хранитель Ремул сразился с драконом Кошмара Эраникусом, осквернённым и обращённым против деревни. Создания Кошмара обрушились на Ночную Гавань, грозя стереть её с лица земли, пока наконец не явилась Тиранда Шелест Ветра и не призвала свет Элуны, чтобы очистить дракона от овладевшей им порчи. Лунные колодцы и поныне горят тем же светом.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Святилище Ремулоса",
			short = "На западе Лунной поляны стоит Святилище Ремулоса, воздвигнутое в честь хранителя, что оберегает эти места. В нём живёт ночная эльфийка Таджарри, наставляющая юных друидов, которые хотят освоить водный облик.",
			full = "На западе Лунной поляны стоит Святилище Ремулоса, воздвигнутое в честь хранителя, что оберегает эти места. В нём живёт ночная эльфийка Таджарри, наставляющая юных друидов, которые хотят освоить водный облик.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Кельи Малфуриона",
			short = "Под тихим дерном Лунной поляны лежат подземные кельи, уходящие в землю, которую многие друиды из ночных эльфов по-настоящему так и не покидают: их тела покоятся здесь, пока их духи странствуют по Изумрудному Сну.",
			full = "Под тихим дерном Лунной поляны лежат подземные кельи, уходящие в землю, которую многие друиды из ночных эльфов по-настоящему так и не покидают: их тела покоятся здесь, пока их духи странствуют по Изумрудному Сну.\n\nКогда-то здесь спал Малфурион Ярость Бури, и потому кельи носят его имя. Когда в Третью войну явились Тихондриус и его повелители ужаса, они нанесли удар по Малфуриону прямо там, где он лежал, едва не разрушив его обитель. Именно Тиранда Шелест Ветра разбудила его, призвав вернуться в мир и выступить против Архимонда и Пылающего Легиона.\n\nПозже, когда Круг Кенария заговорил о том, чтобы вырастить второе Древо Мира, Малфурион вернулся в кельи, чтобы предаться медитации. Когда Тиранда пришла за ним, она нашла его тело неподвижным, словно спящим, и пробудить его было невозможно. Круг счёл, что мудрее его не трогать: если дух Малфуриона всё ещё блуждает по Изумрудному Сну в поисках дороги домой, ему нужно найти тело там, где он его оставил. Так он и остался здесь под присмотром Круга Кенария и Сестер Элуны, и тело его неподвижно покоится в келье, носящей его имя.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Крепость Древобрюхов",
			short = "Крепость Древобрюхов стоит на северо-востоке Оскверненного леса, где туннель пронзает гору насквозь и ведёт к Лунной поляне и Зимним Ключам. Это столица фурболгов из племени Древобрюхов.",
			full = "Крепость Древобрюхов стоит на северо-востоке Оскверненного леса, где туннель пронзает гору насквозь и ведёт к Лунной поляне и Зимним Ключам. Это столица фурболгов из племени Древобрюхов.\n\nКогда порча Пылающего Легиона проникла в священные леса Калимдора, фурболги подпали под её влияние. Лишь племя Древобрюхов избежало этой тьмы, укрывшись в своей крепости и беспомощно наблюдая, как любимый ими лес искажается, превращаясь в гноящееся, извращённое подобие самого себя. Даже после того, как источник порчи был уничтожен, скверна в лесах осталась.\n\nТеперь Древобрюхи опасаются всех чужаков: они боятся, что их примут за осквернённых сородичей и нападут без раздумий. И всё же они знают, что в одиночку им не выстоять, и те, кто заслужит их доверие, узнают, что Древобрюхи превыше всего ценят дружбу. Их шаманские традиции живы по сей день: они славятся мастерством выделки доспехов из шкур и древними знаниями о врачевании. Больше всего на свете племя жаждет положить конец страданиям своих осквернённых сородичей, чтобы однажды древний лес вновь зазвучал песнопениями и смехом, которые он утратил.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
