		},
		["cenarion hold"] = {
			name = "Крепость Кенария",
			short = "Крепость Кенария выросла в Силитусе после Войны Зыбучих песков; Круг Кенария возвёл её на месте древнего поселения ночных эльфов.",
			full = "Крепость Кенария выросла в Силитусе после Войны Зыбучих песков; Круг Кенария возвёл её на месте древнего поселения ночных эльфов. Это одна из величайших твердынь друидов в Калимдоре, по размерам уступающая лишь самой Лунной поляне, и цель у неё одна: сдерживать рои силитидов и нести дозор над тем, что погребено под песками, — над заточённым Древним Богом К'Туном, чтобы его армии не поднялись вновь.\n\nЖить здесь тяжело, это место осаждено со всех сторон. Силитиды непрестанно напирают на стены, а земли вокруг становятся всё враждебнее. И всё же торговцы крепости не закрывают прилавков и торгуют со всяким, кто совершит долгий подъём из кратера Ун'Горо, ведь так далеко от прочих мест торговля скудна и на счету каждая монета.\n\nПуть к крепости вьётся на северо-запад из Ун'Горо, мимо Замшелой Груды, и взбирается по крутому утёсу петляющей тропой, пока не выводит на выжженные пустоши Силитуса.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "Долина Кристаллов",
			short = "В дальнем северо-западном углу Силитуса лежит Долина Кристаллов, отданная во власть элементалям земли и воздуха.",
			full = "В дальнем северо-западном углу Силитуса лежит Долина Кристаллов, отданная во власть элементалям земли и воздуха. Под её камнем пролегают богатые жилы тория, но земля здесь прежде всего принадлежит духам, что шевелятся в ней, беспокойным и древним. В долине разбил лагерь верховный лорд Демитриан.\n\nИменно здесь можно призвать Громораана Искателя Ветра и заново заключить его в клинок, несущий его ярость, — это действо бури и воли, на которое мало кто решается и которое ещё меньше кому удаётся довести до конца.",
