		["scarab dais"] = {
			name = "Помост Скарабея",
			short = "Гонг Скарабея стоит на Помосте Скарабея, к северо-западу от Стены Скарабея у стен Ан'Киража, на юге Силитуса.",
			full = "Гонг Скарабея стоит на Помосте Скарабея, к северо-западу от Стены Скарабея у стен Ан'Киража, на юге Силитуса.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Стена Скарабея",
			short = "Стена Скарабея тянется вдоль южной окраины Силитуса, отделяя пустыню от лежащего за ней разрушенного города Ан'Киража.",
			full = "Стена Скарабея тянется вдоль южной окраины Силитуса, отделяя пустыню от лежащего за ней разрушенного города Ан'Киража. Она была поднята из самого песка в конце Войны Зыбучих песков, и её песчаниковая громада вздымается в небо по меньшей мере на сотню футов. Выше, куда камень подняться уже не мог, бронзовые драконы вплели свою магию в преграду, во много раз превосходящую стену высотой.\n\nЕё создатели, ночные эльфы вместе с бронзовыми драконами, назвали её Ирана'этил — Щит против Тени. Имя прямо говорит о её предназначении: К'Тун и его силитидские выводки были запечатаны в Ан'Кираже, и стена встала между этим ужасом и остальным миром.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Деревня Южного Ветра",
			short = "Некогда Деревня Южного Ветра была заставой ночных эльфов в Силитусе. Войну Зыбучих песков она не пережила.",
			full = "Некогда Деревня Южного Ветра была заставой ночных эльфов в Силитусе. Войну Зыбучих песков она не пережила.\n\nКогда киражи поднялись несметными роями, Вальстан Олений Шлем, сын Фэндрала Оленьего Шлема, повёл отряд армии ночных эльфов оборонять деревню. Его воинов перебили там, где они стояли, а самого Вальстана генерал Раджакс взял живым, пока деревню, которую ему поручили защищать, разрывали на части у него за спиной.\n\nТо, что оставили после себя киражи, не опустело. Духи друидов и Часовых, павших в той резне, задерживаются среди обломков, бесцельно скитаясь, привязанные к месту своей гибели, и следуют за Тенью Эмбермун. Деревня Южного Ветра стоит не тихими руинами, а проклятой землёй, и её мёртвые ещё не покончили с ней.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Лагерь Оленьего Шлема",
			short = "Когда-то вершину на северо-востоке Силитуса венчала башня ночных эльфов. Здесь несёт свою службу Рало'шал Вечная Стражница, а в небе над ней кружит бронзовый дракон из стаи Ноздорму.",
			full = "Когда-то вершину на северо-востоке Силитуса венчала башня ночных эльфов. Здесь несёт свою службу Рало'шал Вечная Стражница, а в небе над ней кружит бронзовый дракон из стаи Ноздорму. Ниже по дороге от башни находится Сумеречная пещера, где укрываются сумеречные культисты, а у входа в неё разбит небольшой лагерь — угроза, с которой стражнице приходится считаться.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Роящаяся вершина",
			short = "Роящаяся вершина поднимается к югу от Крепости Кенария — пик, насквозь изрытый туннелями силитидов, склоны которого никогда не знают покоя.",
			full = "Роящаяся вершина поднимается к югу от Крепости Кенария — пик, насквозь изрытый туннелями силитидов, склоны которого никогда не знают покоя. Вокруг камня в любой час кружит марево мелких силитидов — живое облако, давшее вершине её имя, а под песком у её подножия находится один из покоев улья, самое большое из множества гнёзд, что пронизывают, подобно сотам, землю Силитуса.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
