		["dun mandarr"] = {
			name = "Дун Мандарр",
			short = "Дун Мандарр расположен близ ледяной пещеры на юго-востоке Зимних Ключей, и его имя выдаёт руку дворфов. Теперь лагерь заполонили свирепые лунные совухи, и от тех, кто его возвёл, почти ничего не осталось.",
			full = "Дун Мандарр расположен близ ледяной пещеры на юго-востоке Зимних Ключей, и его имя выдаёт руку дворфов. Теперь лагерь заполонили свирепые лунные совухи, и от тех, кто его возвёл, почти ничего не осталось.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Круговзор",
			short = "Круговзор стоит на перекрёстке торговых путей Зимних Ключей — гоблинский пост картеля Хитрая Шестеренка, среди построек которого укрылась лаборатория.",
			full = "Круговзор стоит на перекрёстке торговых путей Зимних Ключей — гоблинский пост картеля Хитрая Шестеренка, среди построек которого укрылась лаборатория.\n\nСеребряный Рассвет прислал сюда Грегора Грейстоуна, чтобы тот представлял его интересы перед местным правлением картеля.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Источники Ледяного Пламени",
			short = "На дальней западной окраине Зимних Ключей над цепочкой озерец поднимается пар: вода в них слишком тёплая для окружающей их мёрзлой земли. Никто так и не объяснил, почему эти источники пышут жаром под снегом и льдом.",
			full = "На дальней западной окраине Зимних Ключей над цепочкой озерец поднимается пар: вода в них слишком тёплая для окружающей их мёрзлой земли. Никто так и не объяснил, почему эти источники пышут жаром под снегом и льдом. Донова Снегонора, разбившая лагерь неподалёку, гадает, не могла ли какая-то демоническая скверна, просачивающаяся на север из Теснины Зловещего Шепота, добраться сюда и согреть камень.\n\nБлижайшее к Крепости Древобрюхов озерцо так и не удалось вырвать из рук племени Зимней Спячки. Они по-прежнему удерживают его, и фурболги вовсе не склонны делиться захваченным теплом.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Уступ Ледопардов",
			short = "На вершине Уступа Ледопардов стоит Риверн Холодный Ветер, хранитель связи между ледопардами и теми, кто желает на них ездить.",
			full = "На вершине Уступа Ледопардов стоит Риверн Холодный Ветер, хранитель связи между ледопардами и теми, кто желает на них ездить. Он учит друзей Альянса, которые этого заслужат, приручать огромных белых кошек, что бродят по ледяным скалам внизу, и ездить на них верхом.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Теснина Ледяного Шепота",
			short = "Теснина Ледяного Шепота прорезает юг Зимних Ключей, и её дно и гребни усеяны руинами ночных эльфов. Среди этих древних камней обитают великаны Ледяного Молота и их исполинские Хранители.",
			full = "Теснина Ледяного Шепота прорезает юг Зимних Ключей, и её дно и гребни усеяны руинами ночных эльфов. Среди этих древних камней обитают великаны Ледяного Молота и их исполинские Хранители.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "Сокрытая роща",
			short = "Сокрытая роща лежит в глубине кратера в Зимних Ключах, со всех сторон окружённая отвесными утёсами.",
			full = "Сокрытая роща лежит в глубине кратера в Зимних Ключах, со всех сторон окружённая отвесными утёсами. Пройти туда можно лишь через единственную пещеру, прорубленную в юго-восточном гребне, а спуск с высот над ней — путь, на который мало кто отважится.\n\nКогда-то в этой лощине не было никого страшнее белых зайцев, которые безмятежно плодились под её защитой. С тех пор всё изменилось. Теперь рощу заняли лунные совухи, враждебные ко всякому, кто сюда войдёт, и их присутствие запечатало это место так же надёжно, как некогда его утёсы.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Холмы Ледополоха",
			short = "Холмы Ледополоха поднимаются к юго-востоку от Круговзора. Здесь обитают йети Ледополоха: их логово — пещера, что взбирается вверх по склону холма, а сами они бродят по окрестным склонам.",
			full = "Холмы Ледополоха поднимаются к юго-востоку от Круговзора. Здесь обитают йети Ледополоха: их логово — пещера, что взбирается вверх по склону холма, а сами они бродят по окрестным склонам. Их густой мех и светлые рога высоко ценят те, кто отваживается выйти в стужу, чтобы их добыть.\n\nНа открытых склонах растет ледяной зев, а внутри пещеры скалу пронизывают жилы тория. А реже всего, говорят, у самого входа в пещеру иногда расцветает черный лотос, хрупкий и странный посреди владений йети.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Озеро Кел'Терил",
			short = "Замёрзшие воды озера Кел'Терил неподвижно лежат в самом сердце Зимних Ключей, окружённые одноимёнными руинами.",
			full = "Замёрзшие воды озера Кел'Терил неподвижно лежат в самом сердце Зимних Ключей, окружённые одноимёнными руинами. Эти руины — древнее творение высокорожденных, и те, кто когда-то жил там, не ушли, когда пали их чертоги. Их измученные духи всё ещё задерживаются здесь, скользя по льду и разбитым камням.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Маззорил",
			short = "Глубоко во льдах Зимних Ключей, близ озера Кел'Терил, под землёй открывается пещера Маззорил — холодная, огромная, насыщенная магией.",
			full = "Глубоко во льдах Зимних Ключей, близ озера Кел'Терил, под землёй открывается пещера Маззорил — холодная, огромная, насыщенная магией. Здесь обитает выводок синих драконов, присягнувших Малигосу, и здесь их праматерь несёт свой одинокий дозор.\n\nХалех редко принимает облик, который мир назвал бы истинным: она показывается лишь в образе высшей эльфийки, стоящей на самом верхнем уступе пещеры, куда можно попасть через руну перемещения, начертанную в полу далеко внизу. Мало кто, кроме ей подобных, когда-либо видел её лицо.\n\nВокруг себя она выставила стражу, достойную её нелюдимости. Четверо могучих драконов подчиняются только ей. Спеллмо неспешно и неустанно обходит треть нижних пределов Зимних Ключей, а Манаклоу и Скрайер стоят над рунами в глубине пещеры, словно часовые у запертой двери.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Обитель Лунного Ужаса",
			short = "Недалеко к северо-востоку от ворот Круговзора земля поднимается к небольшой пещере, известной как Обитель Лунного Ужаса, где живут свирепые разъярённые совухи.",
			full = "Недалеко к северо-востоку от ворот Круговзора земля поднимается к небольшой пещере, известной как Обитель Лунного Ужаса, где живут свирепые разъярённые совухи. Между логовом и Деревней Зимней Спячки к югу стоит гора, так что, хотя эти места и кажутся близкими, прямой дороги между ними нет — лишь долгий объезд вокруг возвышенности.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Совиная чаща",
			short = "Пещеры Совиной чащи прорезают южные пределы Зимних Ключей; здесь обитают совухи, впавшие в неистовство, осенённые луной и обезумевшие.",
			full = "Пещеры Совиной чащи прорезают южные пределы Зимних Ключей; здесь обитают совухи, впавшие в неистовство, осенённые луной и обезумевшие. Говорят, что древние Стражи Элуны рассказывают здесь о том, как лунные совухи впервые пришли в мир, а их предание хранит Раншалла.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Руины Кел'Терила",
			short = "Руины Кел'Терила лежат в развалинах на берегах одноимённого озера — всё, что осталось от великого города ночных эльфов.",
			full = "Руины Кел'Терила лежат в развалинах на берегах одноимённого озера — всё, что осталось от великого города ночных эльфов. Он пал во время Великого Раскола, когда сам мир был разорван на части, и с тех пор так и не поднялся.\n\nНыне здесь обитает скорбь, не знающая покоя. Высокорожденные, погибшие при падении Кел'Терила, не ушли в иной мир: их измученные духи остаются среди поваленных колонн северных руин, не в силах отпустить то, что утратили. Восточную часть населяют призраки высших эльфов, среди которых преданные следопыты и верховный маг.\n\nС падением этого места связан кристалл под названием Зин-Малор, причастный к разрушению, которое поглотило здесь одно поколение эльфов за другим. Эта история принадлежит самому Кел'Терилу — поваленным камням и призракам, что всё ещё бродят среди них.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Деревня Звездопада",
			short = "Деревня Звездопада стоит у дороги через Зимние Ключи — единственное место в этом холодном краю, где у Альянса есть опора.",
			full = "Деревня Звездопада стоит у дороги через Зимние Ключи — единственное место в этом холодном краю, где у Альянса есть опора. Поселение состоит из домика ночных эльфов и дома поменьше, а неподалёку лежит Берлога Бен'Таллоу, уходящая в землю, подобно курганам, от которых она получила своё название.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Крепость Древобрюхов",
			short = "Крепость Древобрюхов лежит в туннелях северной части Оскверненного леса, в проходе, что открывается к Лунной поляне и Зимним Ключам; это последний оплот фурболгов из племени Древобрюхов.",
			full = "Крепость Древобрюхов лежит в туннелях северной части Оскверненного леса, в проходе, что открывается к Лунной поляне и Зимним Ключам; это последний оплот фурболгов из племени Древобрюхов.\n\nКогда порча Пылающего Легиона проникла в священные леса Калимдора, фурболги тех земель пали её жертвой и превратились в диких и жестоких существ. Лишь племя Древобрюхов избежало этой участи, укрывшись в своих туннелях, пока любимый ими лес вокруг превращался в гноящееся, извращённое подобие самого себя. Даже после того, как источник порчи был уничтожен, скверна не покинула леса.\n\nДревобрюхи по-прежнему опасаются всех чужаков: они боятся, что их примут за осквернённых сородичей и убьют прежде, чем они успеют доказать обратное. И всё же они знают, что в одиночку им не выстоять, и к тем, кто заслужит их доверие, они щедры: они держатся старых шаманских обычаев и охотно делятся своими знаниями о врачевании. Больше всего они хотят положить конец страданиям своих осквернённых собратьев и найти исцеление для ран, нанесённых Оскверненному лесу.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Застава Древобрюхов",
			short = "Застава Древобрюхов носит имя, которое ей больше не подходит.",
			full = "Застава Древобрюхов носит имя, которое ей больше не подходит. Некогда лагерь принадлежал племени Древобрюхов, но теперь им безраздельно владеют осквернённые фурболги из племени Зимней Спячки. Он находится к юго-востоку от Источников Ледяного Пламени и к западу от озера Кел'Терил.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Деревня Зимней Спячки",
			short = "Деревня Зимней Спячки взбирается по восточным склонам Зимних Ключей неподалёку от Круговзора; её фурболги давно поражены порчей. На вершине находится небольшая пещера — резиденция верховного вождя племени Зимней Спячки, который оттуда правит поселением.",
			full = "Деревня Зимней Спячки взбирается по восточным склонам Зимних Ключей неподалёку от Круговзора; её фурболги давно поражены порчей. На вершине находится небольшая пещера — резиденция верховного вождя племени Зимней Спячки, который оттуда правит поселением.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Штормград: 3 subzones
	[1453] = {
		["champions hall"] = {
			name = "Зал Защитников",
			short = "На юге Старого города в Штормграде стоит Зал Защитников, где живут офицеры Альянса, обособленно от прочих в старом городе, как и подобает их званию.",
			full = "На юге Старого города в Штормграде стоит Зал Защитников, где живут офицеры Альянса, обособленно от прочих в старом городе, как и подобает их званию.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Подземный поезд",
			short = "Король Магни Бронзобород построил Подземный поезд вовсе не ради удобства.",
			full = "Король Магни Бронзобород построил Подземный поезд вовсе не ради удобства. В годы после Второй войны, когда Штормград с трудом отстраивался из руин, Магни стал терять терпение от того, как медленно помощь Стальгорна доходит до его союзников-людей, и тревожиться о том, как медленно дворфские воины смогут добраться до них, если снова разразится война. Он обратился к главному механику Гелбину Меггакруту, самому почитаемому инженеру Азерота, и поручил ему решить эту задачу. Ответом Меггакрута стала железная дорога, проложенная под самой землёй и напрямую соединившая две столицы.\n\nНа пути туннеля строители наткнулись на подземное озеро, но не стали его обходить. Поезд и поныне идёт сквозь него: закрытые пути пролегают не вдоль воды, а под ней.\n\nГномы ежедневно обслуживают поезд, следя за тем, чтобы два его состава по три вагона быстро и плавно ходили между Стальгорном и Штормградом, бесплатно для всех, кто выходит на подземные платформы.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["valley of heroes"] = {
			name = "Аллея Героев",
			short = "Мост из светлого камня переносит каждого путника через ров перед южными воротами Штормграда в зелёную долину, по сторонам которой стоят статуи, воздвигнутые не только во славу, но и в скорби.",
			full = "Мост из светлого камня переносит каждого путника через ров перед южными воротами Штормграда в зелёную долину, по сторонам которой стоят статуи, воздвигнутые не только во славу, но и в скорби.\n\nПосле Второй войны, когда Штормград отстроили из руин, город почтил тех, кто повёл экспедицию Альянса через Темный портал, чтобы запечатать его с другой стороны. Слева от дороги стоят Курдран Громовой Молот и верховный маг Кадгар, справа — командующий Данат Троллебой и капитан следопытов Аллерия Ветрокрылая, а в конце дороги, там, где она разветвляется перед входом в сам город, стоит генерал Туралион, который вёл их всех. Ни один из пятерых так и не вернулся.\n\nГоды спустя сына Аллерии и Туралиона, Аратора, принесли на церемонию в долину на плечах рыцаря Серебряной Длани. Он поднял взгляд на каменное изваяние матери — лицо, которого он совсем не помнил. Что-то от неё коснулось его там, ведь мальчик улыбнулся и потянулся к статуе. Взрослея, он возвращался сюда снова и снова, чтобы постоять перед её ликом и знать, даже не помня её, что она его любила.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Оргриммар: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Зал Легенд",
			short = "Зал Легенд стоит на Аллее Силы в Оргриммаре — это казармы, где держат совет офицеры Орды.",
			full = "Зал Легенд стоит на Аллее Силы в Оргриммаре — это казармы, где держат совет офицеры Орды.\n\nВ его центре стоит стол, на котором разложены карты Азерота.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Огненная пропасть",
			short = "Под Оргриммаром земля разверзается огненной пропастью, чьи туннели затянуты лавой и дымом. Здесь из глубин начали выбираться трогги — клан, который в Орде прозвали троггами Огненной пропасти.",
			full = "Под Оргриммаром земля разверзается огненной пропастью, чьи туннели затянуты лавой и дымом. Здесь из глубин начали выбираться трогги — клан, который в Орде прозвали троггами Огненной пропасти. Провидица Магата из племени тауренов попыталась заключить с ними мир в надежде отвратить их от города наверху. Но встретила она лишь враждебность. Стало ясно, что эти создания вовсе не склонны к дипломатии и что, если их не сдерживать, они могут полностью сокрушить Орду.\n\nХуже того, заговор проник и в сам Оргриммар. Нииру Огненный Клинок, скрывавший свою истинную преданность как предводитель Пылающего Клинка, заманивал верных сторонников самого Тралла вниз, в пропасть, и скармливал их укрывшейся там секте тёмных культистов — чтобы и избавиться от них, и проверить, можно ли доверять культистам. Тралл знает об этом предательстве больше, чем показывает, но предводители культистов по-прежнему удерживают пещеры, которые объявили своими.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Стальгорн: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Подземный поезд",
			short = "Король Магни Бронзобород построил Подземный поезд вовсе не ради удобства.",
			full = "Король Магни Бронзобород построил Подземный поезд вовсе не ради удобства. В годы после Второй войны, когда Штормград с трудом отстраивался из руин, Магни стал терять терпение от того, как медленно помощь Стальгорна доходит до его союзников-людей, и тревожиться о том, как медленно дворфские воины смогут добраться до них, если снова разразится война. Он обратился к главному механику Гелбину Меггакруту, самому почитаемому инженеру Азерота, и поручил ему решить эту задачу. Ответом Меггакрута стала железная дорога, проложенная под самой землёй и напрямую соединившая две столицы.\n\nНа пути туннеля строители наткнулись на подземное озеро, но не стали его обходить. Поезд и поныне идёт сквозь него: закрытые пути пролегают не вдоль воды, а под ней.\n\nГномы ежедневно обслуживают поезд, следя за тем, чтобы два его состава по три вагона быстро и плавно ходили между Стальгорном и Штормградом, бесплатно для всех, кто выходит на подземные платформы.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Врата Стальгорна",
			short = "Врата Стальгорна высятся там, где великий подъём Дун Морога взбирается навстречу горе; их видно за много миль над снегами задолго до того, как путник до них доберётся.",
			full = "Врата Стальгорна высятся там, где великий подъём Дун Морога взбирается навстречу горе; их видно за много миль над снегами задолго до того, как путник до них доберётся. Они служат порогом между открытыми землями дворфов и самим Стальгорном.\n\nПройдя через них, путник попадает под взгляд огромной статуи верховного короля Модимуса Анвилмара, поставленной сразу за входом, чтобы никто не вошёл в город, не пройдя прежде под его взором.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
