		["elder rise"] = {
			name = "Вершина Старейшин",
			short = "Вершина Старейшин находится к востоку от центрального утеса, и попасть на неё можно по веревочным мостам с Верхней и Средней вершин.",
			full = "Вершина Старейшин находится к востоку от центрального утеса, и попасть на неё можно по веревочным мостам с Верхней и Средней вершин. Здесь находится обитель Круга Кенария, где собираются друиды и жрецы тауренов и где живёт верховный друид Хамуул Рунический Тотем. Здесь же вершит свое правление Совет старейшин.\n\nМежду двумя мостами стоит хижина, которую заняла Магата Зловещий Тотем, предводительница племени Зловещего Тотема.",
