	-- Дарнасс: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Анклав Кенария",
			short = "Анклав Кенария лежит на северо-западе Дарнасса — круглая роща, где дубы и ясени поднимаются выше каменных чертогов в других частях города.",
			full = "Анклав Кенария лежит на северо-западе Дарнасса — круглая роща, где дубы и ясени поднимаются выше каменных чертогов в других частях города. Каждое дерево здесь несёт руны, не вырезанные, а выращенные прямо из живой коры, а места собраний в роще сами сложены из дерева и камня, сплетённых воедино, словно выращены, а не построены.\n\nЗдесь всегда было средоточие друидов города, так же как Храм Луны — средоточие его жрецов. Верховный друид Фэндрал Олений Шлем руководит ими из ветвей Анклава, а самое большое из его живых строений, стоящее в сердце рощи, — его собственная резиденция.\n\nРоща по-прежнему служит ордену, что собирается под её сенью: сюда приходят друиды, чтобы постигать древние обычаи, охотники упражняются в самом восточном её дереве, а у подножия великого древа Анклава можно научиться ездить на ночных саблезубах, что носят всадников Дарнасса по диким землям. Под землёй, в самой западной ветви, скрывается тайная гильдия разбойников, о которой знают лишь те, кому уже известно, где искать.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Терраса Ремесленников",
			short = "Терраса Ремесленников лежит на севере Дарнасса и отдана торговле, а не войне или поклонению. Здесь держат свои лавки мастера города, а усталые путники могут найти приют в одной из таверн Дарнасса.",
			full = "Терраса Ремесленников лежит на севере Дарнасса и отдана торговле, а не войне или поклонению. Здесь держат свои лавки мастера города, а усталые путники могут найти приют в одной из таверн Дарнасса. Здесь же находится посольство Серебряного Рассвета — чужеземное представительство, которому отведено место в эльфийском городе.\n\nНа юге терраса граничит с Террасой Воинов, а на западе — с Анклавом Кенария.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Храмовые сады",
			short = "В самом сердце Дарнасса раскинулись Сады Храма — широкий простор воды, дорожек и маленьких островков, получивший своё название от великого Храма Луны, что возвышается чуть южнее.",
			full = "В самом сердце Дарнасса раскинулись Сады Храма — широкий простор воды, дорожек и маленьких островков, получивший своё название от великого Храма Луны, что возвышается чуть южнее. Мосты расходятся от них во все стороны, соединяя их с Анклавом Кенария на севере, с Террасами Ремесленников, Воинов и Торговцев на востоке и с Храмом Луны на юге, так что все дороги города словно сходятся здесь.\n\nНа самом большом острове находится городской банк, а портал на западной окраине садов переносит вниз, в деревню Рут'теран у подножия Древа Мира, и потому этот тихий центр воды и камня служит ещё и порогом между Дарнассом и миром за его пределами.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Терраса Торговцев",
			short = "Терраса Торговцев расположена в южной части Дарнасса: здесь лавочники держат свои прилавки, а купцы собираются, чтобы торговаться, и потому она стала сердцем торговли всего города.",
			full = "Терраса Торговцев расположена в южной части Дарнасса: здесь лавочники держат свои прилавки, а купцы собираются, чтобы торговаться, и потому она стала сердцем торговли всего города. С севера она выходит на Террасу Воинов, а на западе тропы ведут к Храму Луны и Садам Храма.\n\nЕё постройки выращены из дерева, как это принято у ночных эльфов, — лёгкие и изящные.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Терраса Воинов",
			short = "Терраса Воинов охраняет восточные ворота Дарнасса, где город открывается на дикие леса Тельдрассила.",
			full = "Терраса Воинов охраняет восточные ворота Дарнасса, где город открывается на дикие леса Тельдрассила. Здесь стоят Часовые, и каждый ночной эльф, желающий взяться за оружие на службе городу, приходит на эту террасу, чтобы упражняться на стрельбищах и площадках для поединков, пока его мастерство не станет пригодным для войны.\n\nВсадники на ночных саблезубах несут дозор у ворот, и терраса служит городу щитом от любого насилия, что может прийти по дороге из леса.\n\nС севера она граничит с Террасой Ремесленников, с юга — с Террасой Торговцев, а с запада — с Садами Храма, так что воин, упражняющийся здесь, всегда находится в пределах оклика от ремесленников, торговцев и жрецов города.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Подгород: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Руины Лордерона",
			short = "Над погребённым городом всё ещё стоит дворец Лордерона: его залы открыты небу, его сады пришли в запустение. Здесь умерло великое королевство Альянса, и здесь его призраки так до конца и не покинули его.",
			full = "Над погребённым городом всё ещё стоит дворец Лордерона: его залы открыты небу, его сады пришли в запустение. Здесь умерло великое королевство Альянса, и здесь его призраки так до конца и не покинули его.\n\nПоложил ему конец Артас Менетил. Принц вернулся домой во главе армии, поднятой против собственного народа, и его встречали у этих ворот колокольным звоном и ликованием, прежде чем кто-либо понял, кем он стал. Он нашёл своего отца, короля Теренаса, ожидавшим его в тронном зале, и там же убил его. Стоя над телом, он произнёс слова, которые до сих пор отдаются эхом в этом зале для всякого, кто задержится там: что королевство падёт, а из его пепла поднимется новый порядок, который потрясёт мир. Это не было пустым бахвальством. За несколько дней город и его жители были перебиты, и Лордерон достался Плети.\n\nГоворят, что и сейчас, пройдя по двору, можно услышать то, что помнит камень: приглушённые голоса, звон приветственных колоколов, ропот из тронного зала, который так и не стихает до конца. Те, кто способен видеть за завесой, говорят, что жители Лордерона по-прежнему ходят там, не ведая, что их королевства больше нет.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
}

